#[test]
fn commit_pipeline_tick_deadline_bypasses_budget_for_saturated_active_recovery() {
    let start = Instant::now();
    let deadline = Some(start);

    assert_eq!(
        Actor::commit_pipeline_tick_deadline(deadline, 1, false, true),
        None,
        "active pending recovery should get a commit-pipeline slice under queue saturation"
    );
    assert_eq!(
        Actor::commit_pipeline_tick_deadline(deadline, 1, true, false),
        None,
        "explicit commit wakeups should get a commit-pipeline slice for active pending work"
    );
    assert_eq!(
        Actor::commit_pipeline_tick_deadline(deadline, 0, true, true),
        deadline,
        "budget bypass requires active pending consensus work"
    );
    assert_eq!(
        Actor::commit_pipeline_tick_deadline(deadline, 1, false, false),
        deadline,
        "normal operation keeps the shared tick budget"
    );
}

#[allow(clippy::too_many_arguments)]
fn select_block_sync_roster(
    block: &SignedBlock,
    block_hash: HashOf<BlockHeader>,
    block_height: u64,
    persisted: Option<BlockSyncRosterSelection>,
    cert_hint: Option<&Qc>,
    checkpoint_hint: Option<&ValidatorSetCheckpoint>,
    state: &State,
    trusted: &iroha_config::parameters::actual::TrustedPeers,
    local_peer: &PeerId,
    mode_tag: &'static str,
    allow_uncertified: bool,
) -> Option<BlockSyncRosterSelection> {
    let roster_cache = roster_cache_for_state(state, EPOCH_LENGTH_BLOCKS);
    super::select_block_sync_roster(
        block,
        block_hash,
        block_height,
        persisted,
        cert_hint,
        checkpoint_hint,
        None,
        state,
        trusted,
        local_peer,
        ConsensusMode::Permissioned,
        mode_tag,
        allow_uncertified,
        &roster_cache,
    )
}

fn roster_cache_for_state(
    state: &State,
    fallback_epoch_length: u64,
) -> super::RosterValidationCache {
    let world = state.world.view();
    let cache = super::RosterValidationCache::from_world(&world, fallback_epoch_length, None);
    drop(world);
    cache
}

fn sample_chunk_with_len(idx: u32, len: usize) -> crate::sumeragi::consensus::RbcChunk {
    let idx_byte = u8::try_from(idx).expect("idx fits in u8 for test chunk");
    crate::sumeragi::consensus::RbcChunk {
        block_hash: HashOf::from_untyped_unchecked(Hash::prehashed([idx_byte; Hash::LENGTH])),
        height: 1,
        view: 1,
        idx,
        epoch: 0,
        bytes: vec![0u8; len],
    }
}

fn roster_hash(roster: &[PeerId]) -> Hash {
    Hash::new(&roster.to_vec().encode())
}

fn signature_sender_index(
    actor: &Actor,
    roster: &[PeerId],
    height: u64,
    view: u64,
    signer_peer: &PeerId,
) -> u32 {
    let topology = super::network_topology::Topology::new(roster.to_vec());
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let idx = signature_topology
        .as_ref()
        .iter()
        .position(|peer| peer == signer_peer)
        .expect("signer peer in topology");
    u32::try_from(idx).expect("signer index fits u32")
}

fn signed_remote_rbc_ready_signatures_for_roster(
    actor: &Actor,
    key_pairs: &[KeyPair],
    roster: &[PeerId],
    block_hash: HashOf<BlockHeader>,
    height: u64,
    view: u64,
    epoch: u64,
    chunk_root: Hash,
    count: usize,
) -> Vec<crate::sumeragi::consensus::RbcReadySignature> {
    let topology = super::network_topology::Topology::new(roster.to_vec());
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let local_peer = actor.common_config.peer.id().clone();
    let signers: Vec<_> = signature_topology
        .as_ref()
        .iter()
        .enumerate()
        .filter(|(_, peer)| *peer != &local_peer)
        .take(count)
        .map(|(idx, peer)| (idx, peer.clone()))
        .collect();
    assert_eq!(
        signers.len(),
        count,
        "test requires enough remote READY signers"
    );

    let roster_hash = roster_hash(roster);
    signers
        .into_iter()
        .map(|(signer_idx, signer_peer)| {
            let signer_kp = key_pairs
                .iter()
                .find(|kp| kp.public_key() == signer_peer.public_key())
                .expect("signer keypair");
            let mut ready = crate::sumeragi::consensus::RbcReady {
                block_hash,
                height,
                view,
                epoch,
                roster_hash,
                chunk_root,
                sender: u32::try_from(signer_idx).expect("sender fits u32"),
                signature: Vec::new(),
            };
            let preimage = super::rbc_ready_preimage(&actor.common_config.chain, mode_tag, &ready);
            let signature = checked_signature(signer_kp.private_key(), &preimage);
            ready.signature = signature.payload().to_vec();
            crate::sumeragi::consensus::RbcReadySignature {
                sender: ready.sender,
                signature: ready.signature,
            }
        })
        .collect()
}

fn attach_background_log(actor: &mut Actor) -> Arc<Mutex<Vec<super::BackgroundRequestLogEntry>>> {
    let log = Arc::new(Mutex::new(Vec::new()));
    actor.background_request_log = Some(Arc::clone(&log));
    log
}

fn take_background_log(
    log: &Arc<Mutex<Vec<super::BackgroundRequestLogEntry>>>,
) -> Vec<super::BackgroundRequestLogEntry> {
    let mut guard = log.lock().expect("background request log mutex poisoned");
    std::mem::take(&mut *guard)
}

