fn deterministic_keypair(seed: impl AsRef<[u8]>, algorithm: Algorithm) -> KeyPair {
    let seed_hash = Hash::new(seed.as_ref());
    KeyPair::try_from_seed(seed_hash.as_ref().to_vec(), algorithm)
        .expect("derive deterministic main-loop fixture key")
}

fn checked_keypair() -> KeyPair {
    KeyPair::try_random().expect("main-loop fixture key generation should succeed")
}

fn checked_keypair_with_algorithm(algorithm: Algorithm) -> KeyPair {
    KeyPair::try_random_with_algorithm(algorithm)
        .expect("main-loop algorithm-specific fixture key generation should succeed")
}

fn checked_bls_keypair() -> KeyPair {
    checked_keypair_with_algorithm(Algorithm::BlsNormal)
}

#[test]
fn deterministic_keypair_uses_checked_seed_derivation() {
    let seed = b"main-loop-deterministic-keypair";
    let seed_hash = Hash::new(seed);
    let expected = KeyPair::try_from_seed(seed_hash.as_ref().to_vec(), Algorithm::Ed25519)
        .expect("derive expected deterministic fixture key");

    assert_eq!(
        deterministic_keypair(seed, Algorithm::Ed25519).public_key(),
        expected.public_key()
    );
}

#[test]
fn checked_keypair_helpers_preserve_requested_algorithm() {
    assert_eq!(checked_keypair().algorithm(), Algorithm::default());
    assert_eq!(checked_bls_keypair().algorithm(), Algorithm::BlsNormal);
    assert_eq!(
        checked_keypair_with_algorithm(Algorithm::Ed25519).algorithm(),
        Algorithm::Ed25519
    );
}

fn checked_signature(private_key: &iroha_crypto::PrivateKey, payload: &[u8]) -> Signature {
    Signature::try_new(private_key, payload).expect("test fixture signing should succeed")
}

fn checked_signature_of_hash<T>(
    private_key: &iroha_crypto::PrivateKey,
    hash: HashOf<T>,
) -> SignatureOf<T> {
    SignatureOf::try_from_hash(private_key, hash).expect("test fixture hash signing should succeed")
}

fn forged_leader_signature_for_block(
    valid_leader_signature: &BlockSignature,
    block: &SignedBlock,
    algorithm: Algorithm,
) -> BlockSignature {
    let wrong_key = checked_keypair_with_algorithm(algorithm);
    let wrong_signature = checked_signature_of_hash(wrong_key.private_key(), block.header().hash());
    BlockSignature::new(valid_leader_signature.index(), wrong_signature)
}

fn insert_validated_pending(actor: &mut Actor, block: SignedBlock) -> HashOf<BlockHeader> {
    let block_hash = block.hash();
    let height = block.header().height().get();
    let view = block.header().view_change_index();
    let committed_height = u64::try_from(actor.state.view().height()).unwrap_or(u64::MAX);
    assert!(
        committed_height < height,
        "test requires pending block height above committed height (committed={committed_height}, pending={height})"
    );
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let mut pending = PendingBlock::new(block, payload_hash, height, view);
    pending.validation_status = ValidationStatus::Valid;
    pending.parent_state_root = Some(zero_state_root());
    pending.post_state_root = Some(zero_state_root());
    actor.pending.pending_blocks.insert(block_hash, pending);
    actor.note_proposal_seen(height, view, payload_hash);
    block_hash
}

fn validated_roots_for_actor_block(
    actor: &mut Actor,
    block: SignedBlock,
    topology: &super::network_topology::Topology,
) -> super::StateRoots {
    let height = block.header().height().get();
    let view = block.header().view_change_index();
    let mut validation_topology = topology.clone();
    actor
        .leader_index_for(&mut validation_topology, height, view)
        .expect("validation topology should align");
    let mut voting_block = None;
    super::validate_block_for_voting(
        block,
        &mut validation_topology,
        &actor.common_config.chain,
        &actor.genesis_account,
        actor.state.as_ref(),
        &mut voting_block,
    )
    .expect("test block should validate before voting")
    .expect("test block should produce execution roots")
}

fn insert_test_vote_with_roster(
    actor: &mut Actor,
    vote: crate::sumeragi::consensus::Vote,
    roster: &[PeerId],
) {
    actor.cache_vote_roster(vote.block_hash, vote.height, vote.view, roster.to_vec());
    if let Some(peer) = actor.vote_signer_peer(&vote) {
        actor.vote_log_identities.insert(
            vote_identity_key_for_vote(&vote, peer.public_key()),
            vote.clone(),
        );
    }
    actor.vote_log.insert(vote_log_key_for_vote(&vote), vote);
}

fn seed_commit_votes_for_block(
    actor: &mut Actor,
    keypairs: &[KeyPair],
    block_hash: HashOf<BlockHeader>,
    height: u64,
    view_idx: u64,
    count: usize,
) -> usize {
    let (consensus_mode, _, _) = actor.consensus_context_for_height(height);
    let roster = super::roster::canonicalize_roster_for_mode(
        actor.effective_commit_topology(),
        consensus_mode,
    );
    seed_commit_votes_for_block_with_roster(
        actor, keypairs, block_hash, height, view_idx, &roster, count,
    )
}

fn seed_commit_votes_for_block_with_roster(
    actor: &mut Actor,
    keypairs: &[KeyPair],
    block_hash: HashOf<BlockHeader>,
    height: u64,
    view_idx: u64,
    roster: &[PeerId],
    count: usize,
) -> usize {
    let epoch = actor.epoch_for_height(height);
    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let roster = super::roster::canonicalize_roster_for_mode(roster.to_vec(), consensus_mode);
    let topology = super::network_topology::Topology::new(roster.clone());
    let signature_topology =
        super::topology_for_view(&topology, height, view_idx, mode_tag, prf_seed);
    let (chain_order_hash, rechain_seq) = actor.vnext_chain_order_binding_for_signature_topology(
        height,
        view_idx,
        consensus_mode,
        &signature_topology,
    );

    let mut seeded = 0usize;
    for peer in signature_topology
        .as_ref()
        .iter()
        .take(count.min(signature_topology.as_ref().len()))
    {
        let signer_idx = signature_topology
            .as_ref()
            .iter()
            .position(|candidate| candidate == peer)
            .expect("signer in topology");
        let signer = ValidatorIndex::try_from(signer_idx).expect("signer fits u32");
        let keypair = keypairs
            .iter()
            .find(|kp| kp.public_key() == peer.public_key())
            .expect("matching signer keypair");
        let mut vote = crate::sumeragi::consensus::Vote {
            phase: Phase::Commit,
            block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view: view_idx,
            epoch,
            chain_order_hash,
            rechain_seq,
            highest_qc: None,
            signer,
            bls_sig: Vec::new(),
        };
        bind_vote_to_signature_topology_chain_order(&mut vote, actor, &signature_topology);
        let preimage = super::vote_preimage(&actor.common_config.chain, mode_tag, &vote);
        let signature = checked_signature(keypair.private_key(), &preimage);
        vote.bls_sig = signature.payload().to_vec();
        insert_test_vote_with_roster(actor, vote, &roster);
        seeded = seeded.saturating_add(1);
    }

    seeded
}

