fn sample_bls_topology(count: usize) -> (Vec<KeyPair>, super::network_topology::Topology) {
    let keypairs: Vec<_> = (0..count).map(|_| checked_bls_keypair()).collect();
    let peers: Vec<_> = keypairs
        .iter()
        .map(|kp| PeerId::new(kp.public_key().clone()))
        .collect();
    let topology = super::network_topology::Topology::new(peers);
    (keypairs, topology)
}

fn canonical_validator_set_for_mode(
    topology: &super::network_topology::Topology,
    consensus_mode: ConsensusMode,
) -> Vec<PeerId> {
    super::roster::canonicalize_roster_for_mode(topology.as_ref().to_vec(), consensus_mode)
}

fn keypair_for_peer<'a>(keypairs: &'a [KeyPair], peer: &PeerId) -> &'a KeyPair {
    keypairs
        .iter()
        .find(|kp| kp.public_key() == peer.public_key())
        .expect("matching keypair for peer")
}

fn keypair_at_index<'a>(
    keypairs: &'a [KeyPair],
    topology: &super::network_topology::Topology,
    index: usize,
) -> &'a KeyPair {
    let peer = topology
        .as_ref()
        .get(index)
        .expect("peer index in topology");
    keypair_for_peer(keypairs, peer)
}

