#[test]
fn update_pending_mode_flip_sets_and_clears() {
    let mut pending = None;
    let first = update_pending_mode_flip(
        ConsensusMode::Permissioned,
        ConsensusMode::Npos,
        &mut pending,
    );
    assert_eq!(pending, Some(ConsensusMode::Npos));
    assert_eq!(first, Some(ConsensusMode::Npos));

    let repeat = update_pending_mode_flip(
        ConsensusMode::Permissioned,
        ConsensusMode::Npos,
        &mut pending,
    );
    assert!(repeat.is_none());
    assert_eq!(pending, Some(ConsensusMode::Npos));

    let cleared = update_pending_mode_flip(
        ConsensusMode::Permissioned,
        ConsensusMode::Permissioned,
        &mut pending,
    );
    assert!(cleared.is_none());
    assert!(pending.is_none());
}

#[test]
fn duration_ms_u64_clamps_large_values() {
    assert_eq!(super::duration_ms_u64(Duration::ZERO), 0);
    assert_eq!(super::duration_ms_u64(Duration::from_millis(1_500)), 1_500);
    assert_eq!(
        super::duration_ms_u64(Duration::from_millis(u64::MAX - 1)),
        u64::MAX - 1
    );
    assert_eq!(
        super::duration_ms_u64(Duration::from_millis(u64::MAX)),
        u64::MAX
    );
    assert_eq!(
        super::duration_ms_u64(Duration::from_secs(u64::MAX)),
        u64::MAX
    );
}

#[test]
fn staged_mode_info_maps_next_mode_tags() {
    use iroha_data_model::parameter::system::{SumeragiConsensusMode, SumeragiParameters};

    let params = SumeragiParameters {
        next_mode: None,
        mode_activation_height: None,
        ..SumeragiParameters::default()
    };
    assert_eq!(staged_mode_info(&params), (None, None));

    let params = SumeragiParameters {
        next_mode: Some(SumeragiConsensusMode::Permissioned),
        mode_activation_height: Some(10),
        ..SumeragiParameters::default()
    };
    assert_eq!(
        staged_mode_info(&params),
        (Some(super::consensus::PERMISSIONED_TAG), Some(10))
    );

    let params = SumeragiParameters {
        next_mode: Some(SumeragiConsensusMode::Npos),
        mode_activation_height: Some(42),
        ..SumeragiParameters::default()
    };
    assert_eq!(
        staged_mode_info(&params),
        (Some(super::consensus::NPOS_TAG), Some(42))
    );
}

#[test]
fn mode_activation_lag_tracks_activation_window() {
    assert_eq!(
        mode_activation_lag(
            5,
            None,
            ConsensusMode::Permissioned,
            ConsensusMode::Permissioned
        ),
        None
    );
    assert_eq!(
        mode_activation_lag(
            4,
            Some(5),
            ConsensusMode::Permissioned,
            ConsensusMode::Permissioned
        ),
        None
    );
    assert_eq!(
        mode_activation_lag(5, Some(5), ConsensusMode::Npos, ConsensusMode::Permissioned),
        Some(1)
    );
    assert_eq!(
        mode_activation_lag(7, Some(5), ConsensusMode::Npos, ConsensusMode::Permissioned),
        Some(3)
    );
    assert_eq!(
        mode_activation_lag(
            7,
            Some(5),
            ConsensusMode::Permissioned,
            ConsensusMode::Permissioned
        ),
        None
    );
}

#[tokio::test(flavor = "current_thread")]
async fn tick_mode_management_clears_pending_mode_flip() {
    let mut harness = test_actor_harness(1).await;
    harness.actor.pending_mode_flip = Some(ConsensusMode::Npos);

    let progressed = harness.actor.tick_mode_management();
    assert!(
        !progressed,
        "no mode flip should apply when effective mode matches"
    );
    assert!(
        harness.actor.pending_mode_flip.is_none(),
        "pending flip should clear when effective mode matches"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn apply_mode_flip_defers_while_commit_pipeline_active() {
    let mut harness = test_actor_harness(1).await;
    let actor = &mut harness.actor;

    actor.pending_mode_flip = Some(ConsensusMode::Npos);

    let committed_height = u64::try_from(actor.state.view().height()).unwrap_or(0);
    let height = committed_height.saturating_add(1).max(1);
    let view = actor.phase_tracker.current_view(height).unwrap_or(0);
    let parent = seed_genesis_block_for_state(actor.state.as_ref());
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(parent));
    let block_hash = block.hash();
    actor.pending.pending_processing.set(Some(block_hash));
    actor
        .pending
        .pending_processing_parent
        .set(block.header().prev_block_hash());

    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let pending = PendingBlock::new(block.clone(), payload_hash, height, view);
    let mut lock = sample_qc_ref(height, view);
    lock.phase = Phase::Commit;
    lock.subject_block_hash = block_hash;
    let commit_topology = actor.effective_commit_topology();
    actor.subsystems.commit.inflight = Some(CommitInFlight {
        id: 1,
        lock,
        block_hash,
        pending,
        commit_topology: commit_topology.clone(),
        signature_topology: commit_topology,
        qc_signers: None,
        commit_qc: None,
        post_commit_qc: None,
        enqueue_time: Instant::now(),
        timeout_reported: false,
    });

    actor
        .apply_mode_flip(ConsensusMode::Npos)
        .expect("mode flip defers while commit pipeline is active");

    assert_eq!(
        actor.consensus_mode,
        ConsensusMode::Permissioned,
        "consensus mode should not flip while commit pipeline is active"
    );
    assert_eq!(
        actor.pending_mode_flip,
        Some(ConsensusMode::Npos),
        "pending mode flip should remain queued"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn apply_mode_flip_uses_world_epoch_params() {
    use iroha_data_model::parameter::system::SumeragiNposParameters;

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.npos.epoch_length_blocks = 5;
    consensus_cfg.npos.vrf.commit_deadline_offset_blocks = 2;
    consensus_cfg.npos.vrf.reveal_deadline_offset_blocks = 3;

    let mut harness = test_actor_harness_with_config_and_height(4, consensus_cfg, None, 1).await;
    let actor = &mut harness.actor;

    {
        let state = std::sync::Arc::get_mut(&mut actor.state).expect("state uniquely held");
        let mut block = state.world.block();
        let params = block.parameters.get_mut();
        let npos_params = SumeragiNposParameters {
            epoch_length_blocks: 11,
            vrf_commit_window_blocks: 4,
            vrf_reveal_window_blocks: 5,
            ..SumeragiNposParameters::default()
        };
        params.custom.insert(
            SumeragiNposParameters::parameter_id(),
            npos_params.into_custom_parameter(),
        );
        block.commit();
    }

    actor
        .apply_mode_flip(ConsensusMode::Npos)
        .expect("mode flip should succeed");
    let manager = actor.epoch_manager.as_ref().expect("epoch manager set");
    assert_eq!(manager.epoch_length_blocks(), 11);
    assert_eq!(manager.commit_window_end(), 4);
    assert_eq!(manager.reveal_window_end(), 9);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn apply_mode_flip_aligns_epoch_to_current_height_without_vrf_record() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.npos.epoch_length_blocks = 5;
    consensus_cfg.npos.vrf.commit_deadline_offset_blocks = 2;
    consensus_cfg.npos.vrf.reveal_deadline_offset_blocks = 4;

    let height = 7u64;
    let mut harness = test_actor_harness_with_config_and_height(4, consensus_cfg, None, 1).await;
    let actor = &mut harness.actor;
    {
        let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
        for idx in 1..=height {
            let idx_byte = u8::try_from(idx).expect("height fits in u8 for test hash");
            let hash = HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed(
                [idx_byte; Hash::LENGTH],
            ));
            state.push_block_hash_for_testing(hash);
        }
    }

    actor
        .apply_mode_flip(ConsensusMode::Npos)
        .expect("mode flip should succeed");
    let manager = actor.epoch_manager.as_ref().expect("epoch manager set");
    let expected_epoch = (height - 1) / 5;
    assert_eq!(manager.epoch(), expected_epoch);
    let expected_seed = {
        let view = actor.state.view();
        super::npos_seed_for_height(&view, height)
    };
    assert_eq!(manager.seed(), expected_seed);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn apply_mode_flip_to_npos_restores_unfinalized_target_epoch_record() {
    use iroha_data_model::{
        consensus::{VrfEpochRecord, VrfLateRevealRecord, VrfParticipantRecord},
        parameter::system::SumeragiNposParameters,
    };

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.npos.epoch_length_blocks = 5;

    let height = 7u64;
    let mut harness =
        test_actor_harness_with_config_and_height(4, consensus_cfg, None, height).await;
    let actor = &mut harness.actor;

    let record_seed = [0x36; 32];
    let reveal = [0x37; 32];
    let commitment: [u8; 32] = Hash::new(reveal).into();
    {
        let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
        let mut block = state.world.block();
        let params = block.parameters.get_mut();
        let npos_params = SumeragiNposParameters {
            epoch_length_blocks: 5,
            vrf_commit_window_blocks: 2,
            vrf_reveal_window_blocks: 3,
            ..SumeragiNposParameters::default().with_epoch_seed([0x99; 32])
        };
        params.custom.insert(
            SumeragiNposParameters::parameter_id(),
            npos_params.into_custom_parameter(),
        );
        block.vrf_epochs.insert(
            1,
            VrfEpochRecord {
                epoch: 1,
                seed: record_seed,
                epoch_length: 5,
                commit_deadline_offset: 2,
                reveal_deadline_offset: 5,
                roster_len: 4,
                finalized: false,
                updated_at_height: height,
                participants: vec![
                    VrfParticipantRecord {
                        signer: 0,
                        commitment: Some(commitment),
                        reveal: Some(reveal),
                        last_updated_height: 6,
                    },
                    VrfParticipantRecord {
                        signer: 1,
                        commitment: Some([0x38; 32]),
                        reveal: None,
                        last_updated_height: 7,
                    },
                ],
                late_reveals: vec![VrfLateRevealRecord {
                    signer: 2,
                    reveal: [0x39; 32],
                    noted_at_height: 7,
                }],
                committed_no_reveal: Vec::new(),
                no_participation: Vec::new(),
                penalties_applied: false,
                penalties_applied_at_height: None,
                validator_election: None,
            },
        );
        block.commit();
    }

    actor
        .apply_mode_flip(ConsensusMode::Npos)
        .expect("mode flip should succeed");

    let manager = actor.epoch_manager.as_ref().expect("epoch manager set");
    assert_eq!(manager.epoch(), 1);
    assert_eq!(manager.seed(), record_seed);
    assert_eq!(manager.epoch_length_blocks(), 5);
    assert_eq!(manager.commit_window_end(), 2);
    assert_eq!(manager.reveal_window_end(), 5);
    let snapshot = manager.snapshot_current_epoch(0, height);
    assert_eq!(snapshot.commits, vec![(0, commitment), (1, [0x38; 32])]);
    assert_eq!(snapshot.reveals, vec![(0, reveal)]);
    assert_eq!(snapshot.late_reveals, vec![(2, [0x39; 32], 7)]);
    assert_eq!(snapshot.roster_len, 4);

    let collectors = actor.npos_collectors.expect("NPoS collectors set");
    assert_eq!(collectors.seed, record_seed);
    assert_eq!(actor.consensus_mode, ConsensusMode::Npos);

    harness.shutdown.send();
}

