#[tokio::test(flavor = "current_thread")]
async fn actor_next_tick_deadline_tracks_rbc_rebroadcast_cooldown() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.npos.timeouts_overrides.commit = Some(Duration::from_secs(1));

    let mut harness = test_actor_harness_with_config(2, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    {
        use iroha_data_model::parameter::system::{Parameter, SumeragiParameter};

        let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
        let mut block = state.world.block();
        let params = block.parameters.get_mut();
        params.set_parameter(Parameter::Sumeragi(SumeragiParameter::BlockTimeMs(1_000)));
        params.set_parameter(Parameter::Sumeragi(SumeragiParameter::CommitTimeMs(1_000)));
        block.commit();
    }

    let now = Instant::now();
    let committed_height = u64::try_from(actor.state.view().height()).unwrap_or(0);
    let height = committed_height.saturating_add(1);
    let tip_hash = actor.state.view().latest_block_hash();
    let block = sample_block(height, 0, tip_hash);
    let block_hash = block.hash();
    let key = (block_hash, height, 0);
    let payload_hash = Hash::prehashed([0x11; Hash::LENGTH]);
    let chunk_root = Hash::prehashed([0x22; Hash::LENGTH]);
    let mut session = RbcSession::test_new(1, Some(payload_hash), Some(chunk_root), 0);
    session.sent_ready = true;
    session.test_set_block_header_and_signature(&block);
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    actor
        .subsystems
        .da_rbc
        .rbc
        .payload_rebroadcast_last_sent
        .insert(key, now);
    actor.subsystems.da_rbc.rbc.chunk_repair.insert(
        key,
        super::RbcChunkRepairState {
            last_sent: now,
            received_chunks_snapshot: 0,
        },
    );

    let roster = vec![
        actor.common_config.peer.id().clone(),
        PeerId::new(harness.key_pairs[1].public_key().clone()),
    ];
    actor.record_rbc_session_roster(key, roster, RbcRosterSource::Derived);

    let payload_cooldown = actor.payload_rebroadcast_cooldown();
    let rbc_due = actor
        .rbc_next_due(now)
        .expect("rbc session should schedule a rebroadcast deadline");
    assert_eq!(rbc_due, now + payload_cooldown);

    let idle_due = actor.idle_view_next_due(now);
    let expected_deadline = idle_due.map_or(rbc_due, |deadline| deadline.min(rbc_due));
    let deadline = actor
        .next_tick_deadline(now)
        .expect("rbc session should schedule a rebroadcast deadline");
    assert_eq!(deadline, expected_deadline);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn actor_next_tick_deadline_wakes_ready_quorum_complete_rbc_before_deliver() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;

    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0_u64;
    let parent = actor.state.view().latest_block_hash();
    let block = sample_block(height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        actor.config.rbc.chunk_max_bytes,
        actor.epoch_for_height(height),
    )
    .expect("RBC session");
    session.test_set_block_header_and_signature(&block);
    session.sent_ready = true;

    let roster = super::roster::canonicalize_roster_for_mode(
        actor.effective_commit_topology(),
        ConsensusMode::Permissioned,
    );
    assert!(!roster.is_empty(), "test requires a commit roster");
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    let topology = super::network_topology::Topology::new(roster.clone());
    let required = actor.rbc_deliver_quorum(&topology);
    assert!(required > 0, "test requires a positive READY quorum");
    for sender in 0..required {
        let sender = u32::try_from(sender).expect("sender index fits u32");
        session.record_ready(sender, vec![sender as u8, 0xDA]);
    }
    assert!(
        !super::rbc_session_has_complete_delivery(&session),
        "test requires complete payload bytes before DELIVER is emitted"
    );
    actor.record_rbc_session_roster(key, roster.clone(), super::RbcRosterSource::Derived);
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);

    let now = Instant::now();
    assert_eq!(
        actor.rbc_next_due(now),
        Some(now),
        "ready-quorum complete RBC sessions should wake immediately to emit local DELIVER"
    );
    assert_eq!(
        actor.next_tick_deadline(now),
        Some(now),
        "ready-to-deliver RBC sessions should wake an otherwise idle actor"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn actor_next_tick_deadline_verifies_recovered_ready_quorum_before_deliver() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;

    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let parent = actor.state.view().latest_block_hash();
    let roster = super::roster::canonicalize_roster_for_mode(
        actor.effective_commit_topology(),
        ConsensusMode::Permissioned,
    );
    assert!(!roster.is_empty(), "test requires a commit roster");
    let topology = super::network_topology::Topology::new(roster.clone());
    let required = actor.rbc_deliver_quorum(&topology);
    assert!(required > 1, "test requires a non-trivial READY quorum");

    let now = Instant::now();
    let view = 0_u64;
    let block = sample_block(height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        actor.config.rbc.chunk_max_bytes,
        actor.epoch_for_height(height),
    )
    .expect("RBC session");
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    session.sent_ready = true;
    session.recovered_from_disk = true;
    assert!(
        session
            .expected_chunk_root
            .or_else(|| session.chunk_root())
            .is_some(),
        "complete recovered session should expose a chunk root"
    );
    for sender in 0..required {
        let sender = u32::try_from(sender).expect("sender index fits u32");
        assert!(session.record_ready(sender, vec![sender as u8, 0xDA]));
    }
    actor.record_rbc_session_roster(key, roster.clone(), super::RbcRosterSource::Derived);
    actor
        .subsystems
        .da_rbc
        .rbc
        .payload_rebroadcast_last_sent
        .insert(key, now);
    actor
        .subsystems
        .da_rbc
        .rbc
        .targeted_payload_rescue_last_sent
        .insert(key, now);
    actor
        .subsystems
        .da_rbc
        .rbc
        .ready_rebroadcast_last_sent
        .insert(key, now);
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);

    let forged_due = actor
        .rbc_next_due(now)
        .expect("forged recovered READY should still schedule cooldown-based repair");
    assert!(
        forged_due > now,
        "forged recovered READY quorum must not wake immediately for local DELIVER"
    );
    assert_ne!(
        actor.next_tick_deadline(now),
        Some(now),
        "forged recovered READY quorum must not hot-loop an otherwise idle actor"
    );

    let view = 1_u64;
    let block = sample_block(height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        actor.config.rbc.chunk_max_bytes,
        actor.epoch_for_height(height),
    )
    .expect("RBC session");
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    session.sent_ready = true;
    session.recovered_from_disk = true;
    let chunk_root = session
        .expected_chunk_root
        .or_else(|| session.chunk_root())
        .expect("complete recovered session should expose a chunk root");
    for ready_signature in signed_remote_rbc_ready_signatures_for_roster(
        actor,
        &harness.key_pairs,
        &roster,
        block.hash(),
        height,
        view,
        session.epoch,
        chunk_root,
        required,
    ) {
        assert!(session.record_ready(ready_signature.sender, ready_signature.signature,));
    }
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);

    assert_eq!(
        actor.rbc_next_due(now),
        Some(now),
        "verified recovered READY quorum should still wake immediately for local DELIVER"
    );
    assert_eq!(
        actor.next_tick_deadline(now),
        Some(now),
        "verified recovered READY quorum should wake an otherwise idle actor"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn actor_next_tick_deadline_rejects_bad_leader_signature_for_ready_rbc() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;

    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let parent = actor.state.view().latest_block_hash();
    let roster = super::roster::canonicalize_roster_for_mode(
        actor.effective_commit_topology(),
        ConsensusMode::Permissioned,
    );
    assert!(!roster.is_empty(), "test requires a commit roster");
    let topology = super::network_topology::Topology::new(roster.clone());
    let required = actor.rbc_deliver_quorum(&topology);
    assert!(required > 0, "test requires a positive READY quorum");

    for (view, label) in [
        (0_u64, "wrong leader index"),
        (1_u64, "wrong leader signature"),
    ] {
        let block = sample_block(height, view, parent);
        let key = Actor::session_key(&block.hash(), height, view);
        let payload = super::proposals::block_payload_bytes(&block);
        let payload_hash = Hash::new(&payload);
        let mut session = Actor::build_rbc_session_from_payload(
            &payload,
            payload_hash,
            actor.config.rbc.chunk_max_bytes,
            actor.epoch_for_height(height),
        )
        .expect("RBC session");
        bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
        session.sent_ready = true;
        for sender in 0..required {
            let sender = u32::try_from(sender).expect("sender index fits u32");
            session.record_ready(sender, vec![sender as u8, 0xBE]);
        }
        let valid_leader_signature = session
            .leader_signature
            .clone()
            .expect("test session must be leader-bound");
        session.leader_signature = Some(if view == 0 {
            BlockSignature::new(
                valid_leader_signature.index().saturating_add(1),
                valid_leader_signature.signature().clone(),
            )
        } else {
            forged_leader_signature_for_block(&valid_leader_signature, &block, Algorithm::BlsNormal)
        });

        actor.record_rbc_session_roster(key, roster.clone(), super::RbcRosterSource::Derived);
        actor.subsystems.da_rbc.rbc.sessions.insert(key, session);

        let now = Instant::now();
        assert!(
            actor.rbc_next_due(now).is_none(),
            "{label} must not wake the actor for local DELIVER"
        );
        assert!(
            actor.next_tick_deadline(now).is_none(),
            "{label} must not hot-loop an otherwise idle actor"
        );
    }

    harness.shutdown.send();
}

