#[tokio::test(flavor = "current_thread")]
async fn vote_inbound_drops_when_pending_validation_full() {
    let _guard = super::status::vote_validation_drops_test_guard();
    super::status::reset_vote_validation_drops_for_tests();

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.worker.validation_pending_cap = 1;
    let mut harness = test_actor_harness_with_config(2, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let vote_a = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash: HashOf::<BlockHeader>::from_untyped_unchecked(iroha_crypto::Hash::prehashed(
            [0xA1; iroha_crypto::Hash::LENGTH],
        )),
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height: 1,
        view: 0,
        epoch: 0,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: 0,
        bls_sig: Vec::new(),
    };
    let mut vote_b = vote_a.clone();
    vote_b.block_hash = HashOf::<BlockHeader>::from_untyped_unchecked(
        iroha_crypto::Hash::prehashed([0xB2; iroha_crypto::Hash::LENGTH]),
    );
    vote_b.signer = 1;

    actor.handle_vote_inbound(vote_a.clone());
    actor.handle_vote_inbound(vote_b.clone());

    let key_a = VoteVerifyKey::from_vote(&vote_a);
    let key_b = VoteVerifyKey::from_vote(&vote_b);
    assert!(
        actor
            .subsystems
            .vote_verify
            .pending_validation
            .contains_key(&key_a),
        "first vote should be enqueued for validation"
    );
    assert!(
        !actor
            .subsystems
            .vote_verify
            .pending_validation
            .contains_key(&key_b),
        "second vote should be dropped once pending-validation cap is hit"
    );

    let drops = super::status::snapshot().vote_validation_drops.entries;
    assert!(
        drops
            .iter()
            .any(|entry| { entry.reason == super::status::VoteValidationDropReason::Backpressure }),
        "backpressure drop should be recorded"
    );

    harness.shutdown.send();
    drop(harness);
}

#[tokio::test(flavor = "current_thread")]
async fn vote_inbound_fast_paths_active_new_view_when_pending_validation_full() {
    let _guard = super::status::vote_validation_drops_test_guard();
    super::status::reset_vote_validation_drops_for_tests();

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.worker.validation_pending_cap = 1;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(&actor.state);

    let filler_vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash: HashOf::<BlockHeader>::from_untyped_unchecked(iroha_crypto::Hash::prehashed(
            [0xC1; iroha_crypto::Hash::LENGTH],
        )),
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height: 2,
        view: 0,
        epoch: 0,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: 0,
        bls_sig: Vec::new(),
    };
    actor.handle_vote_inbound(filler_vote.clone());
    let filler_key = VoteVerifyKey::from_vote(&filler_vote);
    assert!(
        actor
            .subsystems
            .vote_verify
            .pending_validation
            .contains_key(&filler_key),
        "filler vote should occupy the only pending-validation slot"
    );

    let committed_height = actor.committed_height_snapshot();
    let committed_qc = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: genesis_hash,
        height: committed_height,
        view: 0,
        epoch: actor.epoch_for_height(committed_height),
    };
    let height = committed_height.saturating_add(1);
    let view = actor.phase_tracker.current_view(height).unwrap_or(0);
    let epoch = actor.epoch_for_height(height);
    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let topology = super::network_topology::Topology::new(
        actor.roster_for_live_vote_with_mode(height, consensus_mode),
    );
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let mut new_view_vote = crate::sumeragi::consensus::Vote {
        phase: Phase::NewView,
        block_hash: committed_qc.subject_block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: Some(committed_qc),
        signer: 1,
        bls_sig: Vec::new(),
    };
    bind_vote_to_signature_topology_chain_order(&mut new_view_vote, actor, &signature_topology);
    sign_vote_for_view_with_seed(
        &mut new_view_vote,
        &actor.common_config.chain,
        &topology,
        &harness.key_pairs,
        mode_tag,
        prf_seed,
    );

    actor.handle_vote_inbound(new_view_vote.clone());

    let new_view_key = VoteVerifyKey::from_vote(&new_view_vote);
    let vote_log_key = vote_log_key_for_vote(&new_view_vote);
    assert!(
        actor
            .subsystems
            .vote_verify
            .pending_validation
            .contains_key(&filler_key),
        "filler vote should remain queued while NEW_VIEW bypasses deferred validation"
    );
    assert!(
        !actor
            .subsystems
            .vote_verify
            .pending_validation
            .contains_key(&new_view_key),
        "active-frontier NEW_VIEW vote should not sit in pending validation"
    );
    assert!(
        !actor
            .subsystems
            .vote_verify
            .pending
            .contains_key(&new_view_key),
        "active-frontier NEW_VIEW vote should not be deferred to the verify backlog"
    );
    assert!(
        !actor
            .subsystems
            .vote_verify
            .inflight
            .contains_key(&new_view_key),
        "active-frontier NEW_VIEW vote should not wait for worker verification"
    );
    assert!(
        actor.vote_log.contains_key(&vote_log_key),
        "active-frontier NEW_VIEW vote should be recorded immediately"
    );

    let drops = super::status::snapshot().vote_validation_drops.entries;
    assert!(
        !drops.iter().any(|entry| {
            entry.reason == super::status::VoteValidationDropReason::Backpressure
                && entry.height == height
                && entry.view == view
                && entry.block_hash == new_view_vote.block_hash
        }),
        "fast-pathed NEW_VIEW vote must not be dropped due to pending-validation backpressure"
    );

    harness.shutdown.send();
    drop(harness);
}

#[tokio::test(flavor = "current_thread")]
async fn resilience_fast_paths_same_height_commit_votes_for_medium_rosters() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.resilience.enabled = true;
    let mut harness = test_actor_harness_with_config(12, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let view = actor.state.view();
    let committed_height = u64::try_from(view.height()).unwrap_or(u64::MAX);
    let parent = view.latest_block_hash();
    drop(view);

    let height = committed_height.saturating_add(1).max(1);
    let view_idx = 0_u64;
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, view_idx, parent);
    let block_hash = block.hash();
    actor
        .kura
        .store_block(block.clone())
        .expect("store known block");

    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let roster = actor.roster_for_vote_with_mode(block_hash, height, view_idx, consensus_mode);
    assert!(
        roster.len() > 8,
        "test must cover a roster larger than the conservative inline limit"
    );
    assert!(
        roster.len() <= 32,
        "test must stay within the resilience inline limit"
    );
    let topology = super::network_topology::Topology::new(roster);
    let epoch = actor.epoch_for_height(height);
    let (chain_order_hash, rechain_seq) = actor.vnext_chain_order_binding_for(height, view_idx);
    let mut vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view: view_idx,
        epoch,
        chain_order_hash,
        rechain_seq,
        highest_qc: None,
        signer: 0,
        bls_sig: Vec::new(),
    };
    sign_vote_for_view_with_seed(
        &mut vote,
        &actor.common_config.chain,
        &topology,
        &harness.key_pairs,
        mode_tag,
        prf_seed,
    );

    let (work_tx, work_rx) = mpsc::sync_channel(16);
    let (_result_tx, result_rx) = mpsc::sync_channel(16);
    actor.subsystems.vote_verify.work_txs = vec![work_tx];
    actor.subsystems.vote_verify.result_rx = Some(result_rx);

    actor.handle_vote_inbound(vote.clone());
    let verify_key = VoteVerifyKey::from_vote(&vote);
    assert!(
        actor
            .subsystems
            .vote_verify
            .pending_validation
            .contains_key(&verify_key),
        "inbound commit vote should first enter deferred validation"
    );

    assert!(
        actor.process_pending_vote_validation(),
        "deferred validation should make progress"
    );

    let vote_log_key = vote_log_key_for_vote(&vote);
    assert!(
        actor.vote_log.contains_key(&vote_log_key),
        "resilience mode should inline-verify same-height commit votes for medium rosters"
    );
    assert!(
        !actor
            .subsystems
            .vote_verify
            .pending_validation
            .contains_key(&verify_key)
    );
    assert!(
        !actor
            .subsystems
            .vote_verify
            .pending
            .contains_key(&verify_key)
    );
    assert!(
        !actor
            .subsystems
            .vote_verify
            .inflight
            .contains_key(&verify_key)
    );
    assert!(
        matches!(work_rx.try_recv(), Err(mpsc::TryRecvError::Empty)),
        "fast-pathed vote should not be dispatched to async verification"
    );

    harness.shutdown.send();
    drop(harness);
}

#[tokio::test(flavor = "current_thread")]
async fn vote_validation_drop_records_roster_hash_for_signature_rejection() {
    let _guard = super::status::vote_validation_drops_test_guard();
    super::status::reset_vote_validation_drops_for_tests();
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = u64::try_from(actor.state.view().height())
        .unwrap_or_default()
        .saturating_add(1)
        .max(1);
    let view = 0_u64;
    let epoch = actor.epoch_for_height(height);
    let roster = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(roster.clone());
    let local_idx = topology
        .as_ref()
        .iter()
        .position(|peer| peer == actor.common_config.peer.id())
        .expect("local peer should exist in commit topology");
    let vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash: HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed(
            [0xA4; Hash::LENGTH],
        )),
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: u32::try_from(local_idx).expect("signer index fits u32"),
        bls_sig: Vec::new(),
    };

    let chain_id = actor.common_config.chain.clone();
    let evidence_context = crate::sumeragi::EvidenceValidationContext {
        topology: &topology,
        chain_id: &chain_id,
        mode_tag: super::PERMISSIONED_TAG,
        prf_seed: Some(super::prf_seed_for_height(&actor.state.view(), height)),
    };

    let accepted = actor.validate_and_record_vote_with_signature_result(
        &vote,
        &topology,
        &evidence_context,
        super::PERMISSIONED_TAG,
        Some(Err(super::VoteSignatureError::SignatureInvalid)),
    );
    assert!(!accepted, "vote should be rejected on signature error");

    let drops = super::status::snapshot().vote_validation_drops.entries;
    let entry = drops.first().expect("vote drop entry");
    assert_eq!(entry.signer_index, vote.signer);
    assert_eq!(entry.block_hash, vote.block_hash);
    assert_eq!(entry.roster_hash, Some(HashOf::new(&roster)));
    assert_eq!(
        entry.roster_len,
        u32::try_from(roster.len()).unwrap_or(u32::MAX)
    );

    harness.shutdown.send();
    drop(harness);
}

