#[test]
fn block_sync_roster_cache_hits_and_evicts() {
    let roster = vec![
        PeerId::new(checked_keypair().public_key().clone()),
        PeerId::new(checked_keypair().public_key().clone()),
    ];
    let make_qc = |block_hash, height, view| Qc {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        parent_state_root: Hash::prehashed([0x11; Hash::LENGTH]),
        post_state_root: Hash::prehashed([0x22; Hash::LENGTH]),
        height,
        view,
        epoch: 0,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        mode_tag: PERMISSIONED_TAG.to_string(),
        highest_qc: None,
        validator_set_hash: HashOf::new(&roster),
        validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
        validator_set: roster.clone(),
        aggregate: QcAggregate {
            signers_bitmap: vec![0b0000_0011],
            bls_aggregate_signature: vec![0xAA],
        },
    };
    let hash1 =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x31; Hash::LENGTH]));
    let hash2 =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x32; Hash::LENGTH]));
    let hash3 =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x33; Hash::LENGTH]));
    let qc1 = make_qc(hash1, 1, 0);
    let qc2 = make_qc(hash2, 2, 0);
    let qc3 = make_qc(hash3, 3, 0);

    let key1 = super::BlockSyncRosterCacheKey::from_hints(
        hash1,
        1,
        0,
        ConsensusMode::Permissioned,
        Some(&qc1),
        None,
        None,
    )
    .expect("key from qc1");
    let key2 = super::BlockSyncRosterCacheKey::from_hints(
        hash2,
        2,
        0,
        ConsensusMode::Permissioned,
        Some(&qc2),
        None,
        None,
    )
    .expect("key from qc2");
    let key3 = super::BlockSyncRosterCacheKey::from_hints(
        hash3,
        3,
        0,
        ConsensusMode::Permissioned,
        Some(&qc3),
        None,
        None,
    )
    .expect("key from qc3");

    let selection1 = super::BlockSyncRosterSelection {
        roster: roster.clone(),
        source: super::BlockSyncRosterSource::QcHint,
        commit_qc: Some(qc1),
        checkpoint: None,
        stake_snapshot: None,
    };
    let selection2 = super::BlockSyncRosterSelection {
        roster: roster.clone(),
        source: super::BlockSyncRosterSource::QcHint,
        commit_qc: Some(qc2),
        checkpoint: None,
        stake_snapshot: None,
    };
    let selection3 = super::BlockSyncRosterSelection {
        roster,
        source: super::BlockSyncRosterSource::QcHint,
        commit_qc: Some(qc3),
        checkpoint: None,
        stake_snapshot: None,
    };

    let mut cache = super::BlockSyncRosterSelectionCache::new(2);
    cache.insert(key1.clone(), selection1.clone());
    cache.insert(key2.clone(), selection2.clone());
    assert_eq!(cache.get(&key1), Some(selection1.clone()));
    cache.insert(key3.clone(), selection3.clone());

    assert!(
        cache.get(&key2).is_none(),
        "least-recently used entry evicted"
    );
    assert_eq!(cache.get(&key1), Some(selection1));
    assert_eq!(cache.get(&key3), Some(selection3));
}

#[test]
fn block_sync_roster_cache_key_ignores_view_only_variance() {
    let roster = vec![
        PeerId::new(checked_keypair().public_key().clone()),
        PeerId::new(checked_keypair().public_key().clone()),
    ];
    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x3A; Hash::LENGTH]));
    let make_qc = |view| Qc {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        parent_state_root: Hash::prehashed([0x11; Hash::LENGTH]),
        post_state_root: Hash::prehashed([0x22; Hash::LENGTH]),
        height: 7,
        view,
        epoch: 0,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        mode_tag: PERMISSIONED_TAG.to_string(),
        highest_qc: None,
        validator_set_hash: HashOf::new(&roster),
        validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
        validator_set: roster.clone(),
        aggregate: QcAggregate {
            signers_bitmap: vec![0b0000_0011],
            bls_aggregate_signature: vec![0xAB],
        },
    };
    let qc_view_0 = make_qc(0);
    let qc_view_5 = make_qc(5);

    let key_view_0 = super::BlockSyncRosterCacheKey::from_hints(
        block_hash,
        7,
        0,
        ConsensusMode::Permissioned,
        Some(&qc_view_0),
        None,
        None,
    )
    .expect("key from view 0");
    let key_view_5 = super::BlockSyncRosterCacheKey::from_hints(
        block_hash,
        7,
        5,
        ConsensusMode::Permissioned,
        Some(&qc_view_5),
        None,
        None,
    )
    .expect("key from view 5");

    assert_eq!(
        key_view_0, key_view_5,
        "roster cache key should remain stable for view-only QC variance",
    );
}

#[tokio::test(flavor = "current_thread")]
async fn block_sync_update_accepts_uncertified_next_height_in_permissioned_mode() {
    use crate::sumeragi::status;

    status::reset_commit_certs_for_tests();
    status::reset_validator_checkpoints_for_tests();
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    // Seed the committed height; use a non-local hash so the NEW_VIEW QC is not dropped
    // for an empty known block.
    let _genesis_hash = seed_genesis_block_for_state(&actor.state);
    let (committed_height, committed_hash) = {
        let view = actor.state.view();
        (
            u64::try_from(view.height()).unwrap_or(u64::MAX),
            view.latest_block_hash(),
        )
    };
    let block_height = committed_height.saturating_add(1).max(1);
    let view_index = 0_u64;

    let roster = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(roster.clone());
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(block_height);
    let signature_topology =
        super::topology_for_view(&topology, block_height, view_index, mode_tag, prf_seed);
    let signer_peer = signature_topology
        .as_ref()
        .first()
        .expect("signer in topology");
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair exists in harness");
    let signer_idx = signature_topology
        .position(signer_kp.public_key())
        .expect("signer index in topology");
    let prev_hash = if block_height == 1 {
        None
    } else {
        committed_hash
    };
    let tx_params = actor
        .state
        .view()
        .world()
        .parameters()
        .transaction()
        .clone();
    let (time_handle, time_source) = TimeSource::new_mock(Duration::from_millis(1));
    let heartbeat_signer = deterministic_keypair(
        b"block-sync-next-height-permissioned-heartbeat",
        Algorithm::Ed25519,
    );
    let heartbeat = crate::tx::build_heartbeat_transaction_with_time_source(
        actor.common_config.chain.clone(),
        &heartbeat_signer,
        &tx_params,
        block_height,
        &time_source,
    );
    time_handle.advance(Duration::from_millis(1));
    let creation_time_ms =
        u64::try_from(time_source.get_unix_time().as_millis()).expect("creation time fits in u64");
    let header = BlockHeader::new(
        NonZeroU64::new(block_height).expect("block height"),
        prev_hash,
        None,
        None,
        creation_time_ms,
        view_index,
    );
    let mut builder = BlockBuilder::new(header);
    builder.push_transaction(heartbeat);
    let default_policies =
        crate::da::proof_policy_bundle(&iroha_config::parameters::actual::LaneConfig::default());
    builder.set_da_proof_policies(Some(default_policies));
    let block = builder.build_with_signature(
        u64::try_from(signer_idx).expect("signer index fits u64"),
        signer_kp.private_key(),
    );
    let update = super::message::BlockSyncUpdate::from(&block);
    let now = Instant::now();
    let retry_window = Duration::from_secs(1);
    actor.pending.missing_block_requests.insert(
        block.hash(),
        super::MissingBlockRequest {
            height: block_height,
            view: view_index,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window,
            view_change_window: Some(retry_window),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );

    actor
        .handle_block_sync_update(update, None)
        .expect("block sync update");

    assert!(
        actor.vote_roster_cache.contains_key(&block.hash()),
        "block sync roster should be cached for vote validation"
    );
    let pending = actor.pending.pending_blocks.get(&block.hash());
    assert!(pending.is_some(), "pending block should be inserted");
    assert!(
        pending.is_some_and(|pending| !pending.aborted),
        "pending block should not be marked aborted"
    );
    assert!(
        actor.block_known_locally(block.hash()),
        "block sync should accept next-height block without QC when explicitly requested"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn block_sync_update_accepts_catchup_when_local_removed_from_world() {
    use crate::sumeragi::status;

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let _local_removed_guard = super::status::local_removed_test_guard();
    let _message_handling_guard = super::status::message_handling_test_guard();
    super::status::reset_message_handling_for_tests();
    status::reset_commit_certs_for_tests();
    status::reset_validator_checkpoints_for_tests();

    let _genesis_hash = seed_genesis_block_for_state(&actor.state);
    let (committed_height, committed_hash) = {
        let view = actor.state.view();
        (
            u64::try_from(view.height()).unwrap_or(u64::MAX),
            view.latest_block_hash(),
        )
    };
    let block_height = committed_height.saturating_add(1).max(1);
    let view_index = 0_u64;

    let roster = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(roster.clone());
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(block_height);
    let signature_topology =
        super::topology_for_view(&topology, block_height, view_index, mode_tag, prf_seed);
    let signer_peer = signature_topology
        .as_ref()
        .first()
        .expect("signer in topology");
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair exists in harness");
    let signer_idx = signature_topology
        .position(signer_kp.public_key())
        .expect("signer index in topology");
    let prev_hash = if block_height == 1 {
        None
    } else {
        committed_hash
    };
    let tx_params = actor
        .state
        .view()
        .world()
        .parameters()
        .transaction()
        .clone();
    let (time_handle, time_source) = TimeSource::new_mock(Duration::from_millis(1));
    let heartbeat_signer = deterministic_keypair(
        b"block-sync-ignored-local-removed-heartbeat",
        Algorithm::Ed25519,
    );
    let heartbeat = crate::tx::build_heartbeat_transaction_with_time_source(
        actor.common_config.chain.clone(),
        &heartbeat_signer,
        &tx_params,
        block_height,
        &time_source,
    );
    time_handle.advance(Duration::from_millis(1));
    let creation_time_ms =
        u64::try_from(time_source.get_unix_time().as_millis()).expect("creation time fits in u64");
    let header = BlockHeader::new(
        NonZeroU64::new(block_height).expect("block height"),
        prev_hash,
        None,
        None,
        creation_time_ms,
        view_index,
    );
    let mut builder = BlockBuilder::new(header);
    builder.push_transaction(heartbeat);
    let default_policies =
        crate::da::proof_policy_bundle(&iroha_config::parameters::actual::LaneConfig::default());
    builder.set_da_proof_policies(Some(default_policies));
    let block = builder.build_with_signature(
        u64::try_from(signer_idx).expect("signer index fits u64"),
        signer_kp.private_key(),
    );
    let update = super::message::BlockSyncUpdate::from(&block);
    let now = Instant::now();
    let retry_window = Duration::from_secs(1);
    actor.pending.missing_block_requests.insert(
        block.hash(),
        super::MissingBlockRequest {
            height: block_height,
            view: view_index,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window,
            view_change_window: Some(retry_window),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );

    {
        let _removed = LocalRemovedGuard::new(true);
        actor
            .handle_block_sync_update(update, None)
            .expect("block sync update");
    }

    assert!(
        actor.vote_roster_cache.contains_key(&block.hash()),
        "block sync update should still cache vote roster when local removal only reflects stale world state"
    );
    assert!(
        actor.pending.pending_blocks.contains_key(&block.hash()),
        "block sync update should still insert pending block for catch-up after local removal"
    );
    assert!(
        actor
            .pending
            .pending_blocks
            .get(&block.hash())
            .is_some_and(|pending| !pending.aborted),
        "block sync update should not mark catch-up payload aborted after local removal"
    );
    assert!(
        actor.block_known_locally(block.hash()),
        "block sync update should still accept catch-up payload after local removal"
    );

    let entries = super::status::snapshot().consensus_message_handling.entries;
    assert!(
        !entries.iter().any(|entry| {
            entry.kind == super::status::ConsensusMessageKind::BlockSyncUpdate
                && entry.outcome == super::status::ConsensusMessageOutcome::Dropped
                && entry.reason == super::status::ConsensusMessageReason::ModeMismatch
        }),
        "block sync catch-up should not be dropped with mode mismatch after local removal"
    );

    super::status::reset_message_handling_for_tests();
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn block_sync_update_accepts_uncertified_missing_block_when_behind() {
    use crate::sumeragi::status;

    status::reset_commit_certs_for_tests();
    status::reset_validator_checkpoints_for_tests();
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let _genesis_hash = seed_genesis_block_for_state(&actor.state);
    let (committed_height, _committed_hash) = {
        let view = actor.state.view();
        (
            u64::try_from(view.height()).unwrap_or(u64::MAX),
            view.latest_block_hash(),
        )
    };
    let block_height = committed_height.saturating_add(2).max(2);
    let view_index = 0_u64;

    let roster = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(roster.clone());
    let signature_topology =
        super::topology_for_view(&topology, block_height, view_index, PERMISSIONED_TAG, None);
    let leader_peer = signature_topology
        .as_ref()
        .first()
        .expect("signer in topology");
    let leader_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == leader_peer.public_key())
        .expect("signer keypair exists in harness");
    let leader_idx = signature_topology
        .position(leader_kp.public_key())
        .expect("signer index in topology");
    let mut missing_parent =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x61; Hash::LENGTH]));
    if actor.block_known_locally(missing_parent) {
        missing_parent =
            HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x62; Hash::LENGTH]));
    }
    let tx_params = actor
        .state
        .view()
        .world()
        .parameters()
        .transaction()
        .clone();
    let (time_handle, time_source) = TimeSource::new_mock(Duration::from_millis(1));
    let heartbeat_signer = deterministic_keypair(
        b"block-sync-missing-when-behind-heartbeat",
        Algorithm::Ed25519,
    );
    let heartbeat = crate::tx::build_heartbeat_transaction_with_time_source(
        actor.common_config.chain.clone(),
        &heartbeat_signer,
        &tx_params,
        block_height,
        &time_source,
    );
    time_handle.advance(Duration::from_millis(1));
    let creation_time_ms =
        u64::try_from(time_source.get_unix_time().as_millis()).expect("creation time fits in u64");
    let header = BlockHeader::new(
        NonZeroU64::new(block_height).expect("block height"),
        Some(missing_parent),
        None,
        None,
        creation_time_ms,
        view_index,
    );
    let mut builder = BlockBuilder::new(header);
    builder.push_transaction(heartbeat);
    let default_policies =
        crate::da::proof_policy_bundle(&iroha_config::parameters::actual::LaneConfig::default());
    builder.set_da_proof_policies(Some(default_policies));
    let mut block = builder.build_with_signature(
        u64::try_from(leader_idx).expect("signer index fits u64"),
        leader_kp.private_key(),
    );
    let required = signature_topology.min_votes_for_commit().max(1);
    for (idx, peer) in signature_topology
        .as_ref()
        .iter()
        .enumerate()
        .take(required)
    {
        if idx == leader_idx {
            continue;
        }
        let kp = harness
            .key_pairs
            .iter()
            .find(|kp| kp.public_key() == peer.public_key())
            .expect("signer keypair exists in harness");
        let sig = checked_signature_of_hash(kp.private_key(), block.header().hash());
        block
            .add_signature(BlockSignature::new(
                u64::try_from(idx).expect("signer index fits u64"),
                sig,
            ))
            .expect("signature added");
    }

    let update = super::message::BlockSyncUpdate::from(&block);
    let now = Instant::now();
    let retry_window = Duration::from_secs(1);
    actor.pending.missing_block_requests.insert(
        block.hash(),
        super::MissingBlockRequest {
            height: block_height,
            view: view_index,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window,
            view_change_window: Some(retry_window),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );

    actor
        .handle_block_sync_update(update, None)
        .expect("block sync update");

    assert!(
        actor.vote_roster_cache.contains_key(&block.hash()),
        "block sync roster should be cached for vote validation"
    );
    let pending = actor.pending.pending_blocks.get(&block.hash());
    assert!(pending.is_some(), "pending block should be inserted");
    assert!(
        pending.is_some_and(|pending| !pending.aborted),
        "pending block should not be marked aborted"
    );
    assert!(
        actor.block_known_locally(block.hash()),
        "block sync should accept missing-block payloads with quorum signatures when behind"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn block_sync_update_accepts_uncertified_missing_block_in_npos() {
    use crate::sumeragi::status;

    status::reset_commit_certs_for_tests();
    status::reset_validator_checkpoints_for_tests();
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Npos;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let _genesis_hash = seed_genesis_block_for_state(&actor.state);
    let (committed_height, _committed_hash) = {
        let view = actor.state.view();
        (
            u64::try_from(view.height()).unwrap_or(u64::MAX),
            view.latest_block_hash(),
        )
    };
    let block_height = committed_height.saturating_add(2).max(2);
    let view_index = 0_u64;

    let roster = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(roster.clone());
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(block_height);
    let signature_topology =
        super::topology_for_view(&topology, block_height, view_index, mode_tag, prf_seed);
    let leader_peer = signature_topology
        .as_ref()
        .first()
        .expect("signer in topology");
    let leader_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == leader_peer.public_key())
        .expect("signer keypair exists in harness");
    let leader_idx = signature_topology
        .position(leader_kp.public_key())
        .expect("signer index in topology");
    let mut missing_parent =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x61; Hash::LENGTH]));
    if actor.block_known_locally(missing_parent) {
        missing_parent =
            HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x62; Hash::LENGTH]));
    }
    let mut block = heartbeat_block_for_state(
        actor.state.as_ref(),
        &actor.common_config.chain,
        block_height,
        view_index,
        Some(missing_parent),
        leader_kp,
        u64::try_from(leader_idx).expect("signer index fits u64"),
    );
    let required = signature_topology.min_votes_for_commit().max(1);
    for (idx, peer) in signature_topology
        .as_ref()
        .iter()
        .enumerate()
        .take(required)
    {
        if idx == leader_idx {
            continue;
        }
        let kp = harness
            .key_pairs
            .iter()
            .find(|kp| kp.public_key() == peer.public_key())
            .expect("signer keypair exists in harness");
        let sig = checked_signature_of_hash(kp.private_key(), block.header().hash());
        block
            .add_signature(BlockSignature::new(
                u64::try_from(idx).expect("signer index fits u64"),
                sig,
            ))
            .expect("signature added");
    }

    let update = super::message::BlockSyncUpdate::from(&block);
    let now = Instant::now();
    let retry_window = Duration::from_secs(1);
    actor.pending.missing_block_requests.insert(
        block.hash(),
        super::MissingBlockRequest {
            height: block_height,
            view: view_index,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window,
            view_change_window: Some(retry_window),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );

    actor
        .handle_block_sync_update(update, None)
        .expect("block sync update");

    assert!(
        actor.vote_roster_cache.contains_key(&block.hash()),
        "block sync roster should be cached for vote validation"
    );
    let pending = actor.pending.pending_blocks.get(&block.hash());
    assert!(pending.is_some(), "pending block should be inserted");
    assert!(
        pending.is_some_and(|pending| !pending.aborted),
        "pending block should not be marked aborted"
    );
    assert!(
        actor.block_known_locally(block.hash()),
        "block sync should accept missing-block payloads under NPOS when requested"
    );

    harness.shutdown.send();
}

