#[test]
fn rbc_delivered_payload_bytes_reports_verified_complete_payload_size() {
    let payload = vec![1_u8, 2, 3, 4, 5, 6];
    let layout = RbcPayloadLayout::new(RbcEncoding::Plain, 4, payload.len() as u64, 0, 0)
        .expect("plain RBC payload layout");
    let total_chunks = layout.total_chunks().expect("known total chunks") as u32;
    let mut session = RbcSession::new_with_layout(
        layout,
        total_chunks,
        Some(Hash::new(&payload)),
        None,
        None,
        0,
    )
    .expect("RBC session");

    session.ingest_chunk(0, payload[..4].to_vec(), None);
    session.ingest_chunk(1, payload[4..].to_vec(), None);
    assert_eq!(session.delivered_payload_bytes(), None);

    assert!(session.record_deliver(0, vec![0xAA]));
    let expected = u64::try_from(payload.len()).expect("payload length fits u64");
    assert_eq!(session.delivered_payload_bytes(), Some(expected));
    assert_eq!(
        session.take_delivered_payload_bytes_for_telemetry(),
        Some(expected)
    );
    assert_eq!(session.take_delivered_payload_bytes_for_telemetry(), None);
}

#[tokio::test(flavor = "current_thread")]
async fn flush_pending_rbc_if_roster_ready_replays_stashed_ready_and_deliver_with_cached_roster() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Npos;
    consensus_cfg.da.enabled = true;
    consensus_cfg.npos.epoch_length_blocks = 100;
    consensus_cfg.rbc.chunk_max_bytes = 1_000_000;

    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let committed_height = u64::try_from(actor.state.view().height()).unwrap_or(u64::MAX);
    let height = committed_height.saturating_add(1).max(1);
    let view = 0_u64;
    let parent = actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, view, parent);
    let block_hash = block.hash();
    let key = (block_hash, height, view);
    let roster = actor.effective_commit_topology();
    assert!(roster.len() >= 4, "test requires four validators");
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload_bytes,
        payload_hash,
        actor.config.rbc.chunk_max_bytes,
        actor.epoch_for_height(height),
    )
    .expect("session");
    assert_eq!(session.total_chunks(), 1, "test expects a single RBC chunk");
    let chunk_root = session.expected_chunk_root.expect("chunk root");
    session.ingest_chunk(0, payload_bytes, None);
    session.test_set_block_header_and_signature(&block);
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    actor.record_rbc_session_roster(key, roster.clone(), super::RbcRosterSource::Derived);

    let topology = super::network_topology::Topology::new(roster.clone());
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let local_peer = actor.common_config.peer.id().clone();
    let required = actor.rbc_deliver_quorum(&topology).max(1);
    let mut ready_signatures = Vec::new();
    let mut stashed_ready = None;
    let mut deliver_signer = None;
    for peer in signature_topology
        .as_ref()
        .iter()
        .filter(|peer| *peer != &local_peer)
        .take(required)
    {
        let signer_idx = signature_sender_index(actor, &roster, height, view, peer);
        let signer_kp = harness
            .key_pairs
            .iter()
            .find(|kp| kp.public_key() == peer.public_key())
            .expect("signer keypair");
        let mut ready = crate::sumeragi::consensus::RbcReady {
            block_hash,
            height,
            view,
            epoch: actor.epoch_for_height(height),
            roster_hash: roster_hash(&roster),
            chunk_root,
            sender: u32::try_from(signer_idx).expect("signer index fits u32"),
            signature: Vec::new(),
        };
        let preimage = super::rbc_ready_preimage(&actor.common_config.chain, mode_tag, &ready);
        let signature = checked_signature(signer_kp.private_key(), &preimage);
        ready.signature = signature.payload().to_vec();
        if stashed_ready.is_none() {
            stashed_ready = Some(ready.clone());
            deliver_signer = Some((peer.clone(), signer_idx));
        }
        ready_signatures.push(crate::sumeragi::consensus::RbcReadySignature {
            sender: ready.sender,
            signature: ready.signature.clone(),
        });
    }
    let (deliver_peer, deliver_idx) = deliver_signer.expect("deliver signer");
    let deliver_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == deliver_peer.public_key())
        .expect("deliver keypair");
    let mut deliver = crate::sumeragi::consensus::RbcDeliver {
        block_hash,
        height,
        view,
        epoch: actor.epoch_for_height(height),
        roster_hash: roster_hash(&roster),
        chunk_root,
        sender: u32::try_from(deliver_idx).expect("deliver signer index fits u32"),
        signature: Vec::new(),
        ready_signatures,
    };
    let deliver_preimage =
        super::rbc_deliver_preimage(&actor.common_config.chain, mode_tag, &deliver);
    let deliver_signature = checked_signature(deliver_kp.private_key(), &deliver_preimage);
    deliver.signature = deliver_signature.payload().to_vec();

    let stashed_ready = stashed_ready.expect("stashed ready");
    let ready_dedup_key = crate::sumeragi::BlockPayloadDedupKey::RbcReady {
        height: stashed_ready.height,
        view: stashed_ready.view,
        block_hash: stashed_ready.block_hash,
        sender: stashed_ready.sender,
        signature_hash: Hash::new(&stashed_ready.signature),
    };
    let deliver_dedup_key = crate::sumeragi::BlockPayloadDedupKey::RbcDeliver {
        height: deliver.height,
        view: deliver.view,
        block_hash: deliver.block_hash,
        sender: deliver.sender,
        signature_hash: Hash::new(&deliver.signature),
    };
    {
        let mut guard = actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned");
        guard.insert(ready_dedup_key, Instant::now());
        guard.insert(deliver_dedup_key, Instant::now());
    }
    let pending = actor.pending_rbc_slot(key).expect("pending slot");
    let (ready_inserted, _) =
        pending.push_ready_capped(stashed_ready.clone(), usize::MAX, Instant::now());
    assert!(ready_inserted, "test setup should stash a READY frame");
    let (deliver_inserted, _) =
        pending.push_deliver_capped(deliver.clone(), usize::MAX, Instant::now());
    assert!(deliver_inserted, "test setup should stash a DELIVER frame");

    assert!(
        actor.flush_pending_rbc_if_roster_ready(key),
        "cached authoritative roster should replay stashed READY/DELIVER immediately"
    );
    assert!(
        !actor.subsystems.da_rbc.rbc.pending.contains_key(&key),
        "successful replay should clear the pending stash"
    );
    let stored = actor.subsystems.da_rbc.rbc.sessions.get(&key);
    let retained = actor.subsystems.da_rbc.rbc.status_handle.get(&key);
    assert!(
        stored.is_some_and(|session| {
            session
                .ready_signatures
                .iter()
                .any(|entry| entry.sender == stashed_ready.sender)
        }) || retained
            .as_ref()
            .is_some_and(|summary| summary.delivered && !summary.invalid),
        "flush should either replay the stashed READY live or retain a delivered summary after recovery"
    );
    assert!(
        stored.is_some_and(|session| session.delivered)
            || retained
                .as_ref()
                .is_some_and(|summary| summary.delivered && !summary.invalid),
        "flush should replay the stashed DELIVER message"
    );
    assert!(
        stored.is_some_and(|session| session.deliver_signature == Some(deliver.signature.clone()))
            || retained
                .as_ref()
                .is_some_and(|summary| summary.delivered && !summary.invalid),
        "flush should retain the replayed DELIVER outcome"
    );
    assert_block_payload_dedup_keys_absent(
        actor,
        &[ready_dedup_key, deliver_dedup_key],
        "successful pending RBC READY/DELIVER replay should release ingress dedup",
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn block_sync_update_defers_signature_mismatch_when_parent_missing() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let state_height = actor.state.view().height() as u64;
    let block_height = state_height.saturating_add(2);
    let mut missing_parent =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x61; Hash::LENGTH]));
    if actor.block_known_locally(missing_parent) {
        missing_parent =
            HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x62; Hash::LENGTH]));
    }
    let roster = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(roster.clone());
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(block_height);
    let signature_topology =
        super::topology_for_view(&topology, block_height, 0, mode_tag, prf_seed);
    let signer_kp = harness
        .key_pairs
        .first()
        .expect("test harness requires at least one signer key");
    let signer_idx = signature_topology
        .position(signer_kp.public_key())
        .expect("signer index in topology");
    let mismatched_idx = (signer_idx + 1) % roster.len();
    let block = heartbeat_block_for_state(
        actor.state.as_ref(),
        &actor.common_config.chain,
        block_height,
        0,
        Some(missing_parent),
        signer_kp,
        u64::try_from(mismatched_idx).expect("signer index fits u64"),
    );
    let block_hash = block.hash();
    let now = Instant::now();
    let retry_window = Duration::from_secs(1);
    actor.pending.missing_block_requests.insert(
        block_hash,
        super::MissingBlockRequest {
            height: block_height,
            view: 0,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window,
            view_change_window: Some(retry_window),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );

    let update = super::message::BlockSyncUpdate::from(&block);
    actor
        .handle_block_sync_update(update, None)
        .expect("block sync update");

    assert!(
        actor.pending.pending_blocks.contains_key(&block_hash),
        "block sync update should retain payload while parent is missing"
    );
    assert!(
        actor
            .pending
            .missing_block_requests
            .contains_key(&missing_parent),
        "signature mismatch should still trigger a missing-parent request"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn block_sync_update_defers_while_commit_inflight_and_replays() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let view = actor.state.view();
    let committed_height = u64::try_from(view.height()).unwrap_or(u64::MAX);
    let parent = view.latest_block_hash();
    drop(view);

    let height = committed_height.saturating_add(1).max(1);
    let view_idx = 0_u64;
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, view_idx, parent);
    let block_hash = block.hash();

    let roster = actor.effective_commit_topology();
    assert!(!roster.is_empty(), "test requires commit roster");
    let topology = super::network_topology::Topology::new(roster.clone());
    let epoch = actor.epoch_for_height(height);
    let (chain_order_hash, rechain_seq) = actor.vnext_chain_order_binding_for(height, view_idx);
    let mut vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view: view_idx,
        epoch,
        chain_order_hash,
        rechain_seq,
        highest_qc: None,
        signer: 0,
        bls_sig: Vec::new(),
    };
    let chain = actor.common_config.chain.clone();
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    sign_vote_for_view_with_seed(
        &mut vote,
        &chain,
        &topology,
        &harness.key_pairs,
        mode_tag,
        prf_seed,
    );
    let mut update = super::message::BlockSyncUpdate::from(&block);
    update.commit_votes = vec![vote.clone()];

    let now = Instant::now();
    let retry_window = Duration::from_secs(1);
    actor.pending.missing_block_requests.insert(
        block_hash,
        super::MissingBlockRequest {
            height,
            view: view_idx,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window,
            view_change_window: Some(retry_window),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );

    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let pending = PendingBlock::new(block.clone(), payload_hash, height, view_idx);
    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height,
        view: view_idx,
        epoch,
    };
    let inflight = CommitInFlight {
        id: 1,
        lock,
        block_hash,
        pending,
        commit_topology: roster.clone(),
        signature_topology: roster,
        qc_signers: None,
        commit_qc: None,
        post_commit_qc: None,
        enqueue_time: Instant::now(),
        timeout_reported: false,
    };
    actor.subsystems.commit.inflight = Some(inflight);

    actor
        .handle_block_sync_update(update, None)
        .expect("block sync update");

    let vote_key = vote_log_key_for_vote(&vote);
    assert!(
        actor.vote_log.contains_key(&vote_key),
        "commit vote should be processed even when block sync update is deferred"
    );
    assert!(
        actor
            .deferred_block_sync_updates
            .contains_key(&(height, view_idx, block_hash)),
        "block sync update should be deferred while commit pipeline is inflight"
    );
    assert!(
        actor.pending.pending_blocks.get(&block_hash).is_none(),
        "deferred block sync update should not insert a pending block"
    );

    actor.subsystems.commit.inflight = None;
    let progressed = actor.tick();
    assert!(progressed, "tick should replay deferred block sync updates");
    assert!(
        !actor
            .deferred_block_sync_updates
            .contains_key(&(height, view_idx, block_hash)),
        "deferred block sync update should be replayed"
    );

    harness.shutdown.send();
}

