#[tokio::test(flavor = "current_thread")]
async fn fetch_block_body_releases_dedup_after_miss_for_same_requester_retry() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);

    let block = nonempty_block_for_actor(actor, &harness.key_pairs, 2, 0, None);
    let block_hash = block.hash();
    let height = block.header().height().get();
    let view = block.header().view_change_index();

    let requester = actor
        .effective_commit_topology()
        .into_iter()
        .find(|peer| peer != actor.common_config.peer.id())
        .expect("remote requester");
    let dedup_key = crate::sumeragi::BlockPayloadDedupKey::FetchBlockBody {
        height,
        view,
        block_hash,
        requester_hash: Hash::new(requester.encode()),
    };

    {
        let mut guard = actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned");
        guard.insert(dedup_key, Instant::now());
    }

    let _ = take_background_log(&background_log);
    actor
        .handle_fetch_block_body(super::message::FetchBlockBody {
            requester: requester.clone(),
            block_hash,
            height,
            view,
        })
        .expect("initial miss handled");
    assert!(
        !actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned")
            .contains(&dedup_key),
        "missed exact FetchBlockBody must release ingress dedup so the same requester can retry"
    );
    assert!(
        take_background_log(&background_log)
            .into_iter()
            .all(|entry| entry.msg_kind != Some("BlockBodyResponse")),
        "missing local payload should not answer the first exact-body fetch"
    );

    store_block_with_test_ancestors(actor.kura.as_ref(), block);
    {
        let mut guard = actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned");
        guard.insert(dedup_key, Instant::now());
    }

    actor
        .handle_fetch_block_body(super::message::FetchBlockBody {
            requester: requester.clone(),
            block_hash,
            height,
            view,
        })
        .expect("retry handled");
    assert!(
        !actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned")
            .contains(&dedup_key),
        "served exact FetchBlockBody should also release ingress dedup after responding"
    );
    assert!(
        take_background_log(&background_log)
            .into_iter()
            .any(|entry| {
                matches!(
                    entry,
                    super::BackgroundRequestLogEntry {
                        kind: super::BackgroundRequestLogKind::Post,
                        msg_kind: Some("BlockBodyResponse"),
                        peer: Some(peer),
                    } if peer == requester
                )
            }),
        "same-requester retry should receive BlockBodyResponse once the payload is locally available"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn fetch_block_body_stashes_missing_next_body_and_flushes_when_payload_arrives() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);

    let parent_hash = seed_genesis_block_for_state(actor.state.as_ref());
    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0u64;
    let block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(parent_hash));
    let block_hash = block.hash();

    let requester = actor
        .effective_commit_topology()
        .into_iter()
        .find(|peer| peer != actor.common_config.peer.id())
        .expect("remote requester");

    let _ = take_background_log(&background_log);
    actor
        .handle_fetch_block_body(super::message::FetchBlockBody {
            requester: requester.clone(),
            block_hash,
            height,
            view,
        })
        .expect("initial exact-body request");

    assert!(
        actor
            .pending
            .pending_block_body_requests
            .get(&block_hash)
            .is_some_and(|requesters| requesters.contains(&requester)),
        "next-height exact body fetch should be retained until the local payload arrives"
    );
    assert!(
        take_background_log(&background_log)
            .into_iter()
            .all(|entry| entry.msg_kind != Some("BlockBodyResponse")),
        "missing local payload should not answer the exact-body fetch"
    );

    assert_eq!(insert_validated_pending(actor, block.clone()), block_hash);
    assert!(
        actor.flush_pending_block_body_requests_if_ready(&block),
        "stashed exact body requester should flush once the payload is locally retained"
    );
    assert!(
        !actor
            .pending
            .pending_block_body_requests
            .contains_key(&block_hash),
        "flushing exact body requesters should retire the pending requester set"
    );

    let entries = take_background_log(&background_log);
    assert!(
        entries.iter().any(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("BlockBodyResponse"),
                    peer: Some(peer),
                } if peer == &requester
            )
        }),
        "stashed exact body requester should receive BlockBodyResponse after payload arrival"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn fetch_block_body_response_for_committed_block_preserves_commit_sidecars() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(actor.state.as_ref());
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, 2, 0, Some(genesis_hash));
    let block_hash = block.hash();
    actor.kura.store_block(block.clone()).expect("store block");

    let tip_block = sample_block(3, 0, Some(block_hash));
    actor
        .kura
        .store_block(tip_block.clone())
        .expect("store tip block");

    {
        let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
        state.push_block_hash_for_testing(block_hash);
        state.push_block_hash_for_testing(tip_block.hash());
    }

    let roster = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(roster.clone());
    let signers: BTreeSet<ValidatorIndex> = (0..roster.len())
        .map(|idx| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_bitmap = super::build_signers_bitmap(&signers, roster.len());
    let epoch = actor.epoch_for_height(2);
    let qc = qc_with_bitmap(
        &actor.common_config.chain,
        block_hash,
        2,
        0,
        epoch,
        signers_bitmap.clone(),
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    let checkpoint_signature = aggregate_vote_signature_for_bitmap(
        &actor.common_config.chain,
        PERMISSIONED_TAG,
        block_hash,
        2,
        0,
        epoch,
        &signers_bitmap,
        &topology,
        &harness.key_pairs,
    );
    let checkpoint = ValidatorSetCheckpoint::new(
        2,
        0,
        block_hash,
        qc.parent_state_root,
        qc.post_state_root,
        roster,
        signers_bitmap,
        checkpoint_signature,
        VALIDATOR_SET_HASH_VERSION_V1,
        None,
    );
    {
        let mut journal = actor.state.commit_roster_journal.write();
        journal.upsert(qc.clone(), checkpoint.clone(), None);
    }

    let response = actor.block_body_response_for_wire(&block);
    match response.body {
        super::message::BlockBodyData::BlockSyncUpdate(update) => {
            assert_eq!(update.block.hash(), block_hash);
            assert_eq!(update.validator_checkpoint, Some(checkpoint));
            assert!(
                update.commit_qc.is_some() || update.validator_checkpoint.is_some(),
                "committed exact body response should preserve authoritative roster sidecars"
            );
            if let Some(commit_qc) = update.commit_qc.as_ref() {
                assert_eq!(commit_qc.subject_block_hash, qc.subject_block_hash);
                assert_eq!(commit_qc.height, qc.height);
            }
        }
        super::message::BlockBodyData::BlockCreated(_) => {
            panic!("committed exact body response should preserve block-sync sidecars")
        }
    }

    harness.shutdown.send();
}

