#[tokio::test(flavor = "current_thread")]
async fn quorum_reschedule_rebroadcasts_block_created_while_skipping_block_sync_without_roster_proof()
 {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);
    let _ = take_background_log(&background_log);

    let block = nonempty_block_for_actor(actor, &harness.key_pairs, 1, 0, None);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let height = block.header().height().get();
    let view = block.header().view_change_index();
    let epoch = actor.epoch_for_height(height);
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let local_idx = actor
        .local_validator_index_for_topology(&topology)
        .expect("local validator index");
    let vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: local_idx,
        bls_sig: Vec::new(),
    };
    actor.vote_log.insert(
        default_vote_log_key(Phase::Commit, height, view, epoch, local_idx),
        vote,
    );

    let pending = PendingBlock::new(block, payload_hash, height, view);
    let now = Instant::now();

    actor.reschedule_pending_quorum_block(
        pending,
        Duration::from_secs(5),
        Duration::from_secs(5),
        /*min_votes_for_commit*/ 3,
        /*vote_count*/ 3,
        /*quorum_timeout*/ Duration::from_secs(1),
        /*reschedule_backoff*/ Duration::from_secs(1),
        None,
        now,
    );

    let _ = harness.background_rx.try_iter().count();
    let entries_first = take_background_log(&background_log);
    let sync_updates_first = entries_first
        .iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("BlockSyncUpdate"),
                    ..
                }
            )
        })
        .count();
    let block_created_first = entries_first
        .iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("BlockCreated"),
                    ..
                }
            )
        })
        .count();
    assert_eq!(
        sync_updates_first, 0,
        "first reschedule should skip unverifiable block-sync update when roster proof is unavailable"
    );
    assert!(
        block_created_first > 0,
        "first reschedule should still retransmit BlockCreated to help peers recover the known frontier block"
    );

    let pending = actor
        .pending
        .pending_blocks
        .remove(&block_hash)
        .expect("pending block retained");
    actor.reschedule_pending_quorum_block(
        pending,
        Duration::from_secs(5),
        Duration::from_secs(5),
        /*min_votes_for_commit*/ 3,
        /*vote_count*/ 3,
        /*quorum_timeout*/ Duration::from_secs(1),
        /*reschedule_backoff*/ Duration::from_secs(1),
        None,
        now,
    );

    let _ = harness.background_rx.try_iter().count();
    let entries_second = take_background_log(&background_log);
    let sync_updates_second = entries_second
        .iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("BlockSyncUpdate"),
                    ..
                }
            )
        })
        .count();
    let block_created_second = entries_second
        .iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("BlockCreated"),
                    ..
                }
            )
        })
        .count();
    assert_eq!(
        sync_updates_second, 0,
        "duplicate reschedule should skip redundant block sync updates"
    );
    assert_eq!(
        block_created_second, 0,
        "duplicate reschedule should respect the payload rebroadcast cooldown"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn quorum_reschedule_requests_known_block_commit_qc_recovery() {
    let _guard = super::status::missing_block_fetch_test_guard();
    super::status::reset_missing_block_fetch_counters_for_tests();

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);
    let _ = take_background_log(&background_log);

    let block = nonempty_block_for_actor(actor, &harness.key_pairs, 1, 0, None);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let height = block.header().height().get();
    let view = block.header().view_change_index();
    let epoch = actor.epoch_for_height(height);
    let topology_peers = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(topology_peers.clone());
    let min_votes_for_commit = topology.min_votes_for_commit().max(1);
    let local_idx = actor
        .local_validator_index_for_topology(&topology)
        .expect("local validator index");
    actor.vote_log.insert(
        default_vote_log_key(Phase::Commit, height, view, epoch, local_idx),
        crate::sumeragi::consensus::Vote {
            phase: Phase::Commit,
            block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: None,
            signer: local_idx,
            bls_sig: Vec::new(),
        },
    );

    let pending = PendingBlock::new(block, payload_hash, height, view);
    let before = super::status::snapshot();
    assert!(
        actor.reschedule_pending_quorum_block(
            pending,
            Duration::from_secs(5),
            Duration::from_secs(5),
            min_votes_for_commit,
            /*vote_count*/ 1,
            Duration::from_secs(1),
            Duration::from_secs(1),
            None,
            Instant::now(),
        ),
        "vote-backed quorum timeout should trigger retransmit recovery work"
    );

    let _ = harness.background_rx.try_iter().count();
    let entries = take_background_log(&background_log);
    let vote_rebroadcasts = entries
        .iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("QcVote"),
                    ..
                }
            )
        })
        .count();
    let sync_updates = entries
        .iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("BlockSyncUpdate"),
                    ..
                }
            )
        })
        .count();
    let block_created = entries
        .iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("BlockCreated"),
                    ..
                }
            )
        })
        .count();
    assert!(
        vote_rebroadcasts > 0,
        "quorum reschedule should still rebroadcast commit votes"
    );
    assert_eq!(
        sync_updates, 0,
        "known-block commit-QC recovery should not rebuild BlockSyncUpdate hydration locally"
    );
    assert!(
        block_created > 0,
        "known-block commit-QC recovery should still retransmit BlockCreated when commit-vote evidence exists"
    );

    let after = super::status::snapshot();
    let request = actor
        .pending
        .missing_commit_qc_requests
        .get(&block_hash)
        .expect("quorum reschedule should seed missing-block recovery state");
    assert_eq!(request.phase, Phase::Commit);
    assert_eq!(request.priority, super::MissingBlockPriority::Consensus);
    assert_eq!(request.attempts, 1);
    assert_eq!(
        after.missing_block_fetch_total,
        before.missing_block_fetch_total.saturating_add(1),
        "quorum reschedule should request a pending-block recovery fetch for known blocks missing commit QC"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn quorum_reschedule_skips_known_block_commit_qc_recovery_without_vote_backing() {
    let _guard = super::status::missing_block_fetch_test_guard();
    super::status::reset_missing_block_fetch_counters_for_tests();

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let block = nonempty_block_for_actor(actor, &harness.key_pairs, 1, 0, None);
    let block_hash = block.hash();
    let height = block.header().height().get();
    let view = block.header().view_change_index();
    let created = actor.frontier_block_created_for_wire(&block);
    actor
        .handle_block_created(created, None)
        .expect("handle BlockCreated");
    assert!(
        actor.frontier_slot_has_active_owner_state_for_view(height, view),
        "test requires contiguous frontier owner state without vote evidence",
    );

    let pending = actor
        .pending
        .pending_blocks
        .remove(&block_hash)
        .expect("pending block retained after BlockCreated");
    assert_eq!(
        pending.validation_status,
        ValidationStatus::Pending,
        "test requires a pending block that has not yet produced local commit evidence",
    );

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let min_votes_for_commit = topology.min_votes_for_commit().max(1);
    let before = super::status::snapshot();
    assert!(
        !actor.reschedule_pending_quorum_block(
            pending,
            Duration::from_secs(5),
            Duration::from_secs(5),
            min_votes_for_commit,
            /*vote_count*/ 0,
            Duration::from_secs(1),
            Duration::from_secs(1),
            None,
            Instant::now(),
        ),
        "owner-only zero-vote reschedule should not escalate into known-block commit-QC recovery",
    );

    let after = super::status::snapshot();
    assert_eq!(
        after.missing_block_fetch_total, before.missing_block_fetch_total,
        "owner-only zero-vote reschedule must not request generic known-block recovery fetches",
    );
    assert!(
        actor
            .pending
            .missing_commit_qc_requests
            .get(&block_hash)
            .is_none(),
        "owner-only zero-vote reschedule must not seed missing commit-QC recovery state",
    );
    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending block retained after suppressed reschedule");
    assert!(
        pending_after.last_quorum_reschedule.is_none(),
        "suppressed owner-only zero-vote reschedule must not mark commit-quorum retransmit progress",
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn quorum_reschedule_near_quorum_rebroadcasts_votes_block_sync_and_block_created() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);
    let _ = take_background_log(&background_log);

    let block = nonempty_block_for_actor(actor, &harness.key_pairs, 1, 0, None);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let height = block.header().height().get();
    let view = block.header().view_change_index();
    let epoch = actor.epoch_for_height(height);
    let topology_peers = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(topology_peers.clone());
    let min_votes_for_commit = topology.min_votes_for_commit().max(1);
    assert!(
        min_votes_for_commit >= 2,
        "test requires at least two votes for quorum"
    );
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let local_peer_id = actor.common_config.peer.id().clone();
    let non_local_signers: Vec<usize> = signature_topology
        .as_ref()
        .iter()
        .enumerate()
        .filter_map(|(idx, peer)| (peer != &local_peer_id).then_some(idx))
        .collect();
    let near_quorum_votes = min_votes_for_commit.saturating_sub(1);
    assert!(
        non_local_signers.len() >= near_quorum_votes,
        "test requires enough non-local peers to populate near-quorum votes"
    );

    for signer_idx in non_local_signers.into_iter().take(near_quorum_votes) {
        let signer = ValidatorIndex::try_from(signer_idx).expect("signer fits u32");
        let mut vote = crate::sumeragi::consensus::Vote {
            phase: Phase::Commit,
            block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: None,
            signer,
            bls_sig: Vec::new(),
        };
        bind_vote_to_signature_topology_chain_order(&mut vote, actor, &signature_topology);
        actor.vote_log.insert(vote_log_key_for_vote(&vote), vote);
    }

    let pending = PendingBlock::new(block, payload_hash, height, view);
    actor.reschedule_pending_quorum_block(
        pending,
        Duration::from_secs(5),
        Duration::from_secs(5),
        min_votes_for_commit,
        near_quorum_votes,
        Duration::from_secs(1),
        Duration::from_secs(1),
        None,
        Instant::now(),
    );

    let _ = harness.background_rx.try_iter().count();
    let entries = take_background_log(&background_log);
    let vote_rebroadcasts = entries
        .iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("QcVote"),
                    ..
                }
            )
        })
        .count();
    let block_sync_updates = entries
        .iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("BlockSyncUpdate"),
                    ..
                }
            )
        })
        .count();
    let block_created = entries
        .iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("BlockCreated"),
                    ..
                }
            )
        })
        .count();
    assert!(
        vote_rebroadcasts > 0,
        "near-quorum reschedule should still rebroadcast votes"
    );
    assert!(
        block_sync_updates > 0,
        "near-quorum reschedule should rebroadcast a vote-carrying BlockSyncUpdate so stale-view peers can accept the payload and votes atomically"
    );
    assert!(
        block_created > 0,
        "near-quorum reschedule should keep the plain BlockCreated fallback for peers that are not stale"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn quorum_reschedule_rebroadcasts_votes_to_all_missing_targets() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    actor.relay_backpressure.disable_for_tests();
    let background_log = attach_background_log(actor);
    let _ = take_background_log(&background_log);

    let block = nonempty_block_for_actor(actor, &harness.key_pairs, 1, 0, None);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let height = block.header().height().get();
    let view = block.header().view_change_index();
    let epoch = actor.epoch_for_height(height);
    let topology_peers = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(topology_peers.clone());
    let min_votes_for_commit = topology.min_votes_for_commit().max(1);
    assert!(
        min_votes_for_commit >= 3,
        "test requires at least three votes for commit quorum"
    );
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let local_peer_id = actor.common_config.peer.id().clone();
    let signer_idx = signature_topology
        .as_ref()
        .iter()
        .position(|peer| peer != &local_peer_id)
        .expect("non-local signer");
    let signer = ValidatorIndex::try_from(signer_idx).expect("signer fits u32");
    actor.vote_log.insert(
        default_vote_log_key(Phase::Commit, height, view, epoch, signer),
        crate::sumeragi::consensus::Vote {
            phase: Phase::Commit,
            block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: None,
            signer,
            bls_sig: Vec::new(),
        },
    );

    let expected_missing_targets = actor.quorum_retransmit_targets_for_missing_votes(
        block_hash,
        height,
        view,
        &topology_peers,
        min_votes_for_commit,
        1,
    );
    assert_eq!(
        expected_missing_targets.len(),
        2,
        "single commit vote should leave two remote targets missing"
    );
    let all_non_local_targets: BTreeSet<_> = topology_peers
        .iter()
        .filter(|peer| *peer != &local_peer_id)
        .cloned()
        .collect();

    actor.subsystems.propose.collectors_contacted.clear();
    actor
        .subsystems
        .propose
        .collectors_contacted
        .insert(expected_missing_targets[0].clone());

    let pending = PendingBlock::new(block, payload_hash, height, view);
    actor.reschedule_pending_quorum_block(
        pending,
        Duration::from_secs(5),
        Duration::from_secs(5),
        min_votes_for_commit,
        1,
        Duration::from_secs(1),
        Duration::from_secs(1),
        None,
        Instant::now(),
    );

    let actual_targets: BTreeSet<_> = take_background_log(&background_log)
        .into_iter()
        .filter_map(|entry| match entry {
            super::BackgroundRequestLogEntry {
                kind: super::BackgroundRequestLogKind::Post,
                msg_kind: Some("QcVote"),
                peer: Some(peer),
            } => Some(peer),
            _ => None,
        })
        .collect();
    let expected_missing_targets: BTreeSet<_> = expected_missing_targets.into_iter().collect();
    assert!(
        expected_missing_targets.is_subset(&actual_targets),
        "quorum reschedule should still include every inferred missing target"
    );
    assert_eq!(
        actual_targets, all_non_local_targets,
        "exact near-quorum reschedule should widen commit-vote repair beyond the inferred missing set"
    );
    assert!(
        harness.background_rx.try_iter().all(|post| {
            !matches!(
                post,
                BackgroundPost::Post { msg, .. }
                    if matches!(msg.as_ref(), BlockMessage::QcVote(_))
            )
        }),
        "rescheduled QcVote recovery should bypass the saturated background queue"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn quorum_reschedule_widens_exact_near_quorum_repair_to_all_non_local_targets() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(7, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    actor.relay_backpressure.disable_for_tests();
    let background_log = attach_background_log(actor);
    let _ = take_background_log(&background_log);

    let view = actor.state.view();
    let height = view.height() as u64 + 1;
    let parent = view.latest_block_hash();
    drop(view);

    let block = sample_block(height, 0, parent);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let view_idx = block.header().view_change_index();
    let (consensus_mode, _, _) = actor.consensus_context_for_height(height);
    let topology_peers =
        actor.roster_for_vote_with_mode(block_hash, height, view_idx, consensus_mode);
    let topology = super::network_topology::Topology::new(topology_peers.clone());
    let required = topology.min_votes_for_commit().max(1);
    assert!(
        required >= 4,
        "test requires a roster where near-quorum leaves more than one inferred missing target"
    );

    let seeded = seed_commit_votes_for_block(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        view_idx,
        required.saturating_sub(1),
    );
    assert_eq!(
        seeded,
        required.saturating_sub(1),
        "test must seed exactly one vote short of quorum"
    );

    let local_peer_id = actor.common_config.peer.id().clone();
    let all_non_local_targets: BTreeSet<_> = topology_peers
        .iter()
        .filter(|peer| *peer != &local_peer_id)
        .cloned()
        .collect();
    let inferred_targets: BTreeSet<_> = actor
        .quorum_retransmit_targets_for_missing_votes(
            block_hash,
            height,
            view_idx,
            &topology_peers,
            required,
            required.saturating_sub(1),
        )
        .into_iter()
        .collect();
    assert_eq!(
        inferred_targets, all_non_local_targets,
        "near-quorum retransmit target selection should widen to every non-local validator"
    );

    let mut pending = PendingBlock::new(block, payload_hash, height, view_idx);
    pending.note_local_commit_vote_emitted();
    actor.reschedule_pending_quorum_block(
        pending,
        Duration::from_secs(5),
        Duration::from_secs(5),
        required,
        required.saturating_sub(1),
        Duration::from_secs(1),
        Duration::from_secs(1),
        None,
        Instant::now(),
    );

    let actual_targets: BTreeSet<_> = take_background_log(&background_log)
        .into_iter()
        .filter_map(|entry| match entry {
            super::BackgroundRequestLogEntry {
                kind: super::BackgroundRequestLogKind::Post,
                msg_kind: Some("QcVote"),
                peer: Some(peer),
            } => Some(peer),
            _ => None,
        })
        .collect();
    assert_eq!(
        actual_targets, all_non_local_targets,
        "exact near-quorum recovery should widen to every non-local validator once reschedule chooses full repair"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn quorum_reschedule_rotates_payload_backed_frontier_after_retransmit() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    actor.relay_backpressure.disable_for_tests();

    let block = nonempty_block_for_actor(actor, &harness.key_pairs, 1, 0, None);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let height = block.header().height().get();
    let view = block.header().view_change_index();
    let epoch = actor.epoch_for_height(height);
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let min_votes_for_commit = topology.min_votes_for_commit().max(1);
    let local_idx = actor
        .local_validator_index_for_topology(&topology)
        .expect("local validator index");
    actor.vote_log.insert(
        default_vote_log_key(Phase::Commit, height, view, epoch, local_idx),
        crate::sumeragi::consensus::Vote {
            phase: Phase::Commit,
            block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: None,
            signer: local_idx,
            bls_sig: Vec::new(),
        },
    );
    let now = Instant::now();
    actor.phase_tracker.start_new_round(height, now);
    let inactive_slot = super::FrontierSlot::new(
        height,
        view,
        block_hash,
        now,
        actor
            .frontier_recovery_window()
            .max(Duration::from_millis(1)),
        None,
        BTreeSet::new(),
        false,
        false,
        false,
        None,
        None,
    );
    actor.frontier_slot = Some(inactive_slot);

    assert_eq!(
        actor.phase_tracker.current_view(height),
        Some(view),
        "test requires the frontier round to start at the pending block view",
    );
    assert!(
        !actor.frontier_slot_has_active_owner_state_for_view(height, view),
        "test requires no active frontier owner so the immediate-rotation path is eligible",
    );
    assert!(
        actor.frontier_slot.is_some(),
        "test requires an exact frontier slot so the slot FSM would otherwise swallow a generic quorum-timeout trigger",
    );

    let pending = PendingBlock::new(block, payload_hash, height, view);
    assert!(
        actor.reschedule_pending_quorum_block(
            pending,
            Duration::from_secs(5),
            Duration::from_secs(5),
            min_votes_for_commit,
            /*vote_count*/ 1,
            Duration::from_secs(1),
            Duration::from_secs(1),
            None,
            now,
        ),
        "payload-backed vote recovery should still take reschedule action",
    );
    assert_eq!(
        actor.phase_tracker.current_view(height),
        Some(view.saturating_add(1)),
        "payload-backed contiguous-frontier retransmit should rotate the round immediately after recovery work; forced={:?} slot={:?}",
        actor.subsystems.propose.forced_view_after_timeout,
        actor.frontier_slot.as_ref().map(|slot| (
            slot.view,
            slot.active_view,
            slot.mode,
            slot.phase,
            slot.timers.last_view_advance_at.is_some(),
            slot.repair_state.quorum_timeout_rebroadcasted,
        )),
    );

    harness.shutdown.send();
}

