#[tokio::test(flavor = "current_thread")]
async fn pending_kura_persisted_still_checks_kura_before_state_commit() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.persistence.kura_retry_max_attempts = 3;
    let mut harness = test_actor_harness_with_config(1, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let (block_hash, _height, _block, mut inflight, work) =
        start_commit_job_fixture(actor, &harness.key_pairs, 94);

    let committed_height_before = actor.state.committed_height();
    let kura_count_before = actor.kura.blocks_count();
    inflight.pending.mark_kura_persisted();
    actor.kura.fail_next_store_for_tests();
    actor.subsystems.commit.work_tx = None;
    actor.subsystems.commit.result_rx = None;

    assert!(
        !actor.start_commit_job(inflight, work),
        "Kura failure should prevent the commit from reporting progress"
    );
    assert_eq!(
        actor.state.committed_height(),
        committed_height_before,
        "state must not advance when the mandatory Kura check fails"
    );
    assert_eq!(
        actor.kura.blocks_count(),
        kura_count_before,
        "failed durable store must not append the pending block"
    );
    assert!(
        actor.subsystems.commit.inflight.is_none(),
        "inline failure should clear inflight state"
    );
    let pending = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("failed block should remain pending for retry");
    assert!(
        pending.kura_persisted,
        "the flag may remain as retry state, but it must not bypass Kura"
    );
    assert_eq!(pending.kura_retry_attempts, 1);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_qc_rebuild_cooldown_uses_chain_block_time() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    {
        let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
        let mut params_block = state.world.parameters.block();
        params_block.sumeragi.block_time_ms = 200;
        params_block.commit();
    }
    let view = actor.state.view();
    actor.update_effective_timing_status(&view, actor.consensus_mode);
    drop(view);

    let block = sample_block(1, 0, None);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let mut pending = PendingBlock::new(block, payload_hash, 1, 0);
    pending.validation_status = ValidationStatus::Valid;
    actor.pending.pending_blocks.insert(block_hash, pending);
    actor.note_proposal_seen(1, 0, payload_hash);

    let now = Instant::now();
    let last_rebuild = now.checked_sub(Duration::from_millis(250)).unwrap_or(now);
    actor.last_qc_rebuild = last_rebuild;

    actor.process_commit_candidates();
    for _ in 0..16 {
        if actor.poll_commit_results() {
            break;
        }
        std::thread::sleep(Duration::from_millis(1));
    }

    assert!(
        actor.last_qc_rebuild > last_rebuild,
        "QC rebuild cooldown should follow chain block_time"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_votes_highest_view_first_for_same_height() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let _genesis_hash = seed_genesis_block_for_state(actor.state.as_ref());
    let state_view = actor.state.view();
    let parent_hash = state_view.latest_block_hash();
    let height = u64::try_from(state_view.height())
        .unwrap_or(0)
        .saturating_add(1);
    drop(state_view);

    let mut candidates = Vec::new();
    for view in 0_u64..32 {
        let block = sample_block(height, view, parent_hash);
        let hash = block.hash();
        candidates.push((view, block, hash));
    }

    let mut selected = None;
    for i in 0..candidates.len() {
        for j in (i + 1)..candidates.len() {
            let (view_a, block_a, hash_a) = &candidates[i];
            let (view_b, block_b, hash_b) = &candidates[j];
            if view_a < view_b && hash_a > hash_b {
                selected = Some((block_a.clone(), block_b.clone()));
                break;
            }
            if view_b < view_a && hash_b > hash_a {
                selected = Some((block_b.clone(), block_a.clone()));
                break;
            }
        }
        if selected.is_some() {
            break;
        }
    }

    let (low_view_block, high_view_block) =
        selected.expect("failed to find view pair with inverse hash ordering");
    let low_view = low_view_block.header().view_change_index();
    let high_view = high_view_block.header().view_change_index();
    assert!(low_view < high_view);

    let low_payload = super::proposals::block_payload_bytes(&low_view_block);
    let low_payload_hash = Hash::new(&low_payload);
    let mut low_pending =
        PendingBlock::new(low_view_block.clone(), low_payload_hash, height, low_view);
    low_pending.validation_status = ValidationStatus::Valid;
    low_pending.parent_state_root = Some(zero_state_root());
    low_pending.post_state_root = Some(zero_state_root());
    actor
        .pending
        .pending_blocks
        .insert(low_view_block.hash(), low_pending);

    let high_payload = super::proposals::block_payload_bytes(&high_view_block);
    let high_payload_hash = Hash::new(&high_payload);
    let mut high_pending = PendingBlock::new(
        high_view_block.clone(),
        high_payload_hash,
        height,
        high_view,
    );
    high_pending.validation_status = ValidationStatus::Valid;
    high_pending.parent_state_root = Some(zero_state_root());
    high_pending.post_state_root = Some(zero_state_root());
    actor
        .pending
        .pending_blocks
        .insert(high_view_block.hash(), high_pending);
    actor.note_proposal_seen(height, high_view, high_payload_hash);

    actor.pending.last_commit_pipeline_run = Instant::now() - Duration::from_secs(10);
    actor.process_commit_candidates();

    let local_precommits: Vec<_> = actor
        .vote_log
        .values()
        .filter(|vote| vote.phase == Phase::Commit && vote.height == height)
        .collect();
    assert!(!local_precommits.is_empty());
    let highest = local_precommits
        .iter()
        .max_by_key(|vote| vote.view)
        .expect("at least one precommit");
    assert_eq!(highest.view, high_view);
    assert_eq!(highest.block_hash, high_view_block.hash());
    assert!(
        !local_precommits
            .iter()
            .any(|vote| vote.view == low_view && vote.block_hash == low_view_block.hash()),
        "should not emit a lower-view precommit when a higher-view block is available"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_defers_higher_view_precommit_while_lower_view_vote_validation_is_pending()
{
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let _genesis_hash = seed_genesis_block_for_state(actor.state.as_ref());
    let state_view = actor.state.view();
    let parent_hash = state_view.latest_block_hash();
    let height = u64::try_from(state_view.height())
        .unwrap_or(0)
        .saturating_add(1);
    drop(state_view);

    let lower_view = 0_u64;
    let higher_view = 1_u64;
    let lower_block = sample_block(height, lower_view, parent_hash);
    let higher_block = sample_block(height, higher_view, parent_hash);
    let higher_hash = insert_validated_pending(actor, higher_block.clone());
    let epoch = actor.epoch_for_height(height);
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let lower_signature_topology =
        super::topology_for_view(&topology, height, lower_view, mode_tag, prf_seed);
    let local_signer = actor
        .local_validator_index_for_topology(&lower_signature_topology)
        .expect("local signer present in lower-view topology");
    let lower_vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash: lower_block.hash(),
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view: lower_view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: local_signer,
        bls_sig: Vec::new(),
    };
    actor
        .subsystems
        .vote_verify
        .pending_validation
        .insert(VoteVerifyKey::from_vote(&lower_vote), lower_vote);

    actor.process_commit_candidates_with_trigger(CommitPipelineTrigger::Event, None);

    let pending = actor
        .pending
        .pending_blocks
        .get(&higher_hash)
        .expect("higher-view pending retained");
    assert!(
        !pending.local_commit_vote_emitted(),
        "higher-view precommit must wait while a lower-view same-height vote is still being verified"
    );
    assert!(
        actor
            .local_precommit_vote_for(height, higher_view, epoch, &topology)
            .is_none(),
        "the local validator must not add a precommit to the competing higher-view branch"
    );

    actor.subsystems.vote_verify.pending_validation.clear();
    actor.process_commit_candidates_with_trigger(CommitPipelineTrigger::Event, None);

    let pending = actor
        .pending
        .pending_blocks
        .get(&higher_hash)
        .expect("higher-view pending retained after precommit");
    assert!(
        pending.local_commit_vote_emitted(),
        "the guard should clear once the conflicting verification queue is drained"
    );
    assert!(
        actor
            .local_precommit_vote_for(height, higher_view, epoch, &topology)
            .is_some(),
        "higher-view precommit should emit when no conflicting lower-view evidence remains"
    );

    harness.shutdown.send();
}

