#[tokio::test(flavor = "current_thread")]
async fn event_driven_precommit_joins_higher_view_when_candidate_votes_outweigh_lower_conflict() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let _genesis_hash = seed_genesis_block_for_state(actor.state.as_ref());
    let state_view = actor.state.view();
    let parent_hash = state_view.latest_block_hash();
    let height = u64::try_from(state_view.height())
        .unwrap_or(0)
        .saturating_add(1);
    drop(state_view);

    let lower_view = 0_u64;
    let higher_view = 1_u64;
    let lower_block = sample_block(height, lower_view, parent_hash);
    let higher_block = sample_block(height, higher_view, parent_hash);
    let higher_hash = insert_validated_pending(actor, higher_block.clone());
    let epoch = actor.epoch_for_height(height);
    let topology = actor.effective_commit_topology();
    let topology_ref = super::network_topology::Topology::new(topology.clone());
    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let lower_signature_topology =
        super::topology_for_view(&topology_ref, height, lower_view, mode_tag, prf_seed);
    let higher_signature_topology =
        super::topology_for_view(&topology_ref, height, higher_view, mode_tag, prf_seed);
    let lower_chain_order = actor.vnext_chain_order_binding_for_signature_topology(
        height,
        lower_view,
        consensus_mode,
        &lower_signature_topology,
    );
    let higher_chain_order = actor.vnext_chain_order_binding_for_signature_topology(
        height,
        higher_view,
        consensus_mode,
        &higher_signature_topology,
    );

    let make_vote = |block_hash, view, signer| {
        let (chain_order_hash, rechain_seq) = if view == higher_view {
            higher_chain_order
        } else {
            lower_chain_order
        };
        crate::sumeragi::consensus::Vote {
            phase: Phase::Commit,
            block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash,
            rechain_seq,
            highest_qc: None,
            signer,
            bls_sig: Vec::new(),
        }
    };
    let local_peer = actor.common_config.peer.id().clone();
    let remote_signers: Vec<_> = (0..topology.len())
        .filter_map(|idx| ValidatorIndex::try_from(idx).ok())
        .filter(|signer| {
            let vote = make_vote(higher_hash, higher_view, *signer);
            actor.vote_signer_peer(&vote).as_ref() != Some(&local_peer)
        })
        .take(2)
        .collect();
    assert_eq!(
        remote_signers.len(),
        2,
        "test needs two remote signers for the candidate branch"
    );
    let lower_signer = (0..topology.len())
        .filter_map(|idx| ValidatorIndex::try_from(idx).ok())
        .find(|signer| {
            let vote = make_vote(lower_block.hash(), lower_view, *signer);
            actor.vote_signer_peer(&vote).as_ref() != Some(&local_peer)
        })
        .expect("test needs a remote lower-view signer");

    let lower_vote = make_vote(lower_block.hash(), lower_view, lower_signer);
    insert_test_vote_with_roster(actor, lower_vote, &topology);
    for signer in &remote_signers {
        let higher_vote = make_vote(higher_hash, higher_view, *signer);
        insert_test_vote_with_roster(actor, higher_vote, &topology);
    }
    assert!(
        !actor.should_defer_tip_precommit_for_same_height_conflict(
            higher_hash,
            height,
            higher_view,
            epoch
        ),
        "stronger higher-view candidate should pass the same-height conflict guard"
    );
    assert!(
        actor
            .local_conflicting_slot_vote(height, epoch, higher_hash)
            .is_none(),
        "fixture must not seed a local conflicting vote"
    );

    let emitted = actor.maybe_emit_local_commit_vote_for_pending_event(
        higher_hash,
        height,
        higher_view,
        &topology,
        "test_commit_vote_accepted",
    );

    assert!(
        emitted,
        "a single lower-view vote must not block joining a higher-view branch with stronger commit-vote support"
    );
    let pending = actor
        .pending
        .pending_blocks
        .get(&higher_hash)
        .expect("higher-view pending retained");
    assert!(
        pending.local_commit_vote_emitted(),
        "the pending block should record the local precommit"
    );
    assert!(
        actor
            .local_precommit_vote_for(height, higher_view, epoch, &higher_signature_topology)
            .is_some(),
        "the local validator should add the third vote to the stronger higher-view branch"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_uses_commit_qc_roster_for_validation() {
    use crate::sumeragi::status;

    let _history_guard = status::commit_history_test_guard();
    status::reset_commit_certs_for_tests();
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let active_roster = actor.effective_commit_topology();
    assert!(
        active_roster.len() >= 2,
        "test needs at least two validators to rotate roster"
    );
    let mut history_roster = active_roster.clone();
    let rotate_at = super::network_topology::commit_quorum_from_len(history_roster.len());
    if rotate_at > 0 {
        history_roster[..rotate_at].rotate_right(1);
    }
    assert_ne!(
        history_roster, active_roster,
        "history roster should differ from active roster"
    );

    let parent_hash = seed_genesis_block_for_state(actor.state.as_ref());

    let height = 2u64;
    let view = 0u64;
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(
        &super::network_topology::Topology::new(history_roster.clone()),
        height,
        view,
        mode_tag,
        prf_seed,
    );
    let signer_peer = signature_topology
        .as_ref()
        .first()
        .expect("commit topology not empty");
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair exists in harness");
    let signer_idx = signature_topology
        .position(signer_kp.public_key())
        .expect("signer index in topology");
    let block = heartbeat_block_for_state(
        actor.state.as_ref(),
        &actor.common_config.chain,
        height,
        view,
        Some(parent_hash),
        signer_kp,
        u64::try_from(signer_idx).expect("signer index fits u64"),
    );
    let block_hash = block.hash();

    let mut signers = BTreeSet::new();
    for idx in 0..history_roster.len() {
        signers.insert(ValidatorIndex::try_from(idx).expect("signer index fits"));
    }
    let signers_bitmap = super::build_signers_bitmap(&signers, history_roster.len());
    let topology = super::network_topology::Topology::new(history_roster.clone());
    let roots = validated_roots_for_actor_block(actor, block.clone(), &topology);
    let (chain_order_hash, rechain_seq) = actor.vnext_chain_order_binding_for_signature_topology(
        height,
        view,
        ConsensusMode::Permissioned,
        &signature_topology,
    );
    let mut commit_qc = Qc {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        parent_state_root: roots.parent_state_root,
        post_state_root: roots.post_state_root,
        height,
        view,
        epoch: 0,
        chain_order_hash,
        rechain_seq,
        mode_tag: mode_tag.to_string(),
        highest_qc: None,
        validator_set_hash: HashOf::new(&history_roster),
        validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
        validator_set: history_roster,
        aggregate: QcAggregate {
            signers_bitmap,
            bls_aggregate_signature: Vec::new(),
        },
    };
    resign_qc_for_actor(&mut commit_qc, actor, &harness.key_pairs);
    status::record_commit_qc(commit_qc);

    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let mut pending = PendingBlock::new(block, payload_hash, height, view);
    pending.validation_status = ValidationStatus::Valid;
    pending.parent_state_root = Some(roots.parent_state_root);
    pending.post_state_root = Some(roots.post_state_root);
    actor.pending.pending_blocks.insert(block_hash, pending);
    actor.note_proposal_seen(height, view, payload_hash);
    actor.pending.last_commit_pipeline_run = Instant::now() - Duration::from_secs(10);
    actor.subsystems.commit.work_tx = None;
    actor.subsystems.commit.result_rx = None;

    actor.process_commit_candidates_with_trigger(CommitPipelineTrigger::Tick, None);

    assert!(
        actor.kura.get_block_height_by_hash(block_hash).is_some(),
        "commit pipeline should finalize a pending block with a cached commit certificate roster"
    );
    assert_eq!(
        actor.state.latest_block_hash_fast(),
        Some(block_hash),
        "state tip should advance to the certified pending block"
    );

    status::reset_commit_certs_for_tests();
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_routes_local_only_commit_topology_through_vnext_worker() {
    let mut harness = test_actor_harness(1).await;
    let actor = &mut harness.actor;

    let parent_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(0)
        .saturating_add(1);
    let view = 0_u64;
    let block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(parent_hash));
    let block_hash = block.hash();
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);

    let (work_tx, work_rx) = std::sync::mpsc::sync_channel::<super::validation::ValidationWork>(1);
    actor.subsystems.validation.work_txs = vec![work_tx];
    actor.subsystems.validation.result_rx = None;

    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );
    actor.note_proposal_seen(height, view, payload_hash);

    let mut session = Actor::build_rbc_session_from_payload(
        &payload_bytes,
        payload_hash,
        actor.config.rbc.chunk_max_bytes,
        actor.epoch_for_height(height),
    )
    .expect("session");
    assert_eq!(session.total_chunks(), 1, "test expects a single RBC chunk");
    session.ingest_chunk(0, payload_bytes, None);
    session.test_set_delivered(true);
    actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert((block_hash, height, view), session);

    actor.process_commit_candidates_with_trigger(CommitPipelineTrigger::Tick, None);

    let pending = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending block retained");
    assert_eq!(
        pending.validation_status,
        ValidationStatus::Pending,
        "single-validator commit pipeline should defer while vNext worker validation owns the block"
    );
    assert!(
        !pending.local_commit_vote_emitted(),
        "single-validator commit pipeline should wait for vNext validation before voting"
    );
    let queued_work = work_rx
        .try_recv()
        .expect("local-only topology should still dispatch vNext worker validation");
    assert_eq!(queued_work.hash, block_hash);
    assert_eq!(queued_work.height, height);
    assert_eq!(queued_work.view, view);
    assert!(
        actor
            .subsystems
            .validation
            .inflight
            .contains_key(&block_hash),
        "vNext validation should leave worker work inflight"
    );
    assert!(
        actor
            .subsystems
            .validation
            .vnext_inflight
            .contains_key(&block_hash),
        "local-only validation should be tracked as vNext-owned work"
    );
    let has_vote = actor.vote_log.values().any(|vote| {
        vote.phase == Phase::Commit
            && vote.block_hash == block_hash
            && vote.height == height
            && vote.view == view
    });
    assert!(
        !has_vote,
        "single-validator commit pipeline should not record a precommit vote before vNext validation finishes"
    );

    harness.shutdown.send();
}

