#[tokio::test(flavor = "current_thread")]
async fn finalize_pending_block_revives_aborted_on_tip_with_commit_qc() {
    let mut harness = test_actor_harness(1).await;
    let actor = &mut harness.actor;

    {
        let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
        state.commit_topology.mutate_vec(Vec::clear);
        state.prev_commit_topology.mutate_vec(Vec::clear);
        let mut block = state.world.block();
        block.peers.get_mut().clear();
        block.commit();
    }

    let view = actor.state.view();
    let height = view.height() as u64 + 1;
    let parent = view.latest_block_hash();
    drop(view);

    let block = sample_block(height, 0, parent);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let mut pending = PendingBlock::new(block, payload_hash, height, 0);
    pending.mark_aborted();
    let epoch = actor.epoch_for_height(height);
    pending.note_commit_qc_observed(epoch);
    pending.commit_qc_epoch = Some(epoch);
    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height,
        view: 0,
        epoch,
    };

    let committed = actor.finalize_pending_block(lock, pending, None);
    assert!(
        !committed,
        "commit should be deferred without an available commit roster"
    );
    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending block should be retained");
    assert!(
        !pending_after.aborted,
        "aborted pending block should be revived when commit QC is present on tip"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn finalize_pending_block_defers_until_da_payload_available() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let view = actor.state.view();
    let height = view.height() as u64 + 1;
    let parent = view.latest_block_hash();
    drop(view);

    let block = sample_block(height, 0, parent);
    let block_hash = block.hash();
    let local_payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let payload_hash = Hash::prehashed([0xDA; Hash::LENGTH]);
    assert_ne!(
        local_payload_hash, payload_hash,
        "test requires an unavailable DA payload"
    );
    let mut pending = PendingBlock::new(block, payload_hash, height, 0);
    pending.validation_status = ValidationStatus::Valid;
    pending.parent_state_root = Some(zero_state_root());
    pending.post_state_root = Some(zero_state_root());
    let epoch = actor.epoch_for_height(height);
    pending.note_commit_qc_observed(epoch);
    pending.commit_qc_epoch = Some(epoch);
    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height,
        view: 0,
        epoch,
    };

    #[cfg(feature = "telemetry")]
    let (telemetry, da_gate_blocks_before) = {
        let telemetry = actor.telemetry_handle().expect("telemetry enabled").clone();
        let metrics = telemetry.metrics().await;
        let before = metrics
            .sumeragi_da_gate_block_total
            .with_label_values(&[super::status::DaGateReasonSnapshot::MissingLocalData.as_str()])
            .get();
        (telemetry, before)
    };

    let committed = actor.finalize_pending_block(lock, pending, None);

    assert!(
        !committed,
        "commit must wait while DA payload availability is missing"
    );
    assert!(
        actor.subsystems.commit.inflight.is_none(),
        "DA-gated finalize must not enqueue commit work"
    );
    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("DA-gated pending block should be retained");
    assert!(
        pending_after.commit_qc_observed(),
        "commit QC evidence should stay attached while finalize waits"
    );
    assert!(
        matches!(pending_after.last_gate, Some(GateReason::MissingLocalData)),
        "missing DA payload should keep the finalize gate active"
    );
    #[cfg(feature = "telemetry")]
    {
        let metrics = telemetry.metrics().await;
        let da_gate_blocks_after = metrics
            .sumeragi_da_gate_block_total
            .with_label_values(&[super::status::DaGateReasonSnapshot::MissingLocalData.as_str()])
            .get();
        assert_eq!(
            da_gate_blocks_after,
            da_gate_blocks_before + 1,
            "finalize should record exactly one DA gate telemetry block event"
        );
    }

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn cached_future_proposal_does_not_immediately_timeout_after_parent_commit_activation() {
    let mut harness = test_actor_harness(1).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(actor.state.as_ref());
    let height = 2_u64;
    let view = 0_u64;
    let commit_topology = actor.effective_commit_topology();
    let leader_peer = commit_topology.first().expect("commit topology not empty");
    let leader_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == leader_peer.public_key())
        .expect("leader keypair exists");
    let block = heartbeat_block_for_state(
        actor.state.as_ref(),
        &actor.common_config.chain,
        height,
        view,
        Some(genesis_hash),
        leader_kp,
        0,
    );
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let pending = PendingBlock::new(block.clone(), payload_hash, height, view);
    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height,
        view,
        epoch: actor.epoch_for_height(height),
    };
    actor.subsystems.commit.inflight = Some(CommitInFlight {
        id: 23,
        lock,
        block_hash,
        pending,
        commit_topology: commit_topology.clone(),
        signature_topology: commit_topology.clone(),
        qc_signers: None,
        commit_qc: None,
        post_commit_qc: None,
        enqueue_time: Instant::now(),
        timeout_reported: false,
    });

    let (result_tx, result_rx) = mpsc::sync_channel(1);
    actor.subsystems.commit.result_rx = Some(result_rx);

    let future_height = height.saturating_add(1);
    let future_block = sample_block(future_height, view, Some(block_hash));
    let future_hash = future_block.hash();
    let future_payload_hash = Hash::new(super::proposals::block_payload_bytes(&future_block));
    let mut future_pending = PendingBlock::new(
        future_block.clone(),
        future_payload_hash,
        future_height,
        view,
    );
    let quorum_timeout = actor.quorum_timeout(actor.runtime_da_enabled());
    let stale_progress_at = Instant::now()
        .checked_sub(quorum_timeout.saturating_add(Duration::from_millis(25)))
        .unwrap_or_else(Instant::now);
    future_pending.touch_progress(stale_progress_at);
    actor
        .pending
        .pending_blocks
        .insert(future_hash, future_pending);
    actor
        .subsystems
        .propose
        .proposal_cache
        .insert_proposal(Actor::build_consensus_proposal(
            &future_block,
            future_payload_hash,
            lock,
            0,
            view,
            actor.epoch_for_height(future_height),
        ));
    actor.note_proposal_seen(future_height, view, future_payload_hash);

    let work = commit::CommitWork {
        id: 23,
        block,
        validated_commit_artifact: None,
        commit_topology: commit_topology.clone(),
        signature_topology: commit_topology.clone(),
        consensus_mode: actor.consensus_context_for_height(height).0,
        qc_signers: None,
        commit_qc: None,
        allow_signature_index_recovery: false,
        events_sender: actor.events_sender.clone(),
    };
    let (outcome, timings) = execute_commit_work_on_test_stack(
        Arc::clone(&actor.state),
        Arc::clone(&actor.kura),
        actor.common_config.chain.clone(),
        actor.genesis_account.clone(),
        work,
    );
    result_tx
        .send(commit::CommitResult {
            id: 23,
            outcome,
            timings,
        })
        .expect("send commit result");

    let activation_started_at = Instant::now();
    assert!(
        actor.poll_commit_results(),
        "commit outcome should advance the tip"
    );

    let pending_after = actor
        .pending
        .pending_blocks
        .get(&future_hash)
        .expect("future pending block should remain cached after parent commit");
    let activated_at = pending_after.inserted_at;
    assert!(
        activated_at >= activation_started_at,
        "future pending block should restart its pending age when its parent commit activates the frontier"
    );
    assert_eq!(
        pending_after.progress_age(activated_at),
        Duration::ZERO,
        "future pending block should receive a fresh quorum-timeout window after its parent commit activates the frontier"
    );

    let proposed = actor.on_pacemaker_propose_ready(activated_at);
    assert!(
        !proposed,
        "pacemaker should wait on the freshly activated cached proposal instead of reassembling a new one"
    );
    assert!(
        actor
            .subsystems
            .propose
            .last_cached_slot_timeout_trigger
            .is_none(),
        "cached future proposal must not inherit pre-activation stall age into the first committed+1 timeout check"
    );
    assert_eq!(
        actor.phase_tracker.current_view(future_height),
        Some(view),
        "the newly activated cached frontier slot should stay on its current view"
    );

    harness.shutdown.send();
}

