#[tokio::test(flavor = "current_thread")]
async fn finalize_pending_block_commits_retired_same_height_without_conflicting_local_vote() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(u64::MAX)
        .saturating_add(1);
    let parent = Some(genesis_hash);

    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, 0, parent);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let epoch = actor.epoch_for_height(height);
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let roots = validated_roots_for_actor_block(actor, block.clone(), &topology);
    let mut pending = PendingBlock::new(block.clone(), payload_hash, height, 0);
    pending.validation_status = ValidationStatus::Valid;
    pending.parent_state_root = Some(roots.parent_state_root);
    pending.post_state_root = Some(roots.post_state_root);
    pending.retire_same_height();
    pending.note_commit_qc_observed(epoch);
    pending.commit_qc_epoch = Some(epoch);

    let mut qc = qc_with_bitmap_for_actor(
        actor,
        block_hash,
        height,
        0,
        epoch,
        vec![0b0000_1111],
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    qc.parent_state_root = roots.parent_state_root;
    qc.post_state_root = roots.post_state_root;
    resign_qc_for_actor(&mut qc, actor, &harness.key_pairs);
    actor.qc_cache.insert(Actor::qc_tally_key(&qc), qc);

    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height,
        view: 0,
        epoch,
    };

    let committed = actor.finalize_pending_block(lock, pending, None);
    assert!(
        committed,
        "retired same-height block should still commit with a matching QC"
    );
    assert_eq!(
        u64::try_from(actor.state.committed_height()).unwrap_or(u64::MAX),
        height,
        "commit should advance the canonical height"
    );
    assert_eq!(
        actor.state.latest_block_hash_fast(),
        Some(block_hash),
        "matching retired branch should become the committed tip"
    );
    assert!(
        !actor.pending.pending_blocks.contains_key(&block_hash),
        "committed retired branch should leave pending storage"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_recovery_includes_certified_aborted_pending_block() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(u64::MAX)
        .saturating_add(1);
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, 0, Some(genesis_hash));
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let roots = validated_roots_for_actor_block(actor, block.clone(), &topology);
    let block_hash = insert_validated_pending(actor, block);
    let epoch = actor.epoch_for_height(height);

    {
        let pending = actor
            .pending
            .pending_blocks
            .get_mut(&block_hash)
            .expect("pending block inserted");
        pending.mark_aborted();
        pending.validation_status = ValidationStatus::Valid;
        pending.parent_state_root = Some(roots.parent_state_root);
        pending.post_state_root = Some(roots.post_state_root);
        pending.note_commit_qc_observed(epoch);
        pending.commit_qc_epoch = Some(epoch);
    }

    let mut qc = qc_with_bitmap_for_actor(
        actor,
        block_hash,
        height,
        0,
        epoch,
        vec![0b0000_1111],
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    qc.parent_state_root = roots.parent_state_root;
    qc.post_state_root = roots.post_state_root;
    resign_qc_for_actor(&mut qc, actor, &harness.key_pairs);
    actor.qc_cache.insert(Actor::qc_tally_key(&qc), qc);

    assert_eq!(
        actor.commit_candidate_blocks_len(false),
        0,
        "aborted pending blocks should stay off the normal hot path"
    );
    assert_eq!(
        actor.commit_candidate_blocks_len(true),
        1,
        "certified aborted pending blocks should remain eligible for recovery"
    );

    let timings =
        actor.process_commit_candidates_with_trigger_inner(CommitPipelineTrigger::Tick, None, true);

    assert!(
        timings.blocks_considered > 0,
        "recovery commit pipeline should inspect the certified aborted block"
    );
    assert_eq!(
        u64::try_from(actor.state.committed_height()).unwrap_or(u64::MAX),
        height,
        "the certified aborted block should be revived and finalized"
    );
    assert!(
        !actor.pending.pending_blocks.contains_key(&block_hash),
        "finalized recovery block should leave pending storage"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_keeps_certified_recovery_candidate_eligible_with_active_same_height_branch()
 {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(&actor.state);
    let height = actor.committed_height_snapshot().saturating_add(1);
    let certified_view = 0_u64;
    let active_view = 2_u64;

    let certified_block = nonempty_block_for_actor(
        actor,
        &harness.key_pairs,
        height,
        certified_view,
        Some(genesis_hash),
    );
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let certified_roots =
        validated_roots_for_actor_block(actor, certified_block.clone(), &topology);
    let certified_hash = insert_validated_pending(actor, certified_block);
    let active_block = nonempty_block_for_actor(
        actor,
        &harness.key_pairs,
        height,
        active_view,
        Some(genesis_hash),
    );
    let active_hash = insert_validated_pending(actor, active_block);
    let epoch = actor.epoch_for_height(height);

    {
        let pending = actor
            .pending
            .pending_blocks
            .get_mut(&certified_hash)
            .expect("certified pending block inserted");
        pending.retire_same_height();
        pending.note_commit_qc_observed(epoch);
        pending.commit_qc_epoch = Some(epoch);
        pending.validation_status = ValidationStatus::Valid;
        pending.parent_state_root = Some(certified_roots.parent_state_root);
        pending.post_state_root = Some(certified_roots.post_state_root);
    }
    {
        let pending = actor
            .pending
            .pending_blocks
            .get_mut(&active_hash)
            .expect("active pending block inserted");
        pending.note_local_commit_vote_emitted();
        pending.validation_status = ValidationStatus::Valid;
        pending.parent_state_root = Some(zero_state_root());
        pending.post_state_root = Some(zero_state_root());
    }

    let mut qc = qc_with_bitmap_for_actor(
        actor,
        certified_hash,
        height,
        certified_view,
        epoch,
        vec![0b0000_1111],
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    qc.parent_state_root = certified_roots.parent_state_root;
    qc.post_state_root = certified_roots.post_state_root;
    resign_qc_for_actor(&mut qc, actor, &harness.key_pairs);
    actor.qc_cache.insert(Actor::qc_tally_key(&qc), qc);

    let tip_height = actor.state.committed_height();
    let tip_hash = actor.state.latest_block_hash_fast();
    assert_eq!(
        actor.active_pending_blocks_len_for_tip(tip_height, tip_hash),
        1,
        "later same-height branch should stay active"
    );
    assert_eq!(
        actor.commit_candidate_blocks_len(false),
        1,
        "normal hot path should only count the active branch"
    );
    assert_eq!(
        actor.commit_candidate_blocks_len(true),
        2,
        "recovery path must keep the certified branch eligible even while another branch is active"
    );

    let timings =
        actor.process_commit_candidates_with_trigger_inner(CommitPipelineTrigger::Tick, None, true);

    assert!(
        timings.blocks_considered >= 2
            || !actor.pending.pending_blocks.contains_key(&certified_hash),
        "commit pipeline should inspect or finalize the certified recovery candidate"
    );
    assert_eq!(
        u64::try_from(actor.state.committed_height()).unwrap_or(u64::MAX),
        height,
        "the certified same-height branch should finalize"
    );
    assert_eq!(
        actor.state.latest_block_hash_fast(),
        Some(certified_hash),
        "the commit-QC-backed branch should become canonical"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_recovery_includes_vote_backed_retired_same_height_pending_block() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(&actor.state);
    let height = actor.committed_height_snapshot().saturating_add(1);
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, 0, Some(genesis_hash));
    let block_hash = insert_validated_pending(actor, block);
    {
        let pending = actor
            .pending
            .pending_blocks
            .get_mut(&block_hash)
            .expect("pending block inserted");
        pending.retire_same_height();
        pending.validation_status = ValidationStatus::Valid;
        pending.parent_state_root = Some(zero_state_root());
        pending.post_state_root = Some(zero_state_root());
    }

    let commit_topology = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(commit_topology.clone());
    let required = topology.min_votes_for_commit();
    assert!(required > 0, "test topology must have a commit quorum");
    let seeded = seed_verified_commit_votes_for_block_with_roster(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        0,
        &commit_topology,
        required,
    );
    assert_eq!(seeded, required, "test should seed a commit quorum");
    assert_eq!(
        actor.pending_block_commit_votes_count(block_hash, height, 0),
        required,
        "seeded commit votes should be visible to recovery candidate selection"
    );

    assert_eq!(
        actor.commit_candidate_blocks_len(false),
        0,
        "retired same-height pending blocks should stay off the normal hot path"
    );
    assert_eq!(
        actor.commit_candidate_blocks_len(true),
        1,
        "vote-backed retired same-height pending blocks should remain eligible for recovery"
    );
    actor.last_qc_rebuild = Instant::now() - Duration::from_secs(60);

    let timings =
        actor.process_commit_candidates_with_trigger_inner(CommitPipelineTrigger::Tick, None, true);
    let recovered = actor
        .cached_commit_qc_for_block(block_hash, height, 0)
        .is_some()
        || !actor.pending.pending_blocks.contains_key(&block_hash);

    assert!(
        timings.blocks_considered > 0 || recovered,
        "recovery commit pipeline should inspect the vote-backed retired block or recover it during QC replay"
    );
    assert!(
        recovered,
        "cached commit votes should either rebuild a QC or finalize the retired block"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_recovery_skips_retired_vote_backed_branch_after_new_view_qc() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(&actor.state);
    let highest_qc = actor
        .latest_committed_qc()
        .expect("genesis commit QC should be available");
    let height = actor.committed_height_snapshot().saturating_add(1);
    let stale_view = 0_u64;
    let recovery_view = stale_view.saturating_add(2);
    let block = nonempty_block_for_actor(
        actor,
        &harness.key_pairs,
        height,
        stale_view,
        Some(genesis_hash),
    );
    let block_hash = insert_validated_pending(actor, block);
    {
        let pending = actor
            .pending
            .pending_blocks
            .get_mut(&block_hash)
            .expect("pending block inserted");
        pending.retire_same_height();
        pending.validation_status = ValidationStatus::Valid;
        pending.parent_state_root = Some(zero_state_root());
        pending.post_state_root = Some(zero_state_root());
    }

    let seeded = seed_remote_commit_votes_for_block(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        stale_view,
        1,
    );
    assert_eq!(seeded, 1, "test should seed one raw commit vote");
    while actor.poll_vote_verify_results() {}
    assert!(
        actor.pending_block_has_commit_votes(block_hash, height, stale_view),
        "raw commit vote should make the retired branch recovery-visible before view-change proof"
    );
    assert_eq!(
        actor.commit_candidate_blocks_len(true),
        1,
        "vote-backed retired branch should remain eligible until a higher NEW_VIEW QC supersedes it"
    );

    cache_new_view_qc_for_frontier(actor, &harness.key_pairs, height, recovery_view, highest_qc);
    actor.subsystems.propose.new_view_tracker = NewViewTracker::default();
    assert!(
        actor.known_block_commit_qc_request_is_superseded_by_higher_new_view_quorum(
            height, stale_view,
        ),
        "cached NEW_VIEW QC should supersede stale raw commit-vote recovery after tracker pruning"
    );
    assert_eq!(
        actor.commit_candidate_blocks_len(true),
        0,
        "retired branch with only raw commit votes must stop competing after a higher NEW_VIEW QC"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn maybe_request_frontier_gap_realign_after_commit_reanchors_missing_next_height_when_future_qc_evidence_survives()
 {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(&actor.state);
    let _ = seed_block_for_state(&actor.state, 2, genesis_hash);
    let committed_height = actor.committed_height_snapshot();
    let frontier_height = committed_height.saturating_add(1);
    let future_height = frontier_height.saturating_add(1);
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let future_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xF1; Hash::LENGTH]));
    let future_qc = qc_with_bitmap(
        &actor.common_config.chain,
        future_hash,
        future_height,
        0,
        actor.epoch_for_height(future_height),
        vec![0b0000_1111],
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    let qc_key = Actor::qc_tally_key(&future_qc);
    let now = Instant::now();
    actor.deferred_missing_payload_qcs.insert(
        qc_key,
        super::DeferredQcEntry {
            qc: future_qc,
            first_seen: now,
            last_attempt: now,
            attempts: 0,
            escalated_fetch: false,
            reason: "test_future_frontier_realign",
        },
    );

    assert!(
        actor.has_contiguous_frontier_pressure(committed_height),
        "future deferred QC should pin catch-up to the contiguous frontier"
    );
    assert!(
        actor.maybe_request_frontier_gap_realign_after_commit(now),
        "post-commit helper should reanchor the missing contiguous frontier when future QC evidence remains actionable"
    );
    assert!(
        !selected_reanchor_peers_for_height(actor, frontier_height).is_empty(),
        "post-commit helper should emit a committed-anchor range pull for the missing contiguous frontier"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn finalize_pending_block_skips_frontier_reanchor_when_next_height_payload_is_local() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(u64::MAX)
        .saturating_add(1);
    let parent = Some(genesis_hash);

    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, 0, parent);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let epoch = actor.epoch_for_height(height);
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let roots = validated_roots_for_actor_block(actor, block.clone(), &topology);
    let mut pending = PendingBlock::new(block.clone(), payload_hash, height, 0);
    pending.validation_status = ValidationStatus::Valid;
    pending.parent_state_root = Some(roots.parent_state_root);
    pending.post_state_root = Some(roots.post_state_root);
    pending.retire_same_height();
    pending.note_commit_qc_observed(epoch);
    pending.commit_qc_epoch = Some(epoch);

    let mut qc = qc_with_bitmap_for_actor(
        actor,
        block_hash,
        height,
        0,
        epoch,
        vec![0b0000_1111],
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    qc.parent_state_root = roots.parent_state_root;
    qc.post_state_root = roots.post_state_root;
    resign_qc_for_actor(&mut qc, actor, &harness.key_pairs);
    actor.qc_cache.insert(Actor::qc_tally_key(&qc), qc);

    let frontier_height = height.saturating_add(1);
    let frontier_block = nonempty_block_for_actor(
        actor,
        &harness.key_pairs,
        frontier_height,
        0,
        Some(block_hash),
    );
    let frontier_hash = insert_validated_pending(actor, frontier_block);
    let future_height = frontier_height.saturating_add(1);
    let future_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xF2; Hash::LENGTH]));
    let future_qc = qc_with_bitmap_for_actor(
        actor,
        future_hash,
        future_height,
        0,
        actor.epoch_for_height(future_height),
        vec![0b0000_1111],
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    actor
        .qc_cache
        .insert(Actor::qc_tally_key(&future_qc), future_qc);

    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height,
        view: 0,
        epoch,
    };

    assert!(
        actor.finalize_pending_block(lock, pending, None),
        "commit should finalize before checking the post-commit reanchor"
    );
    assert!(
        actor.pending.pending_blocks.contains_key(&frontier_hash),
        "post-commit refresh should keep the local next-height payload available"
    );
    assert!(
        selected_reanchor_peers_for_height(actor, frontier_height).is_empty(),
        "post-commit reanchor should stay suppressed when the contiguous frontier payload is already local"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn finalize_pending_block_promotes_qc_state_for_already_committed_block() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(actor.state.as_ref());
    let height = 2_u64;
    let view = 0_u64;
    let block_hash = seed_block_for_state(actor.state.as_ref(), height, genesis_hash);

    let parent_qc = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: genesis_hash,
        height: 1,
        view: 0,
        epoch: actor.epoch_for_height(1),
    };
    actor.locked_qc = Some(parent_qc);
    actor.highest_qc = Some(parent_qc);
    super::status::set_locked_qc(1, 0, Some(genesis_hash));
    super::status::set_highest_qc(1, 0);
    super::status::set_highest_qc_hash(genesis_hash);

    let header = BlockHeader::new(
        std::num::NonZeroU64::new(height).expect("height must be non-zero"),
        Some(genesis_hash),
        None,
        None,
        view,
        0,
    );
    let mut seed = [0u8; 8 + Hash::LENGTH];
    seed[..8].copy_from_slice(&height.to_le_bytes());
    seed[8..].copy_from_slice(genesis_hash.as_ref());
    let leader = deterministic_keypair(&seed, Algorithm::BlsNormal);
    let block = BlockBuilder::new(header).build_with_signature(0, leader.private_key());
    assert_eq!(
        block.hash(),
        block_hash,
        "test block must match committed block"
    );

    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let mut pending = PendingBlock::new(block, payload_hash, height, view);
    let epoch = actor.epoch_for_height(height);
    pending.note_commit_qc_observed(epoch);
    pending.commit_qc_epoch = Some(epoch);
    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height,
        view,
        epoch,
    };

    assert!(
        actor.finalize_pending_block(lock, pending, None),
        "already committed block should short-circuit finalize"
    );
    assert_eq!(
        actor.locked_qc,
        Some(lock),
        "already committed finalize should advance the lock"
    );
    assert_eq!(
        actor.highest_qc,
        Some(lock),
        "already committed finalize should advance highest QC"
    );

    super::status::set_locked_qc(0, 0, None);
    super::status::set_highest_qc(0, 0);
    super::status::set_highest_qc_hash(HashOf::from_untyped_unchecked(Hash::prehashed(
        [0; Hash::LENGTH],
    )));
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn finalize_pending_block_commits_retired_same_height_with_conflicting_local_vote() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(&actor.state);
    actor.process_committed_blocks_before_consensus("finalize_retired_same_height_conflict_test");
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(u64::MAX)
        .saturating_add(1);
    let parent = Some(genesis_hash);

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let epoch = actor.epoch_for_height(height);

    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let canonical_roster =
        super::roster::canonicalize_roster_for_mode(topology.as_ref().to_vec(), consensus_mode);
    let canonical_topology = super::network_topology::Topology::new(canonical_roster);
    let canonical_signature_topology =
        super::topology_for_view(&canonical_topology, height, 0, mode_tag, prf_seed);
    let canonical_signer = canonical_signature_topology
        .as_ref()
        .first()
        .expect("canonical signature topology not empty");
    let canonical_keypair = harness
        .key_pairs
        .iter()
        .find(|keypair| keypair.public_key() == canonical_signer.public_key())
        .expect("canonical signer keypair exists");
    let canonical_signer_idx = canonical_signature_topology
        .position(canonical_keypair.public_key())
        .expect("canonical signer index in topology");
    let canonical_block = heartbeat_block_for_state(
        actor.state.as_ref(),
        &actor.common_config.chain,
        height,
        0,
        parent,
        canonical_keypair,
        u64::try_from(canonical_signer_idx).expect("canonical signer index fits u64"),
    );
    let conflicting_block = nonempty_block_for_actor(actor, &harness.key_pairs, height, 1, parent);
    insert_validated_pending(actor, conflicting_block.clone());
    assert!(actor.emit_precommit_vote(
        conflicting_block.hash(),
        height,
        1,
        epoch,
        ValidationStatus::Valid,
        &topology,
        conflicting_block.header().prev_block_hash(),
        Some((zero_state_root(), zero_state_root())),
    ));

    let canonical_hash = canonical_block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&canonical_block));
    let canonical_roots =
        validated_roots_for_actor_block(actor, canonical_block.clone(), &topology);
    let mut pending = PendingBlock::new(canonical_block.clone(), payload_hash, height, 0);
    pending.validation_status = ValidationStatus::Valid;
    pending.parent_state_root = Some(canonical_roots.parent_state_root);
    pending.post_state_root = Some(canonical_roots.post_state_root);
    pending.retire_same_height();
    pending.note_commit_qc_observed(epoch);
    pending.commit_qc_epoch = Some(epoch);

    let mut qc = qc_with_bitmap_for_actor(
        actor,
        canonical_hash,
        height,
        0,
        epoch,
        vec![0b0000_1111],
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    qc.parent_state_root = canonical_roots.parent_state_root;
    qc.post_state_root = canonical_roots.post_state_root;
    resign_qc_for_actor(&mut qc, actor, &harness.key_pairs);
    actor.qc_cache.insert(Actor::qc_tally_key(&qc), qc);

    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: canonical_hash,
        height,
        view: 0,
        epoch,
    };

    let committed = actor.finalize_pending_block(lock, pending, None);
    assert!(
        committed,
        "a certified commit must finalize even when local same-height vote history conflicts"
    );
    assert_eq!(
        u64::try_from(actor.state.committed_height()).unwrap_or(u64::MAX),
        height,
        "certified retired branch should advance the committed height despite prior local conflict"
    );
    assert_eq!(
        actor.state.latest_block_hash_fast(),
        Some(canonical_hash),
        "the certified branch should become the committed tip"
    );
    assert!(
        !actor.pending.pending_blocks.contains_key(&canonical_hash),
        "committed retired branch should leave pending storage"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn apply_commit_qc_promotes_qc_state_for_already_committed_block_without_pending() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(actor.state.as_ref());
    let height = 2_u64;
    let view = 0_u64;
    let block_hash = seed_block_for_state(actor.state.as_ref(), height, genesis_hash);

    let parent_qc = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: genesis_hash,
        height: 1,
        view: 0,
        epoch: actor.epoch_for_height(1),
    };
    actor.locked_qc = Some(parent_qc);
    actor.highest_qc = Some(parent_qc);
    super::status::set_locked_qc(1, 0, Some(genesis_hash));
    super::status::set_highest_qc(1, 0);
    super::status::set_highest_qc_hash(genesis_hash);

    let roster = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(roster.clone());
    let required = topology.min_votes_for_commit().max(1);
    let mut signers = BTreeSet::new();
    for idx in 0..topology.as_ref().len() {
        if signers.len() >= required {
            break;
        }
        signers.insert(
            ValidatorIndex::try_from(u32::try_from(idx).expect("signer idx fits"))
                .expect("signer idx fits"),
        );
    }
    let signers_bitmap = super::build_signers_bitmap(&signers, topology.as_ref().len());
    let qc = qc_with_bitmap(
        &actor.common_config.chain,
        block_hash,
        height,
        view,
        actor.epoch_for_height(height),
        signers_bitmap,
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );

    actor.apply_commit_qc(&qc, &roster, block_hash, height, view);

    let expected = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height,
        view,
        epoch: actor.epoch_for_height(height),
    };
    assert_eq!(
        actor.locked_qc,
        Some(expected),
        "commit QC should promote the lock even if the pending block is already gone"
    );
    assert_eq!(
        actor.highest_qc,
        Some(expected),
        "commit QC should promote highest QC even if the pending block is already gone"
    );

    super::status::set_locked_qc(0, 0, None);
    super::status::set_highest_qc(0, 0);
    super::status::set_highest_qc_hash(HashOf::from_untyped_unchecked(Hash::prehashed(
        [0; Hash::LENGTH],
    )));
    harness.shutdown.send();
}

