#[tokio::test(flavor = "current_thread")]
async fn commit_rejection_records_invalid_proposal_view() {
    let mut harness = test_actor_harness(1).await;
    let actor = &mut harness.actor;

    let height = 5u64;
    let view = 2u64;
    let parent_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x22; Hash::LENGTH]));
    let block = sample_block(height, view, Some(parent_hash));
    let failed_block = block.clone();
    let block_hash = block.hash();
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    let pending = PendingBlock::new(block, payload_hash, height, view);
    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: parent_hash,
        height: height.saturating_sub(1),
        view: view.saturating_sub(1),
        epoch: 0,
    };
    let commit_topology = actor.effective_commit_topology();
    let signature_topology = commit_topology.clone();
    let topology = super::network_topology::Topology::new(signature_topology.clone());
    let min_votes_for_commit = topology.min_votes_for_commit();
    let mut signers = BTreeSet::new();
    for idx in 0..min_votes_for_commit {
        signers.insert(ValidatorIndex::try_from(idx).expect("signer index fits"));
    }
    let inflight = CommitInFlight {
        id: 12,
        lock,
        block_hash,
        pending,
        commit_topology,
        signature_topology,
        qc_signers: Some(signers),
        commit_qc: None,
        post_commit_qc: None,
        enqueue_time: Instant::now(),
        timeout_reported: false,
    };
    actor.subsystems.commit.inflight = Some(inflight);

    let (result_tx, result_rx) = mpsc::sync_channel(1);
    actor.subsystems.commit.result_rx = Some(result_rx);

    let outcome = commit::CommitOutcome::Rejected {
        failed_block,
        error: BlockValidationError::EmptyBlock,
        pipeline_events: Vec::new(),
    };
    result_tx
        .send(commit::CommitResult {
            id: 12,
            outcome,
            timings: commit::CommitStageTimings::default(),
        })
        .expect("send commit result");

    actor.process_commit_candidates_with_trigger(CommitPipelineTrigger::Tick, None);

    let evidence_view = actor.state.world.consensus_evidence.view();
    let mut recorded_view = None;
    for (_, record) in evidence_view.iter() {
        if let crate::sumeragi::consensus::EvidencePayload::InvalidProposal { proposal, .. } =
            &record.evidence.payload
        {
            recorded_view = Some(proposal.header.view);
        }
    }
    let recorded_view = recorded_view.expect("invalid proposal evidence recorded");
    assert_eq!(recorded_view, view);
    assert_ne!(recorded_view, height);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_inflight_timeout_reports_and_keeps_inflight_result_attachable() {
    let mut cfg = test_sumeragi_config();
    cfg.consensus_mode = ConsensusMode::Permissioned;
    cfg.da.enabled = true;
    cfg.persistence.commit_inflight_timeout = Duration::from_millis(10);
    let mut harness = test_actor_harness_with_config(1, cfg, None).await;

    // This test asserts on global view-change cause counters. Hold the test guard for the full
    // duration so other concurrently running unit tests do not record into the same counters.
    let _view_change_guard = super::status::view_change_cause_test_guard();
    super::status::reset_view_change_cause_counters_for_tests();

    let height = 1;
    let view = 0u64;
    let block = sample_block(height, view, None);
    let block_hash = block.hash();
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    let pending = PendingBlock::new(block, payload_hash, height, view);
    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height,
        view,
        epoch: 0,
    };
    let commit_topology = harness.actor.effective_commit_topology();
    let signature_topology = commit_topology.clone();
    let inflight = CommitInFlight {
        id: 17,
        lock,
        block_hash,
        pending,
        commit_topology,
        signature_topology,
        qc_signers: None,
        commit_qc: None,
        post_commit_qc: None,
        enqueue_time: Instant::now() - Duration::from_millis(50),
        timeout_reported: false,
    };
    harness.actor.subsystems.commit.inflight = Some(inflight);
    harness
        .actor
        .slot_tracker
        .proposals_seen
        .insert((height, view));

    harness
        .actor
        .process_commit_candidates_with_trigger(CommitPipelineTrigger::Tick, None);

    let inflight = harness
        .actor
        .subsystems
        .commit
        .inflight
        .as_ref()
        .expect("timed-out commit must remain inflight until the worker result arrives");
    assert_eq!(inflight.block_hash, block_hash);
    assert!(
        inflight.timeout_reported,
        "timeout should be recorded without detaching the worker result"
    );
    assert!(
        !harness
            .actor
            .pending
            .pending_blocks
            .contains_key(&block_hash),
        "timed-out inflight work must not be reinserted as an aborted pending block"
    );
    assert!(
        harness
            .actor
            .slot_tracker
            .proposals_seen
            .contains(&(height, view)),
        "timed-out inflight work should not prune the active view"
    );
    assert_eq!(
        harness.actor.phase_tracker.current_view(height),
        None,
        "timeout reporting should not trigger a view change"
    );
    assert_eq!(
        harness.actor.subsystems.propose.forced_view_after_timeout, None,
        "timeout reporting should not force a proposal view"
    );
    let snapshot = super::status::snapshot().view_change_causes;
    assert_eq!(snapshot.commit_failure_total, 0);

    super::status::reset_view_change_cause_counters_for_tests();

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn stalled_pending_timeout_defers_view_change_while_commit_inflight_owns_frontier() {
    use std::borrow::Cow;

    let mut cfg = test_sumeragi_config();
    cfg.consensus_mode = ConsensusMode::Permissioned;
    cfg.da.enabled = true;
    cfg.resilience.enabled = true;
    let mut harness = test_actor_harness_with_config(4, cfg, None).await;
    let actor = &mut harness.actor;

    let view = actor.state.view();
    let committed_height = view.height() as u64;
    let height = committed_height.saturating_add(1);
    let parent = view.latest_block_hash();
    drop(view);

    let view_idx = 0_u64;
    let block = sample_block(height, view_idx, parent);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let now = Instant::now();
    let base_timeout = actor.commit_quorum_timeout().max(Duration::from_millis(1));
    let backlog_timeout = actor.backlog_extended_view_change_timeout(base_timeout, true);
    let frontier_timeout =
        super::saturating_mul_duration(actor.recovery_deferred_qc_ttl(), 2).max(backlog_timeout);
    let stalled_at = now
        .checked_sub(frontier_timeout.saturating_add(Duration::from_millis(1)))
        .unwrap_or(now);

    let mut inflight = commit_inflight_for_block(actor, block, height, view_idx);
    inflight.pending.validation_status = ValidationStatus::Valid;
    inflight
        .pending
        .note_commit_qc_observed(actor.epoch_for_height(height));
    inflight.pending.touch_progress(stalled_at);
    inflight.enqueue_time = stalled_at;
    actor.subsystems.commit.inflight = Some(inflight);
    actor.note_proposal_seen(height, view_idx, payload_hash);
    actor
        .phase_tracker
        .on_view_change(height, view_idx, stalled_at);
    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(sample_transaction())),
            actor.state.view(),
        )
        .expect("push queued transaction");

    assert!(
        !actor.maybe_force_view_change_for_stalled_pending(now),
        "a stalled frontier commit worker must remain attachable instead of triggering view churn"
    );
    assert!(
        actor
            .subsystems
            .commit
            .inflight
            .as_ref()
            .is_some_and(|inflight| inflight.block_hash == block_hash),
        "the active commit worker should keep owning the frontier"
    );
    assert_eq!(
        actor.phase_tracker.current_view(height),
        Some(view_idx),
        "view should not advance while a matching commit worker owns the frontier"
    );
    assert!(
        actor.subsystems.propose.forced_view_after_timeout.is_none(),
        "forced-view marker should stay clear while waiting for the commit result"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn late_successful_commit_result_after_timeout_is_applied() {
    let mut cfg = test_sumeragi_config();
    cfg.consensus_mode = ConsensusMode::Permissioned;
    cfg.da.enabled = true;
    cfg.persistence.commit_inflight_timeout = Duration::from_millis(10);
    let mut harness = test_actor_harness_with_config(1, cfg, None).await;
    let actor = &mut harness.actor;
    let (block_hash, height, _block, mut inflight, work) =
        start_commit_job_fixture(actor, &harness.key_pairs, 95);
    inflight.enqueue_time = Instant::now() - Duration::from_millis(50);

    let (result_tx, result_rx) = mpsc::sync_channel(1);
    actor.subsystems.commit.result_rx = Some(result_rx);
    actor.subsystems.commit.inflight = Some(inflight);

    actor.process_commit_candidates_with_trigger(CommitPipelineTrigger::Tick, None);
    assert!(
        actor
            .subsystems
            .commit
            .inflight
            .as_ref()
            .is_some_and(|inflight| {
                inflight.block_hash == block_hash && inflight.timeout_reported
            }),
        "timeout should leave the matching inflight marker in place"
    );

    let (outcome, timings) = execute_commit_work_on_test_stack(
        Arc::clone(&actor.state),
        Arc::clone(&actor.kura),
        actor.common_config.chain.clone(),
        actor.genesis_account.clone(),
        work,
    );
    match &outcome {
        commit::CommitOutcome::Success { .. } => {}
        commit::CommitOutcome::Rejected { error, .. } => {
            panic!("commit work should succeed after timeout: rejected with {error:?}");
        }
        commit::CommitOutcome::KuraStoreFailed { error, .. } => {
            panic!("commit work should succeed after timeout: Kura store failed: {error:?}");
        }
        commit::CommitOutcome::StateCommitFailed { error, .. } => {
            panic!("commit work should succeed after timeout: state commit failed: {error}");
        }
    }
    result_tx
        .send(commit::CommitResult {
            id: 95,
            outcome,
            timings,
        })
        .expect("send late commit result");

    let summary = actor.drain_commit_results();
    assert!(
        summary.progress,
        "late worker result should still be applied"
    );
    assert_eq!(summary.results, 1);
    assert!(
        actor.subsystems.commit.inflight.is_none(),
        "applying the late result should clear inflight state"
    );
    assert_eq!(
        actor.state.latest_block_hash_fast(),
        Some(block_hash),
        "late successful result should reconcile the actor to the committed block"
    );
    assert!(
        u64::try_from(actor.state.committed_height()).unwrap_or_default() >= height,
        "late successful result should keep committed height advanced"
    );
    assert!(
        !actor
            .pending
            .pending_blocks
            .get(&block_hash)
            .is_some_and(|pending| pending.aborted),
        "late successful result must not leave an aborted pending wrapper behind"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_vote_targets_collectors_or_topology() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);
    let height = 1;
    let block = sample_block(height, 0, None);
    let block_hash = block.hash();
    let parent_hash = block.header().prev_block_hash();
    insert_validated_pending(actor, block.clone());
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let epoch = actor.epoch_for_height(height);
    actor.reset_collector_state();

    let _ = harness.background_rx.try_iter().count();

    let emitted = actor.emit_precommit_vote(
        block_hash,
        1,
        0,
        epoch,
        ValidationStatus::Valid,
        &topology,
        parent_hash,
        Some((Hash::new([]), Hash::new([]))),
    );
    assert!(emitted, "expected local commit vote to be emitted");

    let min_votes_for_commit = topology.min_votes_for_commit().max(1);
    let expected_set: BTreeSet<_> = actor
        .quorum_retransmit_targets_for_missing_votes(
            block_hash,
            1,
            0,
            topology.as_ref(),
            min_votes_for_commit,
            1,
        )
        .into_iter()
        .collect();

    let actual_targets: BTreeSet<_> = take_background_log(&background_log)
        .into_iter()
        .filter_map(|entry| {
            (entry.kind == super::BackgroundRequestLogKind::Post
                && entry.msg_kind == Some("QcVote"))
            .then_some(entry.peer)
        })
        .flatten()
        .collect();

    assert_eq!(
        actual_targets, expected_set,
        "initial commit votes should target quorum retransmit peers"
    );

    harness.shutdown.send();
}

