#[test]
fn block_body_response_retains_same_height_known_block_commit_qc_repair_after_frontier_view_advances()
 {
    crate::sumeragi::sumeragi_thread_builder("sumeragi-block-body-response-repair-test")
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .expect("build tokio test runtime");
            runtime.block_on(block_body_response_repair_after_frontier_view_advances_impl());
        })
        .expect("spawn block-body response repair test worker")
        .join()
        .expect("block-body response repair test worker should not panic");
}

async fn block_body_response_repair_after_frontier_view_advances_impl() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let parent_hash = seed_genesis_block_for_state(actor.state.as_ref());
    let height = actor.committed_height_snapshot().saturating_add(1);
    let owner_view = 2_u64;
    let repair_view = 0_u64;

    let owner_block = nonempty_block_for_actor(
        actor,
        &harness.key_pairs,
        height,
        owner_view,
        Some(parent_hash),
    );
    let owner_hash = insert_validated_pending(actor, owner_block);
    let now = Instant::now();
    assert!(actor.update_frontier_slot(
        owner_hash,
        height,
        owner_view,
        None,
        BTreeSet::new(),
        /*block_created_seen*/ true,
        /*exact_fetch_armed*/ true,
        /*body_present*/ true,
        None,
        None,
        now,
    ));

    let repair_block = nonempty_block_for_actor(
        actor,
        &harness.key_pairs,
        height,
        repair_view,
        Some(parent_hash),
    );
    let repair_hash = repair_block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&repair_block));
    let mut repair_pending =
        PendingBlock::new(repair_block.clone(), payload_hash, height, repair_view);
    repair_pending.validation_status = ValidationStatus::Valid;
    repair_pending.parent_state_root = Some(zero_state_root());
    repair_pending.post_state_root = Some(zero_state_root());
    repair_pending.retire_same_height();
    actor
        .pending
        .pending_blocks
        .insert(repair_hash, repair_pending);
    actor.pending.missing_commit_qc_requests.insert(
        repair_hash,
        super::MissingBlockRequest {
            height,
            view: repair_view,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window: Duration::from_millis(25),
            view_change_window: Some(Duration::from_millis(200)),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 1,
        },
    );

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let signers: BTreeSet<ValidatorIndex> = topology
        .as_ref()
        .iter()
        .enumerate()
        .map(|(idx, _)| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_bitmap = super::build_signers_bitmap(&signers, topology.as_ref().len());
    let epoch = actor.epoch_for_height(height);
    let qc = qc_with_bitmap(
        &actor.common_config.chain,
        repair_hash,
        height,
        repair_view,
        epoch,
        signers_bitmap.clone(),
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    let checkpoint = ValidatorSetCheckpoint::new(
        height,
        repair_view,
        repair_hash,
        qc.parent_state_root,
        qc.post_state_root,
        actor.effective_commit_topology(),
        signers_bitmap,
        qc.aggregate.bls_aggregate_signature.clone(),
        VALIDATOR_SET_HASH_VERSION_V1,
        None,
    );
    let mut update = super::message::BlockSyncUpdate::from(&repair_block);
    update.commit_qc = Some(qc);
    update.validator_checkpoint = Some(checkpoint);
    update.commit_votes.clear();
    let response = super::message::BlockBodyResponse {
        block_hash: repair_hash,
        height,
        view: repair_view,
        body: super::message::BlockBodyData::BlockSyncUpdate(update),
    };
    let dedup_key = crate::sumeragi::BlockPayloadDedupKey::BlockBodyResponse {
        height,
        view: repair_view,
        block_hash: repair_hash,
        evidence_hash: crate::sumeragi::block_body_response_evidence_hash(&response),
    };
    {
        let mut guard = actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned");
        guard.insert(dedup_key, Instant::now());
    }

    let sender = actor
        .effective_commit_topology()
        .into_iter()
        .find(|peer| peer != actor.common_config.peer.id())
        .expect("remote sender");

    actor
        .handle_block_body_response(response, Some(sender))
        .expect("same-height known-block commit-QC repair response handled");
    drain_known_block_qc_work(actor);

    assert!(
        !actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned")
            .contains(&dedup_key),
        "same-height commit-QC repair responses should always release dedup after processing"
    );
    let slot = actor
        .frontier_slot
        .as_ref()
        .expect("later same-height owner should remain active");
    assert_eq!(slot.block_hash, owner_hash);
    assert_eq!(slot.view, owner_view);
    assert!(
        !actor
            .pending
            .missing_commit_qc_requests
            .contains_key(&repair_hash),
        "accepted same-height commit-QC repair should retire the missing commit-QC request"
    );
    assert!(
        actor
            .state
            .view()
            .world()
            .commit_qcs()
            .get(&repair_hash)
            .is_some(),
        "same-height commit-QC repair should still record the recovered certificate"
    );

    harness.shutdown.send();
}

#[test]
fn block_sync_update_targets_cover_full_roster_when_limit_allows() {
    let peers: Vec<_> = (0..4)
        .map(|_| PeerId::new(checked_bls_keypair().public_key().clone()))
        .collect();
    let local_peer = peers[0].clone();
    let registered_peers = peers.clone();
    let online_peers = vec![peers[1].clone()];
    let gossip_limit = peers.len().saturating_sub(1);
    let seed = [7_u8; 32];

    let targets = Actor::block_sync_update_targets_for_peers(
        &local_peer,
        gossip_limit,
        &peers,
        &registered_peers,
        &[],
        &online_peers,
        &seed,
    );

    let expected: BTreeSet<_> = online_peers.into_iter().collect();
    let actual: BTreeSet<_> = targets.into_iter().collect();
    assert_eq!(
        actual, expected,
        "gossip targets should prefer online roster peers when available"
    );
}

#[tokio::test(flavor = "current_thread")]
async fn precommit_vote_targets_collectors_without_broadcast() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);
    let height = 1;
    let block = sample_block(height, 0, None);
    let block_hash = block.hash();
    insert_validated_pending(actor, block.clone());
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let epoch = actor.epoch_for_height(height);
    actor.reset_collector_state();

    let _ = take_background_log(&background_log);

    let emitted = actor.emit_precommit_vote(
        block_hash,
        1,
        0,
        epoch,
        ValidationStatus::Valid,
        &topology,
        block.header().prev_block_hash(),
        Some((Hash::new([]), Hash::new([]))),
    );
    assert!(emitted, "expected local precommit vote to be emitted");

    let min_votes_for_commit = topology.min_votes_for_commit().max(1);
    let expected_set: BTreeSet<_> = actor
        .quorum_retransmit_targets_for_missing_votes(
            block_hash,
            height,
            0,
            topology.as_ref(),
            min_votes_for_commit,
            1,
        )
        .into_iter()
        .collect();

    let actual_contacted: BTreeSet<_> = actor
        .subsystems
        .propose
        .collectors_contacted
        .iter()
        .cloned()
        .collect();
    let actual_targets: BTreeSet<_> = take_background_log(&background_log)
        .into_iter()
        .filter_map(|entry| match entry {
            super::BackgroundRequestLogEntry {
                kind: super::BackgroundRequestLogKind::Post,
                msg_kind: Some("QcVote"),
                peer: Some(peer),
            } => Some(peer),
            _ => None,
        })
        .collect();

    assert_eq!(
        actual_contacted.len(),
        1,
        "initial precommit emit should keep exactly one seeded collector before any retransmit widening"
    );

    assert_eq!(
        actual_targets, expected_set,
        "precommit votes should target quorum retransmit peers even before collector widening"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn precommit_vote_falls_back_to_seeded_collectors_when_quorum_targets_are_satisfied() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Npos;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);
    actor.config.collectors.parallel_topology_fanout = 0;

    let height = 1;
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let local_peer = actor.common_config.peer.id().clone();
    let view = (0..256_u64)
        .find(|candidate_view| {
            actor.reset_collector_state();
            let signature_topology = super::topology_for_view(
                &topology,
                height,
                *candidate_view,
                actor.mode_tag(),
                actor.npos_prf_seed(),
            );
            actor.init_collector_plan(&signature_topology, height, *candidate_view);
            actor
                .subsystems
                .propose
                .collectors_contacted
                .iter()
                .any(|peer| peer != &local_peer)
        })
        .expect("expected a view with a remote seeded collector");
    actor.reset_collector_state();

    let parent_hash = HashOf::<BlockHeader>::from_untyped_unchecked(Hash::new(
        b"precommit_vote_falls_back_to_seeded_collectors_when_quorum_targets_are_satisfied",
    ));
    let block = sample_block(height, view, Some(parent_hash));
    let block_hash = block.hash();
    insert_validated_pending(actor, block.clone());

    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let epoch = actor.epoch_for_height(height);
    for (signer_idx, peer) in signature_topology.as_ref().iter().enumerate() {
        if peer == &local_peer {
            continue;
        }
        let signer = ValidatorIndex::try_from(signer_idx).expect("signer fits u32");
        actor.vote_log.insert(
            default_vote_log_key(Phase::Commit, height, view, epoch, signer),
            crate::sumeragi::consensus::Vote {
                phase: Phase::Commit,
                block_hash,
                parent_state_root: zero_state_root(),
                post_state_root: zero_state_root(),
                height,
                view,
                epoch,
                chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
                rechain_seq: 0,
                highest_qc: None,
                signer,
                bls_sig: Vec::new(),
            },
        );
    }

    assert!(
        actor
            .quorum_retransmit_targets_for_missing_votes(
                block_hash,
                height,
                view,
                topology.as_ref(),
                topology.min_votes_for_commit().max(1),
                1,
            )
            .is_empty(),
        "cached remote commit votes should leave no quorum retransmit targets for the initial local precommit",
    );

    let _ = take_background_log(&background_log);
    assert!(
        actor.emit_precommit_vote(
            block_hash,
            height,
            view,
            epoch,
            ValidationStatus::Valid,
            &topology,
            block.header().prev_block_hash(),
            Some((Hash::new([]), Hash::new([]))),
        ),
        "expected local precommit vote to be emitted",
    );

    let expected_collectors: BTreeSet<_> = actor
        .subsystems
        .propose
        .collectors_contacted
        .iter()
        .filter(|peer| *peer != &local_peer)
        .cloned()
        .collect();
    let actual_targets: BTreeSet<_> = take_background_log(&background_log)
        .into_iter()
        .filter_map(|entry| match entry {
            super::BackgroundRequestLogEntry {
                kind: super::BackgroundRequestLogKind::Post,
                msg_kind: Some("QcVote"),
                peer: Some(peer),
            } => Some(peer),
            _ => None,
        })
        .collect();

    assert_eq!(
        expected_collectors.len(),
        1,
        "collector seeding should still preserve exactly one remote fallback target",
    );
    assert_eq!(
        actual_targets, expected_collectors,
        "initial precommit emit should fall back to the seeded collector subset once quorum retransmit targets are already satisfied",
    );

    harness.shutdown.send();
}

