#[tokio::test(flavor = "current_thread")]
async fn rebuild_qcs_from_cached_votes_uses_snapshot_roster() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let parent = actor.state.view().latest_block_hash();
    let block = sample_block(2, 0, parent);
    let block_hash = block.hash();
    let height = 2;
    let view = block.header().view_change_index();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );

    let mut snapshot_roster = actor.effective_commit_topology();
    let local_peer = actor.common_config.peer.id().clone();
    let removed_peer = snapshot_roster
        .iter()
        .find(|peer| *peer != &local_peer)
        .cloned()
        .expect("non-local roster entry");
    snapshot_roster.retain(|peer| peer != &removed_peer);

    let topology = super::network_topology::Topology::new(snapshot_roster.clone());
    let signers: BTreeSet<ValidatorIndex> = (0..snapshot_roster.len())
        .map(|idx| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_bitmap = super::build_signers_bitmap(&signers, snapshot_roster.len());
    let epoch = actor.epoch_for_height(height);
    let signature_topology = super::topology_for_view(
        &topology,
        height,
        view,
        super::PERMISSIONED_TAG,
        Some(prf_seed_for_chain(&actor.common_config.chain)),
    );
    let (chain_order_hash, rechain_seq) = actor.vnext_chain_order_binding_for_signature_topology(
        height,
        view,
        ConsensusMode::Permissioned,
        &signature_topology,
    );
    let mut commit_qc = qc_with_bitmap(
        &actor.common_config.chain,
        block_hash,
        height,
        view,
        epoch,
        signers_bitmap.clone(),
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    commit_qc.chain_order_hash = chain_order_hash;
    commit_qc.rechain_seq = rechain_seq;
    resign_qc_for_actor(&mut commit_qc, actor, &harness.key_pairs);
    let checkpoint_signature = aggregate_vote_signature_for_bitmap_with_chain_order(
        &actor.common_config.chain,
        PERMISSIONED_TAG,
        block_hash,
        height,
        view,
        epoch,
        chain_order_hash,
        rechain_seq,
        &signers_bitmap,
        &topology,
        &harness.key_pairs,
    );
    let checkpoint = ValidatorSetCheckpoint::new_with_chain_order(
        height,
        view,
        block_hash,
        chain_order_hash,
        rechain_seq,
        commit_qc.parent_state_root,
        commit_qc.post_state_root,
        snapshot_roster.clone(),
        signers_bitmap,
        checkpoint_signature,
        VALIDATOR_SET_HASH_VERSION_V1,
        None,
    );
    {
        let mut journal = actor.state.commit_roster_journal.write();
        journal.upsert(commit_qc, checkpoint, None);
    }

    let commit_topology =
        actor.roster_for_vote_with_mode(block_hash, height, view, ConsensusMode::Permissioned);
    assert_eq!(
        commit_topology, snapshot_roster,
        "expected BlockCreated to rebuild QC using the snapshot roster"
    );

    for signer in 0..snapshot_roster.len() {
        let mut vote = crate::sumeragi::consensus::Vote {
            phase: Phase::Commit,
            block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: None,
            signer: u32::try_from(signer).expect("signer fits u32"),
            bls_sig: Vec::new(),
        };
        sign_vote_for_canonical_signer(
            &mut vote,
            &actor.common_config.chain,
            &topology,
            &harness.key_pairs,
        );
        actor.vote_log.insert(vote_log_key_for_vote(&vote), vote);
    }

    let valid_signers = actor.qc_signers_for_votes(
        Phase::Commit,
        block_hash,
        height,
        view,
        epoch,
        &signature_topology,
    );
    assert_eq!(
        valid_signers.len(),
        snapshot_roster.len(),
        "expected all cached votes to validate before QC rebuild"
    );

    actor.rebuild_qcs_from_cached_votes(&actor.effective_commit_topology());

    let key = (
        Phase::Commit,
        block_hash,
        height,
        view,
        epoch,
        chain_order_hash,
        rechain_seq,
    );
    let qc = actor
        .qc_cache
        .get(&key)
        .expect("QC rebuilt from cached votes");
    assert_eq!(
        qc.validator_set, snapshot_roster,
        "QC rebuild should honor the snapshot roster"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rebuild_qcs_from_cached_votes_does_not_quarantine_uncommitted_sidecar_mismatch() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let parent = actor.state.view().latest_block_hash();
    let block = sample_block(2, 0, parent);
    let block_hash = block.hash();
    let height = 2;
    let view = block.header().view_change_index();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );

    let sidecar_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x7E; Hash::LENGTH]));
    assert_ne!(
        sidecar_hash, block_hash,
        "test requires sidecar hash to differ from rebuild candidate hash"
    );
    actor
        .kura
        .write_roster_metadata(&crate::kura::RosterSidecar::new(
            height,
            sidecar_hash,
            None,
            None,
            None,
        ));

    let missing_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x7F; Hash::LENGTH]));
    assert!(
        !actor.block_payload_available_locally(missing_hash),
        "test requires unresolved missing payload hash"
    );
    let now = Instant::now();
    actor.pending.missing_block_requests.insert(
        missing_hash,
        super::MissingBlockRequest {
            height,
            view,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window: Duration::from_millis(1),
            view_change_window: Some(Duration::from_millis(2)),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let epoch = actor.epoch_for_height(height);
    let mut vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: 0,
        bls_sig: Vec::new(),
    };
    sign_vote_for_canonical_signer(
        &mut vote,
        &actor.common_config.chain,
        &topology,
        &harness.key_pairs,
    );
    actor.vote_log.insert(vote_log_key_for_vote(&vote), vote);

    actor.rebuild_qcs_from_cached_votes(&actor.effective_commit_topology());

    assert!(
        !actor.sidecar_quarantined_for_height(height),
        "qc rebuild replay must not quarantine uncommitted sidecar mismatch branches"
    );
    assert!(
        actor.sidecar_mismatch_recovery.get(&height).is_none(),
        "qc rebuild replay must not record fail-closed sidecar mismatch state"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rebuild_qcs_from_cached_votes_uses_new_view_roster_for_new_view_phase() {
    let _guard = super::status::qc_status_test_guard();
    super::status::reset_commit_certs_for_tests();

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let parent = Some(seed_genesis_block_for_state(&actor.state));
    let target_parent_block = sample_block(2, 0, parent);
    let target_parent_hash = target_parent_block.hash();
    actor
        .kura
        .store_block(target_parent_block)
        .expect("store targeted parent block");

    let height = 3u64;
    let view = 5u64;
    let epoch = actor.epoch_for_height(height);
    let parent_epoch = actor.epoch_for_height(height.saturating_sub(1));
    let canonical_roster = actor.effective_commit_topology();
    assert!(
        canonical_roster.len() >= 3,
        "test requires a multi-validator roster"
    );

    let fallback_parent_roster = canonical_roster.clone();
    let target_parent_roster =
        canonical_roster[..canonical_roster.len().saturating_sub(1)].to_vec();
    assert_ne!(
        fallback_parent_roster, target_parent_roster,
        "test requires distinct parent rosters"
    );

    let all_signers: BTreeSet<ValidatorIndex> = (0..target_parent_roster.len())
        .map(|idx| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_bitmap = super::build_signers_bitmap(&all_signers, target_parent_roster.len());
    let target_parent_topology =
        super::network_topology::Topology::new(target_parent_roster.clone());
    let target_parent_qc = qc_with_bitmap(
        &actor.common_config.chain,
        target_parent_hash,
        height.saturating_sub(1),
        0,
        parent_epoch,
        signers_bitmap,
        Phase::Commit,
        &target_parent_topology,
        &harness.key_pairs,
    );
    super::status::record_commit_qc(target_parent_qc);
    actor.cache_vote_roster(
        target_parent_hash,
        height,
        view,
        fallback_parent_roster.clone(),
    );

    let vote_roster = actor.roster_for_vote_with_mode(
        target_parent_hash,
        height,
        view,
        ConsensusMode::Permissioned,
    );
    let new_view_roster = actor.roster_for_new_view_with_mode(
        target_parent_hash,
        height,
        view,
        ConsensusMode::Permissioned,
    );
    assert_ne!(
        vote_roster, new_view_roster,
        "test requires NewView roster selection to differ from generic vote replay"
    );

    let expected_new_view_roster =
        super::roster::canonicalize_roster_for_mode(new_view_roster, ConsensusMode::Permissioned);
    let new_view_topology =
        super::network_topology::Topology::new(expected_new_view_roster.clone());
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology =
        super::topology_for_view(&new_view_topology, height, view, mode_tag, prf_seed);
    let (chain_order_hash, rechain_seq) = actor.vnext_chain_order_binding_for_signature_topology(
        height,
        view,
        ConsensusMode::Permissioned,
        &signature_topology,
    );
    let highest_qc = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: target_parent_hash,
        height: height.saturating_sub(1),
        view: 0,
        epoch: parent_epoch,
    };
    for signer in 0..new_view_topology.as_ref().len() {
        let mut vote = crate::sumeragi::consensus::Vote {
            phase: Phase::NewView,
            block_hash: target_parent_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash,
            rechain_seq,
            highest_qc: Some(highest_qc),
            signer: u32::try_from(signer).expect("signer fits u32"),
            bls_sig: Vec::new(),
        };
        sign_vote_for_view_with_seed(
            &mut vote,
            &actor.common_config.chain,
            &new_view_topology,
            &harness.key_pairs,
            mode_tag,
            prf_seed,
        );
        actor.vote_log.insert(vote_log_key_for_vote(&vote), vote);
    }

    actor.rebuild_qcs_from_cached_votes(&actor.effective_commit_topology());

    let rebuilt = actor
        .qc_cache
        .get(&(
            Phase::NewView,
            target_parent_hash,
            height,
            view,
            epoch,
            chain_order_hash,
            rechain_seq,
        ))
        .expect("NewView QC rebuilt from cached votes");
    assert_eq!(
        rebuilt.validator_set, expected_new_view_roster,
        "NewView QC rebuild must use the NewView roster path instead of generic vote replay"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rebuild_qcs_from_cached_votes_skips_npos_candidates_without_stake_quorum() {
    let _guard = super::status::qc_status_test_guard();
    super::status::reset_qc_rebuild_counters_for_tests();

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Npos;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let parent = Some(seed_genesis_block_for_state(actor.state.as_ref()));
    let block = sample_block(2, 0, parent);
    let block_hash = block.hash();
    let height = 2_u64;
    let view = 0_u64;
    let epoch = actor.epoch_for_height(height);
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );

    let commit_topology = actor.effective_commit_topology();
    assert!(commit_topology.len() >= 4, "test requires 4 trusted peers");
    {
        let mut block = actor.state.world.public_lane_validators.block();
        let existing: Vec<_> = block.iter().map(|(key, _)| key.clone()).collect();
        for key in existing {
            block.remove(key);
        }
        for (idx, peer) in commit_topology.iter().take(2).enumerate() {
            let account_id = AccountId::new(peer.public_key().clone());
            let lane_id = LaneId::new(u32::try_from(idx + 1).expect("lane index fits u32"));
            let record = PublicLaneValidatorRecord {
                lane_id,
                validator: account_id.clone(),
                peer_id: peer.clone(),
                stake_account: account_id.clone(),
                total_stake: Numeric::new(1, 0),
                self_stake: Numeric::new(1, 0),
                metadata: iroha_data_model::metadata::Metadata::default(),
                status: PublicLaneValidatorStatus::Active,
                activation_epoch: None,
                activation_height: None,
                last_reward_epoch: None,
            };
            block.insert((record.lane_id, account_id), record);
        }
        block.commit();
    }

    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    assert!(
        matches!(consensus_mode, ConsensusMode::Npos),
        "test expects NPoS consensus"
    );
    let active_topology = actor.effective_commit_topology();
    assert_eq!(
        active_topology.len(),
        2,
        "active topology should be constrained to active validators"
    );
    let topology = super::network_topology::Topology::new(active_topology.clone());
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);

    let mut vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: 0,
        bls_sig: Vec::new(),
    };
    bind_vote_to_signature_topology_chain_order(&mut vote, actor, &signature_topology);
    let chain_order_hash = vote.chain_order_hash;
    let rechain_seq = vote.rechain_seq;
    sign_vote_for_view_with_seed(
        &mut vote,
        &actor.common_config.chain,
        &topology,
        &harness.key_pairs,
        mode_tag,
        prf_seed,
    );
    actor.vote_log.insert(vote_log_key_for_vote(&vote), vote);

    let signers = actor.qc_signers_for_votes(
        Phase::Commit,
        block_hash,
        height,
        view,
        epoch,
        &signature_topology,
    );
    assert_eq!(signers.len(), 1, "test expects exactly one cached signer");
    let signer_peers = super::signer_peers_for_topology(&signers, &signature_topology)
        .expect("vote signers should map to peers");
    assert!(
        !super::stake_snapshot::stake_quorum_reached_for_world(
            &actor.state.world_view(),
            &active_topology,
            &signer_peers,
        )
        .expect("stake quorum check should evaluate"),
        "single cached signer must not satisfy NPoS stake quorum"
    );

    actor.rebuild_qcs_from_cached_votes(&actor.effective_commit_topology());

    let snapshot = super::status::snapshot();
    assert_eq!(
        snapshot.qc_rebuild_attempts_total, 0,
        "NPoS replay should not attempt QC rebuild when cached votes cannot meet stake quorum"
    );
    assert_eq!(snapshot.qc_rebuild_successes_total, 0);

    let key = (
        Phase::Commit,
        block_hash,
        height,
        view,
        epoch,
        chain_order_hash,
        rechain_seq,
    );
    assert!(
        !actor.qc_cache.contains_key(&key),
        "stake-insufficient NPoS replay must not cache a QC"
    );
    assert!(
        !actor.deferred_qcs.contains_key(&key),
        "stake-insufficient NPoS replay must not defer a QC"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn precommit_qc_advances_locked_qc_when_block_known() {
    let _guard = super::status::qc_status_test_guard();
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let block1 = nonempty_block_for_actor(actor, &harness.key_pairs, 1, 0, None);
    let block2 = nonempty_block_for_actor(actor, &harness.key_pairs, 2, 0, Some(block1.hash()));

    actor
        .kura
        .store_block(block1.clone())
        .expect("store block1");
    actor
        .kura
        .store_block(block2.clone())
        .expect("store block2");

    let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
    state.push_block_hash_for_testing(block1.hash());

    actor.locked_qc = Some(QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block1.hash(),
        height: 1,
        view: 0,
        epoch: 0,
    });
    super::status::set_locked_qc(1, 0, Some(block1.hash()));

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let qc = qc_with_bitmap_for_actor(
        actor,
        block2.hash(),
        2,
        0,
        0,
        vec![0b0000_1111],
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );

    actor.handle_qc(qc).expect("handle precommit QC");

    let locked = actor.locked_qc.expect("locked qc should be set");
    assert_eq!(locked.height, 2);
    assert_eq!(locked.subject_block_hash, block2.hash());

    harness.shutdown.send();
}

