#[test]
fn select_new_view_highest_qc_accepts_prepare() {
    let highest_height = 1u64;
    let height = highest_height.saturating_add(1);
    let view = 0;
    let epoch = 0;
    let block = sample_block(highest_height, view, None);
    let block_hash = block.hash();
    let signer = ValidatorIndex::try_from(0).expect("signer index fits");
    let highest_prepare = QcHeaderRef {
        phase: Phase::Prepare,
        subject_block_hash: block_hash,
        height: highest_height,
        view,
        epoch,
    };
    let mut accepted_votes = BTreeMap::new();
    accepted_votes.insert(
        signer,
        crate::sumeragi::consensus::Vote {
            phase: Phase::NewView,
            block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: Some(highest_prepare),
            signer,
            bls_sig: Vec::new(),
        },
    );
    let mut signers = BTreeSet::new();
    signers.insert(signer);
    let selected = super::select_new_view_highest_qc_from_votes(
        &accepted_votes,
        &signers,
        height,
        view,
        epoch,
    )
    .expect("highest QC should be selected");
    assert_eq!(selected.phase, Phase::Prepare);
    assert_eq!(selected.height, highest_height);
    assert_eq!(selected.view, view);
    assert_eq!(selected.subject_block_hash, block_hash);

    let commit_signer = ValidatorIndex::try_from(1).expect("signer index fits");
    let highest_commit = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height: highest_height,
        view,
        epoch,
    };
    accepted_votes.insert(
        commit_signer,
        crate::sumeragi::consensus::Vote {
            phase: Phase::NewView,
            block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: Some(highest_commit),
            signer: commit_signer,
            bls_sig: Vec::new(),
        },
    );
    signers.insert(commit_signer);
    let selected = super::select_new_view_highest_qc_from_votes(
        &accepted_votes,
        &signers,
        height,
        view,
        epoch,
    )
    .expect("highest QC should be selected");
    assert_eq!(selected.phase, Phase::Commit);
}

#[test]
fn select_new_view_highest_qc_tiebreaks_same_rank_by_hash() {
    let highest_height = 1u64;
    let height = highest_height.saturating_add(1);
    let view = 0;
    let epoch = 0;
    let block_a_hash = sample_block(highest_height, view, None).hash();
    let block_b_hash = sample_block(highest_height, view.saturating_add(1), None).hash();
    assert_ne!(
        block_a_hash, block_b_hash,
        "test requires distinct same-rank block hashes"
    );
    let (lower_hash, higher_hash) = if block_a_hash < block_b_hash {
        (block_a_hash, block_b_hash)
    } else {
        (block_b_hash, block_a_hash)
    };
    let lower = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: lower_hash,
        height: highest_height,
        view,
        epoch,
    };
    let higher = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: higher_hash,
        height: highest_height,
        view,
        epoch,
    };
    let mut accepted_votes = BTreeMap::new();
    let mut signers = BTreeSet::new();
    for (signer, highest_qc) in [(0, lower), (1, higher)] {
        let signer = ValidatorIndex::try_from(signer).expect("signer index fits");
        accepted_votes.insert(
            signer,
            crate::sumeragi::consensus::Vote {
                phase: Phase::NewView,
                block_hash: highest_qc.subject_block_hash,
                parent_state_root: zero_state_root(),
                post_state_root: zero_state_root(),
                height,
                view,
                epoch,
                chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
                rechain_seq: 0,
                highest_qc: Some(highest_qc),
                signer,
                bls_sig: Vec::new(),
            },
        );
        signers.insert(signer);
    }

    let selected = super::select_new_view_highest_qc_from_votes(
        &accepted_votes,
        &signers,
        height,
        view,
        epoch,
    )
    .expect("highest QC should be selected");
    assert_eq!(selected, higher);
}

#[test]
fn same_rank_new_view_highest_qc_supersedes_by_hash_tiebreak() {
    let highest_height = 1u64;
    let height = highest_height.saturating_add(1);
    let view = 1;
    let epoch = 0;
    let block_a_hash = sample_block(highest_height, view, None).hash();
    let block_b_hash = sample_block(highest_height, view.saturating_add(1), None).hash();
    assert_ne!(
        block_a_hash, block_b_hash,
        "test requires distinct same-rank block hashes"
    );
    let (lower_hash, higher_hash) = if block_a_hash < block_b_hash {
        (block_a_hash, block_b_hash)
    } else {
        (block_b_hash, block_a_hash)
    };
    let lower = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: lower_hash,
        height: highest_height,
        view: 0,
        epoch,
    };
    let higher = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: higher_hash,
        height: highest_height,
        view: 0,
        epoch,
    };
    let chain_order = crate::sumeragi::consensus::default_chain_order_hash();
    let existing = crate::sumeragi::consensus::Vote {
        phase: Phase::NewView,
        block_hash: lower.subject_block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: chain_order,
        rechain_seq: 0,
        highest_qc: Some(lower),
        signer: ValidatorIndex::try_from(0).expect("signer index fits"),
        bls_sig: Vec::new(),
    };

    assert!(
        super::Actor::new_view_highest_qc_supersedes_same_slot_vote(
            &existing,
            height,
            view,
            epoch,
            (chain_order, 0),
            higher,
        ),
        "same-rank NEW_VIEW votes should use the deterministic hash tie-break"
    );
    assert!(
        !super::Actor::new_view_highest_qc_supersedes_same_slot_vote(
            &existing,
            height,
            view,
            epoch,
            (chain_order, 0),
            lower,
        ),
        "an equal highest-QC reference should not supersede itself"
    );
}

#[test]
fn new_view_highest_qc_signer_groups_require_exact_reference() {
    let highest_height = 1u64;
    let height = highest_height.saturating_add(1);
    let view = 0;
    let epoch = 0;
    let block_hash = sample_block(highest_height, view, None).hash();
    let lower = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height: highest_height,
        view,
        epoch,
    };
    let higher = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height: highest_height,
        view: view.saturating_add(1),
        epoch,
    };
    let mut accepted_votes = BTreeMap::new();
    let mut signers = BTreeSet::new();
    for (signer, highest_qc) in [(0, lower), (1, lower), (2, higher)] {
        let signer = ValidatorIndex::try_from(signer).expect("signer index fits");
        accepted_votes.insert(
            signer,
            crate::sumeragi::consensus::Vote {
                phase: Phase::NewView,
                block_hash,
                parent_state_root: zero_state_root(),
                post_state_root: zero_state_root(),
                height,
                view,
                epoch,
                chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
                rechain_seq: 0,
                highest_qc: Some(highest_qc),
                signer,
                bls_sig: Vec::new(),
            },
        );
        signers.insert(signer);
    }

    let groups =
        super::new_view_highest_qc_signer_groups(&accepted_votes, &signers, height, view, epoch);
    let lower_group = groups
        .iter()
        .find_map(|(highest_qc, group)| (*highest_qc == lower).then_some(group))
        .expect("lower highest-QC group present");
    let higher_group = groups
        .iter()
        .find_map(|(highest_qc, group)| (*highest_qc == higher).then_some(group))
        .expect("higher highest-QC group present");
    assert_eq!(groups.len(), 2);
    assert_eq!(lower_group.len(), 2);
    assert_eq!(higher_group.len(), 1);
}

#[tokio::test(flavor = "current_thread")]
async fn try_form_qc_from_votes_skips_when_conflicts_locked_chain() {
    let _guard = super::status::qc_status_test_guard();
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let locked_block = nonempty_block_for_actor(actor, &harness.key_pairs, 1, 0, None);
    let conflicting_block = nonempty_block_for_actor(actor, &harness.key_pairs, 2, 0, None);
    actor
        .kura
        .store_block(locked_block.clone())
        .expect("store locked block");
    actor
        .kura
        .store_block(conflicting_block.clone())
        .expect("store conflicting block");
    let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
    state.push_block_hash_for_testing(locked_block.hash());

    let epoch = actor.epoch_manager.as_ref().map_or(0, EpochManager::epoch);
    actor.locked_qc = Some(QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: locked_block.hash(),
        height: 1,
        view: 0,
        epoch,
    });
    super::status::set_locked_qc(1, 0, Some(locked_block.hash()));

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let chain = actor.common_config.chain.clone();
    let required = topology.min_votes_for_commit();
    let height = 2;
    let view = 0;
    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let (chain_order_hash, rechain_seq) = actor.vnext_chain_order_binding_for_signature_topology(
        height,
        view,
        consensus_mode,
        &signature_topology,
    );

    for signer_idx in 0..required {
        let mut vote = crate::sumeragi::consensus::Vote {
            phase: Phase::Commit,
            block_hash: conflicting_block.hash(),
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: None,
            signer: u32::try_from(signer_idx).expect("signer index fits u32"),
            bls_sig: Vec::new(),
        };
        bind_vote_to_signature_topology_chain_order(&mut vote, actor, &signature_topology);
        sign_vote_for_view_with_seed(
            &mut vote,
            &chain,
            &topology,
            &harness.key_pairs,
            mode_tag,
            prf_seed,
        );
        actor.handle_vote(vote);
    }

    assert!(
        !actor.qc_cache.contains_key(&(
            Phase::Commit,
            conflicting_block.hash(),
            height,
            view,
            epoch,
            chain_order_hash,
            rechain_seq
        )),
        "conflicting precommit QC should not be aggregated"
    );

    harness.shutdown.send();
}

