#[tokio::test(flavor = "current_thread")]
async fn rbc_pending_caps_respect_minimum_chunk_size() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.rbc.chunk_max_bytes = 1;
    let hard_chunk_cap = usize::try_from(super::RBC_MAX_TOTAL_CHUNKS).unwrap_or(usize::MAX);
    let chunk_max_bytes = consensus_cfg.rbc.chunk_max_bytes.max(1);
    let hard_byte_cap = chunk_max_bytes.saturating_mul(hard_chunk_cap);
    let expected_max_bytes = consensus_cfg
        .rbc
        .pending_max_bytes
        .min(hard_byte_cap)
        .max(chunk_max_bytes);
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;

    let (_max_chunks, max_bytes) = harness.actor.pending_rbc_caps();
    assert_eq!(max_bytes, expected_max_bytes);

    let height = 4;
    let view = 0u64;
    let roster = harness.actor.effective_commit_topology();
    let (block_header, leader_signature) =
        rbc_header_and_signature(&harness.actor, &roster, height, view, &harness.key_pairs);
    let block_hash = block_header.hash();
    let key = (block_hash, height, view);

    let payload = vec![0xAB];
    let payload_hash = Hash::new(&payload);
    let seeded =
        Actor::build_rbc_session_from_payload(&payload, payload_hash, 1, 0).expect("session");
    let chunk_root = seeded.chunk_root().expect("chunk root");
    let mut session = RbcSession::new(
        1,
        Some(payload_hash),
        Some(chunk_root),
        Some(
            seeded
                .expected_chunk_digests
                .clone()
                .expect("chunk digests"),
        ),
        0,
    )
    .expect("session");
    session.block_header = Some(block_header);
    session.leader_signature = Some(leader_signature);
    harness
        .actor
        .record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);
    harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert(key, session);

    let chunk = crate::sumeragi::consensus::RbcChunk {
        block_hash,
        height,
        view,
        epoch: 0,
        idx: 0,
        bytes: payload,
    };
    harness
        .actor
        .handle_rbc_chunk(chunk, None)
        .expect("chunk handled");

    let session = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert_eq!(session.received_chunks(), 1);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn duplicate_rbc_ready_is_ignored() {
    let mut harness = test_actor_harness(4).await;
    let height = harness.actor.committed_height_snapshot().saturating_add(1);
    let view = 0_u64;
    let parent = harness.actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(&harness.actor, &harness.key_pairs, height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = b"payload".to_vec();
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        1024,
        harness.actor.epoch_for_height(height),
    )
    .expect("session");
    session.test_set_block_header_and_signature(&block);

    harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert(key, session.clone());
    let roster = harness.actor.effective_commit_topology();
    harness
        .actor
        .record_rbc_session_roster(key, roster.clone(), super::RbcRosterSource::Derived);

    let ready = harness.actor.build_rbc_ready(key, &session).expect("ready");
    harness
        .actor
        .handle_rbc_ready(ready.clone())
        .expect("first ready");
    let count_after_first = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session")
        .ready_signatures
        .len();

    harness
        .actor
        .handle_rbc_ready(ready)
        .expect("duplicate ready");
    let count_after_second = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session")
        .ready_signatures
        .len();

    assert_eq!(count_after_first, 1);
    assert_eq!(count_after_second, count_after_first);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn duplicate_rbc_ready_validates_invalid_stored_signature_before_drop() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.gating.invalid_sig_penalty_threshold = 1;
    consensus_cfg.gating.invalid_sig_penalty_window = Duration::from_secs(10);
    consensus_cfg.gating.invalid_sig_penalty_cooldown = Duration::from_secs(5);
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0_u64;
    let parent = actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block).to_vec();
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        1024,
        actor.epoch_for_height(height),
    )
    .expect("session");
    let roster = actor.effective_commit_topology();
    assert!(roster.len() > 1, "test requires a remote signer");
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    let local_peer = actor.common_config.peer.id().clone();
    let signer_peer = roster
        .iter()
        .find(|peer| *peer != &local_peer)
        .expect("remote signer")
        .clone();
    let signer_sender = signature_sender_index(actor, &roster, height, view, &signer_peer);
    let invalid_signature = vec![0xE1];
    let roster_hash = roster_hash(&roster);
    assert!(session.record_ready_with_roster_hash(
        signer_sender,
        invalid_signature.clone(),
        roster_hash,
    ));
    let chunk_root = session.expected_chunk_root.expect("chunk root");
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);

    let ready = crate::sumeragi::consensus::RbcReady {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch: actor.epoch_for_height(key.1),
        roster_hash,
        chunk_root,
        sender: signer_sender,
        signature: invalid_signature,
    };
    actor.handle_rbc_ready(ready).expect("READY handled");

    assert!(
        actor.invalid_sig_penalty.is_suppressed(
            InvalidSigKind::RbcReady,
            u64::from(signer_sender),
            Instant::now(),
        ),
        "matching stored READY bytes must still be validated and penalized when invalid"
    );
    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert_eq!(
        stored.ready_signatures.len(),
        1,
        "invalid duplicate evidence must not add READY entries"
    );

    harness.shutdown.send();
}

