#[tokio::test(flavor = "current_thread")]
async fn recover_block_from_rbc_session_marks_invalid_on_payload_hash_mismatch() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.state.view().height() as u64 + 1;
    let view = 0u64;
    let epoch = actor.epoch_for_height(height);
    let block = sample_block(height, view, None);
    let block_hash = block.hash();
    let key = (block_hash, height, view);

    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    let mut session =
        Actor::build_rbc_session_from_payload(&payload_bytes, payload_hash, 1024, epoch)
            .expect("session");
    session.payload_hash = Some(Hash::prehashed([0xEE; 32]));
    session.test_set_delivered(true);
    let roster = actor.effective_commit_topology();
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);
    let pending = actor.pending_rbc_slot(key).expect("pending slot");
    let _ = pending.push_chunk_capped(
        crate::sumeragi::consensus::RbcChunk {
            block_hash,
            height,
            view,
            epoch,
            idx: 0,
            bytes: vec![0xCD],
        },
        None,
        usize::MAX,
        usize::MAX,
        std::time::Instant::now(),
    );

    actor.recover_block_from_rbc_session(key);

    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert!(stored.is_invalid());
    assert!(
        !actor.subsystems.da_rbc.rbc.pending.contains_key(&key),
        "pending stash should be cleared on mismatch"
    );
    assert!(
        !actor
            .pending
            .missing_block_requests
            .contains_key(&block_hash),
        "exact-frontier mismatch should avoid a generic missing-block request"
    );
    let frontier_slot = actor
        .frontier_slot
        .as_ref()
        .expect("exact-frontier mismatch should arm frontier body repair");
    assert_eq!(frontier_slot.block_hash, block_hash);
    assert_eq!(frontier_slot.height, height);
    assert_eq!(frontier_slot.view, view);

    harness.shutdown.send();
}

