#[tokio::test(flavor = "current_thread")]
async fn handle_rbc_init_drops_mismatched_cached_chunks() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = 4u64;
    let view = 0u64;
    let epoch = actor.epoch_for_height(height);
    let roster = actor.effective_commit_topology();
    let (block_header, leader_signature) =
        rbc_header_and_signature(actor, &roster, height, view, &harness.key_pairs);
    let block_hash = block_header.hash();
    let key = (block_hash, height, view);

    let session = RbcSession::new(1, None, None, None, epoch).expect("session");
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);

    let session = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get_mut(&key)
        .expect("session");
    session.ingest_chunk(0, vec![0xBE, 0xEF], None);
    let session = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert_eq!(session.received_chunks(), 1);

    let good_bytes = vec![0x11; 8];
    let payload_hash = Hash::new(&good_bytes);
    let digest = Sha256::digest(&good_bytes);
    let mut digest_arr = [0u8; 32];
    digest_arr.copy_from_slice(&digest);
    let digests = vec![digest_arr];
    let chunk_root = MerkleTree::<[u8; 32]>::from_hashed_leaves_sha256(digests.clone())
        .root()
        .map(Hash::from)
        .expect("chunk root");
    let init = crate::sumeragi::consensus::RbcInit {
        block_hash,
        height,
        view,
        epoch,
        roster: roster.clone(),
        roster_hash: roster_hash(&roster),
        total_chunks: 1,
        encoding: iroha_data_model::block::consensus::RbcEncoding::Plain,
        chunk_size_bytes: 0,
        payload_size_bytes: 0,
        data_shards: 0,
        parity_shards: 0,
        chunk_digests: digests,
        payload_hash,
        chunk_root,
        block_header,
        leader_signature: leader_signature.clone(),
    };

    actor.handle_rbc_init(init, None).expect("init handled");

    let session = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert_eq!(
        session.received_chunks(),
        0,
        "mismatched cached chunk should be dropped"
    );
    assert!(!session.is_invalid(), "session should remain valid");

    let good_chunk = crate::sumeragi::consensus::RbcChunk {
        block_hash,
        height,
        view,
        epoch,
        idx: 0,
        bytes: good_bytes,
    };
    actor
        .handle_rbc_chunk(good_chunk, None)
        .expect("chunk handled");
    let session = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert_eq!(session.received_chunks(), 1);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn handle_rbc_init_replaces_preinit_inferred_chunk_root() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = 4u64;
    let view = 0u64;
    let epoch = actor.epoch_for_height(height);
    let roster = actor.effective_commit_topology();
    let (block_header, leader_signature) =
        rbc_header_and_signature(actor, &roster, height, view, &harness.key_pairs);
    let block_hash = block_header.hash();
    let key = (block_hash, height, view);

    let inferred_root = Hash::prehashed([0xA5; 32]);
    let session = RbcSession::new(1, None, Some(inferred_root), None, epoch).expect("session");
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);

    let payload = b"authoritative-init-payload".to_vec();
    let payload_hash = Hash::new(&payload);
    let digest = Sha256::digest(&payload);
    let mut digest_arr = [0u8; 32];
    digest_arr.copy_from_slice(&digest);
    let digests = vec![digest_arr];
    let authoritative_root = MerkleTree::<[u8; 32]>::from_hashed_leaves_sha256(digests.clone())
        .root()
        .map(Hash::from)
        .expect("chunk root");
    assert_ne!(
        inferred_root, authoritative_root,
        "test requires a wrong pre-INIT inferred root"
    );

    let init = crate::sumeragi::consensus::RbcInit {
        block_hash,
        height,
        view,
        epoch,
        roster: roster.clone(),
        roster_hash: roster_hash(&roster),
        total_chunks: 1,
        encoding: iroha_data_model::block::consensus::RbcEncoding::Plain,
        chunk_size_bytes: 0,
        payload_size_bytes: 0,
        data_shards: 0,
        parity_shards: 0,
        chunk_digests: digests,
        payload_hash,
        chunk_root: authoritative_root,
        block_header,
        leader_signature,
    };

    actor.handle_rbc_init(init, None).expect("init handled");

    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session stored");
    assert!(!stored.is_invalid(), "verified INIT should remain valid");
    assert_eq!(
        stored.expected_chunk_root,
        Some(authoritative_root),
        "verified INIT root should replace advisory pre-INIT root"
    );
    assert_eq!(stored.payload_hash(), Some(payload_hash));

    harness.shutdown.send();
}

