#[tokio::test(flavor = "current_thread")]
async fn handle_rbc_deliver_relay_ready_bundle_before_deferring() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    actor.config.debug.rbc.force_deliver_quorum_one = true;

    let height = actor.state.view().height() as u64 + 1;
    let view = 0u64;
    let parent = actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload_hash = Hash::prehashed([0x31; 32]);
    let chunk_root = Hash::prehashed([0x32; 32]);
    let epoch = actor.epoch_for_height(key.1);
    let mut session = RbcSession::test_new(2, Some(payload_hash), Some(chunk_root), epoch);
    session.test_note_chunk(0, b"chunk-a".to_vec(), 0);

    let roster = actor.effective_commit_topology();
    assert_eq!(roster.len(), 4, "test requires exactly four validators");
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    actor.record_rbc_session_roster(key, roster.clone(), super::RbcRosterSource::Derived);

    let topology = super::network_topology::Topology::new(roster.clone());
    let forced_required = actor.rbc_deliver_quorum(&topology);
    let required = Actor::rbc_protocol_deliver_quorum(&topology);
    let relay_threshold = roster
        .len()
        .saturating_sub(required)
        .saturating_add(1)
        .max(1);
    assert_eq!(
        forced_required, 1,
        "test must run with the debug DELIVER quorum override active"
    );
    assert_eq!(required, 3, "test requires a three-vote DELIVER quorum");
    assert_eq!(
        relay_threshold, 2,
        "test requires a two-vote READY relay threshold"
    );
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(key.1);
    let signature_topology = super::topology_for_view(&topology, key.1, key.2, mode_tag, prf_seed);
    let local_sender = actor
        .local_validator_index_for_topology(&signature_topology)
        .expect("local sender");

    let roster_hash = roster_hash(&roster);
    let mut ready_signatures = Vec::new();
    let mut deliver_signer = None;
    for (idx, peer) in signature_topology.as_ref().iter().enumerate() {
        if ready_signatures.len() >= relay_threshold {
            break;
        }
        let sender = u32::try_from(idx).expect("sender fits u32");
        if sender == local_sender {
            continue;
        }
        let signer_kp = harness
            .key_pairs
            .iter()
            .find(|kp| kp.public_key() == peer.public_key())
            .expect("signer keypair");
        let mut ready = crate::sumeragi::consensus::RbcReady {
            block_hash: key.0,
            height: key.1,
            view: key.2,
            epoch,
            roster_hash,
            chunk_root,
            sender,
            signature: Vec::new(),
        };
        let preimage = super::rbc_ready_preimage(&actor.common_config.chain, mode_tag, &ready);
        let signature = checked_signature(signer_kp.private_key(), &preimage);
        ready.signature = signature.payload().to_vec();
        if deliver_signer.is_none() {
            deliver_signer = Some((peer.clone(), sender));
        }
        ready_signatures.push(crate::sumeragi::consensus::RbcReadySignature {
            sender: ready.sender,
            signature: ready.signature.clone(),
        });
    }
    assert_eq!(
        ready_signatures.len(),
        relay_threshold,
        "READY bundle should reach relay threshold but remain below DELIVER quorum"
    );

    let (deliver_peer, deliver_sender) = deliver_signer.expect("deliver signer");
    let deliver_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == deliver_peer.public_key())
        .expect("deliver keypair");
    let mut deliver = crate::sumeragi::consensus::RbcDeliver {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch,
        roster_hash,
        chunk_root,
        sender: deliver_sender,
        signature: Vec::new(),
        ready_signatures,
    };
    let preimage = super::rbc_deliver_preimage(&actor.common_config.chain, mode_tag, &deliver);
    let signature = checked_signature(deliver_kp.private_key(), &preimage);
    deliver.signature = signature.payload().to_vec();

    actor.handle_rbc_deliver(deliver).expect("deliver handled");

    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert!(
        stored.sent_ready,
        "READY relay should run before the inbound DELIVER is deferred"
    );
    assert!(
        stored
            .ready_signatures
            .iter()
            .any(|entry| entry.sender == local_sender),
        "local READY should be recorded after the bundled READYs reach relay threshold"
    );
    assert!(
        !stored.delivered,
        "incomplete chunks should still prevent DELIVER acceptance"
    );
    assert!(
        actor.subsystems.da_rbc.rbc.pending.contains_key(&key),
        "the inbound DELIVER should remain deferred after local READY relay"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rbc_ready_gossips_to_sampled_peers() {
    let mut harness = test_actor_harness(4).await;
    harness.actor.block_sync_gossip_limit = 1;
    let background_log = attach_background_log(&mut harness.actor);

    let height = harness.actor.committed_height_snapshot().saturating_add(1);
    let view = 0_u64;
    let parent = harness.actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(&harness.actor, &harness.key_pairs, height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = b"payload".to_vec();
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        1024,
        harness.actor.epoch_for_height(height),
    )
    .expect("session");
    session.test_set_block_header_and_signature(&block);
    let chunk_root = session.expected_chunk_root.expect("chunk root");
    harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert(key, session);
    harness.actor.record_rbc_session_roster(
        key,
        harness.actor.effective_commit_topology(),
        super::RbcRosterSource::Derived,
    );

    let roster = harness.actor.effective_commit_topology();
    let local_peer = harness.actor.common_config.peer.id().clone();
    let signer_peer = roster
        .iter()
        .find(|peer| *peer != &local_peer)
        .expect("signer peer")
        .clone();
    let signer_idx = signature_sender_index(&harness.actor, &roster, key.1, key.2, &signer_peer);
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair");

    let mut ready = crate::sumeragi::consensus::RbcReady {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch: harness.actor.epoch_for_height(key.1),
        roster_hash: roster_hash(&roster),
        chunk_root,
        sender: u32::try_from(signer_idx).expect("signer index fits u32"),
        signature: Vec::new(),
    };
    let preimage = super::rbc_ready_preimage(
        &harness.actor.common_config.chain,
        harness.actor.mode_tag(),
        &ready,
    );
    let signature = checked_signature(signer_kp.private_key(), &preimage);
    ready.signature = signature.payload().to_vec();
    let sender = ready.sender;

    let _ = take_background_log(&background_log);
    harness
        .actor
        .handle_rbc_ready(ready)
        .expect("ready accepted");

    let entries = take_background_log(&background_log);
    let broadcast_ready = entries
        .iter()
        .filter(|entry| {
            entry.kind == super::BackgroundRequestLogKind::Broadcast
                && entry.msg_kind == Some("RbcReady")
        })
        .count();
    let gossip_ready_posts = entries
        .iter()
        .filter(|entry| {
            entry.kind == super::BackgroundRequestLogKind::Post
                && entry.msg_kind == Some("RbcReady")
        })
        .count();
    let topology = super::network_topology::Topology::new(roster);
    let (_, mode_tag, prf_seed) = harness.actor.consensus_context_for_height(key.1);
    let signature_topology = super::topology_for_view(&topology, key.1, key.2, mode_tag, prf_seed);
    let expected_gossip_targets = harness
        .actor
        .new_view_gossip_targets(signature_topology.as_ref(), Some(sender));
    let local_idx = harness
        .actor
        .local_validator_index_for_topology(&signature_topology)
        .expect("local sender");
    assert_eq!(broadcast_ready, 1, "expected local READY broadcast");
    let stored = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert!(
        stored
            .ready_signatures
            .iter()
            .any(|entry| entry.sender == local_idx),
        "expected local READY to be recorded"
    );
    assert!(
        gossip_ready_posts >= expected_gossip_targets.len(),
        "expected READY gossip to include the sampled targets"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rbc_ready_uses_session_roster_after_topology_change() {
    let mut harness = test_actor_harness(3).await;
    let roster_a = harness.actor.effective_commit_topology();
    assert!(
        roster_a.len() >= 3,
        "test requires at least three peers for roster rotation"
    );
    let (block_header, leader_signature) =
        rbc_header_and_signature(&harness.actor, &roster_a, 1, 0, &harness.key_pairs);
    let key = Actor::session_key(&block_header.hash(), 1, 0);
    let payload = b"payload".to_vec();
    let payload_hash = Hash::new(&payload);
    let mut session =
        Actor::build_rbc_session_from_payload(&payload, payload_hash, 1024, 0).expect("session");
    session.block_header = Some(block_header);
    session.leader_signature = Some(leader_signature);

    harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert(key, session.clone());

    let local_peer = harness.actor.common_config.peer.id().clone();
    let signer_peer = roster_a.last().expect("roster entry").clone();
    let signer_idx = signature_sender_index(&harness.actor, &roster_a, key.1, key.2, &signer_peer);
    let remove_peer = roster_a
        .iter()
        .find(|peer| **peer != local_peer && **peer != signer_peer)
        .expect("removable peer")
        .clone();

    harness
        .actor
        .record_rbc_session_roster(key, roster_a.clone(), super::RbcRosterSource::Derived);

    let mut ready = crate::sumeragi::consensus::RbcReady {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch: 0,
        roster_hash: roster_hash(&roster_a),
        chunk_root: session.expected_chunk_root.expect("session has chunk root"),
        sender: u32::try_from(signer_idx).expect("signer index fits u32"),
        signature: Vec::new(),
    };
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair");
    let preimage = super::rbc_ready_preimage(
        &harness.actor.common_config.chain,
        harness.actor.mode_tag(),
        &ready,
    );
    let signature = checked_signature(signer_kp.private_key(), &preimage);
    ready.signature = signature.payload().to_vec();

    let roster_b: Vec<_> = roster_a
        .iter()
        .filter(|peer| *peer != &remove_peer)
        .cloned()
        .collect();
    {
        let mut block = harness.actor.state.commit_topology.block();
        {
            let mut tx = block.transaction();
            *tx = roster_b;
            tx.apply();
        }
        block.commit();
    }

    harness
        .actor
        .handle_rbc_ready(ready)
        .expect("ready accepted");
    let stored = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert!(
        stored
            .ready_signatures
            .iter()
            .any(|entry| entry.sender == signer_idx),
        "ready should be recorded for the original roster"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rbc_session_roster_persists_across_restart_with_roster_change() {
    let rbc_dir = tempfile::tempdir().expect("tempdir");
    let rbc_cfg = crate::sumeragi::RbcStoreConfig {
        dir: rbc_dir.path().to_path_buf(),
        max_sessions: 16,
        soft_sessions: 8,
        max_bytes: 1 << 20,
        soft_bytes: 1 << 20,
        ttl: Duration::from_secs(60),
    };
    let mut harness = test_actor_harness_with_rbc_store(4, Some(rbc_cfg.clone())).await;
    let height = 1_u64;
    let view = 0_u64;
    let parent = harness.actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(&harness.actor, &harness.key_pairs, height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block).to_vec();
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        harness.actor.config.rbc.chunk_max_bytes,
        harness.actor.epoch_for_height(height),
    )
    .expect("session");
    let roster_a = harness.actor.effective_commit_topology();
    assert!(!roster_a.is_empty(), "roster should not be empty");
    bind_session_to_roster_leader(
        &harness.actor,
        &mut session,
        &block,
        &roster_a,
        &harness.key_pairs,
    );
    let removed_peer = roster_a.first().cloned().expect("roster entry");
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == removed_peer.public_key())
        .cloned()
        .expect("signer keypair");

    harness
        .actor
        .record_rbc_session_roster(key, roster_a.clone(), super::RbcRosterSource::Derived);
    harness.actor.persist_rbc_session(key, &session);
    harness.shutdown.send();
    drop(harness);

    let mut harness = test_actor_harness_with_rbc_store(4, Some(rbc_cfg)).await;
    let persisted_roster = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .session_rosters
        .get(&key)
        .cloned()
        .expect("persisted roster");
    assert_eq!(persisted_roster, roster_a);

    let mut roster_b = roster_a.clone();
    roster_b.retain(|peer| peer != &removed_peer);
    assert!(!roster_b.is_empty(), "roster should remain non-empty");
    {
        let mut block = harness.actor.state.world.block();
        let peers = block.peers.get_mut();
        peers.clear();
        for peer in &roster_b {
            let _ = peers.push(peer.clone());
        }
        block.commit();
    }

    let session_loaded = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .cloned()
        .expect("session");
    let topology = super::network_topology::Topology::new(roster_a.clone());
    let signature_topology = super::topology_for_view(
        &topology,
        key.1,
        key.2,
        harness.actor.mode_tag(),
        harness.actor.npos_prf_seed(),
    );
    let signer_idx = signature_topology
        .position(removed_peer.public_key())
        .expect("signer index");
    let mut ready = crate::sumeragi::consensus::RbcReady {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch: session_loaded.epoch,
        roster_hash: roster_hash(&roster_a),
        chunk_root: session_loaded.chunk_root().expect("chunk root"),
        sender: u32::try_from(signer_idx).expect("signer index fits u32"),
        signature: Vec::new(),
    };
    let preimage = super::rbc_ready_preimage(
        &harness.actor.common_config.chain,
        harness.actor.mode_tag(),
        &ready,
    );
    let signature = checked_signature(signer_kp.private_key(), &preimage);
    ready.signature = signature.payload().to_vec();
    let ready_sender = ready.sender;

    harness
        .actor
        .handle_rbc_ready(ready)
        .expect("ready accepted");
    let stored = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert!(
        stored
            .ready_signatures
            .iter()
            .any(|entry| entry.sender == ready_sender),
        "persisted roster should validate READY signatures from removed peers after restart"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rbc_status_summary_survives_roster_change_reset_after_restart_recovery() {
    let rbc_dir = tempfile::tempdir().expect("tempdir");
    let rbc_cfg = crate::sumeragi::RbcStoreConfig {
        dir: rbc_dir.path().to_path_buf(),
        max_sessions: 16,
        soft_sessions: 8,
        max_bytes: 1 << 20,
        soft_bytes: 1 << 20,
        ttl: Duration::from_secs(60),
    };
    let key = session_key();
    let payload = b"payload".to_vec();
    let payload_hash = Hash::new(&payload);

    let mut harness = test_actor_harness_with_rbc_store(4, Some(rbc_cfg.clone())).await;
    let mut session = RbcSession::test_new(1, Some(payload_hash), None, 0);
    session.test_note_chunk(0, payload, 0);
    let roster = harness.actor.effective_commit_topology();
    harness
        .actor
        .record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);
    harness.actor.persist_rbc_session(key, &session);
    harness.shutdown.send();
    drop(harness);

    let mut harness = test_actor_harness_with_rbc_store(4, Some(rbc_cfg)).await;
    let summary_before = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .status_handle
        .get(&key)
        .expect("recovered summary");
    assert!(
        summary_before.recovered_from_disk,
        "restart should mark the persisted session summary as recovered"
    );
    assert!(
        harness
            .actor
            .subsystems
            .da_rbc
            .rbc
            .sessions
            .contains_key(&key),
        "restart should rebuild the live RBC session before the roster reset"
    );

    harness.actor.reset_consensus_state_for_roster_change(true);

    assert!(
        !harness
            .actor
            .subsystems
            .da_rbc
            .rbc
            .sessions
            .contains_key(&key),
        "roster reset should still clear runtime RBC sessions"
    );
    let summary_after = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .status_handle
        .get(&key)
        .expect("retained summary after roster reset");
    assert!(
        summary_after.recovered_from_disk,
        "roster reset should retain the recovered RBC status summary"
    );
    assert_eq!(
        summary_after.received_chunks, 1,
        "retained summary should keep the persisted chunk-progress snapshot"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn duplicate_rbc_deliver_is_ignored() {
    let mut harness = test_actor_harness(4).await;
    let height = harness.actor.committed_height_snapshot().saturating_add(1);
    let view = 0_u64;
    let parent = harness.actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(&harness.actor, &harness.key_pairs, height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block).to_vec();
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        1024,
        harness.actor.epoch_for_height(height),
    )
    .expect("session");
    assert!(session.record_ready(0, vec![0xAA]));
    assert!(session.record_ready(1, vec![0xBB]));
    assert!(session.record_ready(2, vec![0xCC]));

    let roster = harness.actor.effective_commit_topology();
    bind_session_to_roster_leader(
        &harness.actor,
        &mut session,
        &block,
        &roster,
        &harness.key_pairs,
    );
    harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert(key, session.clone());
    harness
        .actor
        .record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);

    let deliver = harness
        .actor
        .build_rbc_deliver(key, &session)
        .expect("deliver");
    harness
        .actor
        .handle_rbc_deliver(deliver.clone())
        .expect("deliver");
    let signature_after_first = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session")
        .deliver_signature
        .clone();

    harness
        .actor
        .handle_rbc_deliver(deliver)
        .expect("duplicate deliver");
    let signature_after_second = harness
        .actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session")
        .deliver_signature
        .clone();

    assert_eq!(signature_after_first, signature_after_second);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn duplicate_rbc_deliver_validates_invalid_stored_signature_before_drop() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.gating.invalid_sig_penalty_threshold = 1;
    consensus_cfg.gating.invalid_sig_penalty_window = Duration::from_secs(10);
    consensus_cfg.gating.invalid_sig_penalty_cooldown = Duration::from_secs(5);
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0_u64;
    let parent = actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block).to_vec();
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        1024,
        actor.epoch_for_height(height),
    )
    .expect("session");
    let roster = actor.effective_commit_topology();
    assert!(roster.len() > 1, "test requires a remote signer");
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    let local_peer = actor.common_config.peer.id().clone();
    let signer_peer = roster
        .iter()
        .find(|peer| *peer != &local_peer)
        .expect("remote signer")
        .clone();
    let signer_sender = signature_sender_index(actor, &roster, height, view, &signer_peer);
    let invalid_signature = vec![0xE2];
    assert!(session.record_deliver(signer_sender, invalid_signature.clone()));
    assert!(rbc_session_has_complete_delivery(&session));
    let chunk_root = session.expected_chunk_root.expect("chunk root");
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    let roster_hash = roster_hash(&roster);
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);

    let deliver = crate::sumeragi::consensus::RbcDeliver {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch: actor.epoch_for_height(key.1),
        roster_hash,
        chunk_root,
        sender: signer_sender,
        signature: invalid_signature,
        ready_signatures: Vec::new(),
    };
    actor.handle_rbc_deliver(deliver).expect("DELIVER handled");

    assert!(
        actor.invalid_sig_penalty.is_suppressed(
            InvalidSigKind::RbcDeliver,
            u64::from(signer_sender),
            Instant::now(),
        ),
        "matching stored DELIVER bytes must still be validated and penalized when invalid"
    );
    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert_eq!(stored.deliver_signature.as_deref(), Some(&[0xE2][..]));

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn duplicate_rbc_deliver_validates_chunk_root_before_drop() {
    let _guard = super::status::message_handling_test_guard();
    super::status::reset_message_handling_for_tests();
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0_u64;
    let parent = actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block).to_vec();
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        1024,
        actor.epoch_for_height(height),
    )
    .expect("session");
    let roster = actor.effective_commit_topology();
    assert!(roster.len() > 1, "test requires a remote signer");
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    let local_peer = actor.common_config.peer.id().clone();
    let signer_peer = roster
        .iter()
        .find(|peer| *peer != &local_peer)
        .expect("remote signer")
        .clone();
    let signer_sender = signature_sender_index(actor, &roster, height, view, &signer_peer);
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair");
    let roster_hash = roster_hash(&roster);
    let wrong_root = Hash::prehashed([0x9D; Hash::LENGTH]);
    let mut deliver = crate::sumeragi::consensus::RbcDeliver {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch: actor.epoch_for_height(key.1),
        roster_hash,
        chunk_root: wrong_root,
        sender: signer_sender,
        signature: Vec::new(),
        ready_signatures: Vec::new(),
    };
    let (_, mode_tag, _) = actor.consensus_context_for_height(key.1);
    let preimage = super::rbc_deliver_preimage(&actor.common_config.chain, mode_tag, &deliver);
    let signature = checked_signature(signer_kp.private_key(), &preimage);
    deliver.signature = signature.payload().to_vec();
    assert!(session.record_deliver(signer_sender, deliver.signature.clone()));
    assert!(rbc_session_has_complete_delivery(&session));
    let deliver_signature = deliver.signature.clone();
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);

    actor
        .handle_rbc_deliver(deliver)
        .expect("DELIVER duplicate handled");

    let entries = super::status::snapshot().consensus_message_handling.entries;
    assert!(
        entries.iter().any(|entry| {
            entry.kind == super::status::ConsensusMessageKind::RbcDeliver
                && entry.outcome == super::status::ConsensusMessageOutcome::Dropped
                && entry.reason == super::status::ConsensusMessageReason::ChunkRootMismatch
                && entry.total > 0
        }),
        "wrong-root duplicate DELIVER must be recorded as a chunk-root mismatch before duplicate drop"
    );
    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert_eq!(
        stored.deliver_signature.as_deref(),
        Some(deliver_signature.as_slice())
    );

    super::status::reset_message_handling_for_tests();
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn duplicate_rbc_deliver_validates_ready_bundle_shape_before_drop() {
    let _guard = super::status::message_handling_test_guard();
    super::status::reset_message_handling_for_tests();
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0_u64;
    let parent = actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, view, parent);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block).to_vec();
    let payload_hash = Hash::new(&payload);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload,
        payload_hash,
        1024,
        actor.epoch_for_height(height),
    )
    .expect("session");
    let roster = actor.effective_commit_topology();
    assert!(roster.len() > 1, "test requires a remote signer");
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    let local_peer = actor.common_config.peer.id().clone();
    let signer_peer = roster
        .iter()
        .find(|peer| *peer != &local_peer)
        .expect("remote signer")
        .clone();
    let signer_sender = signature_sender_index(actor, &roster, height, view, &signer_peer);
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair");
    let roster_hash = roster_hash(&roster);
    let chunk_root = session.expected_chunk_root.expect("chunk root");
    let mut deliver = crate::sumeragi::consensus::RbcDeliver {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch: actor.epoch_for_height(key.1),
        roster_hash,
        chunk_root,
        sender: signer_sender,
        signature: Vec::new(),
        ready_signatures: vec![
            crate::sumeragi::consensus::RbcReadySignature {
                sender: 0,
                signature: vec![0xAA],
            },
            crate::sumeragi::consensus::RbcReadySignature {
                sender: 0,
                signature: vec![0xBB],
            },
        ],
    };
    let (_, mode_tag, _) = actor.consensus_context_for_height(key.1);
    let preimage = super::rbc_deliver_preimage(&actor.common_config.chain, mode_tag, &deliver);
    let signature = checked_signature(signer_kp.private_key(), &preimage);
    deliver.signature = signature.payload().to_vec();
    assert!(session.record_deliver(signer_sender, deliver.signature.clone()));
    assert!(rbc_session_has_complete_delivery(&session));
    let deliver_signature = deliver.signature.clone();
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);

    actor
        .handle_rbc_deliver(deliver)
        .expect("DELIVER duplicate handled");

    let entries = super::status::snapshot().consensus_message_handling.entries;
    assert!(
        entries.iter().any(|entry| {
            entry.kind == super::status::ConsensusMessageKind::RbcDeliver
                && entry.outcome == super::status::ConsensusMessageOutcome::Dropped
                && entry.reason == super::status::ConsensusMessageReason::InvalidPayload
                && entry.total > 0
        }),
        "malformed duplicate DELIVER bundle must be rejected before duplicate drop"
    );
    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert_eq!(
        stored.deliver_signature.as_deref(),
        Some(deliver_signature.as_slice())
    );

    super::status::reset_message_handling_for_tests();
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn duplicate_rbc_deliver_does_not_refresh_pending_progress_or_rerun_commit_pipeline() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let key = insert_active_pending_block(actor, 0);
    let pending_block = actor
        .pending
        .pending_blocks
        .get(&key.0)
        .expect("pending block")
        .block
        .clone();
    let payload = super::proposals::block_payload_bytes(&pending_block).to_vec();
    let payload_hash = Hash::new(&payload);
    let epoch = actor.epoch_for_height(key.1);
    let mut session = Actor::build_rbc_session_from_payload(&payload, payload_hash, 1024, epoch)
        .expect("session");
    session.test_set_block_header_and_signature(&pending_block);
    session.sent_ready = true;
    assert!(session.record_ready(0, vec![0xAA]));
    assert!(session.record_ready(1, vec![0xBB]));
    assert!(session.record_ready(2, vec![0xCC]));

    let roster = actor.effective_commit_topology();
    bind_session_to_roster_leader(
        actor,
        &mut session,
        &pending_block,
        &roster,
        &harness.key_pairs,
    );
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);
    {
        let pending = actor
            .pending
            .pending_blocks
            .get_mut(&key.0)
            .expect("pending block");
        pending.validation_status = ValidationStatus::Valid;
        pending.parent_state_root = Some(zero_state_root());
        pending.post_state_root = Some(zero_state_root());
    }

    let deliver = actor.build_rbc_deliver(key, &session).expect("deliver");
    assert!(session.record_deliver(deliver.sender, deliver.signature.clone()));
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);

    let check_at = Instant::now();
    let stale_at = check_at
        .checked_sub(Duration::from_secs(5))
        .unwrap_or(check_at);
    actor.pending.last_commit_pipeline_run = stale_at;
    actor.pending.commit_pipeline_wakeup = false;
    actor
        .pending
        .pending_blocks
        .get_mut(&key.0)
        .expect("pending block")
        .touch_progress(stale_at);

    actor
        .handle_rbc_deliver(deliver)
        .expect("duplicate deliver");

    let pending = actor
        .pending
        .pending_blocks
        .get(&key.0)
        .expect("pending block retained");
    assert_eq!(
        pending.progress_age(check_at),
        Duration::from_secs(5),
        "duplicate DELIVER should not refresh pending progress"
    );
    assert_eq!(
        actor.pending.last_commit_pipeline_run, stale_at,
        "duplicate DELIVER should not rerun the commit pipeline"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn duplicate_rbc_deliver_on_incomplete_delivered_session_hydrates_but_keeps_pending_idle() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.state.view().height() as u64 + 1;
    let view = 0u64;
    let parent = actor.state.view().latest_block_hash();
    let txs: Vec<_> = (0..16).map(|_| sample_transaction()).collect();
    let block = block_with_txs(height, view, parent, txs);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload);
    let mut session = partial_rbc_session_for_block(actor, &block, 1024);
    session.sent_ready = true;
    assert!(session.record_ready(0, vec![0xAA]));
    assert!(
        session.received_chunks() < session.total_chunks(),
        "test requires an incomplete chunk set"
    );

    actor.pending.pending_blocks.insert(
        block.hash(),
        PendingBlock::new(block.clone(), payload_hash, height, view),
    );
    let roster = actor.effective_commit_topology();
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);

    let deliver = actor.build_rbc_deliver(key, &session).expect("deliver");
    assert!(session.record_deliver(deliver.sender, deliver.signature.clone()));
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    let now = Instant::now();
    actor.subsystems.da_rbc.rbc.deliver_deferral.insert(
        key,
        super::RbcDeliverDeferral {
            last_attempt: now,
            ready_count: 0,
            received_chunks: 0,
            total_chunks: 0,
        },
    );

    let stale_at = now.checked_sub(Duration::from_secs(5)).unwrap_or(now);
    actor.pending.last_commit_pipeline_run = stale_at;
    actor.pending.commit_pipeline_wakeup = false;
    actor
        .pending
        .pending_blocks
        .get_mut(&key.0)
        .expect("pending block")
        .touch_progress(stale_at);

    actor
        .handle_rbc_deliver(deliver)
        .expect("duplicate deliver on incomplete session");

    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session retained");
    assert!(stored.delivered);
    assert!(
        super::rbc_session_has_complete_delivery(stored),
        "duplicate DELIVER should hydrate matching local payload and make the delivered session terminal"
    );
    assert!(
        !actor
            .subsystems
            .da_rbc
            .rbc
            .deliver_deferral
            .contains_key(&key),
        "terminal delivered sessions should clear DELIVER deferral state"
    );
    let pending = actor
        .pending
        .pending_blocks
        .get(&key.0)
        .expect("pending block retained");
    assert_eq!(
        pending.progress_age(now),
        Duration::from_secs(5),
        "duplicate DELIVER should not refresh pending progress even if local hydration completes"
    );
    assert!(
        actor.pending.commit_pipeline_wakeup,
        "duplicate DELIVER that hydrates a terminal payload should wake the commit pipeline"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rbc_deliver_bundle_ready_on_incomplete_delivered_session_refreshes_progress_and_wakes_commit_pipeline()
 {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.state.view().height() as u64 + 1;
    let view = 0u64;
    let parent = actor.state.view().latest_block_hash();
    let txs: Vec<_> = (0..16).map(|_| sample_transaction()).collect();
    let block = block_with_txs(height, view, parent, txs);
    let key = Actor::session_key(&block.hash(), height, view);
    let payload = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload);
    let epoch = actor.epoch_for_height(height);
    let mut session = partial_rbc_session_for_block(actor, &block, 1024);
    session.sent_ready = true;
    let chunk_root = session.expected_chunk_root.expect("chunk root");
    assert!(
        session.received_chunks() < session.total_chunks(),
        "test requires an incomplete chunk set"
    );

    let roster = actor.effective_commit_topology();
    assert!(roster.len() >= 4, "test requires a four-peer topology");
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    let ready_signature = signed_remote_rbc_ready_signatures_for_roster(
        actor,
        &harness.key_pairs,
        &roster,
        key.0,
        height,
        view,
        epoch,
        chunk_root,
        1,
    )
    .pop()
    .expect("remote READY signature");

    actor.pending.pending_blocks.insert(
        block.hash(),
        PendingBlock::new(block.clone(), payload_hash, height, view),
    );
    actor.note_proposal_seen(height, view, payload_hash);
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);

    let mut deliver = actor.build_rbc_deliver(key, &session).expect("deliver");
    assert!(session.record_deliver(deliver.sender, deliver.signature.clone()));
    deliver.ready_signatures = vec![ready_signature.clone()];
    let (_, mode_tag, _) = actor.consensus_context_for_height(height);
    let preimage = super::rbc_deliver_preimage(&actor.common_config.chain, mode_tag, &deliver);
    let signature = checked_signature(actor.common_config.key_pair.private_key(), &preimage);
    deliver.signature = signature.payload().to_vec();
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);

    let now = Instant::now();
    actor.subsystems.da_rbc.rbc.deliver_deferral.insert(
        key,
        super::RbcDeliverDeferral {
            last_attempt: now,
            ready_count: 0,
            received_chunks: 0,
            total_chunks: 0,
        },
    );

    let stale_at = now.checked_sub(Duration::from_secs(5)).unwrap_or(now);
    actor.pending.commit_pipeline_wakeup = false;
    actor.pending.last_commit_pipeline_run = stale_at;
    actor
        .pending
        .pending_blocks
        .get_mut(&key.0)
        .expect("pending block")
        .touch_progress(stale_at);

    actor
        .handle_rbc_deliver(deliver)
        .expect("duplicate DELIVER with bundled READY");

    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session retained");
    assert!(stored.delivered);
    assert!(
        super::rbc_session_has_complete_delivery(stored),
        "bundled READY should keep the hydrated raw-delivered session terminal"
    );
    assert!(
        stored
            .ready_signatures
            .iter()
            .any(|entry| entry.sender == ready_signature.sender),
        "valid READY from the duplicate DELIVER bundle should be recorded"
    );
    assert!(
        !actor
            .subsystems
            .da_rbc
            .rbc
            .deliver_deferral
            .contains_key(&key),
        "terminal delivered sessions should clear DELIVER deferral state"
    );
    let pending = actor
        .pending
        .pending_blocks
        .get(&key.0)
        .expect("pending block retained");
    assert!(
        pending.progress_age(now) < Duration::from_secs(5),
        "bundled READY on an incomplete delivered session should refresh pending progress"
    );
    assert!(
        actor.pending.commit_pipeline_wakeup,
        "bundled READY on an incomplete delivered session should wake the commit pipeline"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rbc_deliver_bundle_conflicting_ready_invalidates_session_and_clears_pending() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.state.view().height() as u64 + 1;
    let view = 0u64;
    let parent = actor.state.view().latest_block_hash();
    let txs: Vec<_> = (0..16).map(|_| sample_transaction()).collect();
    let block = block_with_txs(height, view, parent, txs);
    let key = Actor::session_key(&block.hash(), height, view);
    let epoch = actor.epoch_for_height(height);
    let mut session = partial_rbc_session_for_block(actor, &block, 1024);
    session.sent_ready = true;
    let chunk_root = session.expected_chunk_root.expect("chunk root");
    assert!(
        session.received_chunks() < session.total_chunks(),
        "test requires an incomplete chunk set"
    );

    let roster = actor.effective_commit_topology();
    assert!(roster.len() >= 4, "test requires a four-peer topology");
    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    let ready_signature = signed_remote_rbc_ready_signatures_for_roster(
        actor,
        &harness.key_pairs,
        &roster,
        key.0,
        height,
        view,
        epoch,
        chunk_root,
        1,
    )
    .pop()
    .expect("remote READY signature");
    let roster_hash = super::rbc::rbc_roster_hash(&roster);
    assert!(session.record_ready_with_roster_hash(ready_signature.sender, vec![0xE1], roster_hash));

    bind_session_to_roster_leader(actor, &mut session, &block, &roster, &harness.key_pairs);
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);
    let mut deliver = actor.build_rbc_deliver(key, &session).expect("deliver");
    assert!(session.record_deliver(deliver.sender, deliver.signature.clone()));
    deliver.ready_signatures = vec![ready_signature.clone()];
    let (_, mode_tag, _) = actor.consensus_context_for_height(height);
    let preimage = super::rbc_deliver_preimage(&actor.common_config.chain, mode_tag, &deliver);
    let signature = checked_signature(actor.common_config.key_pair.private_key(), &preimage);
    deliver.signature = signature.payload().to_vec();
    let total_chunks = session.total_chunks();
    let received_chunks = session.received_chunks();
    let now = Instant::now();

    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    actor
        .subsystems
        .da_rbc
        .rbc
        .pending
        .insert(key, super::pending_rbc::PendingRbcMessages::new(now));
    actor.subsystems.da_rbc.rbc.ready_deferral.insert(
        key,
        super::RbcReadyDeferral {
            last_attempt: now,
            reason: super::RbcReadyDeferralReason::MissingPayload,
            ready_count: 1,
            required_ready: 2,
            received_chunks,
            total_chunks,
        },
    );
    actor.subsystems.da_rbc.rbc.deliver_deferral.insert(
        key,
        super::RbcDeliverDeferral {
            last_attempt: now,
            ready_count: 1,
            received_chunks,
            total_chunks,
        },
    );
    assert!(
        actor.subsystems.da_rbc.rbc.pending.contains_key(&key),
        "test setup requires pending RBC state before the conflicting bundle"
    );

    actor
        .handle_rbc_deliver(deliver)
        .expect("conflicting bundled READY");

    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session retained");
    assert!(
        stored.is_invalid(),
        "conflicting READY evidence inside a DELIVER bundle should invalidate the session"
    );
    assert_eq!(
        stored.ready_signatures.len(),
        1,
        "conflicting bundled READY must not overwrite the original sender evidence"
    );
    assert!(
        !actor.subsystems.da_rbc.rbc.pending.contains_key(&key),
        "conflicting bundled READY should clear pending RBC state"
    );
    assert!(
        !actor
            .subsystems
            .da_rbc
            .rbc
            .ready_deferral
            .contains_key(&key),
        "conflicting bundled READY should clear READY deferral bookkeeping"
    );
    assert!(
        !actor
            .subsystems
            .da_rbc
            .rbc
            .deliver_deferral
            .contains_key(&key),
        "conflicting bundled READY should clear DELIVER deferral bookkeeping"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn late_rbc_ready_after_delivery_does_not_refresh_pending_progress_or_rerun_commit_pipeline()
{
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let key = insert_active_pending_block(actor, 0);
    let pending_block = actor
        .pending
        .pending_blocks
        .get(&key.0)
        .expect("pending block")
        .block
        .clone();
    let payload = super::proposals::block_payload_bytes(&pending_block).to_vec();
    let payload_hash = Hash::new(&payload);
    let epoch = actor.epoch_for_height(key.1);
    let mut session = Actor::build_rbc_session_from_payload(&payload, payload_hash, 1024, epoch)
        .expect("session");
    session.test_set_block_header_and_signature(&pending_block);
    session.sent_ready = true;

    let roster = actor.effective_commit_topology();
    assert!(roster.len() >= 4, "test requires a four-peer topology");
    session.leader_signature = Some(leader_signature_for_header(
        actor,
        &roster,
        &pending_block.header(),
        &harness.key_pairs,
    ));
    let late_sender = u32::try_from(roster.len() - 1).expect("sender index fits u32");
    let topology = super::network_topology::Topology::new(roster.clone());
    let required = actor.rbc_deliver_quorum(&topology).max(1);
    for (idx, _peer) in roster.iter().enumerate() {
        let idx = u32::try_from(idx).expect("sender index fits u32");
        if idx == late_sender {
            continue;
        }
        if session.ready_signatures.len() >= required {
            break;
        }
        assert!(session.record_ready(idx, vec![u8::try_from(idx).expect("sender fits u8")]));
    }
    assert!(
        session.ready_signatures.len() >= required,
        "test setup requires a deliver-quorum READY set before the late READY arrives"
    );

    actor.record_rbc_session_roster(key, roster.clone(), super::RbcRosterSource::Derived);
    {
        let pending = actor
            .pending
            .pending_blocks
            .get_mut(&key.0)
            .expect("pending block");
        pending.validation_status = ValidationStatus::Valid;
        pending.parent_state_root = Some(zero_state_root());
        pending.post_state_root = Some(zero_state_root());
    }

    let deliver = actor.build_rbc_deliver(key, &session).expect("deliver");
    let chunk_root = session.expected_chunk_root.expect("chunk root");
    assert!(session.record_deliver(deliver.sender, deliver.signature.clone()));
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    assert!(
        actor
            .subsystems
            .da_rbc
            .rbc
            .sessions
            .get(&key)
            .is_some_and(|session| session.delivered),
        "test setup requires the session to be delivered before the late READY arrives"
    );
    assert!(
        !actor.subsystems.da_rbc.rbc.pending.contains_key(&key),
        "test setup requires no deferred RBC messages before the late READY arrives"
    );

    let signer_peer = roster
        .get(usize::try_from(late_sender).expect("sender fits usize"))
        .expect("late sender peer")
        .public_key()
        .clone();
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == &signer_peer)
        .expect("late sender keypair");
    let mut ready = crate::sumeragi::consensus::RbcReady {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch,
        roster_hash: super::rbc::rbc_roster_hash(&roster),
        chunk_root,
        sender: late_sender,
        signature: Vec::new(),
    };
    let (_, mode_tag, _) = actor.consensus_context_for_height(key.1);
    let preimage = super::rbc_ready_preimage(&actor.chain_id, mode_tag, &ready);
    let signature = checked_signature(signer_kp.private_key(), &preimage);
    ready.signature = signature.payload().to_vec();

    let check_at = Instant::now();
    let stale_at = check_at
        .checked_sub(Duration::from_secs(5))
        .unwrap_or(check_at);
    actor.pending.last_commit_pipeline_run = stale_at;
    actor
        .pending
        .pending_blocks
        .get_mut(&key.0)
        .expect("pending block")
        .touch_progress(stale_at);

    actor.handle_rbc_ready(ready).expect("late ready");

    let pending = actor
        .pending
        .pending_blocks
        .get(&key.0)
        .expect("pending block retained");
    assert_eq!(
        pending.progress_age(check_at),
        Duration::from_secs(5),
        "late READY after delivery should not refresh pending progress"
    );
    assert_eq!(
        actor.pending.last_commit_pipeline_run, stale_at,
        "late READY after delivery should not rerun the commit pipeline"
    );

    harness.shutdown.send();
}

