#[tokio::test(flavor = "current_thread")]
async fn frontier_recovery_rotates_stale_partial_vote_commit_qc_repair_without_generic_state() {
    let _view_change_guard = super::status::view_change_proof_test_guard();
    super::status::reset_view_change_cause_counters_for_tests();

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let genesis_hash = seed_genesis_block_for_state(&actor.state);

    let height = actor.committed_height_snapshot().saturating_add(1);
    let now = Instant::now();
    actor.phase_tracker.start_new_round(height, now);
    let view = actor.phase_tracker.current_view(height).unwrap_or(0);
    let block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(genesis_hash));
    let block_hash = insert_validated_pending(actor, block);
    actor.note_authoritative_slot_owner(height, view, block_hash);
    assert!(
        actor.update_frontier_slot(
            block_hash,
            height,
            view,
            None,
            BTreeSet::new(),
            /*block_created_seen*/ true,
            /*exact_fetch_armed*/ false,
            /*body_present*/ true,
            None,
            None,
            now,
        ),
        "test setup should seed a body-present exact frontier owner"
    );

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let required = topology.min_votes_for_commit().max(1);
    assert!(required >= 2, "test requires a multi-validator quorum");
    let seeded = seed_verified_commit_votes_for_block_with_roster(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        view,
        topology.as_ref(),
        required.saturating_sub(1),
    );
    assert_eq!(
        seeded,
        required.saturating_sub(1),
        "test requires partial commit-vote evidence below quorum"
    );
    assert!(
        !actor
            .commit_vote_quorum_status_for_block_detail(block_hash, height, view)
            .quorum_reached,
        "partial vote evidence must remain below commit quorum"
    );

    let stale = now
        .checked_sub(
            actor
                .frontier_recovery_window()
                .saturating_add(Duration::from_millis(1)),
        )
        .unwrap_or(now);
    if let Some(slot) = actor.frontier_slot.as_mut() {
        slot.phase = super::FrontierSlotPhase::AwaitCommitQc;
        slot.quorum_progress.votes_observed = true;
        slot.quorum_progress.last_vote_at = Some(stale);
        slot.timers.last_progress_at = stale;
        slot.timers.last_updated_at = stale;
    }
    actor.pending.missing_commit_qc_requests.insert(
        block_hash,
        super::MissingBlockRequest {
            height,
            view,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window: Duration::from_millis(5),
            view_change_window: Some(Duration::from_millis(20)),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 1,
        },
    );
    assert!(
        actor.frontier_recovery.is_none(),
        "regression setup must exercise the exact-slot path without generic recovery state"
    );

    let first_advance =
        actor.advance_frontier_recovery("quorum_timeout", height, view, false, true, true, now);
    assert_eq!(
        first_advance,
        super::FrontierRecoveryAdvance::None,
        "the first quorum timeout should spend the slot-owned rebroadcast window"
    );
    assert!(
        actor
            .frontier_slot
            .as_ref()
            .is_some_and(|slot| slot.repair_state.quorum_timeout_rebroadcasted),
        "the exact slot should remember the bounded quorum-timeout rebroadcast"
    );

    let second_advance = actor.advance_frontier_recovery(
        "quorum_timeout",
        height,
        view,
        false,
        true,
        true,
        now.checked_add(Duration::from_millis(1)).unwrap_or(now),
    );
    assert_eq!(
        second_advance,
        super::FrontierRecoveryAdvance::Rotate,
        "fresh missing commit-QC fetch state must not pin a stale partial-vote frontier forever"
    );
    assert!(
        actor
            .phase_tracker
            .current_view(height)
            .is_some_and(|current_view| current_view > view),
        "exhausted partial-vote commit-QC repair should advance the local view"
    );
    assert!(
        actor
            .pending
            .missing_commit_qc_requests
            .contains_key(&block_hash),
        "view rotation should preserve the missing commit-QC request so a late valid QC can still commit"
    );

    super::status::reset_view_change_cause_counters_for_tests();
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn frontier_recovery_quorum_timeout_keeps_live_slot_without_range_pull() {
    let mut harness = test_actor_harness_with_config(4, test_sumeragi_config(), None).await;
    let actor = &mut harness.actor;
    let genesis_hash = seed_genesis_block_for_state(&actor.state);

    let height = actor.committed_height_snapshot().saturating_add(1);
    let now = Instant::now();
    actor.phase_tracker.start_new_round(height, now);
    let view = actor.phase_tracker.current_view(height).unwrap_or(0);
    let block = sample_block(height, view, Some(genesis_hash));
    let block_hash = block.hash();
    let payload_hash = Hash::new(&super::proposals::block_payload_bytes(&block));

    actor.note_authoritative_slot_owner(height, view, block_hash);
    assert!(
        actor.update_frontier_slot(
            block_hash,
            height,
            view,
            None,
            BTreeSet::new(),
            /*block_created_seen*/ true,
            /*exact_fetch_armed*/ true,
            /*body_present*/ true,
            None,
            None,
            now,
        ),
        "test setup should seed the live contiguous frontier slot"
    );
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );

    let stale = now
        .checked_sub(
            super::saturating_mul_duration(actor.frontier_recovery_window(), 3)
                .saturating_add(Duration::from_millis(1)),
        )
        .unwrap_or(now);
    actor.frontier_recovery = Some(super::FrontierRecoveryState {
        frontier_height: height,
        phase: super::FrontierRecoveryPhase::CatchUp,
        entered_at: stale,
        last_progress_at: stale,
        last_dependency_progress_at: Some(stale),
        last_action_at: None,
        no_progress_windows: 2,
        cleanup_done: false,
        last_view: view,
        last_rotation_view: None,
        last_cause: "quorum_timeout",
    });
    actor.range_pull_escalation_cooldowns.clear();

    let advance =
        actor.advance_frontier_recovery("quorum_timeout", height, view, false, true, true, now);

    assert_eq!(
        advance,
        super::FrontierRecoveryAdvance::None,
        "the first live-slot quorum timeout should consume the deterministic rebroadcast window without emitting range-pull recovery"
    );
    assert!(
        actor.frontier_slot.as_ref().is_some_and(|slot| {
            slot.height == height
                && slot.view == view
                && slot.block_hash == block_hash
                && slot.body_present()
                && slot.block_created_seen
        }),
        "quorum-timeout recovery must keep the live contiguous frontier slot intact"
    );
    assert_eq!(
        actor.authoritative_slot_owner_hash(height, view),
        Some(block_hash),
        "quorum-timeout recovery must keep the authoritative owner for committed + 1"
    );
    assert!(
        actor.range_pull_escalation_cooldowns.is_empty(),
        "quorum-timeout recovery must not emit block-sync reanchor traffic for committed + 1"
    );
    assert!(
        actor
            .frontier_slot
            .as_ref()
            .is_some_and(|slot| { slot.repair_state.quorum_timeout_rebroadcasted }),
        "the live slot should remember that it consumed the first rebroadcast window"
    );
}

#[tokio::test(flavor = "current_thread")]
async fn frontier_recovery_cleanup_prunes_descendant_state_above_frontier() {
    let _missing_block_guard = super::status::missing_block_fetch_test_guard();
    super::status::reset_missing_block_fetch_counters_for_tests();

    let mut harness = test_actor_harness_with_config(4, test_sumeragi_config(), None).await;
    let actor = &mut harness.actor;
    let _ = seed_genesis_block_for_state(&actor.state);

    let committed_height = actor.committed_height_snapshot();
    let frontier_height = committed_height.saturating_add(1);
    let descendant_height = frontier_height.saturating_add(1);
    let now = Instant::now();
    let stale = now.checked_sub(Duration::from_secs(30)).unwrap_or(now);
    let descendant_hash = insert_unresolved_missing_request_for_tests(
        actor,
        0xF5,
        descendant_height,
        1,
        stale,
        stale,
    );
    let descendant_key = actor.missing_block_recovery_key_for_height(descendant_height);
    actor.missing_block_height_recovery.insert(
        descendant_key,
        super::MissingBlockHeightRecoveryBudget::new(
            stale,
            descendant_hash,
            0,
            super::MissingBlockRecoveryStage::RangePullFromAnchor,
        ),
    );
    actor
        .missing_block_range_pull_expiry_streaks
        .insert(descendant_key, 9);

    actor.apply_frontier_recovery_cleanup(frontier_height, 0, now, "test_frontier_cleanup");

    assert!(
        !actor
            .pending
            .missing_block_requests
            .contains_key(&descendant_hash),
        "frontier cleanup must prune descendant missing-request state above the contiguous frontier"
    );
    assert!(
        !actor
            .missing_block_height_recovery
            .contains_key(&descendant_key),
        "frontier cleanup must remove descendant recovery budgets so only the contiguous frontier owns recovery"
    );
    assert!(
        !actor
            .missing_block_range_pull_expiry_streaks
            .contains_key(&descendant_key),
        "frontier cleanup must drop descendant expiry streaks with the pruned future state"
    );

    super::status::reset_missing_block_fetch_counters_for_tests();
    harness.shutdown.send();
}

