#[tokio::test(flavor = "current_thread")]
async fn frontier_missing_qc_cleanup_preserves_rbc_ready_frontier_repair_state() {
    let _missing_block_guard = super::status::missing_block_fetch_test_guard();
    super::status::reset_missing_block_fetch_counters_for_tests();

    let mut harness = test_actor_harness_with_config(4, test_sumeragi_config(), None).await;
    let actor = &mut harness.actor;
    let parent = seed_genesis_block_for_state(&actor.state);

    let frontier_height = actor.committed_height_snapshot().saturating_add(1);
    let descendant_height = frontier_height.saturating_add(1);
    let view = 2_u64;
    let now = Instant::now();
    let frontier_block = nonempty_block_for_actor(
        actor,
        &harness.key_pairs,
        frontier_height,
        view,
        Some(parent),
    );
    let frontier_hash = frontier_block.hash();
    let frontier_payload_hash = Hash::new(super::proposals::block_payload_bytes(&frontier_block));
    let frontier_key = (frontier_hash, frontier_height, view);

    actor.note_authoritative_slot_owner(frontier_height, view, frontier_hash);
    actor.pending.pending_blocks.insert(
        frontier_hash,
        PendingBlock::new(frontier_block, frontier_payload_hash, frontier_height, view),
    );
    let mut session = RbcSession::test_new(
        1,
        Some(frontier_payload_hash),
        None,
        actor.epoch_for_height(frontier_height),
    );
    session.sent_ready = true;
    let roster = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(roster.clone());
    let required = actor.rbc_deliver_quorum(&topology);
    assert!(required > 0, "test setup requires a non-zero RBC quorum");
    for sender in 0..required {
        session.record_ready(
            u32::try_from(sender).expect("sender index fits"),
            vec![u8::try_from(sender).unwrap_or(u8::MAX)],
        );
    }
    actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert(frontier_key, session);
    actor.record_rbc_session_roster(frontier_key, roster, super::RbcRosterSource::Derived);
    actor
        .subsystems
        .da_rbc
        .rbc
        .ready_rebroadcast_last_sent
        .insert(frontier_key, now);

    let descendant_hash =
        insert_unresolved_missing_request_for_tests(actor, 0xE7, descendant_height, 1, now, now);
    let descendant_key = (descendant_hash, descendant_height, view);
    actor.subsystems.da_rbc.rbc.sessions.insert(
        descendant_key,
        RbcSession::test_new(
            1,
            Some(Hash::prehashed([0xE7; Hash::LENGTH])),
            None,
            actor.epoch_for_height(descendant_height),
        ),
    );

    assert!(
        actor.has_rbc_available_frontier_repair_for_missing_qc_cleanup(frontier_height),
        "test setup requires RBC-ready frontier repair evidence before cleanup",
    );

    actor.apply_frontier_recovery_cleanup(frontier_height, view, now, "missing_qc");

    assert!(
        actor.pending.pending_blocks.contains_key(&frontier_hash),
        "missing-QC cleanup must not evict RBC-ready contiguous-frontier pending payloads",
    );
    assert!(
        actor
            .subsystems
            .da_rbc
            .rbc
            .sessions
            .contains_key(&frontier_key),
        "missing-QC cleanup must retain same-height RBC repair state with READY quorum",
    );
    assert!(
        actor
            .subsystems
            .da_rbc
            .rbc
            .ready_rebroadcast_last_sent
            .contains_key(&frontier_key),
        "missing-QC cleanup must retain same-height RBC READY pacing metadata",
    );
    assert!(
        !actor
            .pending
            .missing_block_requests
            .contains_key(&descendant_hash),
        "missing-QC cleanup should still prune descendant missing-request state above the frontier",
    );
    assert!(
        !actor
            .subsystems
            .da_rbc
            .rbc
            .sessions
            .contains_key(&descendant_key),
        "missing-QC cleanup should still prune descendant RBC state above the frontier",
    );

    super::status::reset_missing_block_fetch_counters_for_tests();
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn frontier_missing_qc_cleanup_ignores_status_only_delivery_when_local_payload_mismatches() {
    let _missing_block_guard = super::status::missing_block_fetch_test_guard();
    super::status::reset_missing_block_fetch_counters_for_tests();

    let mut harness = test_actor_harness_with_config(4, test_sumeragi_config(), None).await;
    let actor = &mut harness.actor;
    let parent = seed_genesis_block_for_state(&actor.state);

    let frontier_height = actor.committed_height_snapshot().saturating_add(1);
    let view = 2_u64;
    let frontier_block = nonempty_block_for_actor(
        actor,
        &harness.key_pairs,
        frontier_height,
        view,
        Some(parent),
    );
    let frontier_hash = frontier_block.hash();
    let actual_payload_hash = Hash::new(super::proposals::block_payload_bytes(&frontier_block));
    let advertised_payload_hash = Hash::new(b"status-only-advertised-payload");
    assert_ne!(
        actual_payload_hash, advertised_payload_hash,
        "test requires a pending payload hash that does not match the local body"
    );
    let frontier_key = (frontier_hash, frontier_height, view);

    actor.pending.pending_blocks.insert(
        frontier_hash,
        PendingBlock::new(
            frontier_block,
            advertised_payload_hash,
            frontier_height,
            view,
        ),
    );
    actor.subsystems.da_rbc.rbc.status_handle.update(
        super::rbc_status::Summary {
            block_hash: frontier_hash,
            height: frontier_height,
            view,
            total_chunks: 2,
            encoding: iroha_data_model::block::consensus::RbcEncoding::Plain,
            data_shards: 0,
            parity_shards: 0,
            received_chunks: 2,
            ready_count: 0,
            delivered: true,
            payload_hash: Some(advertised_payload_hash),
            recovered_from_disk: true,
            invalid: false,
            reconstructed_stripes: 0,
            reconstructable_stripes: 0,
            lane_backlog: Vec::new(),
            dataspace_backlog: Vec::new(),
        },
        SystemTime::now(),
    );

    assert!(
        !actor.has_rbc_available_frontier_repair_for_missing_qc_cleanup(frontier_height),
        "status-only delivered summaries must not make missing-QC cleanup treat a mismatched local body as available repair payload",
    );

    let ready_roster = actor.effective_commit_topology();
    let ready_topology = super::network_topology::Topology::new(ready_roster.clone());
    let required_ready = actor.rbc_deliver_quorum(&ready_topology);
    assert!(
        required_ready > 0,
        "test setup requires a positive READY quorum"
    );
    actor.record_rbc_session_roster(frontier_key, ready_roster, super::RbcRosterSource::Derived);
    actor.subsystems.da_rbc.rbc.status_handle.update(
        super::rbc_status::Summary {
            block_hash: frontier_hash,
            height: frontier_height,
            view,
            total_chunks: 2,
            encoding: iroha_data_model::block::consensus::RbcEncoding::Plain,
            data_shards: 0,
            parity_shards: 0,
            received_chunks: 1,
            ready_count: u64::try_from(required_ready).unwrap_or(u64::MAX),
            delivered: false,
            payload_hash: Some(advertised_payload_hash),
            recovered_from_disk: true,
            invalid: false,
            reconstructed_stripes: 0,
            reconstructable_stripes: 0,
            lane_backlog: Vec::new(),
            dataspace_backlog: Vec::new(),
        },
        SystemTime::now(),
    );
    assert!(
        !actor.has_rbc_available_frontier_repair_for_missing_qc_cleanup(frontier_height),
        "status-only READY quorum must not make missing-QC cleanup treat a mismatched local body as available repair payload",
    );
    assert!(
        actor
            .subsystems
            .da_rbc
            .rbc
            .status_handle
            .get(&frontier_key)
            .is_some(),
        "negative check should leave the diagnostic retained summary visible"
    );

    super::status::reset_missing_block_fetch_counters_for_tests();
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn frontier_recovery_cleanup_clears_frontier_new_view_state() {
    let mut harness = test_actor_harness_with_config(4, test_sumeragi_config(), None).await;
    let actor = &mut harness.actor;
    let _ = seed_genesis_block_for_state(&actor.state);

    let frontier_height = actor.committed_height_snapshot().saturating_add(1);
    let future_height = frontier_height.saturating_add(1);
    let higher_view = 5_u64;
    let future_view = 2_u64;
    let now = Instant::now();
    let committed_qc = actor.latest_committed_qc().expect("committed QC seeded");
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let tracker_peer = topology
        .as_ref()
        .first()
        .cloned()
        .expect("topology should include at least one peer");

    assert!(
        actor.emit_new_view_vote(frontier_height, higher_view, committed_qc, &topology),
        "test setup should seed a higher-view NEW_VIEW vote at the frontier"
    );
    actor.subsystems.propose.new_view_tracker.record(
        frontier_height,
        higher_view,
        tracker_peer.clone(),
        committed_qc,
    );
    actor.subsystems.propose.new_view_tracker.record(
        future_height,
        future_view,
        tracker_peer,
        sample_qc_ref(frontier_height, 0),
    );
    actor.subsystems.propose.forced_view_after_timeout = Some((future_height, future_view));

    actor.apply_frontier_recovery_cleanup(
        frontier_height,
        higher_view,
        now,
        "test_frontier_cleanup",
    );

    assert!(
        !actor
            .vote_log
            .values()
            .any(|vote| { vote.phase == Phase::NewView && vote.height >= frontier_height }),
        "frontier cleanup should drop NEW_VIEW vote history at or above the contiguous frontier"
    );
    assert_eq!(
        actor
            .subsystems
            .propose
            .new_view_tracker
            .count(frontier_height, higher_view),
        0,
        "frontier cleanup should clear same-height NEW_VIEW tracker state"
    );
    assert_eq!(
        actor
            .subsystems
            .propose
            .new_view_tracker
            .count(future_height, future_view),
        0,
        "frontier cleanup should clear future NEW_VIEW tracker state with the pruned frontier"
    );
    assert!(
        actor.subsystems.propose.forced_view_after_timeout.is_none(),
        "frontier cleanup should clear forced-view markers at or above the contiguous frontier"
    );
    assert!(
        actor.emit_new_view_vote(frontier_height, 0, committed_qc, &topology),
        "frontier cleanup should allow canonical NEW_VIEW voting after stale higher-view history is cleared"
    );

    harness.shutdown.send();
}

