#[tokio::test(flavor = "current_thread")]
async fn missing_payload_fetch_window_formal_gate_snapshot_lifecycle() {
    {
        let mut harness = test_actor_harness(4).await;
        let actor = &mut harness.actor;
        let height = actor.active_consensus_round_height();
        let wrong_height = height.saturating_add(1);
        let now = Instant::now();
        let block_hash = test_block_hash(0xD0);
        actor.missing_payload_fetch_window_gates.insert(
            (wrong_height, block_hash),
            missing_payload_fetch_window_gate_for_tests(wrong_height, block_hash, now, 4, Some(4)),
        );

        assert!(
            actor
                .missing_payload_fetch_window_snapshot(wrong_height, block_hash, now)
                .is_none(),
            "snapshot for a non-active round height must be rejected"
        );
        assert!(
            !actor
                .missing_payload_fetch_window_gates
                .contains_key(&(wrong_height, block_hash)),
            "wrong-height snapshot should clear only the requested gate"
        );
        harness.shutdown.send();
    }

    {
        let mut harness = test_actor_harness(4).await;
        let actor = &mut harness.actor;
        let height = actor.active_consensus_round_height();
        let now = Instant::now();
        let stale = now.checked_sub(Duration::from_secs(45)).unwrap_or(now);
        let block_hash =
            insert_unresolved_missing_request_for_tests(actor, 0xD1, height, 1, stale, stale);
        actor.missing_payload_fetch_window_gates.insert(
            (height, block_hash),
            missing_payload_fetch_window_gate_for_tests(height, block_hash, now, 0, Some(0)),
        );

        assert!(
            actor
                .missing_payload_fetch_window_snapshot(height, block_hash, now)
                .is_none(),
            "inactive same-height stall state must not keep payload fetch pacing gates"
        );
        assert!(
            !actor
                .missing_payload_fetch_window_gates
                .contains_key(&(height, block_hash)),
            "inactive stall snapshot should remove the payload fetch gate"
        );
        harness.shutdown.send();
    }

    {
        let mut harness = test_actor_harness(4).await;
        let actor = &mut harness.actor;
        let height = actor.active_consensus_round_height();
        let now = Instant::now();
        let block_hash = test_block_hash(0xD2);
        actor.missing_qc_height_stall = Some(super::MissingQcHeightStallState {
            height,
            dependency_height: height,
            committed_height: actor.committed_height_snapshot(),
            entered_at: now,
            last_window_at: now,
            windows_without_commit_progress: 3,
            mode_active: true,
            window_index: 0,
            last_rotation_at: None,
            last_rotation_window_index: None,
            last_reacquire_window_index: None,
        });
        actor.missing_payload_fetch_window_gates.insert(
            (height, block_hash),
            missing_payload_fetch_window_gate_for_tests(height, block_hash, now, 0, Some(0)),
        );

        assert!(
            actor
                .missing_payload_fetch_window_snapshot(height, block_hash, now)
                .is_none(),
            "absent unresolved payload dependency must clear payload fetch pacing gates"
        );
        assert!(
            !actor
                .missing_payload_fetch_window_gates
                .contains_key(&(height, block_hash)),
            "dependency-free snapshot should remove the payload fetch gate"
        );
        harness.shutdown.send();
    }

    {
        let mut harness = test_actor_harness(4).await;
        let actor = &mut harness.actor;
        let height = actor.active_consensus_round_height();
        let now = Instant::now();
        let stale = now.checked_sub(Duration::from_secs(45)).unwrap_or(now);
        let block_hash =
            insert_unresolved_missing_request_for_tests(actor, 0xD3, height, 1, stale, stale);
        let (stall_window, activate_at) =
            activate_missing_qc_height_stall_mode_for_tests(actor, height, now);
        let fresh = actor
            .missing_payload_fetch_window_snapshot(height, block_hash, activate_at)
            .expect("active same-height stall with unresolved payload should create a gate");
        assert_eq!(fresh.height, height);
        assert_eq!(fresh.block_hash, block_hash);
        assert_eq!(fresh.entered_at, activate_at);
        assert_eq!(fresh.window_index, 0);
        assert_eq!(fresh.last_targeted_fetch_at, None);
        assert_eq!(
            actor
                .missing_payload_fetch_window_gates
                .get(&(height, block_hash))
                .expect("fresh payload fetch gate should be stored")
                .last_window_at,
            activate_at
        );

        actor.mark_missing_payload_fetch_window_emitted(
            height,
            block_hash,
            fresh.window_index,
            activate_at,
        );
        let same_window_at = activate_at + Duration::from_millis(1);
        let same_window = actor
            .missing_payload_fetch_window_snapshot(height, block_hash, same_window_at)
            .expect("same active stall window should preserve the payload fetch gate");
        assert_eq!(same_window.entered_at, fresh.entered_at);
        assert_eq!(same_window.window_index, fresh.window_index);
        assert_eq!(same_window.last_targeted_fetch_at, Some(activate_at));
        assert!(
            actor.missing_payload_fetch_window_already_emitted(
                height,
                block_hash,
                same_window.window_index,
            ),
            "same-window snapshot should preserve the prior targeted-fetch mark"
        );

        actor.missing_payload_fetch_window_gates.insert(
            (height, block_hash),
            missing_payload_fetch_window_gate_for_tests(
                height,
                block_hash,
                activate_at,
                9,
                Some(9),
            ),
        );
        let older_reset = actor
            .missing_payload_fetch_window_snapshot(height, block_hash, same_window_at)
            .expect("older stall window should reset stale payload fetch gate metadata");
        assert_eq!(older_reset.entered_at, same_window_at);
        assert_eq!(older_reset.window_index, 0);
        assert_eq!(older_reset.last_targeted_fetch_at, None);
        assert!(
            !actor.missing_payload_fetch_window_already_emitted(height, block_hash, 0),
            "older-window reset should clear stale targeted-fetch marks"
        );

        actor.mark_missing_payload_fetch_window_emitted(height, block_hash, 0, same_window_at);
        let next_window_at = activate_at + stall_window + Duration::from_millis(1);
        let newer = actor
            .missing_payload_fetch_window_snapshot(height, block_hash, next_window_at)
            .expect("newer active stall window should advance the payload fetch gate");
        assert_eq!(
            newer.entered_at, same_window_at,
            "newer stall windows should preserve original gate entry time"
        );
        assert_eq!(newer.window_index, 1);
        assert_eq!(newer.last_targeted_fetch_at, Some(same_window_at));
        assert!(
            !actor.missing_payload_fetch_window_already_emitted(height, block_hash, 1),
            "newer stall window must not claim the new window was already emitted"
        );
        harness.shutdown.send();
    }
}

#[tokio::test(flavor = "current_thread")]
async fn missing_payload_fetch_window_formal_gate_emit_and_clear_scope() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let height = actor.active_consensus_round_height();
    let other_height = height.saturating_add(1);
    let now = Instant::now();
    let block_hash = test_block_hash(0xD4);
    let other_hash = test_block_hash(0xD5);

    assert!(
        !actor.missing_payload_fetch_window_already_emitted(height, block_hash, 0),
        "absent payload fetch gates must not report a targeted fetch emission"
    );
    actor.mark_missing_payload_fetch_window_emitted(height, block_hash, 0, now);
    assert!(
        !actor
            .missing_payload_fetch_window_gates
            .contains_key(&(height, block_hash)),
        "marking an absent payload fetch gate must be a no-op"
    );

    actor.missing_payload_fetch_window_gates.insert(
        (height, block_hash),
        missing_payload_fetch_window_gate_for_tests(height, block_hash, now, 2, None),
    );
    assert!(
        !actor.missing_payload_fetch_window_already_emitted(height, block_hash, 1),
        "prior payload fetch windows must not suppress later windows"
    );
    actor.mark_missing_payload_fetch_window_emitted(height, block_hash, 2, now);
    assert!(
        actor.missing_payload_fetch_window_already_emitted(height, block_hash, 2),
        "marking an existing payload fetch gate should suppress the exact emitted window"
    );
    assert_eq!(
        actor
            .missing_payload_fetch_window_gates
            .get(&(height, block_hash))
            .expect("marked payload fetch gate should remain stored")
            .last_targeted_fetch_at,
        Some(now)
    );

    actor.missing_payload_fetch_window_gates.insert(
        (other_height, block_hash),
        missing_payload_fetch_window_gate_for_tests(other_height, block_hash, now, 2, Some(2)),
    );
    actor.missing_payload_fetch_window_gates.insert(
        (height, other_hash),
        missing_payload_fetch_window_gate_for_tests(height, other_hash, now, 2, Some(2)),
    );

    actor.clear_missing_payload_fetch_window_gate_for_height(other_height);
    assert!(
        !actor
            .missing_payload_fetch_window_gates
            .contains_key(&(other_height, block_hash)),
        "height-scoped clearing should remove the exact height"
    );
    assert!(
        actor
            .missing_payload_fetch_window_gates
            .contains_key(&(height, block_hash)),
        "height-scoped clearing must retain other heights"
    );
    assert!(
        actor
            .missing_payload_fetch_window_gates
            .contains_key(&(height, other_hash)),
        "height-scoped clearing must retain other blocks at retained heights"
    );

    actor.clear_missing_payload_fetch_window_gate_for_block(height, other_hash);
    assert!(
        !actor
            .missing_payload_fetch_window_gates
            .contains_key(&(height, other_hash)),
        "block-scoped clearing should remove the exact block"
    );
    assert!(
        actor
            .missing_payload_fetch_window_gates
            .contains_key(&(height, block_hash)),
        "block-scoped clearing must retain other blocks at the same height"
    );

    actor.clear_missing_payload_fetch_window_gate_for_height(height);
    assert!(
        actor.missing_payload_fetch_window_gates.is_empty(),
        "final exact-height clearing should remove the remaining payload fetch gate"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn missing_payload_fetch_window_formal_gate_hash_miss_cap() {
    {
        let mut harness = test_actor_harness(4).await;
        let actor = &mut harness.actor;
        assert_eq!(
            actor.effective_hash_miss_escalation_cap(10, 2, 10),
            2,
            "hash-miss cap should stay at the base value without lock-lag"
        );
        harness.shutdown.send();
    }

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let frontier = seed_lock_lag_frontier_for_tests(actor, 0xD6, 6);
    let below_frontier = frontier.saturating_sub(1);
    let near_height = frontier.saturating_add(1);
    let far_height = frontier.saturating_add(4);

    assert_eq!(
        actor.effective_hash_miss_escalation_cap(below_frontier, 2, 10),
        2,
        "lock-lag widening should not apply below the catch-up frontier"
    );
    assert_eq!(
        actor.effective_hash_miss_escalation_cap(near_height, 2, 3),
        3,
        "near-frontier cap should clamp to max(base, attempt) when base+2 would exceed it"
    );
    assert_eq!(
        actor.effective_hash_miss_escalation_cap(near_height, 1, 10),
        4,
        "near-frontier cap should use ceiling division when it dominates base+2"
    );
    assert_eq!(
        actor.effective_hash_miss_escalation_cap(far_height, 1, 12),
        6,
        "far-future lock-lag cap should include the half-attempt widening"
    );
    assert_eq!(
        actor.effective_hash_miss_escalation_cap(near_height, 1, 12),
        4,
        "far-future flag must still respect actual distance from the catch-up frontier"
    );
    assert_eq!(
        actor.effective_hash_miss_escalation_cap(near_height, 5, 6),
        6,
        "widened caps must be clamped by max(base, attempt cap)"
    );
    assert_eq!(
        actor.effective_hash_miss_escalation_cap(near_height, 5, 2),
        5,
        "attempt caps below the base cap must not shrink the base threshold"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn missing_qc_height_stall_mode_throttles_deferred_qc_targeted_fetch_to_one_per_window() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.active_consensus_round_height();
    let now = Instant::now();
    let stale = now.checked_sub(Duration::from_secs(45)).unwrap_or(now);
    let block_hash =
        insert_unresolved_missing_request_for_tests(actor, 0xA9, height, 1, stale, stale);

    let (stall_window, activate_at) =
        activate_missing_qc_height_stall_mode_for_tests(actor, height, now);
    assert!(
        actor
            .missing_qc_height_stall_snapshot(height, activate_at)
            .is_some_and(|stall| stall.mode_active),
        "test setup should activate same-height missing-QC stall mode"
    );

    let first_window = actor
        .missing_payload_fetch_window_snapshot(height, block_hash, activate_at)
        .expect("stall window gate should be available for unresolved same-height payload");
    assert!(
        !actor.missing_payload_fetch_window_already_emitted(
            height,
            block_hash,
            first_window.window_index,
        ),
        "fresh stalled window should not be marked as already emitted"
    );
    actor.mark_missing_payload_fetch_window_emitted(
        height,
        block_hash,
        first_window.window_index,
        activate_at,
    );
    assert!(
        actor.missing_payload_fetch_window_already_emitted(
            height,
            block_hash,
            first_window.window_index
        ),
        "first emission mark should gate repeated targeted fetches in the same window"
    );

    if let Some(stall) = actor.missing_qc_height_stall.as_mut() {
        let rewind = stall_window.saturating_add(Duration::from_millis(1));
        stall.last_window_at = stall
            .last_window_at
            .checked_sub(rewind)
            .unwrap_or(stall.last_window_at);
    }

    let second_window = actor
        .missing_payload_fetch_window_snapshot(
            height,
            block_hash,
            activate_at + stall_window + Duration::from_millis(1),
        )
        .expect("next stall window should still track unresolved payload gate");
    assert!(
        second_window.window_index > first_window.window_index,
        "stall window index should advance once the window elapses"
    );
    assert!(
        !actor.missing_payload_fetch_window_already_emitted(
            height,
            block_hash,
            second_window.window_index,
        ),
        "next stalled window should allow one deferred-QC targeted fetch again"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn deferred_missing_payload_qc_replay_respects_same_height_stall_window_pacing() {
    let _view_guard = super::status::view_change_cause_test_guard();
    super::status::reset_view_change_cause_counters_for_tests();

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.active_consensus_round_height();
    let view = 0_u64;
    let now = Instant::now();
    let stale = now.checked_sub(Duration::from_secs(45)).unwrap_or(now);
    let block_hash =
        insert_unresolved_missing_request_for_tests(actor, 0xAA, height, 1, stale, stale);

    let (stall_window, activate_at) =
        activate_missing_qc_height_stall_mode_for_tests(actor, height, now);
    assert!(
        actor
            .missing_qc_height_stall_snapshot(height, activate_at)
            .is_some_and(|stall| stall.mode_active),
        "test setup should activate same-height missing-QC stall mode"
    );

    let qc = Qc {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch: actor.epoch_for_height(height),
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        mode_tag: super::PERMISSIONED_TAG.to_string(),
        highest_qc: None,
        validator_set_hash: HashOf::new(&Vec::<PeerId>::new()),
        validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
        validator_set: Vec::new(),
        aggregate: QcAggregate {
            signers_bitmap: Vec::new(),
            bls_aggregate_signature: Vec::new(),
        },
    };
    let key = super::Actor::qc_tally_key(&qc);
    actor.deferred_missing_payload_qcs.insert(
        key,
        super::DeferredQcEntry {
            qc,
            first_seen: activate_at
                .checked_sub(actor.recovery_deferred_qc_ttl() + Duration::from_millis(1))
                .unwrap_or(activate_at),
            last_attempt: activate_at,
            attempts: super::DEFERRED_MISSING_PAYLOAD_QC_MAX_ATTEMPTS,
            escalated_fetch: true,
            reason: "test_stall_window_pacing",
        },
    );

    let before = super::status::snapshot()
        .view_change_causes
        .missing_payload_total;
    assert!(
        !actor.try_replay_deferred_missing_payload_qcs(activate_at + Duration::from_millis(1)),
        "replay should be paced while still in the same stalled window"
    );
    assert!(
        actor.deferred_missing_payload_qcs.contains_key(&key),
        "paced replay should keep deferred QC queued"
    );
    assert_eq!(
        super::status::snapshot()
            .view_change_causes
            .missing_payload_total,
        before,
        "paced replay must not rotate view in the same stalled window"
    );

    assert!(
        actor.try_replay_deferred_missing_payload_qcs(
            activate_at + stall_window + Duration::from_millis(1)
        ),
        "replay should proceed once the next stalled window opens"
    );
    assert!(
        !actor.deferred_missing_payload_qcs.contains_key(&key),
        "deferred QC should be drained after paced replay is allowed"
    );
    assert!(
        actor.frontier_recovery.is_some_and(|state| {
            state.frontier_height == height && state.last_cause == "missing_payload"
        }),
        "paced replay should hand contiguous-frontier MissingPayload recovery to the unified controller"
    );
    assert_eq!(
        super::status::snapshot()
            .view_change_causes
            .missing_payload_total,
        before,
        "paced replay should no longer emit an immediate direct MissingPayload rotation"
    );

    super::status::reset_view_change_cause_counters_for_tests();
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn missing_qc_height_stall_mode_hard_cap_suppression_retries_next_window() {
    let mut harness = test_actor_harness_with_config(4, test_sumeragi_config(), None).await;
    let _guard = super::status::view_change_cause_test_guard();
    super::status::reset_view_change_cause_counters_for_tests();
    let actor = &mut harness.actor;

    let now = Instant::now();
    let height = actor.active_consensus_round_height();
    let stall_window = actor.missing_qc_height_stall_window();
    actor.missing_qc_height_stall = Some(super::MissingQcHeightStallState {
        height,
        dependency_height: height,
        committed_height: actor.committed_height_snapshot(),
        entered_at: now,
        last_window_at: now,
        windows_without_commit_progress: 3,
        mode_active: true,
        window_index: 0,
        last_rotation_at: Some(now),
        last_rotation_window_index: Some(0),
        last_reacquire_window_index: None,
    });

    let view = 0_u64;
    actor.phase_tracker.start_new_round(height, now);
    actor.phase_tracker.on_view_change(height, view, now);

    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xAB; Hash::LENGTH]));
    let ttl = actor
        .recovery_missing_block_height_ttl()
        .max(Duration::from_millis(1));
    let stale = now
        .checked_sub(ttl + Duration::from_millis(1))
        .unwrap_or(now);

    actor.note_missing_block_height_attempt(
        block_hash,
        height,
        view,
        super::MissingBlockRecoveryStage::HashFetch,
        None,
        stale,
    );
    let key = actor.missing_block_recovery_key_for_height(height);
    let attempt_cap = actor.recovery_missing_block_height_attempt_cap().max(1);
    {
        let budget = actor
            .missing_block_height_recovery
            .get_mut(&key)
            .expect("height budget should exist");
        budget.attempts = attempt_cap;
        budget.first_seen = stale;
        budget.last_seen = now;
        budget.range_pull.stage = super::MissingBlockRecoveryStage::RangePullFromAnchor;
        budget.range_pull.candidate_tier = super::RangePullCandidateTier::TrustedPeers;
        budget.range_pull.inflight = true;
        budget.range_pull.last_requested = Some(now - ttl / 2);
        budget.range_pull.last_progress = stale;
    }

    actor.pending.missing_block_requests.insert(
        block_hash,
        super::MissingBlockRequest {
            height,
            view,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window: Duration::from_millis(10),
            view_change_window: Some(Duration::from_millis(10)),
            first_seen: stale,
            last_requested: now - ttl / 2,
            last_dependency_progress: stale,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 2,
        },
    );

    let before = super::status::snapshot();
    let _ = actor.maybe_escalate_missing_block_height_recovery(block_hash, height, view, now);
    let after_first = super::status::snapshot();
    assert_eq!(
        after_first.view_change_causes.missing_payload_total,
        before.view_change_causes.missing_payload_total,
        "used stall-window rotation budget should suppress hard-cap escalation in the same window"
    );
    assert!(
        actor.missing_block_height_recovery.contains_key(&key),
        "suppressed hard-cap escalation should keep recovery budget for next window retry"
    );

    let second_now = now + stall_window + Duration::from_millis(1);
    assert!(
        actor.maybe_escalate_missing_block_height_recovery(block_hash, height, view, second_now),
        "next stalled window should allow fail-closed hard-cap escalation"
    );
    let after_second = super::status::snapshot();
    assert_eq!(
        after_second.view_change_causes.missing_payload_total,
        before
            .view_change_causes
            .missing_payload_total
            .saturating_add(1),
        "fail-closed hard-cap escalation must fire once next stall window opens"
    );

    super::status::reset_view_change_cause_counters_for_tests();
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn deterministic_fanout_committee_uses_formula_and_key_tiebreak() {
    let _guard = super::status::missing_block_fetch_test_guard();
    super::status::reset_missing_block_fetch_counters_for_tests();
    let mut harness = test_actor_harness(10).await;
    let mut fallback_peers: Vec<_> = harness
        .key_pairs
        .iter()
        .map(|key_pair| PeerId::new(key_pair.public_key().clone()))
        .collect();
    fallback_peers.sort();
    fallback_peers.dedup();
    let actor = &mut harness.actor;
    actor.config.fanout.large_set_threshold = 1;
    actor.config.fanout.activity_lookback_blocks = 64;

    let mut peers = actor.effective_commit_topology();
    if peers.len() <= 1 {
        peers = fallback_peers;
    }
    assert!(peers.len() > 1, "test requires a multi-peer topology");
    let committee = actor.deterministic_fanout_committee_for_round(
        &peers,
        actor.config.fanout.activity_lookback_blocks,
    );
    let topology = super::network_topology::Topology::new(peers.clone());
    let required_commit_votes = topology.min_votes_for_commit();
    let redundancy_margin = std::cmp::max(2, required_commit_votes.saturating_add(9) / 10);
    let expected_size = required_commit_votes
        .saturating_add(redundancy_margin)
        .min(peers.len());
    assert_eq!(
        committee.peers.len(),
        expected_size,
        "deterministic committee size should follow quorum + redundancy formula"
    );

    let mut expected_sorted = peers.clone();
    expected_sorted.sort_by(|lhs, rhs| {
        lhs.public_key()
            .cmp(rhs.public_key())
            .then_with(|| lhs.cmp(rhs))
    });
    let expected_sorted: Vec<_> = expected_sorted.into_iter().take(expected_size).collect();
    assert_eq!(
        committee.peers, expected_sorted,
        "without activity evidence, committee should tie-break by peer key ordering"
    );

    let selected = actor.transport_fanout_targets_for_round(&peers, 7, 3, "test_committee");
    assert_eq!(
        selected, committee.peers,
        "transport fanout should use the deterministic committee for large sets"
    );

    let snapshot = super::status::snapshot();
    assert_eq!(
        snapshot.consensus_deterministic_committee_size,
        u64::try_from(expected_size).unwrap_or(u64::MAX)
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn missing_block_hash_miss_streak_escalates_to_range_pull() {
    let _missing_block_guard = super::status::missing_block_fetch_test_guard();
    super::status::reset_missing_block_fetch_counters_for_tests();
    let mut harness = test_actor_harness_with_config(4, test_sumeragi_config(), None).await;
    let actor = &mut harness.actor;
    let committed_block = sample_block(1, 0, None);
    actor
        .kura
        .store_block(committed_block.clone())
        .expect("store committed anchor block");
    Arc::get_mut(&mut actor.state)
        .expect("state uniquely held")
        .push_block_hash_for_testing(committed_block.hash());
    let height = actor.state.view().height() as u64 + 1;
    let view = 0;
    let now = Instant::now();
    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xDA; Hash::LENGTH]));
    insert_unresolved_missing_request_for_hash_for_tests(
        actor, block_hash, height, view, 0, now, now,
    );
    let before = super::status::snapshot();

    let hash_miss_cap = actor.recovery_range_pull_escalation_after_hash_misses();
    for idx in 0..hash_miss_cap {
        let at = now + Duration::from_millis(u64::from(idx) + 1);
        actor.note_missing_block_height_hash_miss(
            block_hash,
            height,
            view,
            super::MissingBlockRecoveryStage::HashFetch,
            at,
        );
        let escalated =
            actor.maybe_escalate_missing_block_height_recovery(block_hash, height, view, at);
        if idx + 1 < hash_miss_cap {
            assert!(!escalated, "hash miss streak should wait for cap");
        } else {
            assert!(escalated, "hash miss streak should escalate to range pull");
        }
    }
    let key = actor.missing_block_recovery_key_for_height(height);
    let entry = actor
        .missing_block_height_recovery
        .get(&key)
        .copied()
        .expect("recovery budget should remain tracked");
    assert_eq!(
        entry.range_pull.stage,
        super::MissingBlockRecoveryStage::RangePullFromAnchor
    );

    let after = super::status::snapshot();
    assert!(
        after.blocksync_range_pull_escalation_total
            >= before
                .blocksync_range_pull_escalation_total
                .saturating_add(1)
    );
    assert_eq!(
        after.consensus_missing_block_height_escalation_total,
        before.consensus_missing_block_height_escalation_total,
        "hash-miss range pull should not count as hard-cap view-change escalation"
    );

    harness.shutdown.send();
}

