#[tokio::test(flavor = "current_thread")]
async fn retry_missing_block_requests_forces_view_change_after_backlog_extension_expires() {
    super::status::reset_worker_loop_snapshot_for_tests();
    let mut harness = test_actor_harness_with_config(4, test_sumeragi_config(), None).await;
    let _guard = super::status::view_change_proof_test_guard();
    super::status::reset_view_change_cause_counters_for_tests();
    let actor = &mut harness.actor;
    actor.queue_drop_backpressure.reset_to_current();
    let height = actor.state.view().height() as u64 + 1;
    let view = 0;
    let now = Instant::now();
    actor.phase_tracker.start_new_round(height, now);
    actor.phase_tracker.on_view_change(height, view, now);

    let mut block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xFA; Hash::LENGTH]));
    if actor.block_payload_available_locally(block_hash) {
        block_hash =
            HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xFB; Hash::LENGTH]));
    }

    let retry_window = Duration::from_millis(10);
    let base_window = Duration::from_millis(40);
    let extended_window = actor.backlog_extended_view_change_timeout(base_window, true);
    let dwell_start = now - extended_window - Duration::from_millis(1);
    let stale_progress = dwell_start
        .checked_sub(actor.recovery_missing_block_height_ttl() + Duration::from_millis(1))
        .unwrap_or(dwell_start);
    actor.pending.missing_block_requests.insert(
        block_hash,
        super::MissingBlockRequest {
            height,
            view,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window,
            view_change_window: Some(base_window),
            first_seen: dwell_start,
            last_requested: dwell_start,
            last_dependency_progress: stale_progress,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );

    super::status::record_worker_queue_drop(super::status::WorkerQueueKind::RbcChunks);

    assert!(
        actor.retry_missing_block_requests(now, None),
        "retry should progress by forcing a view change once backlog extension is exhausted"
    );
    assert_eq!(
        actor
            .pending
            .missing_block_requests
            .get(&block_hash)
            .and_then(|stats| stats.view_change_triggered_view),
        None,
        "backlog-extension expiry should hand recovery to the frontier controller instead of marking a direct view change"
    );
    assert!(
        actor.frontier_recovery.is_some_and(|state| {
            state.frontier_height == height
                && state.phase == super::FrontierRecoveryPhase::CatchUp
                && state.last_cause == "missing_payload"
        }) || actor.frontier_slot.as_ref().is_some_and(|slot| {
            slot.height == height
                && slot.view == view
                && slot.block_hash == block_hash
                && slot.exact_fetch_armed
                && !slot.body_present()
        }),
        "backlog-extension expiry should hand ownership to the frontier recovery controller"
    );
    let snapshot = super::status::snapshot().view_change_causes;
    assert_eq!(snapshot.missing_payload_total, 0);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn retry_missing_block_requests_defers_view_change_when_queue_blocks_seen() {
    let _worker_guard = super::status::worker_queue_test_guard();
    super::status::reset_worker_loop_snapshot_for_tests();
    let mut harness = test_actor_harness(4).await;
    let _guard = super::status::view_change_proof_test_guard();
    super::status::reset_view_change_cause_counters_for_tests();
    let actor = &mut harness.actor;
    actor.queue_block_backpressure.reset_to_current();
    let height = actor.state.view().height() as u64 + 1;
    let view = 0;
    let now = Instant::now();
    actor.phase_tracker.start_new_round(height, now);
    actor.phase_tracker.on_view_change(height, view, now);

    let mut block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xBF; Hash::LENGTH]));
    if actor.block_payload_available_locally(block_hash) {
        block_hash =
            HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xC0; Hash::LENGTH]));
    }

    let retry_window = Duration::from_millis(10);
    let dwell_start = now - retry_window - Duration::from_millis(1);
    actor.pending.missing_block_requests.insert(
        block_hash,
        super::MissingBlockRequest {
            height,
            view,
            phase: Phase::Commit,
            priority: super::MissingBlockPriority::Consensus,
            retry_window,
            view_change_window: Some(retry_window),
            first_seen: dwell_start,
            last_requested: dwell_start,
            last_dependency_progress: dwell_start,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );

    super::status::record_worker_queue_blocked(
        super::status::WorkerQueueKind::BlockPayload,
        Duration::from_millis(5),
    );

    assert!(
        actor.retry_missing_block_requests(now, None),
        "retry should attempt fetch or deferred view change"
    );
    assert!(
        actor
            .pending
            .missing_block_requests
            .get(&block_hash)
            .is_none(),
        "contiguous frontier retry should leave the generic missing-block tracker",
    );
    let frontier_slot = actor
        .frontier_slot
        .as_ref()
        .expect("frontier slot retained");
    assert_eq!(frontier_slot.height, height);
    assert_eq!(frontier_slot.view, view);
    assert_eq!(frontier_slot.block_hash, block_hash);
    assert!(
        frontier_slot.exact_fetch_armed,
        "queue-block backpressure should still keep contiguous frontier recovery on the exact-body lane",
    );
    assert!(
        !frontier_slot.body_present(),
        "test setup expects the frontier body to remain missing while view change stays deferred",
    );
    assert!(
        frontier_slot.repair_state.fetch_stage == super::FrontierBodyFetchStage::Leader,
        "contiguous frontier retry should stay on the leader-first exact fetch stage",
    );
    assert!(
        frontier_slot.timers.last_fetch_at.is_none(),
        "queue-block backpressure should not advance exact frontier fetch timing before the grace window elapses",
    );
    assert!(
        !frontier_slot.block_created_seen,
        "generic retry should not fabricate authoritative BlockCreated identity",
    );
    assert!(
        frontier_slot.frontier_info.as_ref().is_none(),
        "generic retry should not fabricate authoritative frontier metadata",
    );
    assert!(
        frontier_slot.repair_state.pending_requesters.is_empty(),
        "local exact frontier routing should remain receiver-driven only",
    );
    assert!(
        actor.frontier_recovery.is_none(),
        "queue-block backpressure should keep contiguous recovery inside the exact frontier slot instead of handing off to the old frontier controller",
    );
    assert!(
        actor.frontier_body_next_due(now).is_some(),
        "exact frontier retry should still schedule a later leader-first body fetch",
    );
    assert!(
        !actor
            .pending
            .pending_fetch_requests
            .contains_key(&block_hash),
        "exact frontier routing should not leave a generic pending fetch request behind",
    );
    let snapshot = super::status::snapshot().view_change_causes;
    assert_eq!(snapshot.missing_payload_total, 0);

    harness.shutdown.send();
}

