#[test]
fn lane_interleave_formal_gate_matrix() {
    struct Case {
        name: &'static str,
        lanes: &'static [u32],
        offset: usize,
        height: u64,
        view: u64,
        expected: &'static [usize],
    }

    fn routing_for_lanes(lanes: &[u32]) -> Vec<RoutingDecision> {
        lanes
            .iter()
            .enumerate()
            .map(|(idx, lane)| {
                RoutingDecision::new(
                    LaneId::new(*lane),
                    DataSpaceId::new(u64::try_from(idx + 1).expect("dataspace id fits")),
                )
            })
            .collect()
    }

    let cases = [
        Case {
            name: "empty",
            lanes: &[],
            offset: 2,
            height: 2,
            view: 0,
            expected: &[],
        },
        Case {
            name: "single_item",
            lanes: &[1],
            offset: 7,
            height: 7,
            view: 0,
            expected: &[0],
        },
        Case {
            name: "single_lane",
            lanes: &[5, 5, 5],
            offset: 3,
            height: 3,
            view: 0,
            expected: &[0, 1, 2],
        },
        Case {
            name: "two_lanes_balanced",
            lanes: &[1, 2, 1, 2],
            offset: 0,
            height: 0,
            view: 0,
            expected: &[0, 1, 2, 3],
        },
        Case {
            name: "two_lanes_skewed",
            lanes: &[1, 1, 1, 2, 2],
            offset: 0,
            height: 0,
            view: 0,
            expected: &[0, 3, 1, 4, 2],
        },
        Case {
            name: "offset_rotates",
            lanes: &[1, 2, 1, 2],
            offset: 1,
            height: 1,
            view: 0,
            expected: &[1, 0, 3, 2],
        },
        Case {
            name: "offset_wraps",
            lanes: &[1, 2, 3, 1],
            offset: 5,
            height: 5,
            view: 0,
            expected: &[2, 0, 1, 3],
        },
        Case {
            name: "sorted_lanes_not_first_seen",
            lanes: &[3, 1, 3, 2],
            offset: 0,
            height: 0,
            view: 0,
            expected: &[1, 3, 0, 2],
        },
        Case {
            name: "three_lanes_missing_later",
            lanes: &[1, 1, 2, 3, 2],
            offset: 0,
            height: 0,
            view: 0,
            expected: &[0, 2, 3, 1, 4],
        },
    ];

    for case in cases {
        let routing = routing_for_lanes(case.lanes);
        let offset_order = super::interleave_lane_indices_from_offset(&routing, case.offset);
        assert_eq!(
            offset_order.as_slice(),
            case.expected,
            "{} offset",
            case.name
        );

        let slot_order = super::interleave_lane_indices_for_slot(&routing, case.height, case.view);
        assert_eq!(slot_order.as_slice(), case.expected, "{} slot", case.name);

        if case.offset == 0 {
            let zero_offset_order = super::interleave_lane_indices(&routing);
            assert_eq!(
                zero_offset_order.as_slice(),
                case.expected,
                "{} zero offset",
                case.name
            );
        }
    }
}

#[tokio::test(flavor = "current_thread")]
async fn derive_rbc_allocations_splits_chunks_across_lanes() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let chain: ChainId = "rbc-alloc".parse().expect("chain id");
    let key_pair = checked_keypair();
    let (_, private_key) = key_pair.clone().into_parts();
    let authority = AccountId::new(key_pair.public_key().clone());
    let build_tx = |count: u32| {
        let instructions = (0..count).map(|idx| {
            let domain_id =
                DomainId::try_new(format!("alloc{idx}"), "universal").expect("domain id");
            let domain = Domain::new(domain_id);
            InstructionBox::from(Register::domain(domain))
        });
        TransactionBuilder::new(chain.clone(), authority.clone())
            .with_instructions(instructions)
            .sign(&private_key)
    };

    let txs = vec![
        AcceptedTransaction::new_unchecked(Cow::Owned(build_tx(1))),
        AcceptedTransaction::new_unchecked(Cow::Owned(build_tx(3))),
    ];
    let routing = vec![
        RoutingDecision::new(LaneId::new(1), DataSpaceId::new(10)),
        RoutingDecision::new(LaneId::new(2), DataSpaceId::new(20)),
    ];
    let tx_sizes: Vec<usize> = txs.iter().map(|tx| tx.as_ref().encode().len()).collect();

    let total_chunks = 4;
    let (lane_alloc, dataspace_alloc) = actor
        .derive_rbc_allocations(&txs, &routing, &tx_sizes, total_chunks)
        .expect("allocations");

    assert_eq!(lane_alloc.len(), 2);
    assert_eq!(dataspace_alloc.len(), 2);
    let assigned: u32 = lane_alloc.iter().map(|alloc| alloc.total_chunks).sum();
    assert_eq!(assigned, total_chunks);

    let mut lane_totals = BTreeMap::new();
    for alloc in &lane_alloc {
        lane_totals.insert(alloc.lane_id, alloc.total_chunks);
    }
    for lane_id in [LaneId::new(1), LaneId::new(2)] {
        let lane_total = lane_totals.get(&lane_id).copied().unwrap_or(0);
        let dataspace_total: u32 = dataspace_alloc
            .iter()
            .filter(|alloc| alloc.lane_id == lane_id)
            .map(|alloc| alloc.total_chunks)
            .sum();
        assert_eq!(dataspace_total, lane_total);
        assert!(
            lane_total > 0,
            "each lane with traffic should receive chunk allocations"
        );
    }

    harness.shutdown.send();
}

#[cfg(target_pointer_width = "64")]
#[tokio::test(flavor = "current_thread")]
async fn derive_rbc_allocations_rejects_allocation_byte_overflow() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let chain: ChainId = "rbc-alloc-overflow".parse().expect("chain id");
    let key_pair = checked_keypair();
    let (_, private_key) = key_pair.clone().into_parts();
    let authority = AccountId::new(key_pair.public_key().clone());
    let build_tx = || {
        let domain_id = DomainId::try_new("alloc-overflow", "universal").expect("domain id");
        let domain = Domain::new(domain_id);
        TransactionBuilder::new(chain.clone(), authority.clone())
            .with_instructions([Register::domain(domain)])
            .sign(&private_key)
    };

    let txs = vec![
        AcceptedTransaction::new_unchecked(Cow::Owned(build_tx())),
        AcceptedTransaction::new_unchecked(Cow::Owned(build_tx())),
    ];
    let routing = vec![
        RoutingDecision::new(LaneId::new(7), DataSpaceId::new(70)),
        RoutingDecision::new(LaneId::new(7), DataSpaceId::new(70)),
    ];
    let tx_sizes = vec![
        usize::try_from(u64::MAX).expect("u64::MAX fits usize on 64-bit targets"),
        1,
    ];

    let err = actor
        .derive_rbc_allocations(&txs, &routing, &tx_sizes, 2)
        .expect_err("overflowing allocation byte counter must fail");
    let rbc_err = err
        .downcast_ref::<super::rbc::RbcError>()
        .expect("derive_rbc_allocations should report an RBC error");
    assert!(matches!(
        rbc_err,
        super::rbc::RbcError::AllocationCounterOverflow {
            field: "lane.rbc_bytes_total",
            current: u64::MAX,
            added: 1
        }
    ));

    harness.shutdown.send();
}

#[test]
fn topology_refresh_decision_flags_changes_and_strays() {
    let peer_a = PeerId::new(checked_keypair().public_key().clone());
    let peer_b = PeerId::new(checked_keypair().public_key().clone());
    let peer_c = PeerId::new(checked_keypair().public_key().clone());

    let current: BTreeSet<_> = [peer_a.clone(), peer_b.clone()].into_iter().collect();
    let last_advertised: BTreeSet<_> = [peer_a.clone()].into_iter().collect();
    let empty = BTreeSet::new();

    assert_eq!(
        super::topology_refresh_decision(&empty, &last_advertised, &[]),
        super::TopologyRefreshDecision::NoPeers
    );
    assert_eq!(
        super::topology_refresh_decision(&current, &current, &[]),
        super::TopologyRefreshDecision::Unchanged
    );
    assert_eq!(
        super::topology_refresh_decision(&current, &last_advertised, &[]),
        super::TopologyRefreshDecision::AdvertiseChanged
    );
    assert_eq!(
        super::topology_refresh_decision(&current, &current, &[peer_c]),
        super::TopologyRefreshDecision::AdvertiseForStrays { stray_count: 1 }
    );
}

#[test]
fn topology_advertisement_skips_strays() {
    let peer_a = PeerId::new(checked_keypair().public_key().clone());
    let peer_b = PeerId::new(checked_keypair().public_key().clone());
    let peer_c = PeerId::new(checked_keypair().public_key().clone());

    let current: BTreeSet<_> = [peer_a.clone(), peer_b.clone()].into_iter().collect();
    let last_advertised = current.clone();
    let stray_online = vec![peer_c];

    let (decision, advertised) =
        super::topology_advertisement_for_refresh(&current, &last_advertised, &stray_online);
    let advertised = advertised.expect("should advertise when strays are present");

    assert!(matches!(
        decision,
        super::TopologyRefreshDecision::AdvertiseForStrays { stray_count: 1 }
    ));
    assert_eq!(advertised, current);
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum P2pRefreshExpectedDecision {
    NoPeers,
    Unchanged,
    AdvertiseChanged,
    AdvertiseForStrays { stray_count: usize },
    LocalRemoved,
}

fn p2p_refresh_peer_ids() -> Vec<PeerId> {
    (1..=6)
        .map(|idx| {
            let key_pair = KeyPair::try_from_seed(
                format!("p2p-topology-refresh-{idx}").into_bytes(),
                Algorithm::BlsNormal,
            )
            .expect("derive p2p refresh fixture key");
            PeerId::new(key_pair.public_key().clone())
        })
        .collect()
}

fn p2p_refresh_peer_set(peers: &[PeerId], indices: &[usize]) -> BTreeSet<PeerId> {
    indices.iter().map(|idx| peers[idx - 1].clone()).collect()
}

fn p2p_refresh_peer_vec(peers: &[PeerId], indices: &[usize]) -> Vec<PeerId> {
    indices.iter().map(|idx| peers[idx - 1].clone()).collect()
}

fn p2p_refresh_trusted(peers: &[PeerId]) -> iroha_config::parameters::actual::TrustedPeers {
    trusted_with_pops(
        Peer::new(
            "127.0.0.1:7201".parse::<SocketAddr>().expect("addr").into(),
            peers[0].clone(),
        ),
        vec![Peer::new(
            "127.0.0.1:7204".parse::<SocketAddr>().expect("addr").into(),
            peers[3].clone(),
        )],
        BTreeMap::new(),
    )
}

fn p2p_refresh_expected_decision(
    decision: &super::TopologyRefreshDecision,
) -> P2pRefreshExpectedDecision {
    match decision {
        super::TopologyRefreshDecision::NoPeers => P2pRefreshExpectedDecision::NoPeers,
        super::TopologyRefreshDecision::Unchanged => P2pRefreshExpectedDecision::Unchanged,
        super::TopologyRefreshDecision::AdvertiseChanged => {
            P2pRefreshExpectedDecision::AdvertiseChanged
        }
        super::TopologyRefreshDecision::AdvertiseForStrays { stray_count } => {
            P2pRefreshExpectedDecision::AdvertiseForStrays {
                stray_count: *stray_count,
            }
        }
    }
}

#[test]
fn p2p_topology_refresh_formal_gate_matrix() {
    struct Case {
        current: &'static [usize],
        last_advertised: &'static [usize],
        initial_seen: bool,
        online_strays: &'static [usize],
        expected_decision: P2pRefreshExpectedDecision,
        expected_seen_after: bool,
        expected_removed: bool,
    }

    let peers = p2p_refresh_peer_ids();
    let local = &peers[0];
    let trusted = p2p_refresh_trusted(&peers);

    for case in [
        Case {
            current: &[],
            last_advertised: &[2],
            initial_seen: false,
            online_strays: &[],
            expected_decision: P2pRefreshExpectedDecision::NoPeers,
            expected_seen_after: false,
            expected_removed: false,
        },
        Case {
            current: &[1, 2],
            last_advertised: &[1, 2],
            initial_seen: true,
            online_strays: &[],
            expected_decision: P2pRefreshExpectedDecision::Unchanged,
            expected_seen_after: true,
            expected_removed: false,
        },
        Case {
            current: &[1, 2, 3],
            last_advertised: &[1, 2],
            initial_seen: true,
            online_strays: &[],
            expected_decision: P2pRefreshExpectedDecision::AdvertiseChanged,
            expected_seen_after: true,
            expected_removed: false,
        },
        Case {
            current: &[1, 2],
            last_advertised: &[1],
            initial_seen: true,
            online_strays: &[],
            expected_decision: P2pRefreshExpectedDecision::AdvertiseChanged,
            expected_seen_after: true,
            expected_removed: false,
        },
        Case {
            current: &[1, 2],
            last_advertised: &[1, 2],
            initial_seen: true,
            online_strays: &[5, 6],
            expected_decision: P2pRefreshExpectedDecision::AdvertiseForStrays { stray_count: 2 },
            expected_seen_after: true,
            expected_removed: false,
        },
        Case {
            current: &[1, 3],
            last_advertised: &[],
            initial_seen: false,
            online_strays: &[],
            expected_decision: P2pRefreshExpectedDecision::AdvertiseChanged,
            expected_seen_after: true,
            expected_removed: false,
        },
        Case {
            current: &[2, 3],
            last_advertised: &[],
            initial_seen: false,
            online_strays: &[],
            expected_decision: P2pRefreshExpectedDecision::AdvertiseChanged,
            expected_seen_after: false,
            expected_removed: false,
        },
        Case {
            current: &[2, 3],
            last_advertised: &[1, 2, 3],
            initial_seen: true,
            online_strays: &[],
            expected_decision: P2pRefreshExpectedDecision::LocalRemoved,
            expected_seen_after: true,
            expected_removed: true,
        },
        Case {
            current: &[],
            last_advertised: &[1, 2],
            initial_seen: true,
            online_strays: &[],
            expected_decision: P2pRefreshExpectedDecision::NoPeers,
            expected_seen_after: true,
            expected_removed: false,
        },
        Case {
            current: &[1, 2],
            last_advertised: &[],
            initial_seen: true,
            online_strays: &[],
            expected_decision: P2pRefreshExpectedDecision::AdvertiseChanged,
            expected_seen_after: true,
            expected_removed: false,
        },
    ] {
        let current = p2p_refresh_peer_set(&peers, case.current);
        let last_advertised = p2p_refresh_peer_set(&peers, case.last_advertised);
        let online_strays = p2p_refresh_peer_vec(&peers, case.online_strays);
        let (seen_after, removed) =
            super::topology_refresh_local_status(&current, local, case.initial_seen);

        assert_eq!(seen_after, case.expected_seen_after);
        assert_eq!(removed, case.expected_removed);

        if removed {
            assert_eq!(
                case.expected_decision,
                P2pRefreshExpectedDecision::LocalRemoved
            );
            let gossip_topology = super::topology_update_for_local_removal(&last_advertised);
            assert!(gossip_topology.is_empty());
            continue;
        }

        let (decision, advertised) =
            super::topology_advertisement_for_refresh(&current, &last_advertised, &online_strays);
        assert_eq!(
            p2p_refresh_expected_decision(&decision),
            case.expected_decision
        );

        match case.expected_decision {
            P2pRefreshExpectedDecision::NoPeers | P2pRefreshExpectedDecision::Unchanged => {
                assert!(advertised.is_none());
            }
            P2pRefreshExpectedDecision::AdvertiseChanged
            | P2pRefreshExpectedDecision::AdvertiseForStrays { .. } => {
                let advertised = advertised.expect("changed or stray refresh advertises current");
                assert_eq!(advertised, current);

                let network_topology =
                    super::commit::p2p_topology_with_trusted(&advertised, &trusted);
                let mut expected_network_topology = current.clone();
                expected_network_topology.insert(peers[0].clone());
                expected_network_topology.insert(peers[3].clone());
                assert_eq!(network_topology, expected_network_topology);
            }
            P2pRefreshExpectedDecision::LocalRemoved => unreachable!("handled above"),
        }
    }
}

#[test]
fn topology_update_for_local_removal_disconnects() {
    let peer_a = PeerId::new(checked_keypair().public_key().clone());
    let peer_b = PeerId::new(checked_keypair().public_key().clone());

    let last_advertised: BTreeSet<_> = [peer_a, peer_b].into_iter().collect();
    let updated = super::topology_update_for_local_removal(&last_advertised);

    assert!(updated.is_empty());

    let updated_without_prior_advertisement =
        super::topology_update_for_local_removal(&BTreeSet::new());
    assert!(
        updated_without_prior_advertisement.is_empty(),
        "local removal should advertise an empty topology even before a prior advertisement"
    );
}

#[test]
fn view_change_suggest_counter_increments() {
    let _guard = super::status::view_change_proof_test_guard();
    super::status::reset_view_change_proof_counters_for_tests();
    assert_eq!(super::status::snapshot().view_change_suggest_total, 0);

    super::status::inc_view_change_suggest();

    let snapshot = super::status::snapshot();
    assert_eq!(snapshot.view_change_suggest_total, 1);
}

#[test]
fn new_view_tracker_deduplicates_senders() {
    let mut tracker = NewViewTracker::default();
    let qc = sample_qc_ref(3, 1);
    let peer_a = PeerId::new(checked_keypair().public_key().clone());
    let peer_b = PeerId::new(checked_keypair().public_key().clone());
    assert_eq!(tracker.record(4, 2, peer_a.clone(), qc), 1);
    assert_eq!(tracker.record(4, 2, peer_b.clone(), qc), 2);
    // Duplicate sender should not increment count.
    assert_eq!(tracker.record(4, 2, peer_b.clone(), qc), 2);
    assert_eq!(tracker.count(4, 2), 2);
}

#[test]
fn new_view_tracker_counts_with_local_validator() {
    let mut tracker = NewViewTracker::default();
    let qc = sample_qc_ref(3, 1);
    let peer_a = PeerId::new(checked_keypair().public_key().clone());
    let peer_b = PeerId::new(checked_keypair().public_key().clone());
    assert_eq!(tracker.record(4, 2, peer_a.clone(), qc), 1);
    assert_eq!(tracker.count_with_local(4, 2, Some(&peer_b)), 2);
    assert_eq!(
        tracker.count_with_local(4, 2, Some(&peer_a)),
        1,
        "local sender should not be double-counted"
    );
    assert_eq!(tracker.count_with_local(4, 2, None), 1);
}

#[test]
fn new_view_tracker_selects_highest_entry_with_quorum() {
    let mut tracker = NewViewTracker::default();
    let qc_low = sample_qc_ref(5, 1);
    let qc_high = sample_qc_ref(6, 2);
    let peer_a = PeerId::new(checked_keypair().public_key().clone());
    let peer_b = PeerId::new(checked_keypair().public_key().clone());
    let peer_c = PeerId::new(checked_keypair().public_key().clone());
    let peer_d = PeerId::new(checked_keypair().public_key().clone());
    // Populate lower (height, view) with quorum-1 votes.
    tracker.record(5, 1, peer_a.clone(), qc_low);
    tracker.record(5, 1, peer_b.clone(), qc_low);
    // Populate higher entry with quorum votes excluding local (will be added later).
    tracker.record(6, 2, peer_a.clone(), qc_high);
    tracker.record(6, 2, peer_b.clone(), qc_high);
    tracker.record(6, 2, peer_c.clone(), qc_high);

    let roster = vec![
        peer_a.clone(),
        peer_b.clone(),
        peer_c.clone(),
        peer_d.clone(),
    ];
    let selection = tracker
        .select_with_quorum(3, Some(&peer_d), &roster)
        .expect("quorum reached");
    assert_eq!(selection.key, (6, 2));
    assert_eq!(selection.highest_qc.height, 6);
    assert_eq!(selection.highest_qc.view, 2);
    // Local index is inserted as part of selection.
    assert_eq!(selection.quorum, 4);
}

