    let peer_b = PeerId::new(checked_keypair().public_key().clone());
    tracker.record(4, 0, peer_a, qc);
    tracker.record(5, 0, peer_b, qc);

    tracker.drop_below_height(5);

    assert_eq!(tracker.count(4, 0), 0);
