#[tokio::test(flavor = "current_thread")]
async fn frontier_slot_lag_window_expiry_enters_deep_catchup_and_stops_exact_retry() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0u64;
    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xA8; Hash::LENGTH]));
    let now = Instant::now();
    actor.frontier_slot = Some(super::FrontierSlot::new(
        height,
        view,
        block_hash,
        now,
        Duration::from_millis(1),
        None,
        BTreeSet::new(),
        false,
        true,
        false,
        None,
        None,
    ));

    let actions = actor.apply_frontier_slot_event(
        now,
        super::FrontierSlotEvent::OnLagWindowExpired {
            reason: "frontier_stall_reset",
        },
    );
    assert_eq!(actions.enter_deep_catchup, Some("frontier_stall_reset"));
    assert!(
        actor
            .frontier_slot
            .as_ref()
            .is_some_and(|slot| { matches!(slot.mode, super::FrontierSlotMode::DeepCatchup) }),
        "lag-window expiry must move the exact frontier slot into absorbing deep catch-up mode"
    );

    let retry_actions =
        actor.apply_frontier_slot_event(now, super::FrontierSlotEvent::OnFetchRetryDue);
    assert!(
        !retry_actions.fetch_block_body,
        "exact body retry loop must stop once the exact frontier slot enters deep catch-up"
    );

    harness.shutdown.send();
}

#[test]
fn frontier_slot_quorum_timeout_rotates_same_height_candidate_without_deep_catchup() {
    let observed_at = Instant::now();
    let mut slot = super::FrontierSlot::new(
        7,
        0,
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xC2; Hash::LENGTH])),
        observed_at,
        Duration::from_millis(1),
        None,
        BTreeSet::new(),
        true,
        false,
        true,
        None,
        None,
    );
    let progress_at = observed_at
        .checked_add(Duration::from_secs(1))
        .unwrap_or(observed_at);
    let early_timeout_at = progress_at
        .checked_add(Duration::from_millis(50))
        .unwrap_or(progress_at);
    let expired_timeout_at = progress_at
        .checked_add(Duration::from_millis(150))
        .unwrap_or(progress_at);
    let lag_window = Duration::from_millis(100);

    let vote_actions = slot.step(
        progress_at,
        super::FrontierSlotEvent::OnVoteObserved {
            block_hash: slot.block_hash,
            view: slot.view,
            voter: None,
        },
        lag_window,
    );
    assert_eq!(
        vote_actions.enter_deep_catchup, None,
        "same-height vote progress should not immediately drive the slot into deep catch-up"
    );
    assert!(
        matches!(slot.phase, super::FrontierSlotPhase::AwaitCommitQc),
        "vote progress should move the slot into commit-QC wait"
    );

    let early_timeout_actions = slot.step(
        early_timeout_at,
        super::FrontierSlotEvent::OnQuorumTimeout {
            cause: super::ViewChangeCause::QuorumTimeout,
            requested_view: slot.view,
        },
        lag_window,
    );
    assert_eq!(
        early_timeout_actions.enter_deep_catchup, None,
        "body-present same-height commit-QC wait should stay out of deep catch-up"
    );
    assert_eq!(
        early_timeout_actions.request_view_change, None,
        "the first quorum timeout should consume the deterministic rebroadcast window"
    );
    assert!(
        matches!(slot.mode, super::FrontierSlotMode::Normal),
        "the slot must stay in normal same-height recovery while the refreshed lag window is still open"
    );

    let lag_expired_actions = slot.step(
        expired_timeout_at,
        super::FrontierSlotEvent::OnLagWindowExpired {
            reason: "frontier_stall_reset",
        },
        lag_window,
    );
    assert_eq!(
        lag_expired_actions.enter_deep_catchup, None,
        "body-present same-height commit-QC wait must not be reclassified into deep catch-up by the lag timer"
    );
    assert!(
        matches!(slot.mode, super::FrontierSlotMode::Normal),
        "same-height commit-QC wait must stay in normal mode after lag expiry"
    );

    let expired_timeout_actions = slot.step(
        expired_timeout_at,
        super::FrontierSlotEvent::OnQuorumTimeout {
            cause: super::ViewChangeCause::QuorumTimeout,
            requested_view: slot.view,
        },
        lag_window,
    );
    assert_eq!(
        expired_timeout_actions.enter_deep_catchup, None,
        "same-height quorum timeout should stay in slot-owned view rotation, not deep catch-up"
    );
    assert_eq!(
        expired_timeout_actions.request_view_change,
        Some((7, 1, super::ViewChangeCause::QuorumTimeout)),
        "the second deterministic quorum timeout should advance the slot view while preserving the candidate"
    );
    assert_eq!(
        slot.active_view, 1,
        "quorum-timeout rotation should advance the active view for the same authoritative slot"
    );
}

#[test]
fn frontier_slot_quorum_timeout_rotates_exact_body_wait_before_lag_window_expiry() {
    let observed_at = Instant::now();
    let mut slot = super::FrontierSlot::new(
        8,
        0,
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xC7; Hash::LENGTH])),
        observed_at,
        Duration::from_millis(1),
        None,
        BTreeSet::new(),
        false,
        true,
        false,
        None,
        None,
    );
    let lag_window = Duration::from_millis(100);
    let first_timeout_at = observed_at
        .checked_add(Duration::from_millis(40))
        .unwrap_or(observed_at);
    let second_timeout_at = observed_at
        .checked_add(Duration::from_millis(80))
        .unwrap_or(first_timeout_at);

    let first_timeout_actions = slot.step(
        first_timeout_at,
        super::FrontierSlotEvent::OnQuorumTimeout {
            cause: super::ViewChangeCause::QuorumTimeout,
            requested_view: slot.view,
        },
        lag_window,
    );
    assert_eq!(
        first_timeout_actions.request_view_change, None,
        "the first exact-body quorum timeout should spend the bounded body-fetch rebroadcast window"
    );
    assert!(
        first_timeout_actions.fetch_block_body,
        "the first exact-body quorum timeout should reissue the same-slot body fetch"
    );
    assert!(
        slot.repair_state.quorum_timeout_rebroadcasted,
        "exact-body repair should remember that it already spent the bounded rebroadcast window"
    );
    assert!(
        matches!(slot.mode, super::FrontierSlotMode::Normal),
        "exact-body repair should stay in normal mode while the lag window is still open"
    );

    let second_timeout_actions = slot.step(
        second_timeout_at,
        super::FrontierSlotEvent::OnQuorumTimeout {
            cause: super::ViewChangeCause::QuorumTimeout,
            requested_view: slot.view,
        },
        lag_window,
    );
    assert_eq!(
        second_timeout_actions.enter_deep_catchup, None,
        "continued exact-body stalls before lag expiry should rotate the slot view instead of dropping into deep catch-up"
    );
    assert_eq!(
        second_timeout_actions.request_view_change,
        Some((8, 1, super::ViewChangeCause::QuorumTimeout)),
        "the second exact-body quorum timeout should advance the slot view before the lag window expires"
    );
    assert_eq!(
        slot.active_view, 1,
        "exact-body same-slot recovery should advance the active view after the bounded rebroadcast window is consumed"
    );
    assert!(
        !slot.repair_state.quorum_timeout_rebroadcasted,
        "view rotation should reset the rebroadcast guard for the new slot view"
    );
}

#[test]
fn frontier_slot_quorum_timeout_rotates_after_deep_catchup_rebroadcast_window() {
    let observed_at = Instant::now();
    let mut slot = super::FrontierSlot::new(
        8,
        0,
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xC6; Hash::LENGTH])),
        observed_at,
        Duration::from_millis(1),
        None,
        BTreeSet::new(),
        false,
        true,
        false,
        None,
        None,
    );
    let lag_window = Duration::from_millis(100);
    let lag_expired_at = observed_at
        .checked_add(Duration::from_millis(150))
        .unwrap_or(observed_at);

    let lag_actions = slot.step(
        lag_expired_at,
        super::FrontierSlotEvent::OnLagWindowExpired {
            reason: "frontier_stall_reset",
        },
        lag_window,
    );
    assert_eq!(
        lag_actions.enter_deep_catchup,
        Some("frontier_stall_reset"),
        "lag-window expiry should move an exact-body wait into deep catch-up before view rotation"
    );
    assert!(
        matches!(slot.mode, super::FrontierSlotMode::DeepCatchup),
        "test setup must enter deep catch-up"
    );

    let first_timeout_at = lag_expired_at
        .checked_add(Duration::from_millis(50))
        .unwrap_or(lag_expired_at);
    let first_timeout_actions = slot.step(
        first_timeout_at,
        super::FrontierSlotEvent::OnQuorumTimeout {
            cause: super::ViewChangeCause::QuorumTimeout,
            requested_view: slot.view,
        },
        lag_window,
    );
    assert_eq!(
        first_timeout_actions.request_view_change, None,
        "the first deep-catchup quorum timeout should consume the deterministic rebroadcast window"
    );
    assert_eq!(
        first_timeout_actions.enter_deep_catchup,
        Some("frontier_stall_reset"),
        "deep catch-up should reissue one bounded recovery attempt before rotating"
    );
    assert!(
        slot.repair_state.quorum_timeout_rebroadcasted,
        "deep catch-up should remember that it already consumed the rebroadcast window"
    );

    let second_timeout_at = first_timeout_at
        .checked_add(Duration::from_millis(50))
        .unwrap_or(first_timeout_at);
    let second_timeout_actions = slot.step(
        second_timeout_at,
        super::FrontierSlotEvent::OnQuorumTimeout {
            cause: super::ViewChangeCause::QuorumTimeout,
            requested_view: slot.view,
        },
        lag_window,
    );
    assert_eq!(
        second_timeout_actions.enter_deep_catchup, None,
        "after the rebroadcast window is consumed, deep catch-up should rotate instead of looping"
    );
    assert_eq!(
        second_timeout_actions.request_view_change,
        Some((8, 1, super::ViewChangeCause::QuorumTimeout)),
        "the second deep-catchup quorum timeout should advance the exact-slot view"
    );
    assert_eq!(
        slot.active_view, 1,
        "deep-catchup rotation should advance the active view for the same authoritative slot"
    );
}

#[tokio::test(flavor = "current_thread")]
async fn frontier_slot_lag_window_expiry_only_applies_to_exact_body_wait() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0u64;
    let now = Instant::now();
    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xC3; Hash::LENGTH]));

    actor.frontier_slot = Some(super::FrontierSlot::new(
        height,
        view,
        block_hash,
        now,
        Duration::from_millis(1),
        None,
        BTreeSet::new(),
        true,
        false,
        true,
        None,
        None,
    ));
    let progress_at = now.checked_add(Duration::from_secs(1)).unwrap_or(now);
    let expired_at = progress_at
        .checked_add(
            actor
                .frontier_slot_lag_window()
                .saturating_add(Duration::from_millis(1)),
        )
        .unwrap_or(progress_at);
    let lag_window = actor.frontier_slot_lag_window();

    let vote_actions = actor.apply_frontier_slot_event(
        progress_at,
        super::FrontierSlotEvent::OnVoteObserved {
            block_hash,
            view,
            voter: None,
        },
    );
    assert_eq!(vote_actions.enter_deep_catchup, None);
    assert!(
        actor
            .frontier_slot
            .as_ref()
            .is_some_and(|slot| { matches!(slot.phase, super::FrontierSlotPhase::AwaitCommitQc) }),
        "test setup must move the slot into commit-QC wait"
    );
    assert!(
        !actor.frontier_slot_lag_window_expired(height, expired_at),
        "external lag-expiry emitters must stay off while the slot is waiting for same-height commit QC with the body already present"
    );

    let timeout_actions = actor.apply_frontier_slot_event(
        expired_at,
        super::FrontierSlotEvent::OnQuorumTimeout {
            cause: super::ViewChangeCause::QuorumTimeout,
            requested_view: view,
        },
    );
    assert_eq!(
        timeout_actions.enter_deep_catchup, None,
        "body-present commit-QC timeout must not move the current frontier into deep catch-up"
    );
    assert_eq!(
        timeout_actions.request_view_change, None,
        "the first quorum-timeout event should consume the deterministic rebroadcast window"
    );

    let rotate_actions = actor.apply_frontier_slot_event(
        expired_at.checked_add(lag_window).unwrap_or(expired_at),
        super::FrontierSlotEvent::OnQuorumTimeout {
            cause: super::ViewChangeCause::QuorumTimeout,
            requested_view: view,
        },
    );
    assert_eq!(
        rotate_actions.request_view_change,
        Some((height, 1, super::ViewChangeCause::QuorumTimeout)),
        "after the rebroadcast window, the same slot should rotate views instead of entering deep catch-up"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn stale_frontier_slot_does_not_hijack_exact_frontier_view_advance() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let stale_height = actor.committed_height_snapshot();
    let frontier_height = stale_height.saturating_add(1);
    let view = 0u64;
    let now = Instant::now();
    let stale_block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xC8; Hash::LENGTH]));

    actor.phase_tracker.start_new_round(frontier_height, now);
    actor
        .phase_tracker
        .on_view_change(frontier_height, view, now);
    actor.frontier_slot = Some(super::FrontierSlot::new(
        stale_height,
        view,
        stale_block_hash,
        now,
        Duration::from_millis(1),
        None,
        BTreeSet::new(),
        true,
        false,
        true,
        None,
        None,
    ));
    actor
        .frontier_slot
        .as_mut()
        .expect("stale frontier slot")
        .phase = super::FrontierSlotPhase::AwaitCommitQc;

    actor.trigger_view_change_with_cause(frontier_height, view, super::ViewChangeCause::MissingQc);

    assert_eq!(
        actor.phase_tracker.current_view(frontier_height),
        Some(view.saturating_add(1)),
        "MissingQc rotation for the live frontier must ignore stale prior-height slot ownership"
    );
    assert!(
        actor
            .frontier_slot
            .as_ref()
            .is_none_or(|slot| slot.height == frontier_height),
        "stale prior-height frontier slots must not survive exact-frontier view rotation"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn duplicate_vote_observation_keeps_frontier_quorum_timeout_rebroadcast_window_armed() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0u64;
    let now = Instant::now();
    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xC4; Hash::LENGTH]));
    let remote_voter = actor
        .effective_commit_topology()
        .into_iter()
        .find(|peer| peer != actor.common_config.peer.id())
        .expect("remote voter");

    actor.frontier_slot = Some(super::FrontierSlot::new(
        height,
        view,
        block_hash,
        now,
        Duration::from_millis(1),
        None,
        BTreeSet::new(),
        true,
        false,
        true,
        None,
        None,
    ));
    let progress_at = now.checked_add(Duration::from_secs(1)).unwrap_or(now);
    let first_timeout_at = progress_at
        .checked_add(Duration::from_millis(50))
        .unwrap_or(progress_at);
    let second_timeout_at = first_timeout_at
        .checked_add(Duration::from_millis(50))
        .unwrap_or(first_timeout_at);

    let vote_actions = actor.apply_frontier_slot_event(
        progress_at,
        super::FrontierSlotEvent::OnVoteObserved {
            block_hash,
            view,
            voter: Some(remote_voter.clone()),
        },
    );
    assert_eq!(vote_actions.request_view_change, None);

    let first_timeout_actions = actor.apply_frontier_slot_event(
        first_timeout_at,
        super::FrontierSlotEvent::OnQuorumTimeout {
            cause: super::ViewChangeCause::QuorumTimeout,
            requested_view: view,
        },
    );
    assert_eq!(
        first_timeout_actions.request_view_change, None,
        "the first quorum timeout should only arm the deterministic rebroadcast window"
    );
    assert!(
        actor
            .frontier_slot
            .as_ref()
            .is_some_and(|slot| slot.repair_state.quorum_timeout_rebroadcasted),
        "the slot must retain the armed rebroadcast window after the first timeout"
    );

    let duplicate_vote_actions = actor.apply_frontier_slot_event(
        first_timeout_at,
        super::FrontierSlotEvent::OnVoteObserved {
            block_hash,
            view,
            voter: Some(remote_voter),
        },
    );
    assert_eq!(duplicate_vote_actions.request_view_change, None);
    assert!(
        actor
            .frontier_slot
            .as_ref()
            .is_some_and(|slot| slot.repair_state.quorum_timeout_rebroadcasted),
        "duplicate same-slot vote observations must not clear the armed rebroadcast window"
    );

    let second_timeout_actions = actor.apply_frontier_slot_event(
        second_timeout_at,
        super::FrontierSlotEvent::OnQuorumTimeout {
            cause: super::ViewChangeCause::QuorumTimeout,
            requested_view: view,
        },
    );
    assert_eq!(
        second_timeout_actions.request_view_change,
        Some((height, 1, super::ViewChangeCause::QuorumTimeout)),
        "after a duplicate same-slot vote observation, the next quorum timeout must still rotate the view"
    );

    harness.shutdown.send();
}

