#[tokio::test(flavor = "current_thread")]
async fn apply_commit_outcome_updates_view_change_install() {
    use crate::block::ValidBlock;

    let mut harness = test_actor_harness(1).await;
    let _guard = super::status::view_change_proof_test_guard();
    super::status::reset_view_change_proof_counters_for_tests();
    super::status::set_view_change_index(0);
    let actor = &mut harness.actor;

    let leader_key = harness
        .key_pairs
        .first()
        .expect("leader keypair available")
        .private_key();
    let valid_block = ValidBlock::new_dummy_and_modify_header(leader_key, |header| {
        header.set_height(nonzero!(1_u64));
        header.set_view_change_index(1);
    });
    let committed_block = valid_block.clone().commit_unchecked().unpack(|_| {});
    let signed_block: SignedBlock = valid_block.into();
    let block_hash = signed_block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&signed_block));
    let pending = PendingBlock::new(signed_block, payload_hash, 1, 1);
    let lock = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        height: 1,
        view: 1,
        epoch: 0,
    };
    let commit_topology = actor.effective_commit_topology();
    let signature_topology = commit_topology.clone();
    let inflight = CommitInFlight {
        id: 1,
        lock,
        block_hash,
        pending,
        commit_topology,
        signature_topology,
        qc_signers: None,
        commit_qc: None,
        post_commit_qc: None,
        enqueue_time: Instant::now(),
        timeout_reported: false,
    };

    actor.subsystems.commit.inflight = Some(inflight);
    let (result_tx, result_rx) = mpsc::sync_channel(1);
    actor.subsystems.commit.result_rx = Some(result_rx);
    let now = Instant::now();
    let stale_hash = HashOf::from_untyped_unchecked(Hash::prehashed([0xA5; Hash::LENGTH]));
    let future_hash = HashOf::from_untyped_unchecked(Hash::prehashed([0xB4; Hash::LENGTH]));
    actor.pending.missing_block_requests.insert(
        stale_hash,
        MissingBlockRequest {
            height: 1,
            view: 0,
            phase: Phase::Commit,
            priority: MissingBlockPriority::Consensus,
            retry_window: Duration::from_secs(1),
            view_change_window: Some(Duration::from_secs(1)),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );
    actor.pending.missing_block_requests.insert(
        future_hash,
        MissingBlockRequest {
            height: 2,
            view: 0,
            phase: Phase::Commit,
            priority: MissingBlockPriority::Consensus,
            retry_window: Duration::from_secs(1),
            view_change_window: Some(Duration::from_secs(1)),
            first_seen: now,
            last_requested: now,
            last_dependency_progress: now,
            last_rbc_observed: None,
            last_view_change_triggered: None,
            view_change_triggered_view: None,
            attempts: 0,
        },
    );
    result_tx
        .send(commit::CommitResult {
            id: 1,
            outcome: commit::CommitOutcome::Success {
                committed_block,
                exec_witness: None,
                fastpq_witness_context: None,
                pipeline_events: Vec::new(),
                state_events: Vec::new(),
                post_apply_snapshot: commit::CommitPostApplySnapshot::default(),
                post_commit_persistence_error: None,
            },
            timings: commit::CommitStageTimings::default(),
        })
        .expect("send commit result");
    assert!(
        actor.poll_commit_results(),
        "commit outcome should be applied"
    );
    assert!(
        !actor
            .pending
            .missing_block_requests
            .contains_key(&stale_hash),
        "missing block requests at committed height should be cleared after commit"
    );
    assert!(
        actor
            .pending
            .missing_block_requests
            .contains_key(&future_hash),
        "future missing block requests should be retained after commit"
    );

    let snapshot = super::status::snapshot();
    assert_eq!(snapshot.view_change_index, 1);
    assert_eq!(snapshot.view_change_install_total, 1);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn prune_stale_missing_requests_clears_linked_state_and_records_counter() {
    let _guard = super::status::missing_block_fetch_test_guard();
    super::status::reset_missing_block_fetch_counters_for_tests();

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    actor.config.recovery.missing_request_stale_height_margin = 1;

    let stale_height = 2_u64;
    let stale_view = 0_u64;
    let fresh_height = 4_u64;
    let local_height = 5_u64;
    let now = Instant::now();
    let retry_window = Duration::from_secs(1);
    let parent = actor.state.view().latest_block_hash();

    let stale_block = sample_block(stale_height, stale_view, parent);
    let stale_hash = stale_block.hash();
    let stale_payload_hash = Hash::new(super::proposals::block_payload_bytes(&stale_block));
    actor.pending.pending_blocks.insert(
        stale_hash,
        PendingBlock::new(
            stale_block.clone(),
            stale_payload_hash,
            stale_height,
            stale_view,
        ),
    );
    actor.pending.pending_fetch_requests.insert(
        stale_hash,
        BTreeMap::from([(
            actor
                .effective_commit_topology()
                .first()
                .expect("commit topology has at least one peer")
                .clone(),
            super::PendingFetchRequestMeta {
                priority: super::message::FetchPendingBlockPriority::Background,
                requester_roster_proof_known: false,
                commit_qc_only: false,
            },
        )]),
    );
    actor.deferred_block_sync_updates.insert(
        (stale_height, stale_view, stale_hash),
        super::DeferredBlockSyncUpdate {
            update: super::message::BlockSyncUpdate::from(&stale_block),
            sender: None,
        },
    );
    actor.subsystems.da_rbc.rbc.sessions.insert(
        (stale_hash, stale_height, stale_view),
        RbcSession::test_new(
            1,
            Some(stale_payload_hash),
            Some(Hash::prehashed([0x55; Hash::LENGTH])),
            0,
        ),
    );

    let request = |height| super::MissingBlockRequest {
        height,
        view: stale_view,
        phase: Phase::Commit,
        priority: super::MissingBlockPriority::Consensus,
        retry_window,
        view_change_window: Some(retry_window),
        first_seen: now,
        last_requested: now,
        last_dependency_progress: now,
        last_rbc_observed: None,
        last_view_change_triggered: None,
        view_change_triggered_view: None,
        attempts: 0,
    };
    actor
        .pending
        .missing_block_requests
        .insert(stale_hash, request(stale_height));
    let fresh_hash = HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x91; 32]));
    actor
        .pending
        .missing_block_requests
        .insert(fresh_hash, request(fresh_height));

    actor.prune_stale_missing_requests_for_committed_height(
        local_height,
        now.checked_add(Duration::from_millis(1)).unwrap_or(now),
    );

    assert!(
        !actor
            .pending
            .missing_block_requests
            .contains_key(&stale_hash),
        "stale missing request should be pruned once outside stale margin"
    );
    assert!(
        actor
            .pending
            .missing_block_requests
            .contains_key(&fresh_hash),
        "request within stale margin should be retained"
    );
    assert!(
        !actor
            .pending
            .pending_fetch_requests
            .contains_key(&stale_hash),
        "linked pending fetch requests should be pruned with stale missing request"
    );
    assert!(
        !actor.pending.pending_blocks.contains_key(&stale_hash),
        "linked pending block should be pruned with stale missing request"
    );
    assert!(
        !actor
            .deferred_block_sync_updates
            .contains_key(&(stale_height, stale_view, stale_hash)),
        "linked deferred block-sync state should be pruned with stale request"
    );
    assert!(
        !actor
            .subsystems
            .da_rbc
            .rbc
            .sessions
            .contains_key(&(stale_hash, stale_height, stale_view)),
        "linked RBC session should be pruned with stale request"
    );

    let snapshot = super::status::snapshot();
    assert_eq!(
        snapshot.missing_request_pruned_stale_height, 1,
        "stale missing-request pruning should be counted"
    );

    super::status::reset_missing_block_fetch_counters_for_tests();
    harness.shutdown.send();
}

#[test]
fn pacemaker_defers_under_backpressure() {
    let start = Instant::now();
    let mut pacemaker = Pacemaker::with_interval(Duration::from_millis(10), start);
    let mut tracker = PacemakerBackpressure::new();
    let state = BackpressureState::Saturated {
        queued: 5,
        capacity: NonZeroUsize::new(5).expect("non-zero"),
    };
    let backpressure = ProposalBackpressure {
        queue_state: state,
        active_pending: false,
        rbc_backlog: false,
        relay_backpressure: false,
        consensus_queue_backpressure: false,
    };
    let (log_initial, log_fire, should_attempt) =
        Actor::evaluate_pacemaker(&mut pacemaker, &mut tracker, backpressure, start);
    assert!(log_initial);
    assert!(log_fire);
    assert!(!should_attempt);
}

