#[tokio::test(flavor = "current_thread")]
async fn force_view_change_if_idle_rotates_post_rotation_round_with_stale_quorum_timeout_owner() {
    use std::borrow::Cow;

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let _guard = super::status::view_change_cause_test_guard();
    let _worker_guard = super::status::worker_queue_test_guard();

    super::status::reset_view_change_cause_counters_for_tests();
    super::status::reset_worker_loop_snapshot_for_tests();

    let tx = sample_transaction();
    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(tx)),
            actor.state.view(),
        )
        .expect("push tx");

    let committed_height = actor.state.view().height() as u64;
    actor.highest_qc = Some(sample_qc_ref(committed_height, 0));
    let height = super::active_round_height(
        actor.highest_qc,
        actor.latest_committed_qc(),
        committed_height,
    );
    let search_limit = u64::try_from(actor.effective_commit_topology().len().saturating_mul(8))
        .unwrap_or(0)
        .max(2);
    let current_view = (1..search_limit)
        .find(|candidate_view| !actor.local_is_round_leader(height, *candidate_view))
        .expect("find non-zero post-rotation view where local peer is not leader");
    let now = Instant::now();
    let timeout = super::idle_view_timeout(
        false,
        actor.commit_quorum_timeout(),
        actor.subsystems.propose.pacemaker.propose_interval,
        actor.runtime_da_enabled(),
    );
    let start = now
        .checked_sub(timeout.saturating_add(Duration::from_millis(1)))
        .unwrap_or(now);
    actor
        .phase_tracker
        .on_view_change(height, current_view, start);
    actor.queue_ready_since = Some(super::QueueReadySince {
        height,
        view: current_view,
        since: start,
    });
    actor.subsystems.propose.last_pacemaker_attempt = Some(now);
    actor.frontier_recovery = Some(super::FrontierRecoveryState {
        frontier_height: height,
        phase: super::FrontierRecoveryPhase::CatchUp,
        entered_at: now,
        last_progress_at: now,
        last_dependency_progress_at: None,
        last_action_at: None,
        no_progress_windows: 0,
        cleanup_done: false,
        last_view: current_view.saturating_sub(1),
        last_rotation_view: Some(current_view.saturating_sub(1)),
        last_cause: "quorum_timeout",
    });
    assert!(
        !actor.slot_has_proposal_evidence(height, current_view),
        "stale old-view frontier ownership must not count as proposal evidence for the post-rotation round"
    );
    assert!(
        !actor.local_is_round_leader(height, current_view),
        "test setup must avoid the forced leader self-proposal path"
    );

    let before = super::status::snapshot();
    assert!(
        !actor.force_view_change_if_idle(now),
        "the empty post-rotation view should keep stale quorum-timeout ownership inside unified recovery on the first pass"
    );
    let after = super::status::snapshot();
    assert_eq!(
        actor.phase_tracker.current_view(height),
        Some(current_view),
        "unified recovery should not advance the post-rotation view on the first pass"
    );
    assert_eq!(
        after.view_change_causes.last_cause.as_deref(),
        before.view_change_causes.last_cause.as_deref(),
        "arming unified recovery should not count a direct post-rotation timeout"
    );
    assert!(
        actor.frontier_slot_is_exact_height(height)
            || actor.frontier_recovery_exists_at_height(height),
        "stale old-view ownership should remain represented by exact-frontier recovery state"
    );

    super::status::reset_view_change_cause_counters_for_tests();
    super::status::reset_worker_loop_snapshot_for_tests();
    harness.shutdown.send();
}

