 {
    use std::borrow::Cow;

    let _commit_history_guard = isolate_commit_history_state();
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.resilience.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    seed_genesis_block_for_state(&actor.state);

    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(sample_transaction())),
            actor.state.view(),
        )
        .expect("push tx");

    let highest_qc = actor
        .latest_committed_qc()
        .expect("genesis commit QC should be available");
    actor.highest_qc = Some(highest_qc);
    let height = highest_qc.height.saturating_add(1);
    let owner_view = 1_u64;
    let roster = actor.effective_commit_topology();
    let (mut proposal_topology, fresh_view, leader_index, local_idx) =
        (owner_view.saturating_add(1)..=owner_view.saturating_add(32))
            .find_map(|candidate_view| {
                let mut topology = super::network_topology::Topology::new(roster.clone());
                let leader_index = actor
                    .leader_index_for(&mut topology, height, candidate_view)
                    .ok()?;
                let local_idx = actor.local_validator_index_for_topology(&topology)?;
                (u32::try_from(leader_index).ok()? == local_idx).then_some((
                    topology,
                    candidate_view,
                    leader_index,
                    local_idx,
                ))
            })
            .expect("find later view where local peer is leader");

    let owner_block = sample_block(height, owner_view, Some(highest_qc.subject_block_hash));
    let owner_hash = insert_validated_pending(actor, owner_block.clone());
    let vote_topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    assert!(
        actor.emit_precommit_vote(
            owner_hash,
            height,
            owner_view,
            actor.epoch_for_height(height),
            ValidationStatus::Valid,
            &vote_topology,
            owner_block.header().prev_block_hash(),
            Some((zero_state_root(), zero_state_root())),
        ),
        "test setup should record a local Commit vote for the stale branch"
    );
    while actor.poll_vote_verify_results() {}

    let now = Instant::now();
    let stale_at = now
        .checked_sub(
            actor
                .known_block_commit_qc_recovery_view_change_window()
                .saturating_add(Duration::from_millis(1)),
        )
        .unwrap_or(now);
    let pending = actor
        .pending
        .pending_blocks
        .get_mut(&owner_hash)
        .expect("stale pending branch exists");
    pending.inserted_at = stale_at;
    pending.touch_progress(stale_at);
    pending.note_local_commit_vote_emitted();
    actor.phase_tracker.start_new_round(height, stale_at);
    actor.phase_tracker.on_view_change(height, fresh_view, now);
    actor.subsystems.propose.proposal_liveness =
        Some(super::ProposalLivenessSlot::new(height, fresh_view, now));

    let existing_vote = actor
        .local_same_height_vote(height, actor.epoch_for_height(height))
        .expect("test setup requires local same-height vote history");
    assert!(
        actor.local_same_height_vote_blocks_fresh_proposal(
            height,
            fresh_view,
            &existing_vote,
            now,
            true,
        ),
        "raw local Commit vote must still block local re-voting"
    );
    assert!(
        !actor.local_same_height_vote_blocks_fresh_proposal_assembly(
            height,
            fresh_view,
            &existing_vote,
            now,
            true,
            highest_qc,
        ),
        "proposal assembly may continue after the stale branch's commit-QC repair window expires"
    );

    let assembled = actor
        .assemble_and_broadcast_proposal(
            height,
            fresh_view,
            highest_qc,
            &mut proposal_topology,
            leader_index,
            local_idx,
            None,
            now,
        )
        .expect("proposal assembly should not fail");
    assert!(
        assembled,
        "stale local Commit vote should not prevent proposal broadcast after missing-QC repair expiry"
    );
    let (fresh_hash, fresh_parent) = actor
        .pending
        .pending_blocks
        .iter()
        .find_map(|(hash, pending)| {
            (pending.height == height && pending.view == fresh_view)
                .then_some((*hash, pending.block.header().prev_block_hash()))
        })
        .expect("fresh proposal should create a pending block");
    assert!(
        !actor.emit_precommit_vote(
            fresh_hash,
            height,
            fresh_view,
            actor.epoch_for_height(height),
            ValidationStatus::Valid,
            &vote_topology,
            fresh_parent,
            Some((zero_state_root(), zero_state_root())),
        ),
        "the same stale local Commit vote must still block a conflicting local precommit"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn pacemaker_allows_new_view_qc_to_supersede_local_same_height_vote_blocker() {
    use std::borrow::Cow;

    let _commit_history_guard = isolate_commit_history_state();
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.resilience.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    seed_genesis_block_for_state(&actor.state);

    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(sample_transaction())),
            actor.state.view(),
        )
        .expect("push tx");
    actor.subsystems.propose.new_view_tracker = NewViewTracker::default();

    let highest_qc = actor
        .latest_committed_qc()
        .expect("genesis commit QC should be available");
    actor.highest_qc = Some(highest_qc);
    let height = highest_qc.height.saturating_add(1);
    let owner_view = 0_u64;

    let owner_block = sample_block(height, owner_view, Some(highest_qc.subject_block_hash));
    let owner_hash = insert_validated_pending(actor, owner_block.clone());
    let vote_topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    assert!(actor.emit_precommit_vote(
        owner_hash,
        height,
        owner_view,
        actor.epoch_for_height(height),
        ValidationStatus::Valid,
        &vote_topology,
        owner_block.header().prev_block_hash(),
        Some((zero_state_root(), zero_state_root())),
    ));
    while actor.poll_vote_verify_results() {}

    let existing_vote = actor
        .local_same_height_vote(height, actor.epoch_for_height(height))
        .expect("test setup requires local same-height vote history");
    actor.frontier_slot = None;
    let (consensus_mode, _, _) = actor.consensus_context_for_height(height);
    let live_roster = actor.roster_for_live_vote_with_mode(height, consensus_mode);
    let local_peer = actor.common_config.peer.id().clone();
    let search_limit = u64::try_from(live_roster.len().saturating_mul(12))
        .unwrap_or(1)
        .max(2);
    let fresh_view = (owner_view.saturating_add(1)..search_limit)
        .find(|candidate_view| actor.local_is_round_leader(height, *candidate_view))
        .expect("find later view where local peer is leader");
    assert!(
        actor.local_same_height_vote_blocks_fresh_proposal(
            height,
            fresh_view,
            &existing_vote,
            Instant::now(),
            true,
        ),
        "fresh local vote history should still be a raw preflight blocker"
    );

    cache_new_view_qc_for_frontier(actor, &harness.key_pairs, height, fresh_view, highest_qc);
    assert!(
        actor.new_view_qc_supersedes_same_height_vote_conflict(
            height,
            fresh_view,
            highest_qc,
            existing_vote.block_hash,
            existing_vote.view,
        ),
        "cached NEW_VIEW QC over the committed parent should supersede raw local vote history"
    );

    let now = Instant::now();
    actor.subsystems.propose.last_successful_proposal =
        Some(now.checked_sub(Duration::from_millis(1)).unwrap_or(now));
    let live_topology = actor.roster_for_live_vote_with_mode(height, ConsensusMode::Permissioned);
    let required = super::network_topology::Topology::new(live_topology.clone())
        .min_votes_for_commit()
        .max(1);
    let tracker_count = actor.subsystems.propose.new_view_tracker.count_with_local(
        height,
        fresh_view,
        Some(&local_peer),
    );
    let selection_probe = actor
        .subsystems
        .propose
        .new_view_tracker
        .select_with_quorum_for_height(height, required, Some(&local_peer), &live_topology);
    let mut leader_topology = super::network_topology::Topology::new(live_topology.clone());
    let leader_index = actor.leader_index_for(&mut leader_topology, height, fresh_view);
    let local_pos = leader_topology.position(local_peer.public_key());
    let proposed = actor.on_pacemaker_propose_ready(now);
    assert!(
        proposed,
        "pacemaker preflight should honor NEW_VIEW QC supersession and reach proposal assembly; tracker_count={tracker_count}, required={required}, selection_probe={selection_probe:?}, leader_index={leader_index:?}, local_pos={local_pos:?}, current_view={:?}, pending={}, queue_len={}",
        actor.phase_tracker.current_view(height),
        actor.pending.pending_blocks.len(),
        actor.queue.queued_len(),
    );
    assert!(
        actor.slot_has_proposal_evidence(height, fresh_view)
            || actor
                .pending
                .pending_blocks
                .values()
                .any(|pending| pending.height == height && pending.view == fresh_view),
        "fresh proposal should leave durable evidence for the later view"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn proposal_waits_for_stale_commit_inflight_worker_result() {
    use std::borrow::Cow;

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.resilience.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let _ = seed_genesis_block_for_state(&actor.state);

    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(sample_transaction())),
            actor.state.view(),
        )
        .expect("push tx");

    let frontier_height = actor.committed_height_snapshot().saturating_add(1);
    let owner_view = 0_u64;
    let fresh_view = owner_view.saturating_add(1);
    let now = Instant::now();
    let min_yield_age = actor
        .quorum_timeout(actor.runtime_da_enabled())
        .max(actor.frontier_slot_lag_window())
        .max(Duration::from_millis(1));
    let stale_at = now
        .checked_sub(min_yield_age.saturating_add(Duration::from_millis(1)))
        .unwrap_or(now);
    actor
        .phase_tracker
        .start_new_round(frontier_height, stale_at);
    actor
        .phase_tracker
        .on_view_change(frontier_height, fresh_view, now);

    let block = sample_block(
        frontier_height,
        owner_view,
        actor.state.latest_block_hash_fast(),
    );
    let owner_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let mut pending = PendingBlock::new(block.clone(), payload_hash, frontier_height, owner_view);
    pending.inserted_at = stale_at;
    pending.touch_progress(stale_at);
    actor.pending.pending_blocks.insert(owner_hash, pending);
    actor.frontier_slot = Some(super::FrontierSlot::new(
        frontier_height,
        owner_view,
        owner_hash,
        stale_at,
        actor
            .frontier_recovery_window()
            .max(Duration::from_millis(1)),
        None,
        BTreeSet::new(),
        true,
        true,
        true,
        None,
        None,
    ));
    let mut inflight = commit_inflight_for_block(actor, block, frontier_height, owner_view);
    inflight.enqueue_time = stale_at;
    inflight.pending.inserted_at = stale_at;
    inflight.pending.touch_progress(stale_at);
    actor.subsystems.commit.inflight = Some(inflight);

    assert!(
        actor
            .frontier_slot_live_local_owner_for_round(frontier_height, fresh_view)
            .is_some(),
        "stale commit-inflight should initially keep the old owner live"
    );
    assert!(
        !actor.maybe_yield_stale_frontier_owner_for_fresh_proposal(
            frontier_height,
            fresh_view,
            owner_hash,
            owner_view,
            now,
            actor.queue.queued_len(),
        ),
        "active commit-inflight work must stay attached until the worker result is drained"
    );
    assert!(
        actor
            .subsystems
            .commit
            .inflight
            .as_ref()
            .is_some_and(|inflight| inflight.block_hash == owner_hash),
        "yielding must not clear a running local commit-inflight marker"
    );
    assert!(
        actor.pending.pending_blocks.contains_key(&owner_hash),
        "yielding must not drop the pending wrapper while commit work is still active"
    );
    assert!(
        actor
            .frontier_slot_live_local_owner_for_round(frontier_height, fresh_view)
            .is_some(),
        "the active commit worker should keep the frontier owner live"
    );

    harness.shutdown.send();
}

