#[tokio::test(flavor = "current_thread")]
async fn cached_recovery_proposal_without_pending_rotates_view() {
    use std::borrow::Cow;

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.resilience.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let _ = seed_genesis_block_for_state(&actor.state);

    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(sample_transaction())),
            actor.state.view(),
        )
        .expect("push tx");

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 1_u64;
    let parent = actor
        .state
        .view()
        .latest_block_hash()
        .expect("genesis hash should exist");
    actor.phase_tracker.start_new_round(height, Instant::now());
    actor
        .phase_tracker
        .on_view_change(height, view, Instant::now());
    actor
        .subsystems
        .propose
        .proposal_cache
        .insert_proposal(sample_proposal(parent, height, view));
    let repair_window = actor
        .frontier_slot_lag_window()
        .max(actor.recovery_deferred_qc_ttl())
        .max(actor.quorum_timeout(true))
        .max(actor.rebroadcast_cooldown());
    let now = Instant::now();
    let stale_observed_at = now
        .checked_sub(repair_window.saturating_add(Duration::from_millis(1)))
        .expect("repair window should fit in Instant range");
    actor
        .subsystems
        .propose
        .proposal_cache
        .observed_at
        .insert((height, view), stale_observed_at);

    let proposed = actor.on_pacemaker_propose_ready(now);
    assert!(
        !proposed,
        "first pass should rotate away from the orphaned cached proposal"
    );
    assert!(
        actor
            .subsystems
            .propose
            .proposal_cache
            .get_proposal(height, view)
            .is_none(),
        "orphaned cached proposal should be dropped"
    );
    assert!(
        actor
            .phase_tracker
            .current_view(height)
            .is_some_and(|current| current > view),
        "orphaned cached proposal should advance the recovery view"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn cached_recovery_proposal_with_hint_repairs_missing_body_before_rotation() {
    use std::borrow::Cow;

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.resilience.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);
    let _ = seed_genesis_block_for_state(&actor.state);

    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(sample_transaction())),
            actor.state.view(),
        )
        .expect("push tx");

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 1_u64;
    let parent = actor
        .state
        .view()
        .latest_block_hash()
        .expect("genesis hash should exist");
    let missing_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xC7; Hash::LENGTH]));
    actor.phase_tracker.start_new_round(height, Instant::now());
    actor
        .phase_tracker
        .on_view_change(height, view, Instant::now());
    actor
        .subsystems
        .propose
        .proposal_cache
        .insert_hint(sample_hint(missing_hash, height, view, Some(parent)));
    actor
        .subsystems
        .propose
        .proposal_cache
        .insert_proposal(sample_proposal(parent, height, view));

    let _ = take_background_log(&background_log);
    let proposed = actor.on_pacemaker_propose_ready(Instant::now());
    assert!(
        !proposed,
        "body repair should defer proposal reassembly for the cached slot"
    );
    assert!(
        actor
            .subsystems
            .propose
            .proposal_cache
            .get_proposal(height, view)
            .is_some(),
        "cached proposal should stay available while exact body repair is active"
    );
    assert!(
        actor
            .subsystems
            .propose
            .proposal_cache
            .get_hint(height, view)
            .is_some(),
        "proposal hint should stay available to preserve the exact repair target"
    );
    assert_eq!(
        actor.phase_tracker.current_view(height),
        Some(view),
        "recovery should not rotate before the exact body repair window expires"
    );
    assert!(
        actor.frontier_slot.as_ref().is_some_and(|slot| {
            slot.height == height
                && slot.view == view
                && slot.block_hash == missing_hash
                && slot.exact_fetch_armed
                && !slot.body_present()
        }),
        "missing cached body should be routed through exact frontier repair"
    );
    assert!(
        take_background_log(&background_log)
            .iter()
            .any(|entry| entry.msg_kind == Some("FetchBlockBody")),
        "resilience repair should issue an immediate FetchBlockBody for the cached hint"
    );

    let repair_window = actor
        .frontier_slot_lag_window()
        .max(actor.recovery_deferred_qc_ttl())
        .max(actor.quorum_timeout(true))
        .max(actor.rebroadcast_cooldown());
    assert!(
        repair_window > Duration::ZERO,
        "test requires a finite exact-repair wait window"
    );
    let stale_started_at = Instant::now()
        .checked_sub(repair_window.saturating_add(Duration::from_millis(1)))
        .expect("repair window should fit in Instant range");
    actor
        .frontier_slot
        .as_mut()
        .expect("frontier slot should remain armed")
        .timers
        .lag_window_started_at = Some(stale_started_at);
    actor
        .subsystems
        .propose
        .proposal_cache
        .observed_at
        .insert((height, view), stale_started_at);

    let rotated = actor.on_pacemaker_propose_ready(Instant::now());
    assert!(
        !rotated,
        "expired body repair should rotate away from the orphaned cached proposal"
    );
    assert!(
        actor
            .subsystems
            .propose
            .proposal_cache
            .get_proposal(height, view)
            .is_none(),
        "orphaned cached proposal should be dropped after the exact repair window expires"
    );
    assert!(
        actor
            .subsystems
            .propose
            .proposal_cache
            .get_hint(height, view)
            .is_none(),
        "orphaned cached hint should be dropped after the exact repair window expires"
    );
    assert!(
        actor
            .phase_tracker
            .current_view(height)
            .is_some_and(|current| current > view),
        "expired exact repair should advance the recovery view"
    );

    harness.shutdown.send();
}

