#[tokio::test(flavor = "current_thread")]
async fn qc_signers_for_votes_revalidates_on_roster_hash_mismatch() {
    let mut harness = test_actor_harness(3).await;
    let actor = &mut harness.actor;
    let chain = actor.common_config.chain.clone();
    let height = 1u64;
    let view = 0u64;
    let epoch = actor.epoch_for_height(height);
    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    assert_eq!(
        consensus_mode,
        ConsensusMode::Permissioned,
        "test assumes permissioned consensus"
    );

    let roster: Vec<PeerId> = harness
        .key_pairs
        .iter()
        .map(|keypair| PeerId::new(keypair.public_key().clone()))
        .collect();
    let topology = super::network_topology::Topology::new(roster);
    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x55; Hash::LENGTH]));
    let mut vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: 0,
        bls_sig: Vec::new(),
    };
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    bind_vote_to_signature_topology_chain_order(&mut vote, actor, &signature_topology);
    sign_vote_for_view_with_seed(
        &mut vote,
        &chain,
        &topology,
        &harness.key_pairs,
        mode_tag,
        prf_seed,
    );

    let key = vote_log_key_for_vote(&vote);
    let roster_hash = HashOf::new(&signature_topology.as_ref().to_vec());
    let membership_hash = HashOf::new(&super::roster::canonicalize_roster_for_mode(
        signature_topology.as_ref().to_vec(),
        consensus_mode,
    ));
    actor.vote_log.insert(key, vote.clone());
    actor.vote_validation_cache.insert(
        key,
        super::VoteValidationCacheEntry {
            roster_hash,
            membership_hash,
        },
    );
    assert!(
        actor.vote_validation_cache.contains_key(&key),
        "vote validation cache should track validated votes"
    );

    let signers = actor.qc_signers_for_votes(
        Phase::Commit,
        block_hash,
        height,
        view,
        epoch,
        &signature_topology,
    );
    assert!(
        signers.contains(&vote.signer),
        "cached signers should include the validated vote"
    );

    let mismatched_roster = vec![PeerId::new(checked_bls_keypair().public_key().clone())];
    let mismatched_topology = super::network_topology::Topology::new(mismatched_roster);
    let mismatched_signature_topology =
        super::topology_for_view(&mismatched_topology, height, view, mode_tag, prf_seed);
    assert_ne!(
        HashOf::new(&signature_topology.as_ref().to_vec()),
        HashOf::new(&mismatched_signature_topology.as_ref().to_vec()),
        "test setup must use mismatched roster hashes"
    );
    let mismatched_signers = actor.qc_signers_for_votes(
        Phase::Commit,
        block_hash,
        height,
        view,
        epoch,
        &mismatched_signature_topology,
    );
    assert!(
        mismatched_signers.is_empty(),
        "mismatched roster hash should force signature revalidation"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn qc_signers_for_votes_uses_mode_aware_membership_hash_for_rotated_views() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let chain = actor.common_config.chain.clone();
    let height = 1u64;
    let epoch = actor.epoch_for_height(height);
    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    assert_eq!(
        consensus_mode,
        ConsensusMode::Permissioned,
        "test assumes permissioned consensus"
    );

    let roster: Vec<PeerId> = harness
        .key_pairs
        .iter()
        .map(|keypair| PeerId::new(keypair.public_key().clone()))
        .collect();
    let topology = super::network_topology::Topology::new(roster);

    let mut selected: Option<(u64, super::network_topology::Topology)> = None;
    for candidate_view in 0..32_u64 {
        let signature_topology =
            super::topology_for_view(&topology, height, candidate_view, mode_tag, prf_seed);
        let sorted_membership =
            super::roster::canonicalize_roster(signature_topology.as_ref().to_vec());
        if signature_topology.as_ref() != sorted_membership.as_slice() {
            selected = Some((candidate_view, signature_topology));
            break;
        }
    }
    let (view, signature_topology) = selected.unwrap_or_else(|| {
        (
            0,
            super::topology_for_view(&topology, height, 0, mode_tag, prf_seed),
        )
    });

    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x5A; Hash::LENGTH]));
    let mut vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: 0,
        bls_sig: Vec::new(),
    };
    bind_vote_to_signature_topology_chain_order(&mut vote, actor, &signature_topology);
    sign_vote_for_view_with_seed(
        &mut vote,
        &chain,
        &topology,
        &harness.key_pairs,
        mode_tag,
        prf_seed,
    );

    let key = vote_log_key_for_vote(&vote);
    let roster_hash = HashOf::new(&signature_topology.as_ref().to_vec());
    let membership_hash = HashOf::new(&super::roster::canonicalize_roster_for_mode(
        signature_topology.as_ref().to_vec(),
        consensus_mode,
    ));
    actor.vote_log.insert(key, vote.clone());
    actor.vote_validation_cache.insert(
        key,
        super::VoteValidationCacheEntry {
            roster_hash,
            membership_hash,
        },
    );

    let signers = actor.qc_signers_for_votes(
        Phase::Commit,
        block_hash,
        height,
        view,
        epoch,
        &signature_topology,
    );
    assert!(
        signers.contains(&vote.signer),
        "mode-aware membership hash should keep cached vote for rotated view"
    );

    harness.shutdown.send();
}

