#[tokio::test(flavor = "current_thread")]
async fn process_new_view_qc_rejects_invalid_highest_reference() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let signers: BTreeSet<ValidatorIndex> = (0..topology.as_ref().len())
        .map(|idx| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_vec = signers.iter().copied().collect::<Vec<_>>();
    let signers_bitmap = super::build_signers_bitmap(&signers, topology.as_ref().len());
    let height = actor.committed_height_snapshot().saturating_add(1);
    let highest_height = height.saturating_sub(1);
    let view = 1_u64;
    let epoch = actor.epoch_for_height(height);
    let highest_epoch = actor.epoch_for_height(highest_height);
    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x5C; Hash::LENGTH]));
    let other_block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x5D; Hash::LENGTH]));

    for (label, highest_qc) in [
        (
            "subject mismatch",
            QcHeaderRef {
                subject_block_hash: other_block_hash,
                height: highest_height,
                view: 0,
                epoch: highest_epoch,
                phase: Phase::Commit,
            },
        ),
        (
            "future highest epoch",
            QcHeaderRef {
                subject_block_hash: block_hash,
                height: highest_height,
                view: 0,
                epoch: epoch.saturating_add(1),
                phase: Phase::Commit,
            },
        ),
    ] {
        let qc = qc_with_bitmap_and_highest_for_actor(
            actor,
            block_hash,
            height,
            view,
            epoch,
            signers_bitmap.clone(),
            Phase::NewView,
            Some(highest_qc),
            &topology,
            &harness.key_pairs,
        );

        actor.process_new_view_qc(&qc, &signers_vec, &topology);

        assert!(
            actor.subsystems.propose.new_view_tracker.entries.is_empty(),
            "{label} highest evidence must not seed NEW_VIEW tracker state"
        );
    }

    harness.shutdown.send();
}

#[test]
fn validate_qc_against_votes_falls_back_without_stake_snapshot() {
    let chain: ChainId = "qc-npos-snapshot-missing".parse().expect("chain id parses");
    let (keypairs, topology) = sample_bls_topology(2);
    let validator_set = canonical_validator_set_for_mode(&topology, ConsensusMode::Npos);
    let canonical_topology = super::network_topology::Topology::new(validator_set.clone());
    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x81; Hash::LENGTH]));
    let signers_bitmap = vec![0b0000_0011];
    let aggregate_sig = aggregate_signature_for_bitmap(
        &chain,
        super::NPOS_TAG,
        Phase::Commit,
        block_hash,
        1,
        0,
        0,
        &signers_bitmap,
        &canonical_topology,
        &keypairs,
    );
    let qc = Qc {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height: 1,
        view: 0,
        epoch: 0,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        mode_tag: super::NPOS_TAG.to_string(),
        highest_qc: None,
        validator_set_hash: HashOf::new(&validator_set),
        validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
        validator_set: validator_set.clone(),
        aggregate: QcAggregate {
            signers_bitmap,
            bls_aggregate_signature: aggregate_sig,
        },
    };

    let vote_log = BTreeMap::new();
    let outcome = validate_qc_against_votes_with_keys(
        &vote_log,
        &qc,
        &topology,
        &keypairs,
        &chain,
        ConsensusMode::Npos,
        None,
        super::NPOS_TAG,
        None,
    )
    .expect("missing stake snapshot should fall back for NPoS QC");
    assert_eq!(outcome.len(), 2);
}

#[tokio::test(flavor = "current_thread")]
async fn recover_qc_from_aggregate_accepts_commit_subject_mismatch() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0_u64;
    let epoch = actor.epoch_for_height(height);
    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x91; Hash::LENGTH]));
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let signers: BTreeSet<ValidatorIndex> = (0..topology.as_ref().len())
        .map(|idx| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_bitmap = super::build_signers_bitmap(&signers, topology.as_ref().len());
    let qc = qc_with_bitmap(
        &actor.common_config.chain,
        block_hash,
        height,
        view,
        epoch,
        signers_bitmap,
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );

    let recovered = actor.recover_qc_from_aggregate(
        &qc,
        &topology,
        ConsensusMode::Permissioned,
        None,
        Some(true),
        &super::QcValidationError::SubjectMismatch { signer: 0 },
    );
    assert!(
        recovered.is_some(),
        "aggregate recovery should tolerate stale local vote subjects for catch-up QCs"
    );
    let recovered = actor.recover_qc_from_aggregate(
        &qc,
        &topology,
        ConsensusMode::Permissioned,
        None,
        Some(true),
        &super::QcValidationError::RootsMismatch { signer: 0 },
    );
    assert!(
        recovered.is_some(),
        "aggregate recovery should tolerate stale local vote roots for catch-up QCs"
    );

    harness.shutdown.send();
}

