#[tokio::test(flavor = "current_thread")]
async fn future_new_view_votes_still_form_qc_when_local_view_lags() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    seed_genesis_block_for_state(&actor.state);
    while harness.background_rx.try_recv().is_ok() {}

    let view = actor.state.view();
    let committed_height = view.height() as u64;
    let highest_qc = QcHeaderRef {
        subject_block_hash: view.latest_block_hash().expect("committed block hash"),
        height: committed_height,
        view: 0,
        epoch: actor.epoch_for_height(committed_height),
        phase: Phase::Commit,
    };
    drop(view);

    let height = highest_qc.height.saturating_add(1);
    let local_view = 0_u64;
    let far_view = local_view
        .saturating_add(super::VOTE_CACHE_VIEW_WINDOW)
        .saturating_add(4);
    let now = Instant::now();
    actor.phase_tracker.start_new_round(height, now);

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let epoch = actor.epoch_for_height(height);
    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology =
        super::topology_for_view(&topology, height, far_view, mode_tag, prf_seed);
    let (chain_order_hash, rechain_seq) = actor.vnext_chain_order_binding_for_signature_topology(
        height,
        far_view,
        consensus_mode,
        &signature_topology,
    );
    let local_signer = actor
        .local_validator_index_for_topology(&signature_topology)
        .expect("local peer in far-view topology");
    let remote_signers: Vec<_> = signature_topology
        .as_ref()
        .iter()
        .enumerate()
        .filter_map(|(idx, _)| {
            let signer = ValidatorIndex::try_from(idx).ok()?;
            (signer != local_signer).then_some(signer)
        })
        .take(signature_topology.min_votes_for_commit())
        .collect();
    assert_eq!(
        remote_signers.len(),
        signature_topology.min_votes_for_commit(),
        "test requires enough remote signers to finish the far-view NEW_VIEW quorum"
    );
    let qc_key = (
        Phase::NewView,
        highest_qc.subject_block_hash,
        height,
        far_view,
        epoch,
        chain_order_hash,
        rechain_seq,
    );

    for signer in remote_signers {
        let mut vote = crate::sumeragi::consensus::Vote {
            phase: Phase::NewView,
            block_hash: highest_qc.subject_block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view: far_view,
            epoch,
            chain_order_hash,
            rechain_seq,
            highest_qc: Some(highest_qc),
            signer,
            bls_sig: Vec::new(),
        };
        sign_vote_for_view(
            &mut vote,
            &actor.common_config.chain,
            &topology,
            &harness.key_pairs,
        );
        actor.handle_vote(vote);
    }

    let recorded_votes = actor
        .vote_log
        .values()
        .filter(|vote| {
            vote.phase == Phase::NewView
                && vote.block_hash == highest_qc.subject_block_hash
                && vote.height == height
                && vote.view == far_view
                && vote.epoch == epoch
        })
        .count();
    assert_eq!(
        recorded_votes,
        signature_topology.min_votes_for_commit(),
        "far-future NEW_VIEW votes should remain recorded while the local round catches up"
    );
    let qc_signers = actor.qc_signers_for_votes(
        Phase::NewView,
        highest_qc.subject_block_hash,
        height,
        far_view,
        epoch,
        &signature_topology,
    );
    assert_eq!(
        qc_signers.len(),
        signature_topology.min_votes_for_commit(),
        "far-future NEW_VIEW votes should remain QC-eligible while the local round lags"
    );
    assert!(
        actor.qc_cache.contains_key(&qc_key),
        "far-future NEW_VIEW quorum should still aggregate into a QC"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn future_new_view_commit_quorum_advances_local_view_and_emits_vote() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.gating.future_view_window = 4;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    seed_genesis_block_for_state(&actor.state);
    while harness.background_rx.try_recv().is_ok() {}

    let view = actor.state.view();
    let committed_height = view.height() as u64;
    let highest_qc = QcHeaderRef {
        subject_block_hash: view.latest_block_hash().expect("committed block hash"),
        height: committed_height,
        view: 0,
        epoch: actor.epoch_for_height(committed_height),
        phase: Phase::Commit,
    };
    drop(view);

    let height = highest_qc.height.saturating_add(1);
    let local_view = 1_u64;
    let future_view = 3_u64;
    let now = Instant::now();
    actor.phase_tracker.start_new_round(height, now);
    actor.phase_tracker.on_view_change(height, local_view, now);
    actor.subsystems.propose.new_view_tracker = NewViewTracker::default();
    let _ = actor.process_committed_blocks_before_consensus(
        "new_view_qc_completion_emits_late_local_vote_for_installable_future_view",
    );

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology =
        super::topology_for_view(&topology, height, future_view, mode_tag, prf_seed);
    let (chain_order_hash, rechain_seq) = actor.vnext_chain_order_binding_for_signature_topology(
        height,
        future_view,
        consensus_mode,
        &signature_topology,
    );
    let local_peer = actor.common_config.peer.id().clone();
    let remote_signers: Vec<_> = signature_topology
        .as_ref()
        .iter()
        .enumerate()
        .filter_map(|(idx, peer)| {
            (peer != &local_peer).then(|| ValidatorIndex::try_from(idx).expect("signer fits"))
        })
        .take(topology.min_votes_for_commit().saturating_sub(1))
        .collect();
    assert_eq!(
        remote_signers.len(),
        topology.min_votes_for_commit().saturating_sub(1),
        "test requires enough remote signers to finish the future-view NEW_VIEW commit quorum"
    );
    let epoch = actor.epoch_for_height(height);

    for (idx, remote_signer) in remote_signers.into_iter().enumerate() {
        let mut vote = crate::sumeragi::consensus::Vote {
            phase: Phase::NewView,
            block_hash: highest_qc.subject_block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view: future_view,
            epoch,
            chain_order_hash,
            rechain_seq,
            highest_qc: Some(highest_qc),
            signer: remote_signer,
            bls_sig: Vec::new(),
        };
        sign_vote_for_view_with_seed(
            &mut vote,
            &actor.common_config.chain,
            &topology,
            &harness.key_pairs,
            mode_tag,
            prf_seed,
        );

        actor.handle_vote(vote);

        if idx == 0 {
            assert_eq!(
                actor.phase_tracker.current_view(height),
                Some(local_view),
                "f+1 higher NEW_VIEW support must not move the local pacemaker"
            );
            assert!(
                !actor.stored_votes().any(|vote| {
                    vote.phase == Phase::NewView
                        && vote.height == height
                        && vote.view == future_view
                        && actor
                            .vote_signer_peer(vote)
                            .as_ref()
                            .is_some_and(|peer| peer == &local_peer)
                }),
                "the local validator should not echo future NEW_VIEW support before commit quorum"
            );
        }
    }

    let roster: BTreeSet<_> = topology.as_ref().iter().cloned().collect();
    let effective_support = actor
        .subsystems
        .propose
        .new_view_tracker
        .entries
        .get(&(height, future_view))
        .map_or(0, |entry| entry.count_in_roster(&roster, Some(&local_peer)));
    assert_eq!(
        effective_support,
        topology.min_votes_for_commit(),
        "test setup should provide a full NEW_VIEW commit quorum"
    );
    assert_eq!(
        actor.phase_tracker.current_view(height),
        Some(future_view),
        "future NEW_VIEW commit quorum should move the local pacemaker to that view"
    );
    assert!(
        actor.stored_votes().any(|vote| {
            vote.phase == Phase::NewView
                && vote.height == height
                && vote.view == future_view
                && actor
                    .vote_signer_peer(vote)
                    .as_ref()
                    .is_some_and(|peer| peer == &local_peer)
        }),
        "following the future view should emit the local NEW_VIEW vote"
    );
    assert!(
        actor.subsystems.propose.new_view_tracker.count_with_local(
            height,
            future_view,
            Some(&local_peer)
        ) >= topology.min_votes_for_commit(),
        "the followed view should retain commit-quorum support to keep converging"
    );

    harness.shutdown.send();
}

