#[tokio::test(flavor = "current_thread")]
async fn assemble_proposal_skips_view_overflow() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = 1u64;
    let view = u64::MAX;
    let highest_qc = sample_qc_ref(0, 0);
    let mut topology = super::network_topology::Topology::new(actor.effective_commit_topology());

    let assembled = actor
        .assemble_and_broadcast_proposal(
            height,
            view,
            highest_qc,
            &mut topology,
            /*leader_index*/ 0,
            /*local_validator_index*/ 0,
            None,
            Instant::now(),
        )
        .expect("proposal assembly should skip overflow view");
    assert!(!assembled, "overflow view should not assemble a proposal");

    assert!(
        actor.pending.pending_blocks.is_empty(),
        "overflow view should not enqueue pending blocks"
    );
    assert!(
        actor.slot_tracker.proposals_seen.is_empty(),
        "overflow view should not mark proposals as seen"
    );
    assert!(
        actor
            .subsystems
            .propose
            .proposal_cache
            .get_hint(height, view)
            .is_none(),
        "overflow view should not cache proposal hints"
    );
    assert!(
        actor
            .subsystems
            .propose
            .proposal_cache
            .get_proposal(height, view)
            .is_none(),
        "overflow view should not cache proposals"
    );
    assert!(
        actor.phase_tracker.current_view(height).is_none(),
        "phase tracker should not advance on overflow view"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn assemble_proposal_uses_inline_frontier_block_created_with_rbc_backup_transport() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.rbc.chunk_max_bytes = 64 * 1024;
    consensus_cfg.rbc.inline_block_created_backup = true;

    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    widen_sumeragi_timing_for_heavy_proposal_test(actor);
    let background_log: Arc<Mutex<Vec<super::BackgroundRequestLogEntry>>> =
        Arc::new(Mutex::new(Vec::new()));
    actor.background_request_log = Some(Arc::clone(&background_log));

    let tx = sample_transaction();
    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(tx)),
            actor.state.view(),
        )
        .expect("push tx");

    let height = 1u64;
    let highest_qc = sample_qc_ref(0, 0);
    let mut topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let (_, _, prf_seed) = actor.consensus_context_for_height(height);
    let seed = prf_seed.expect("PRF seed available");
    topology.canonicalize_order();
    topology.shuffle_prf(seed, height);
    let local_pos = topology
        .position(actor.common_config.peer.id().public_key())
        .expect("local peer in topology");
    let view = u64::try_from(local_pos).expect("view fits u64");
    let leader_index = actor
        .leader_index_for(&mut topology, height, view)
        .expect("leader index");
    let local_idx = actor
        .local_validator_index_for_topology(&topology)
        .expect("local validator index");
    let leader_index_u32 = u32::try_from(leader_index).expect("leader index fits u32");
    assert_eq!(
        leader_index_u32, local_idx,
        "local peer must be leader for proposal assembly"
    );

    let assembled = actor
        .assemble_and_broadcast_proposal(
            height,
            view,
            highest_qc,
            &mut topology,
            /*leader_index*/ leader_index,
            /*local_validator_index*/ local_idx,
            None,
            Instant::now(),
        )
        .expect("proposal assembly should succeed");
    assert!(assembled, "proposal assembly should succeed");

    let posts = background_log
        .lock()
        .expect("background request log mutex poisoned")
        .clone();
    let mut block_created_indexes = Vec::new();
    let mut rbc_indexes = Vec::new();
    for (idx, post) in posts.iter().enumerate() {
        match post.msg_kind {
            Some("BlockCreated") => block_created_indexes.push(idx),
            Some("RbcInit") | Some("RbcChunk") | Some("RbcChunkCompact") | Some("RbcReady") => {
                rbc_indexes.push(idx);
            }
            _ => (),
        }
    }
    assert!(
        !block_created_indexes.is_empty(),
        "BlockCreated messages should be scheduled"
    );
    assert!(
        !rbc_indexes.is_empty(),
        "exact-frontier proposal assembly should seed RBC transport alongside inline BlockCreated"
    );
    assert!(
        posts
            .iter()
            .any(|post| post.msg_kind == Some("ProposalHint")),
        "frontier assembly should advertise proposal hints for peers that miss inline BlockCreated"
    );
    assert!(
        posts.iter().any(|post| post.msg_kind == Some("Proposal")),
        "frontier assembly should keep proposal metadata available when seeding RBC backup transport"
    );
    assert!(
        block_created_indexes.iter().any(|block_created_idx| {
            posts
                .iter()
                .enumerate()
                .find_map(|(idx, post)| (post.msg_kind == Some("Proposal")).then_some(idx))
                .is_some_and(|proposal_idx| *block_created_idx < proposal_idx)
        }),
        "inline BlockCreated should still be posted before standalone Proposal backup traffic"
    );
    if let Some(first_ready_idx) = posts
        .iter()
        .position(|post| post.msg_kind == Some("RbcReady"))
    {
        let first_body_idx = posts
            .iter()
            .position(|post| {
                matches!(
                    post.msg_kind,
                    Some("BlockCreated")
                        | Some("RbcInit")
                        | Some("RbcChunk")
                        | Some("RbcChunkCompact")
                )
            })
            .expect("body transport should be scheduled");
        assert!(
            first_body_idx < first_ready_idx,
            "body transport should be posted before local READY evidence"
        );
    }

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn assemble_proposal_skips_rbc_backup_but_keeps_metadata_for_inline_frontier_when_disabled() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.rbc.chunk_max_bytes = 64 * 1024;
    consensus_cfg.rbc.inline_block_created_backup = false;

    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    widen_sumeragi_timing_for_heavy_proposal_test(actor);
    let background_log: Arc<Mutex<Vec<super::BackgroundRequestLogEntry>>> =
        Arc::new(Mutex::new(Vec::new()));
    actor.background_request_log = Some(Arc::clone(&background_log));

    let tx = sample_transaction();
    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(tx)),
            actor.state.view(),
        )
        .expect("push tx");

    let height = 1u64;
    let highest_qc = sample_qc_ref(0, 0);
    let mut topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let (_, _, prf_seed) = actor.consensus_context_for_height(height);
    let seed = prf_seed.expect("PRF seed available");
    topology.canonicalize_order();
    topology.shuffle_prf(seed, height);
    let local_pos = topology
        .position(actor.common_config.peer.id().public_key())
        .expect("local peer in topology");
    let view = u64::try_from(local_pos).expect("view fits u64");
    let leader_index = actor
        .leader_index_for(&mut topology, height, view)
        .expect("leader index");
    let local_idx = actor
        .local_validator_index_for_topology(&topology)
        .expect("local validator index");
    let leader_index_u32 = u32::try_from(leader_index).expect("leader index fits u32");
    assert_eq!(
        leader_index_u32, local_idx,
        "local peer must be leader for proposal assembly"
    );

    let assembled = actor
        .assemble_and_broadcast_proposal(
            height,
            view,
            highest_qc,
            &mut topology,
            /*leader_index*/ leader_index,
            /*local_validator_index*/ local_idx,
            None,
            Instant::now(),
        )
        .expect("proposal assembly should succeed");
    assert!(assembled, "proposal assembly should succeed");

    let posts = background_log
        .lock()
        .expect("background request log mutex poisoned")
        .clone();
    assert!(
        posts
            .iter()
            .any(|post| post.msg_kind == Some("BlockCreated")),
        "inline BlockCreated messages should be scheduled"
    );
    assert!(
        !posts.iter().any(|post| matches!(
            post.msg_kind,
            Some("RbcInit") | Some("RbcChunk") | Some("RbcChunkCompact") | Some("RbcReady")
        )),
        "exact-frontier assembly should skip RBC body traffic when backup is disabled"
    );
    let local_peer = actor.common_config.peer.id().clone();
    let expected_targets: BTreeSet<_> = topology
        .as_ref()
        .iter()
        .filter(|peer| *peer != &local_peer)
        .cloned()
        .collect();
    let proposal_hint_targets: BTreeSet<_> = posts
        .iter()
        .filter_map(|post| match post {
            super::BackgroundRequestLogEntry {
                kind: super::BackgroundRequestLogKind::Post,
                msg_kind: Some("ProposalHint"),
                peer: Some(peer),
            } => Some(peer.clone()),
            _ => None,
        })
        .collect();
    let proposal_targets: BTreeSet<_> = posts
        .iter()
        .filter_map(|post| match post {
            super::BackgroundRequestLogEntry {
                kind: super::BackgroundRequestLogKind::Post,
                msg_kind: Some("Proposal"),
                peer: Some(peer),
            } => Some(peer.clone()),
            _ => None,
        })
        .collect();
    assert_eq!(
        proposal_hint_targets, expected_targets,
        "inline-only assembly should still advertise proposal hints to remote validators"
    );
    assert_eq!(
        proposal_targets, expected_targets,
        "inline-only assembly should still keep proposal metadata available to remote validators"
    );

    harness.shutdown.send();
}

#[test]
fn inline_frontier_backup_transport_requires_da_inline_and_config() {
    assert!(super::propose::should_seed_frontier_backup_transport(
        true, true, true
    ));
    assert!(!super::propose::should_seed_frontier_backup_transport(
        true, true, false
    ));
    assert!(!super::propose::should_seed_frontier_backup_transport(
        false, true, true
    ));
    assert!(!super::propose::should_seed_frontier_backup_transport(
        true, false, true
    ));
}

#[tokio::test(flavor = "current_thread")]
async fn assemble_proposal_uses_rbc_transport_for_multi_chunk_frontier_payloads() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.rbc.chunk_max_bytes = 256;

    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    widen_sumeragi_timing_for_heavy_proposal_test(actor);
    let background_log: Arc<Mutex<Vec<super::BackgroundRequestLogEntry>>> =
        Arc::new(Mutex::new(Vec::new()));
    actor.background_request_log = Some(Arc::clone(&background_log));

    let tx = sample_log_transaction_with_message_len(8 * 1024);
    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(tx)),
            actor.state.view(),
        )
        .expect("push tx");

    let height = 1u64;
    let highest_qc = sample_qc_ref(0, 0);
    let mut topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let (_, _, prf_seed) = actor.consensus_context_for_height(height);
    let seed = prf_seed.expect("PRF seed available");
    topology.canonicalize_order();
    topology.shuffle_prf(seed, height);
    let local_pos = topology
        .position(actor.common_config.peer.id().public_key())
        .expect("local peer in topology");
    let view = u64::try_from(local_pos).expect("view fits u64");
    let leader_index = actor
        .leader_index_for(&mut topology, height, view)
        .expect("leader index");
    let local_idx = actor
        .local_validator_index_for_topology(&topology)
        .expect("local validator index");
    let leader_index_u32 = u32::try_from(leader_index).expect("leader index fits u32");
    assert_eq!(
        leader_index_u32, local_idx,
        "local peer must be leader for proposal assembly"
    );

    let assembled = actor
        .assemble_and_broadcast_proposal(
            height,
            view,
            highest_qc,
            &mut topology,
            leader_index,
            local_idx,
            None,
            Instant::now(),
        )
        .expect("proposal assembly should succeed");
    assert!(assembled, "proposal assembly should succeed");

    let posts = background_log
        .lock()
        .expect("background request log mutex poisoned")
        .clone();
    assert!(
        posts
            .iter()
            .any(|post| post.msg_kind == Some("BlockCreated")),
        "multi-chunk frontier payloads should send an exact body companion"
    );
    assert!(
        posts.iter().any(|post| {
            matches!(
                post.msg_kind,
                Some("RbcInit") | Some("RbcChunk") | Some("RbcChunkCompact") | Some("RbcReady")
            )
        }),
        "multi-chunk frontier payloads should still use RBC transport"
    );
    assert!(
        posts.iter().any(|post| post.msg_kind == Some("Proposal")),
        "multi-chunk frontier payloads should advertise proposal metadata on the wire"
    );
    assert!(
        posts
            .iter()
            .any(|post| post.msg_kind == Some("ProposalHint")),
        "multi-chunk frontier payloads should advertise proposal hints"
    );
    let first_body_idx = posts
        .iter()
        .position(|post| post.msg_kind == Some("BlockCreated"))
        .expect("exact body companion should be scheduled");
    let first_rbc_idx = posts
        .iter()
        .position(|post| {
            matches!(
                post.msg_kind,
                Some("RbcInit") | Some("RbcChunk") | Some("RbcChunkCompact")
            )
        })
        .expect("RBC body transport should be scheduled");
    let first_hint_idx = posts
        .iter()
        .position(|post| post.msg_kind == Some("ProposalHint"))
        .expect("proposal hint should be scheduled");
    assert_ne!(
        first_rbc_idx, first_hint_idx,
        "multi-chunk frontier body transport and proposal hints should be distinct posts"
    );
    assert!(
        first_body_idx < first_hint_idx,
        "multi-chunk exact body companion should be posted before proposal hints"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn assemble_proposal_defers_when_candidate_conflicts_with_local_vote_history() {
    use std::borrow::Cow;

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = 1u64;
    let roster = actor.effective_commit_topology();
    let vote_topology = {
        let mut topology = super::network_topology::Topology::new(roster.clone());
        let (_, _, prf_seed) = actor.consensus_context_for_height(height);
        let seed = prf_seed.expect("PRF seed available");
        topology.canonicalize_order();
        topology.shuffle_prf(seed, height);
        topology
    };
    let (mut topology, view, leader_index, local_idx) = (1..=roster.len().saturating_mul(3))
        .find_map(|view| {
            let view = u64::try_from(view).ok()?;
            let mut topology = super::network_topology::Topology::new(roster.clone());
            let leader_index = actor.leader_index_for(&mut topology, height, view).ok()?;
            let local_idx = actor.local_validator_index_for_topology(&topology)?;
            (u32::try_from(leader_index).ok()? == local_idx).then_some((
                topology,
                view,
                leader_index,
                local_idx,
            ))
        })
        .expect("test requires a later view led by the local peer");

    let conflicting_block = sample_block(height, 0, None);
    let conflicting_hash = insert_validated_pending(actor, conflicting_block);
    let epoch = actor.epoch_for_height(height);
    assert!(
        actor.emit_precommit_vote(
            conflicting_hash,
            height,
            0,
            epoch,
            ValidationStatus::Valid,
            &vote_topology,
            None,
            Some((Hash::new([]), Hash::new([]))),
        ),
        "test setup should record a local same-height vote for the conflicting branch"
    );
    let proposal_now = Instant::now();
    let pending = actor
        .pending
        .pending_blocks
        .get_mut(&conflicting_hash)
        .expect("conflicting branch should remain pending");
    pending.inserted_at = proposal_now;
    pending.touch_progress(proposal_now);

    let tx = sample_transaction();
    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(tx)),
            actor.state.view(),
        )
        .expect("push tx");

    let assembled = actor
        .assemble_and_broadcast_proposal(
            height,
            view,
            sample_qc_ref(0, 0),
            &mut topology,
            leader_index,
            local_idx,
            None,
            proposal_now,
        )
        .expect("proposal assembly should defer cleanly");
    assert!(
        !assembled,
        "leader must not assemble a conflicting higher-view proposal once local same-height vote history exists"
    );
    assert_eq!(
        actor.queue.queued_len(),
        1,
        "deferred conflicting proposal assembly must leave the queued transaction available for the eventual voted-branch recovery"
    );
    assert!(
        actor
            .subsystems
            .propose
            .proposal_cache
            .get_proposal(height, view)
            .is_none(),
        "deferred conflicting proposal assembly must not populate proposal cache entries for the blocked view"
    );
    assert!(
        !actor.slot_tracker.proposals_seen.contains(&(height, view)),
        "deferred conflicting proposal assembly must not mark the blocked view as observed"
    );
    assert!(
        actor
            .pending
            .pending_blocks
            .get(&conflicting_hash)
            .is_some_and(|pending| pending.height == height),
        "existing voted branch should remain intact after broadcasting the conflicting candidate"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn assemble_proposal_allows_stale_retired_prior_view_local_vote_history() {
    use std::borrow::Cow;

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    widen_sumeragi_timing_for_heavy_proposal_test(actor);
    let committed_tip = seed_genesis_block_for_state(actor.state.as_ref());

    let height = actor.committed_height_snapshot().saturating_add(1);
    let roster = actor.effective_commit_topology();
    let vote_topology = {
        let mut topology = super::network_topology::Topology::new(roster.clone());
        let (_, _, prf_seed) = actor.consensus_context_for_height(height);
        let seed = prf_seed.expect("PRF seed available");
        topology.canonicalize_order();
        topology.shuffle_prf(seed, height);
        topology
    };
    let (mut topology, view, leader_index, local_idx) = (1..=roster.len().saturating_mul(3))
        .find_map(|view| {
            let view = u64::try_from(view).ok()?;
            let mut topology = super::network_topology::Topology::new(roster.clone());
            let leader_index = actor.leader_index_for(&mut topology, height, view).ok()?;
            let local_idx = actor.local_validator_index_for_topology(&topology)?;
            (u32::try_from(leader_index).ok()? == local_idx).then_some((
                topology,
                view,
                leader_index,
                local_idx,
            ))
        })
        .expect("test requires a later view led by the local peer");

    let prior_view = 0_u64;
    let prior_block = sample_block(height, prior_view, actor.state.latest_block_hash_fast());
    let prior_hash = insert_validated_pending(actor, prior_block);
    let epoch = actor.epoch_for_height(height);
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology =
        super::topology_for_view(&vote_topology, height, prior_view, mode_tag, prf_seed);
    let local_signer = actor
        .local_validator_index_for_topology(&signature_topology)
        .expect("local validator index");
    actor.vote_log.insert(
        default_vote_log_key(Phase::Commit, height, prior_view, epoch, local_signer),
        crate::sumeragi::consensus::Vote {
            phase: Phase::Commit,
            block_hash: prior_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view: prior_view,
            epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: None,
            signer: local_signer,
            bls_sig: Vec::new(),
        },
    );

    let now = Instant::now();
    let stale_at = now
        .checked_sub(
            actor
                .quorum_timeout(actor.runtime_da_enabled())
                .max(actor.frontier_slot_lag_window())
                .saturating_add(Duration::from_millis(1)),
        )
        .unwrap_or(now);
    let prior_pending = actor
        .pending
        .pending_blocks
        .get_mut(&prior_hash)
        .expect("prior pending block exists");
    prior_pending.inserted_at = stale_at;
    prior_pending.touch_progress(stale_at);
    prior_pending.retire_same_height();

    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(sample_transaction())),
            actor.state.view(),
        )
        .expect("push tx");

    let highest_qc = QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: committed_tip,
        height: height.saturating_sub(1),
        view: 0,
        epoch: actor.epoch_for_height(height.saturating_sub(1)),
    };

    let assembled = actor
        .assemble_and_broadcast_proposal(
            height,
            view,
            highest_qc,
            &mut topology,
            leader_index,
            local_idx,
            None,
            now,
        )
        .expect("proposal assembly should succeed");

    assert!(
        assembled,
        "stale retired prior-view vote history should not block a fresh resilience proposal"
    );
    assert!(
        actor
            .subsystems
            .propose
            .proposal_cache
            .get_proposal(height, view)
            .is_some(),
        "fresh proposal should be cached for the later view"
    );
    assert!(
        actor.slot_tracker.proposals_seen.contains(&(height, view)),
        "fresh proposal should mark the later view as observed"
    );

    harness.shutdown.send();
}

