#[tokio::test(flavor = "current_thread")]
async fn proposal_queue_scan_budget_looks_ahead_for_rotated_lane() {
    use iroha_config::parameters::actual::{
        LaneRoutingMatcher, LaneRoutingPolicy, LaneRoutingRule,
    };
    use iroha_data_model::nexus::{DataSpaceCatalog, DataSpaceMetadata, LaneCatalog, LaneConfig};

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;

    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let (_time_handle, time_source) = TimeSource::new_mock(Duration::default());

    let lane0 = RoutingDecision::new(LaneId::SINGLE, DataSpaceId::UNIVERSAL);
    let lane1 = RoutingDecision::new(LaneId::new(1), DataSpaceId::new(1));
    let lane_catalog = LaneCatalog::new(
        nonzero!(2_u32),
        vec![
            LaneConfig::default(),
            LaneConfig {
                id: lane1.lane_id,
                dataspace_id: lane1.dataspace_id,
                alias: "lane-1".to_string(),
                ..LaneConfig::default()
            },
        ],
    )
    .expect("lane catalog");
    let dataspace_catalog = DataSpaceCatalog::new(vec![
        DataSpaceMetadata::default(),
        DataSpaceMetadata {
            id: lane1.dataspace_id,
            alias: "space-1".to_string(),
            description: None,
            fault_tolerance: 1,
        },
    ])
    .expect("dataspace catalog");
    let mut staged = Vec::new();
    for routing in [lane0, lane0, lane0, lane1] {
        let key_pair = checked_keypair();
        let (_, private_key) = key_pair.clone().into_parts();
        let authority = AccountId::new(key_pair.public_key().clone());
        let tx = TransactionBuilder::new(ChainId::from("test-chain"), authority)
            .with_instructions([Log::new(Level::INFO, "lane scan budget".to_string())])
            .sign(&private_key);
        staged.push((tx, routing));
    }
    let lane1_authority = staged
        .iter()
        .find_map(|(tx, routing)| (*routing == lane1).then(|| tx.authority().to_string()))
        .expect("lane1 transaction authority");
    let routing_policy = LaneRoutingPolicy {
        default_lane: lane0.lane_id,
        default_dataspace: lane0.dataspace_id,
        rules: vec![LaneRoutingRule {
            lane: lane1.lane_id,
            dataspace: Some(lane1.dataspace_id),
            matcher: LaneRoutingMatcher {
                account: Some(lane1_authority),
                instruction: None,
                description: None,
            },
        }],
    };
    let mut nexus = actor.state.nexus_snapshot();
    nexus.enabled = true;
    nexus.lane_catalog = lane_catalog.clone();
    nexus.dataspace_catalog = dataspace_catalog.clone();
    nexus.routing_policy = routing_policy.clone();
    nexus.fees.base_fee = Numeric::zero();
    nexus.fees.per_byte_fee = Numeric::zero();
    nexus.fees.per_instruction_fee = Numeric::zero();
    nexus.fees.per_gas_unit_fee = Numeric::zero();
    Arc::get_mut(&mut actor.state)
        .expect("state uniquely held")
        .set_nexus(nexus)
        .expect("set Nexus config");

    let queue_router = Arc::new(ConfigLaneRouter::new(
        routing_policy,
        dataspace_catalog,
        lane_catalog,
    ));
    actor.queue = Arc::new(Queue::test_with_router_for_routes(
        QueueConfig::default(),
        &time_source,
        queue_router,
        &[
            (LaneId::SINGLE, DataSpaceId::UNIVERSAL),
            (LaneId::new(1), DataSpaceId::new(1)),
        ],
    ));
    let mut accepted = Vec::new();
    for (tx, routing) in staged {
        let tx = AcceptedTransaction::new_unchecked(Cow::Owned(tx));
        actor
            .queue
            .push(tx.clone(), actor.state.view())
            .expect("push tx");
        accepted.push((tx.hash(), routing));
    }
    let expected_lane1_hash = accepted
        .iter()
        .find_map(|(hash, routing)| (*routing == lane1).then_some(*hash))
        .expect("lane1 transaction");

    let mut tx_guards = Vec::new();
    let deferred = actor.pull_transactions_for_proposal(
        actor.state.as_ref(),
        nonzero!(1_usize),
        4,
        None,
        None,
        false,
        &mut tx_guards,
        1,
        0,
    );

    assert_eq!(tx_guards.len(), 1);
    assert_eq!(tx_guards[0].as_accepted().hash(), expected_lane1_hash);
    assert_eq!(tx_guards[0].routing(), lane1);
    assert_eq!(
        deferred.len(),
        3,
        "lookahead transactions that do not fit the slot are returned for requeue"
    );
    assert!(
        deferred
            .iter()
            .all(|(_, plan)| plan.coordinator_route().lane_id == LaneId::SINGLE),
        "only the lane0 burst should be deferred after the rotated lane wins"
    );

    drop(tx_guards);
    for (tx, routing_plan) in deferred {
        actor
            .queue
            .push_requeued_with_routing_plan(tx, routing_plan, actor.state.as_ref())
            .expect("requeue deferred tx");
    }
    assert_eq!(actor.queue.queued_len(), 3);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn proposal_filter_drops_committed_transactions_after_queue_scan() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let committed_tx = sample_transaction();
    let live_tx = sample_transaction();

    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(committed_tx.clone())),
            actor.state.view(),
        )
        .expect("push committed tx");
    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(live_tx.clone())),
            actor.state.view(),
        )
        .expect("push live tx");

    let height = 1u64;
    let view = 0u64;
    let mut tx_guards = Vec::new();
    let _ = actor.pull_transactions_for_proposal(
        actor.state.as_ref(),
        nonzero!(2_usize),
        2,
        None,
        None,
        false,
        &mut tx_guards,
        height,
        view,
    );

    assert_eq!(tx_guards.len(), 2, "queue should return both transactions");

    let transactions: Vec<_> = tx_guards
        .iter()
        .map(crate::queue::TransactionGuard::clone_accepted)
        .collect();
    let routing: Vec<_> = tx_guards
        .iter()
        .map(crate::queue::TransactionGuard::routing)
        .collect();
    let routing_plans: Vec<_> = tx_guards
        .iter()
        .map(crate::queue::TransactionGuard::routing_plan)
        .collect();
    let tx_sizes: Vec<_> = tx_guards
        .iter()
        .map(crate::queue::TransactionGuard::encoded_len)
        .collect();

    {
        let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
        let mut tx_block = state.transactions.block();
        let next_height = state
            .transactions_latest_height_for_testing()
            .saturating_add(1);
        let next_height =
            NonZeroUsize::new(next_height).expect("transaction height must be non-zero");
        tx_block.insert_block_with_single_tx(committed_tx.hash(), next_height);
        tx_block.commit().expect("commit transactions block");
    }

    let (
        filtered_guards,
        filtered_transactions,
        _filtered_routing,
        _filtered_routing_plans,
        _filtered_sizes,
        dropped,
    ) = Actor::filter_committed_transactions_for_proposal(
        actor.state.as_ref(),
        tx_guards,
        transactions,
        routing,
        routing_plans,
        tx_sizes,
        height,
        view,
    );

    assert_eq!(dropped, 1, "one committed transaction should be dropped");
    assert_eq!(
        filtered_transactions.len(),
        1,
        "only the live transaction should remain"
    );
    assert_eq!(
        filtered_transactions[0].hash(),
        live_tx.hash(),
        "live transaction should remain in proposal batch"
    );

    drop(filtered_guards);

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn proposal_gas_budget_limits_fetch() {
    use iroha_data_model::transaction::Executable;

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;

    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let tx = sample_transaction();
    let instructions = match tx.instructions() {
        Executable::Instructions(batch) => batch.iter().map(Clone::clone).collect::<Vec<_>>(),
        Executable::ContractCall(_) => panic!("sample transaction should be ISI-based"),
        Executable::Ivm(_) => panic!("sample transaction should be ISI-based"),
        Executable::IvmProved(_) => panic!("sample transaction should be ISI-based"),
    };
    let gas_cost = crate::gas::meter_instructions(&instructions);
    assert!(gas_cost > 0, "expected non-zero ISI gas cost");
    let gas_cap = NonZeroU64::new(gas_cost).expect("non-zero gas cap");

    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(tx)),
            actor.state.view(),
        )
        .expect("push tx");
    actor
        .queue
        .push(
            AcceptedTransaction::new_unchecked(Cow::Owned(sample_transaction())),
            actor.state.view(),
        )
        .expect("push tx");

    let mut tx_guards = Vec::new();
    let deferred = actor.pull_transactions_for_proposal(
        actor.state.as_ref(),
        nonzero!(5_usize),
        5,
        Some(gas_cap),
        None,
        false,
        &mut tx_guards,
        1,
        0,
    );

    assert_eq!(tx_guards.len(), 1, "gas cap should allow one tx");
    assert_eq!(deferred.len(), 1, "second tx should be deferred");

    drop(tx_guards);

    for (tx, routing_plan) in deferred {
        actor
            .queue
            .push_requeued_with_routing_plan(tx, routing_plan, actor.state.as_ref())
            .expect("requeue deferred tx");
    }

    assert_eq!(
        actor.queue.queued_len(),
        1,
        "deferred tx should remain queued"
    );

    harness.shutdown.send();
}

