struct SnapshotRosterBlockCreatedSetup {
    snapshot_roster: Vec<PeerId>,
    topology: super::network_topology::Topology,
    signature_topology: super::network_topology::Topology,
    consensus_mode: ConsensusMode,
    mode_tag: &'static str,
    prf_seed: Option<[u8; 32]>,
    block: SignedBlock,
    block_hash: HashOf<BlockHeader>,
    epoch: u64,
}

fn setup_snapshot_roster_block_created(
    actor: &mut Actor,
    key_pairs: &[KeyPair],
    height: u64,
    view: u64,
) -> SnapshotRosterBlockCreatedSetup {
    assert!(height > 1, "test expects non-genesis height");
    let genesis_hash = seed_genesis_block_for_state(&actor.state);

    let mut snapshot_roster = actor.effective_commit_topology();
    let local_peer = actor.common_config.peer.id().clone();
    let removed_peer = snapshot_roster
        .iter()
        .find(|peer| *peer != &local_peer)
        .cloned()
        .expect("non-local roster entry");
    snapshot_roster.retain(|peer| peer != &removed_peer);

    let topology = super::network_topology::Topology::new(snapshot_roster.clone());
    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let signer_peer = signature_topology
        .as_ref()
        .first()
        .expect("commit topology not empty");
    let signer_kp = key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair exists in harness");
    let signer_idx = signature_topology
        .position(signer_kp.public_key())
        .expect("signer index in topology");
    let block = heartbeat_block_for_state(
        actor.state.as_ref(),
        &actor.common_config.chain,
        height,
        view,
        Some(genesis_hash),
        signer_kp,
        u64::try_from(signer_idx).expect("signer index fits u64"),
    );
    let block_hash = block.hash();

    let signers: BTreeSet<ValidatorIndex> = (0..snapshot_roster.len())
        .map(|idx| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_bitmap = super::build_signers_bitmap(&signers, snapshot_roster.len());
    let epoch = actor.epoch_for_height(height);
    let bls_aggregate_signature = aggregate_signature_for_bitmap(
        &actor.common_config.chain,
        mode_tag,
        Phase::Commit,
        block_hash,
        height,
        view,
        epoch,
        &signers_bitmap,
        &topology,
        key_pairs,
    );
    let commit_qc = Qc {
        phase: Phase::Commit,
        subject_block_hash: block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        mode_tag: mode_tag.to_string(),
        highest_qc: None,
        validator_set_hash: HashOf::new(&snapshot_roster),
        validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
        validator_set: snapshot_roster.clone(),
        aggregate: QcAggregate {
            signers_bitmap: signers_bitmap.clone(),
            bls_aggregate_signature,
        },
    };
    let checkpoint_signature = aggregate_vote_signature_for_bitmap(
        &actor.common_config.chain,
        mode_tag,
        block_hash,
        height,
        view,
        epoch,
        &signers_bitmap,
        &topology,
        key_pairs,
    );
    let checkpoint = ValidatorSetCheckpoint::new(
        height,
        view,
        block_hash,
        commit_qc.parent_state_root,
        commit_qc.post_state_root,
        snapshot_roster.clone(),
        signers_bitmap,
        checkpoint_signature,
        VALIDATOR_SET_HASH_VERSION_V1,
        None,
    );
    {
        let mut journal = actor.state.commit_roster_journal.write();
        journal.upsert(commit_qc, checkpoint, None);
    }

    SnapshotRosterBlockCreatedSetup {
        snapshot_roster,
        topology,
        signature_topology,
        consensus_mode,
        mode_tag,
        prf_seed,
        block,
        block_hash,
        epoch,
    }
}

#[tokio::test(flavor = "current_thread")]
async fn block_created_stores_pending_without_commit_quorum() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let key_pairs = harness.key_pairs.clone();
    let actor = &mut harness.actor;

    let height = 2;
    let view = 0;

    let SnapshotRosterBlockCreatedSetup {
        snapshot_roster,
        topology,
        signature_topology,
        consensus_mode,
        mode_tag,
        prf_seed,
        block,
        block_hash,
        epoch,
    } = setup_snapshot_roster_block_created(actor, &key_pairs, height, view);

    let required = signature_topology.min_votes_for_commit().max(1);
    let vote_count = required.saturating_sub(1);
    assert!(vote_count < required, "test expects a non-quorum vote set");
    for signer in 0..vote_count {
        let mut vote = crate::sumeragi::consensus::Vote {
            phase: Phase::Commit,
            block_hash,
            parent_state_root: zero_state_root(),
            post_state_root: zero_state_root(),
            height,
            view,
            epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: None,
            signer: u32::try_from(signer).expect("signer fits u32"),
            bls_sig: Vec::new(),
        };
        let (chain_order_hash, rechain_seq) = actor
            .vnext_chain_order_binding_for_signature_topology(
                height,
                view,
                consensus_mode,
                &signature_topology,
            );
        vote.chain_order_hash = chain_order_hash;
        vote.rechain_seq = rechain_seq;
        sign_vote_for_view_with_seed(
            &mut vote,
            &actor.common_config.chain,
            &topology,
            &key_pairs,
            mode_tag,
            prf_seed,
        );
        actor.vote_log.insert(vote_log_key_for_vote(&vote), vote);
    }

    let commit_topology = actor.roster_for_vote_with_mode(block_hash, height, view, consensus_mode);
    assert_eq!(
        commit_topology, snapshot_roster,
        "expected commit roster to use the snapshot roster"
    );
    let qc_topology = super::network_topology::Topology::new(commit_topology);
    let qc_signature_topology =
        super::topology_for_view(&qc_topology, height, view, mode_tag, prf_seed);
    let valid_signers = actor.qc_signers_for_votes(
        Phase::Commit,
        block_hash,
        height,
        view,
        epoch,
        &qc_signature_topology,
    );
    assert_eq!(
        valid_signers.len(),
        vote_count,
        "expected only the non-quorum votes to validate"
    );
    assert!(
        !block.is_empty(),
        "test expects heartbeat BlockCreated to be non-empty"
    );

    actor
        .handle_block_created(
            super::message::BlockCreated {
                block,
                frontier: None,
            },
            None,
        )
        .expect("handle BlockCreated");

    assert!(
        actor.pending.pending_blocks.contains_key(&block_hash),
        "BlockCreated should store the pending block without commit quorum"
    );
    let qc_key = (
        Phase::Commit,
        block_hash,
        height,
        view,
        epoch,
        crate::sumeragi::consensus::default_chain_order_hash(),
        0,
    );
    assert!(
        actor.qc_cache.get(&qc_key).is_none(),
        "QC should not be cached without commit quorum"
    );

    harness.shutdown.send();
}

