#[tokio::test(flavor = "current_thread")]
async fn pending_block_hydration_invalidates_mismatched_root_and_clears_deferrals() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.rbc.chunk_max_bytes = 1024;
    let mut harness = test_actor_harness_with_config(1, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let committed_height = actor.state.view().height() as u64;
    let height = committed_height.saturating_add(1);
    let view = 0u64;
    let roster = actor.effective_commit_topology();
    assert!(!roster.is_empty(), "commit roster must not be empty");
    let (block_header, leader_signature) =
        rbc_header_and_signature(actor, &roster, height, view, &harness.key_pairs);
    let block = SignedBlock::presigned(leader_signature, block_header, Vec::new());
    let block_hash = block.hash();
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block.clone(), payload_hash, height, view),
    );

    let epoch = actor.epoch_for_height(height);
    let seeded = Actor::build_rbc_session_from_payload(
        &payload_bytes,
        payload_hash,
        actor.config.rbc.chunk_max_bytes,
        epoch,
    )
    .expect("rbc session");
    let expected_root = seeded.chunk_root().expect("chunk root");
    let mut mismatched_root_bytes = *expected_root.as_ref();
    mismatched_root_bytes[0] ^= 0xFF;
    let mismatched_root = Hash::prehashed(mismatched_root_bytes);
    let init_session = RbcSession::new(
        seeded.total_chunks(),
        Some(payload_hash),
        Some(mismatched_root),
        Some(
            seeded
                .expected_chunk_digests
                .clone()
                .expect("chunk digests"),
        ),
        epoch,
    )
    .expect("init session");

    let key = Actor::session_key(&block_hash, height, view);
    actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert(key, init_session);
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);
    let dedup_keys = insert_pending_rbc_stash_with_dedup(actor, key, 0xD1);
    let now = Instant::now();
    actor.subsystems.da_rbc.rbc.ready_deferral.insert(
        key,
        super::RbcReadyDeferral {
            last_attempt: now,
            reason: super::RbcReadyDeferralReason::MissingPayload,
            ready_count: 0,
            required_ready: 1,
            received_chunks: 0,
            total_chunks: seeded.total_chunks(),
        },
    );
    actor.subsystems.da_rbc.rbc.deliver_deferral.insert(
        key,
        super::RbcDeliverDeferral {
            last_attempt: now,
            ready_count: 0,
            received_chunks: 0,
            total_chunks: seeded.total_chunks(),
        },
    );

    let hydrated = actor
        .maybe_hydrate_rbc_session_from_local_payload(key, None)
        .expect("hydrate");
    assert!(
        hydrated,
        "pending payload should reach the mismatched session"
    );
    let session = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert!(session.is_invalid(), "mismatched hydrated root is terminal");
    assert!(
        !actor.subsystems.da_rbc.rbc.pending.contains_key(&key),
        "terminal hydration mismatch should clear pending RBC stash"
    );
    assert_block_payload_dedup_keys_absent(
        actor,
        &dedup_keys,
        "terminal hydration mismatch should release pending RBC dedup",
    );
    assert!(
        !actor
            .subsystems
            .da_rbc
            .rbc
            .ready_deferral
            .contains_key(&key),
        "terminal hydration mismatch should clear READY deferral bookkeeping"
    );
    assert!(
        !actor
            .subsystems
            .da_rbc
            .rbc
            .deliver_deferral
            .contains_key(&key),
        "terminal hydration mismatch should clear DELIVER deferral bookkeeping"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn pending_block_hydrates_rbc_session_for_init() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.rbc.chunk_max_bytes = 1024;
    let mut harness = test_actor_harness_with_config(1, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let committed_height = actor.state.view().height() as u64;
    let height = committed_height.saturating_add(1);
    let view = 0u64;
    let roster = actor.effective_commit_topology();
    assert!(!roster.is_empty(), "commit roster must not be empty");
    let (block_header, leader_signature) =
        rbc_header_and_signature(actor, &roster, height, view, &harness.key_pairs);
    let block = SignedBlock::presigned(leader_signature, block_header, Vec::new());
    let block_hash = block.hash();
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block.clone(), payload_hash, height, view),
    );

    let epoch = actor.epoch_for_height(height);
    let seeded = Actor::build_rbc_session_from_payload(
        &payload_bytes,
        payload_hash,
        actor.config.rbc.chunk_max_bytes,
        epoch,
    )
    .expect("rbc session");
    let expected_root = seeded.chunk_root().expect("chunk root");
    let init_session = RbcSession::new(
        seeded.total_chunks(),
        Some(payload_hash),
        Some(expected_root),
        Some(
            seeded
                .expected_chunk_digests
                .clone()
                .expect("chunk digests"),
        ),
        epoch,
    )
    .expect("init session");

    let key = Actor::session_key(&block_hash, height, view);
    actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert(key, init_session);

    let hydrated = actor
        .maybe_hydrate_rbc_session_from_local_payload(key, None)
        .expect("hydrate");
    assert!(hydrated, "pending payload should hydrate the RBC session");
    let session = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert_eq!(
        session.received_chunks(),
        session.total_chunks(),
        "pending payload should hydrate the missing chunks"
    );
    assert!(!session.is_invalid(), "hydrated session should stay valid");

    harness.shutdown.send();
}

async fn assert_rbc_init_missing_payload_arms_frontier_body_repair(
    existing_session: bool,
    view: u64,
) {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.rbc.chunk_max_bytes = 32;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);

    let committed_height = actor.state.view().height() as u64;
    let height = committed_height.saturating_add(1);
    let roster = actor.effective_commit_topology();
    assert!(!roster.is_empty(), "commit roster must not be empty");
    let (block, init, _payload_hash) =
        rbc_init_with_block(actor, &roster, height, view, &harness.key_pairs);
    let key = Actor::session_key(&block.hash(), height, view);
    assert!(
        init.total_chunks > 1,
        "test requires a multi-chunk RBC session so INIT metadata alone stays advisory"
    );
    assert!(
        !actor.block_known_locally(key.0),
        "test precondition: block must not be locally available"
    );

    if existing_session {
        let session =
            RbcSession::new(init.total_chunks, None, None, None, init.epoch).expect("seed session");
        actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    }

    let _ = take_background_log(&background_log);
    actor.handle_rbc_init(init, None).expect("rbc init");

    assert!(
        !actor.pending.missing_block_requests.contains_key(&key.0),
        "frontier INIT payload gaps must stay out of generic missing-block recovery"
    );
    let frontier_slot = actor
        .frontier_slot
        .as_ref()
        .expect("frontier INIT payload gaps should arm exact body repair");
    assert_eq!(frontier_slot.block_hash, key.0);
    assert_eq!(frontier_slot.height, height);
    assert_eq!(frontier_slot.view, view);
    assert!(
        frontier_slot.exact_fetch_armed,
        "frontier INIT payload gaps must arm exact body repair"
    );
    assert!(
        !frontier_slot.block_created_seen,
        "INIT metadata alone must not become authoritative BlockCreated ownership"
    );
    assert!(
        !frontier_slot.body_present(),
        "frontier INIT payload gaps must still treat the body as missing"
    );
    assert!(
        !actor
            .subsystems
            .da_rbc
            .rbc
            .ready_deferral
            .contains_key(&key),
        "INIT without chunks should not arm the missing-payload READY fallback before the first chunk is processed"
    );
    let session = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session should remain cached after INIT");
    assert_eq!(
        session.received_chunks(),
        0,
        "INIT without local payload should still wait for RBC chunks"
    );
    assert!(
        session.block_header.is_some(),
        "INIT should cache the block header"
    );
    assert!(
        session.leader_signature.is_some(),
        "INIT should cache the leader signature"
    );
    assert!(
        !actor.rbc_session_needs_block_created_recovery(key),
        "INIT metadata should be sufficient to rebuild the signed block after delivery"
    );
    assert!(
        take_background_log(&background_log)
            .into_iter()
            .all(|entry| {
                entry.msg_kind != Some("FetchPendingBlock")
                    && entry.msg_kind != Some("FetchBlockBody")
            }),
        "frontier INIT payload gaps should arm exact repair first and wait out ingress grace before fetching"
    );

    harness.shutdown.send();
}

