#[tokio::test(flavor = "current_thread")]
async fn frontier_block_created_from_proposal_rejects_noncanonical_payload_hint_even_with_roster_hint()
 {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let genesis_hash = seed_genesis_block_for_state(&actor.state);
    let height = actor.committed_height_snapshot().saturating_add(1);
    let view = 0u64;
    let block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(genesis_hash));
    let payload = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload);
    let highest_qc = QcHeaderRef {
        height: height.saturating_sub(1),
        view,
        epoch: actor.epoch_for_height(height.saturating_sub(1)),
        subject_block_hash: genesis_hash,
        phase: Phase::Commit,
    };
    let roster = actor.effective_commit_topology();
    let mut topology = super::network_topology::Topology::new(roster.clone());
    let leader_index = actor
        .leader_index_for(&mut topology, height, view)
        .expect("leader index");
    let leader_index_u64 = u64::try_from(leader_index).expect("leader index fits u64");
    let proposal = Actor::build_consensus_proposal(
        &block,
        payload_hash,
        highest_qc,
        0,
        view,
        actor.epoch_for_height(height),
    );
    let created = actor
        .frontier_block_created_from_proposal_with_roster_hint_and_payload(
            &block,
            &proposal,
            Some(roster.as_slice()),
            Some((payload.as_slice(), payload_hash)),
        )
        .expect("canonical payload hint should still build frontier BlockCreated metadata");
    let frontier = created.frontier.expect("frontier metadata");
    assert_eq!(
        frontier.leader_signature.index(),
        leader_index_u64,
        "frontier metadata should carry the roster-derived leader signature"
    );
    let leader_peer = topology
        .as_ref()
        .get(leader_index)
        .expect("leader peer should exist");
    assert!(
        frontier
            .leader_signature
            .signature()
            .verify_hash(leader_peer.public_key(), block.header().hash())
            .is_ok(),
        "frontier metadata should carry a signature verified by the roster-derived leader"
    );

    let wrong_key = checked_keypair_with_algorithm(Algorithm::Ed25519);
    let wrong_signature = checked_signature_of_hash(wrong_key.private_key(), block.header().hash());
    let mut forged_leader_signature_block = block.clone();
    forged_leader_signature_block
        .replace_signatures(BTreeSet::from([BlockSignature::new(
            leader_index_u64,
            wrong_signature,
        )]))
        .expect("replace signatures");
    assert!(
        actor
            .frontier_block_created_from_proposal_with_roster_hint_and_payload(
                &forged_leader_signature_block,
                &proposal,
                Some(roster.as_slice()),
                Some((payload.as_slice(), payload_hash)),
            )
            .is_none(),
        "roster-hint fallback must reject leader-indexed signatures from the wrong signer"
    );

    let wrong_payload = b"non-canonical proposal payload".to_vec();
    let wrong_payload_hash = Hash::new(&wrong_payload);
    let wrong_proposal = Actor::build_consensus_proposal(
        &block,
        wrong_payload_hash,
        highest_qc,
        0,
        view,
        actor.epoch_for_height(height),
    );
    assert!(
        actor
            .frontier_block_created_from_proposal_with_roster_hint_and_payload(
                &block,
                &wrong_proposal,
                Some(roster.as_slice()),
                Some((wrong_payload.as_slice(), wrong_payload_hash)),
            )
            .is_none(),
        "roster-hint fallback must not build RBC metadata from non-canonical block payload bytes"
    );

    assert!(
        actor
            .frontier_block_created_from_proposal_with_roster_hint_and_payload(
                &block,
                &wrong_proposal,
                Some(roster.as_slice()),
                Some((payload.as_slice(), wrong_payload_hash)),
            )
            .is_none(),
        "roster-hint fallback must not build RBC metadata when carried bytes and payload hash mismatch"
    );

    harness.shutdown.send();
}

