#[tokio::test(flavor = "current_thread")]
async fn validation_fast_finality_inline_transaction_cap_is_configurable() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.da.enabled = true;
    consensus_cfg
        .worker
        .fast_finality_inline_validation_max_transactions = 17;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let parent_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(0)
        .saturating_add(1);
    let view = 0_u64;
    let txs = (0..17)
        .map(|idx| sample_log_transaction_with_message_len(idx + 1))
        .collect();
    let block = block_with_txs(height, view, Some(parent_hash), txs);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    actor.note_proposal_seen(height, view, payload_hash);
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );

    let local_height = u64::try_from(actor.state.view().height()).unwrap_or(0);
    let pending = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending block retained");
    assert_eq!(
        actor.fast_finality_inline_validation_tx_count(block_hash, pending, local_height, None),
        Some(17),
        "configured cap should allow a 17-transaction fast-finality block to validate inline"
    );

    actor
        .config
        .worker
        .fast_finality_inline_validation_max_transactions = 16;
    let pending = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending block retained");
    assert_eq!(
        actor.fast_finality_inline_validation_tx_count(block_hash, pending, local_height, None),
        None,
        "lowering the configured cap should keep the same block on the worker path"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn validation_allows_near_tip_delivered_rbc_without_proposal_evidence() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.da.enabled = true;
    consensus_cfg.worker.validation_worker_threads = 0;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let parent_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(0)
        .saturating_add(1);
    let view = 0_u64;
    let block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(parent_hash));
    let block_hash = block.hash();
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );

    let mut session = Actor::build_rbc_session_from_payload(
        &payload_bytes,
        payload_hash,
        actor.config.rbc.chunk_max_bytes,
        actor.epoch_for_height(height),
    )
    .expect("session");
    assert_eq!(session.total_chunks(), 1, "test expects a single RBC chunk");
    session.ingest_chunk(0, payload_bytes, None);
    assert_eq!(
        session.received_chunks(),
        session.total_chunks(),
        "full payload chunk should be accepted"
    );
    session.test_set_delivered(true);
    actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert((block_hash, height, view), session);

    let commit_topology = actor.effective_commit_topology();
    let outcome = actor.validate_pending_block_for_voting_inline(block_hash, &commit_topology);
    assert!(
        matches!(outcome, ValidationGateOutcome::Valid),
        "near-tip RBC DELIVER should unblock inline validation without proposal evidence"
    );
    assert!(
        actor.block_known_for_lock(block_hash),
        "successful inline validation should make the delivered block available for QC handling"
    );

    harness.shutdown.send();
}

