#[tokio::test(flavor = "current_thread")]
async fn commit_qc_keeps_fresh_inflight_validation_deferred_past_inline_fallback() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let parent_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(0)
        .saturating_add(1);
    let view = 0_u64;
    let block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(parent_hash));
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );

    let (work_tx, work_rx) = mpsc::sync_channel::<super::validation::ValidationWork>(1);
    let (_result_tx, result_rx) = mpsc::sync_channel::<super::validation::ValidationResult>(1);
    actor.subsystems.validation.work_txs = vec![work_tx];
    actor.subsystems.validation.result_rx = Some(result_rx);
    let inline_fallback_timeout = actor.commit_validation_inline_fallback_timeout();
    actor.subsystems.validation.inflight.insert(
        block_hash,
        super::ValidationInFlight {
            id: 23,
            started_at: Instant::now()
                - inline_fallback_timeout.saturating_add(Duration::from_millis(1)),
            frontier_generation: None,
        },
    );

    let commit_topology = actor.effective_commit_topology();
    let qc = commit_qc_for_block(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        view,
        &commit_topology,
    );
    actor.qc_cache.insert(
        (
            Phase::Commit,
            block_hash,
            height,
            view,
            qc.epoch,
            crate::sumeragi::consensus::default_chain_order_hash(),
            0,
        ),
        qc.clone(),
    );

    assert!(
        !actor.maybe_validate_pending_for_commit_qc(&qc, &commit_topology),
        "fresh inflight validation should stay deferred beyond the old inline fallback"
    );
    assert!(
        matches!(work_rx.try_recv(), Err(mpsc::TryRecvError::Empty)),
        "commit QC should not enqueue duplicate validation while fresh inflight exists"
    );
    assert!(
        actor
            .subsystems
            .validation
            .inflight
            .contains_key(&block_hash),
        "fresh inflight validation should not be superseded"
    );
    let pending = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained");
    assert_eq!(pending.validation_status, ValidationStatus::Pending);
    assert!(pending.parent_state_root.is_none());
    assert!(pending.post_state_root.is_none());

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_qc_redrives_stale_inflight_validation_through_vnext() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let parent_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(0)
        .saturating_add(1);
    let view = 0_u64;
    let block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(parent_hash));
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );
    actor.note_proposal_seen(height, view, payload_hash);

    let (work_tx, work_rx) = mpsc::sync_channel::<super::validation::ValidationWork>(1);
    let (_result_tx, result_rx) = mpsc::sync_channel::<super::validation::ValidationResult>(1);
    actor.subsystems.validation.work_txs = vec![work_tx];
    actor.subsystems.validation.result_rx = Some(result_rx);
    actor.subsystems.validation.inflight.insert(
        block_hash,
        super::ValidationInFlight {
            id: 24,
            started_at: Instant::now(),
            frontier_generation: Some(1),
        },
    );

    let commit_topology = actor.effective_commit_topology();
    let qc = commit_qc_for_block(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        view,
        &commit_topology,
    );
    actor.qc_cache.insert(
        (
            Phase::Commit,
            block_hash,
            height,
            view,
            qc.epoch,
            crate::sumeragi::consensus::default_chain_order_hash(),
            0,
        ),
        qc.clone(),
    );

    assert!(
        !actor.maybe_validate_pending_for_commit_qc(&qc, &commit_topology),
        "stale inflight validation should redrive through vNext and remain deferred"
    );
    let queued_work = work_rx
        .try_recv()
        .expect("stale commit-QC validation should enqueue replacement vNext work");
    assert_eq!(queued_work.hash, block_hash);
    assert!(
        actor
            .subsystems
            .validation
            .inflight
            .contains_key(&block_hash),
        "redriven commit-QC validation should install a fresh inflight marker"
    );
    assert!(
        actor
            .subsystems
            .validation
            .vnext_inflight
            .contains_key(&block_hash),
        "redriven commit-QC validation should be owned by vNext"
    );
    let pending = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained while redriven validation runs");
    assert_eq!(pending.validation_status, ValidationStatus::Pending);
    assert!(pending.parent_state_root.is_none());
    assert!(pending.post_state_root.is_none());

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_qc_redrives_stalled_vnext_owned_validation_through_vnext() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let parent_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(0)
        .saturating_add(1);
    let view = 0_u64;
    let block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(parent_hash));
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );
    actor.note_proposal_seen(height, view, payload_hash);

    let (work_tx, work_rx) = mpsc::sync_channel::<super::validation::ValidationWork>(1);
    let (_result_tx, result_rx) = mpsc::sync_channel::<super::validation::ValidationResult>(1);
    actor.subsystems.validation.work_txs = vec![work_tx];
    actor.subsystems.validation.result_rx = Some(result_rx);
    assert!(
        actor.drive_vnext_validation_for_pending(block_hash, height, view, payload_hash),
        "vNext validation should own the pending block"
    );
    let first_work = work_rx
        .try_recv()
        .expect("vNext validation should queue initial worker work");
    let stall_timeout = actor.validation_worker_stall_timeout();
    {
        let inflight = actor
            .subsystems
            .validation
            .inflight
            .get_mut(&block_hash)
            .expect("vNext validation should install an inflight marker");
        assert_eq!(first_work.id, inflight.id);
        inflight.started_at = Instant::now() - stall_timeout - Duration::from_millis(1);
    }

    let commit_topology = actor.effective_commit_topology();
    let qc = commit_qc_for_block(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        view,
        &commit_topology,
    );
    actor.qc_cache.insert(
        (
            Phase::Commit,
            block_hash,
            height,
            view,
            qc.epoch,
            crate::sumeragi::consensus::default_chain_order_hash(),
            0,
        ),
        qc.clone(),
    );

    assert!(
        !actor.maybe_validate_pending_for_commit_qc(&qc, &commit_topology),
        "stalled vNext-owned validation should redrive through vNext and remain deferred"
    );
    let replacement = work_rx
        .try_recv()
        .expect("stalled vNext-owned commit-QC validation should enqueue replacement work");
    assert_eq!(replacement.hash, block_hash);
    assert_ne!(
        replacement.id, first_work.id,
        "commit-QC redrive should allocate a new vNext worker id"
    );
    assert_eq!(
        actor
            .subsystems
            .validation
            .inflight
            .get(&block_hash)
            .map(|inflight| inflight.id),
        Some(replacement.id),
        "redriven commit-QC validation should install a fresh inflight marker"
    );
    assert!(
        actor
            .subsystems
            .validation
            .vnext_inflight
            .contains_key(&block_hash),
        "redriven commit-QC validation should remain vNext-owned"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn validation_dispatches_near_tip_cached_commit_qc_to_workers() {
    let _qc_guard = super::status::qc_status_test_guard();
    let _history_guard = super::status::commit_history_test_guard();
    super::status::reset_commit_certs_for_tests();
    super::status::reset_precommit_signer_history_for_tests();

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let parent_hash = seed_genesis_block_for_state(&actor.state);
    let parent_height = u64::try_from(actor.state.view().height()).unwrap_or(0);
    let parent_epoch = actor.epoch_for_height(parent_height);
    actor.locked_qc = Some(QcHeaderRef {
        phase: Phase::Commit,
        subject_block_hash: parent_hash,
        height: parent_height,
        view: 0,
        epoch: parent_epoch,
    });
    actor.highest_qc = actor.locked_qc;
    super::status::set_locked_qc(parent_height, 0, Some(parent_hash));
    super::status::set_highest_qc(parent_height, 0);
    super::status::set_highest_qc_hash(parent_hash);

    let height = parent_height.saturating_add(1);
    let view = 0_u64;
    let block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(parent_hash));
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block.clone(), payload_hash, height, view),
    );

    let commit_topology = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(commit_topology.clone());
    let mut validation_topology = topology.clone();
    actor
        .leader_index_for(&mut validation_topology, height, view)
        .expect("validation topology should align");
    let mut voting_block = None;
    let worker_roots = super::validate_block_for_voting(
        block,
        &mut validation_topology,
        &actor.common_config.chain,
        &actor.genesis_account,
        actor.state.as_ref(),
        &mut voting_block,
    )
    .expect("worker fixture block should validate")
    .expect("worker fixture block should produce execution roots");
    let required = topology.min_votes_for_commit().max(1);
    let signers: BTreeSet<_> = (0..required)
        .map(|idx| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_bitmap = super::build_signers_bitmap(&signers, commit_topology.len());
    let epoch = actor.epoch_for_height(height);
    let mut qc = qc_with_bitmap_for_actor(
        actor,
        block_hash,
        height,
        view,
        epoch,
        signers_bitmap,
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    qc.parent_state_root = worker_roots.parent_state_root;
    qc.post_state_root = worker_roots.post_state_root;
    resign_qc_for_actor(&mut qc, actor, &harness.key_pairs);
    actor.cache_block_sync_qc_for_unknown_block(
        qc,
        block_hash,
        height,
        view,
        &topology,
        &signers,
        false,
        ConsensusMode::Permissioned,
        None,
        PERMISSIONED_TAG,
        None,
    );

    let (work_tx, work_rx) = mpsc::sync_channel::<super::validation::ValidationWork>(1);
    let (_result_tx, result_rx) = mpsc::sync_channel::<super::validation::ValidationResult>(1);
    actor.subsystems.validation.work_txs = vec![work_tx];
    actor.subsystems.validation.result_rx = Some(result_rx);
    actor.subsystems.validation.inflight.clear();

    let outcome = actor.validate_pending_block_for_voting(block_hash, &commit_topology);
    assert!(
        matches!(outcome, ValidationGateOutcome::Deferred),
        "cached commit-QC pending blocks should wait for worker validation when the worker channel is healthy"
    );
    let queued_work = work_rx
        .try_recv()
        .expect("cached commit-QC pending blocks should enqueue worker validation");
    assert_eq!(queued_work.hash, block_hash);
    assert_eq!(queued_work.height, height);
    assert_eq!(queued_work.view, view);
    assert!(
        actor
            .subsystems
            .validation
            .inflight
            .contains_key(&block_hash),
        "worker-dispatched cached commit-QC validation should stay inflight until the worker result arrives"
    );
    assert_eq!(
        actor.locked_qc.map(|qc| qc.height),
        Some(parent_height),
        "cached commit QC should not replay before worker validation succeeds"
    );
    assert_eq!(
        actor.highest_qc.map(|qc| qc.height),
        Some(parent_height),
        "highest QC should not advance before worker validation succeeds"
    );

    harness.shutdown.send();
    super::status::reset_commit_certs_for_tests();
    super::status::reset_precommit_signer_history_for_tests();
}

