#[derive(Debug, Clone, Copy)]
enum QcSignerBitmapErrorKind {
    Length,
    OutOfBounds,
}

#[derive(Debug, Clone, Copy)]
struct QcSignerBitmapCase {
    name: &'static str,
    voting_len: usize,
    observer_count: usize,
    bitmap_len: usize,
    signer_indices: &'static [usize],
    expected_parsed: bool,
    expected_accepted: bool,
    expected_voting_signers: usize,
    expected_present_signers: usize,
    expected_error: Option<QcSignerBitmapErrorKind>,
}

fn bitmap_for_indices(len: usize, indices: &[usize]) -> Vec<u8> {
    let mut bitmap = vec![0u8; len];
    for idx in indices {
        let byte_idx = idx / 8;
        let bit = idx % 8;
        if let Some(byte) = bitmap.get_mut(byte_idx) {
            *byte |= 1u8 << bit;
        }
    }
    bitmap
}

#[test]
fn qc_signer_bitmap_formal_gate_matrix() {
    let cases = [
        QcSignerBitmapCase {
            name: "empty single-node bitmap parses but fails quorum",
            voting_len: 1,
            observer_count: 0,
            bitmap_len: 1,
            signer_indices: &[],
            expected_parsed: true,
            expected_accepted: false,
            expected_voting_signers: 0,
            expected_present_signers: 0,
            expected_error: None,
        },
        QcSignerBitmapCase {
            name: "single-node signer reaches quorum",
            voting_len: 1,
            observer_count: 0,
            bitmap_len: 1,
            signer_indices: &[0],
            expected_parsed: true,
            expected_accepted: true,
            expected_voting_signers: 1,
            expected_present_signers: 1,
            expected_error: None,
        },
        QcSignerBitmapCase {
            name: "four-voter exact quorum",
            voting_len: 4,
            observer_count: 0,
            bitmap_len: 1,
            signer_indices: &[0, 1, 2],
            expected_parsed: true,
            expected_accepted: true,
            expected_voting_signers: 3,
            expected_present_signers: 3,
            expected_error: None,
        },
        QcSignerBitmapCase {
            name: "four-voter under quorum",
            voting_len: 4,
            observer_count: 0,
            bitmap_len: 1,
            signer_indices: &[0, 1],
            expected_parsed: true,
            expected_accepted: false,
            expected_voting_signers: 2,
            expected_present_signers: 2,
            expected_error: None,
        },
        QcSignerBitmapCase {
            name: "observer padding does not satisfy quorum",
            voting_len: 4,
            observer_count: 3,
            bitmap_len: 1,
            signer_indices: &[0, 1, 4],
            expected_parsed: true,
            expected_accepted: false,
            expected_voting_signers: 2,
            expected_present_signers: 3,
            expected_error: None,
        },
        QcSignerBitmapCase {
            name: "observer bit is present but not counted",
            voting_len: 4,
            observer_count: 3,
            bitmap_len: 1,
            signer_indices: &[0, 1, 2, 4],
            expected_parsed: true,
            expected_accepted: true,
            expected_voting_signers: 3,
            expected_present_signers: 4,
            expected_error: None,
        },
        QcSignerBitmapCase {
            name: "short bitmap rejected",
            voting_len: 4,
            observer_count: 3,
            bitmap_len: 0,
            signer_indices: &[0, 1, 2],
            expected_parsed: false,
            expected_accepted: false,
            expected_voting_signers: 0,
            expected_present_signers: 0,
            expected_error: Some(QcSignerBitmapErrorKind::Length),
        },
        QcSignerBitmapCase {
            name: "long bitmap rejected",
            voting_len: 4,
            observer_count: 3,
            bitmap_len: 2,
            signer_indices: &[0, 1, 2],
            expected_parsed: false,
            expected_accepted: false,
            expected_voting_signers: 0,
            expected_present_signers: 0,
            expected_error: Some(QcSignerBitmapErrorKind::Length),
        },
        QcSignerBitmapCase {
            name: "padding bit outside topology rejected",
            voting_len: 4,
            observer_count: 3,
            bitmap_len: 1,
            signer_indices: &[0, 1, 2, 7],
            expected_parsed: false,
            expected_accepted: false,
            expected_voting_signers: 0,
            expected_present_signers: 0,
            expected_error: Some(QcSignerBitmapErrorKind::OutOfBounds),
        },
        QcSignerBitmapCase {
            name: "two-byte voting quorum parses",
            voting_len: 7,
            observer_count: 3,
            bitmap_len: 2,
            signer_indices: &[0, 1, 2, 3, 4],
            expected_parsed: true,
            expected_accepted: true,
            expected_voting_signers: 5,
            expected_present_signers: 5,
            expected_error: None,
        },
        QcSignerBitmapCase {
            name: "two-byte observer cannot complete quorum",
            voting_len: 7,
            observer_count: 3,
            bitmap_len: 2,
            signer_indices: &[0, 1, 2, 3, 8],
            expected_parsed: true,
            expected_accepted: false,
            expected_voting_signers: 4,
            expected_present_signers: 5,
            expected_error: None,
        },
    ];

    for case in cases {
        let topology_len = case.voting_len + case.observer_count;
        let expected_bitmap_len = topology_len.div_ceil(8);
        let bitmap = bitmap_for_indices(case.bitmap_len, case.signer_indices);
        let parsed = super::parse_signers_bitmap(&bitmap, topology_len, case.voting_len);
        assert_eq!(
            bitmap.len() == expected_bitmap_len && case.expected_error.is_none(),
            case.expected_parsed,
            "model parsed expectation mismatch for {}",
            case.name
        );
        match (parsed, case.expected_error) {
            (Ok(parsed), None) => {
                let required = super::network_topology::commit_quorum_from_len(case.voting_len);
                let accepted = parsed.voting.len() >= required;
                assert_eq!(accepted, case.expected_accepted, "{}", case.name);
                assert_eq!(
                    parsed.voting.len(),
                    case.expected_voting_signers,
                    "{}",
                    case.name
                );
                assert_eq!(
                    parsed.present.len(),
                    case.expected_present_signers,
                    "{}",
                    case.name
                );
            }
            (
                Err(super::QcValidationError::BitmapLengthMismatch { expected, actual }),
                Some(QcSignerBitmapErrorKind::Length),
            ) => {
                assert_eq!(expected, expected_bitmap_len, "{}", case.name);
                assert_eq!(actual, case.bitmap_len, "{}", case.name);
                assert!(!case.expected_accepted, "{}", case.name);
            }
            (
                Err(super::QcValidationError::SignerOutOfBounds {
                    signer,
                    topology_len: actual_topology_len,
                }),
                Some(QcSignerBitmapErrorKind::OutOfBounds),
            ) => {
                assert!(signer >= topology_len, "{}", case.name);
                assert_eq!(actual_topology_len, topology_len, "{}", case.name);
                assert!(!case.expected_accepted, "{}", case.name);
            }
            (result, expected_error) => panic!(
                "unexpected parser result for {}: result={result:?} expected_error={expected_error:?}",
                case.name
            ),
        }
    }
}

#[test]
fn voting_signer_count_includes_full_roster() {
    // Roster len 4 → voting_len 4 → set-B signers count toward quorum.
    let voting_len = 4;
    let signers: BTreeSet<ValidatorIndex> = [0u32, 1u32, 3u32].into_iter().collect();
    assert_eq!(super::voting_signer_count(&signers, voting_len), 3);

    let full: BTreeSet<ValidatorIndex> = [0u32, 1u32, 2u32, 3u32].into_iter().collect();
    assert_eq!(super::voting_signer_count(&full, voting_len), 4);
}

#[test]
fn voting_quorum_accepts_any_three_signers() {
    let roster_len = 4;
    let required = super::network_topology::commit_quorum_from_len(roster_len);
    let two_signers: BTreeSet<ValidatorIndex> = [0u32, 1u32].into_iter().collect();
    assert!(
        super::voting_signer_count(&two_signers, roster_len) < required,
        "two signatures must not reach quorum for N=4"
    );

    let any_three: BTreeSet<ValidatorIndex> = [0u32, 1u32, 3u32].into_iter().collect();
    assert!(
        super::voting_signer_count(&any_three, roster_len) >= required,
        "set-B signatures should satisfy quorum"
    );

    let full_roster: BTreeSet<ValidatorIndex> = [0u32, 1u32, 2u32, 3u32].into_iter().collect();
    assert!(
        super::voting_signer_count(&full_roster, roster_len) >= required,
        "full roster should satisfy quorum for a four-peer topology"
    );
}

#[test]
fn validate_qc_against_votes_accepts_any_quorum_signers() {
    let chain: ChainId = "qc-any-quorum".parse().expect("chain id parses");
    let peer_keys: Vec<_> = (0..4).map(|_| checked_bls_keypair()).collect();
    let peers: Vec<PeerId> = peer_keys
        .iter()
        .map(|kp| PeerId::new(kp.public_key().clone()))
        .collect();
    let topology = super::network_topology::Topology::new(peers);
    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x5F; Hash::LENGTH]));
    // Leader(0) + validator(1) + set-B validator(3); proxy tail(2) missing but quorum holds.
    let qc = qc_with_bitmap(
        &chain,
        block_hash,
        1,
        0,
        0,
        vec![0b0000_1011],
        crate::sumeragi::consensus::Phase::Commit,
        &topology,
        &peer_keys,
    );

    let mut vote_log = BTreeMap::new();
    for signer in [0u32, 1u32, 3u32] {
        let mut vote = crate::sumeragi::consensus::Vote {
            phase: crate::sumeragi::consensus::Phase::Commit,
            block_hash,
            parent_state_root: iroha_crypto::Hash::prehashed([0u8; iroha_crypto::Hash::LENGTH]),
            post_state_root: iroha_crypto::Hash::prehashed([0u8; iroha_crypto::Hash::LENGTH]),
            height: qc.height,
            view: qc.view,
            epoch: qc.epoch,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: None,
            signer,
            bls_sig: Vec::new(),
        };
        sign_vote_for_canonical_signer(&mut vote, &chain, &topology, &peer_keys);
        vote_log.insert(vote_log_key_for_vote(&vote), vote);
    }

    let outcome = validate_qc_against_votes_with_keys(
        &vote_log,
        &qc,
        &topology,
        &peer_keys,
        &chain,
        ConsensusMode::Permissioned,
        None,
        super::PERMISSIONED_TAG,
        None,
    )
    .expect("QC should accept any quorum signers");
    assert_eq!(outcome.signers.len(), 3);
    assert_eq!(outcome.present_signers, 3);
    assert_eq!(outcome.missing_votes, 0);
    assert!(
        outcome
            .signers
            .contains(&ValidatorIndex::try_from(3u32).expect("validator index parses"))
    );
}

