#[test]
fn evaluate_rbc_deliver_outcome_marks_zero_total_invalid_payload() {
    let key = session_key();
    let payload_hash = Hash::new(b"payload");
    let mut session = RbcSession::test_new(0, Some(payload_hash), None, 0);
    let _ = session.record_ready(0, vec![0xAA]);
    let deliver = crate::sumeragi::consensus::RbcDeliver {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch: 0,
        roster_hash: Hash::prehashed([0x12; Hash::LENGTH]),
        chunk_root: Hash::new(b"chunk-root"),
        sender: 0,
        signature: vec![0xBB],
        ready_signatures: Vec::new(),
    };

    let (
        ignored,
        first_deliver,
        delivered_bytes,
        invalidate,
        chunk_root_mismatch,
        defer_reason,
        defer_kind,
        drop_kind,
    ) = Actor::evaluate_rbc_deliver_outcome(1, &mut session, key, &deliver, None, false);

    assert!(ignored);
    assert!(!first_deliver);
    assert!(delivered_bytes.is_none());
    assert!(invalidate);
    assert!(!chunk_root_mismatch);
    assert!(defer_reason.is_none());
    assert!(defer_kind.is_none());
    assert_eq!(
        drop_kind,
        Some(super::status::ConsensusMessageReason::InvalidPayload)
    );
    assert!(session.is_invalid());
    assert!(!session.delivered);
}

#[test]
fn evaluate_rbc_deliver_outcome_marks_overcounted_invalid_payload() {
    let key = session_key();
    let payload_hash = Hash::new(b"payload");
    let mut session = RbcSession::test_new(1, Some(payload_hash), None, 0);
    let _ = session.record_ready(0, vec![0xAA]);
    session.test_set_received_chunks(2);
    let deliver = crate::sumeragi::consensus::RbcDeliver {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch: 0,
        roster_hash: Hash::prehashed([0x12; Hash::LENGTH]),
        chunk_root: Hash::new(b"chunk-root"),
        sender: 0,
        signature: vec![0xBB],
        ready_signatures: Vec::new(),
    };

    let (
        ignored,
        first_deliver,
        delivered_bytes,
        invalidate,
        chunk_root_mismatch,
        defer_reason,
        defer_kind,
        drop_kind,
    ) = Actor::evaluate_rbc_deliver_outcome(1, &mut session, key, &deliver, None, false);

    assert!(ignored);
    assert!(!first_deliver);
    assert!(delivered_bytes.is_none());
    assert!(invalidate);
    assert!(!chunk_root_mismatch);
    assert!(defer_reason.is_none());
    assert_eq!(
        defer_kind, None,
        "malformed over-counted sessions should be dropped, not deferred"
    );
    assert_eq!(
        drop_kind,
        Some(super::status::ConsensusMessageReason::InvalidPayload)
    );
    assert!(session.is_invalid());
    assert!(!session.delivered);

    let mut da_policy_session = RbcSession::test_new(1, Some(payload_hash), None, 0);
    let _ = da_policy_session.record_ready(0, vec![0xCC]);
    da_policy_session.test_set_received_chunks(2);
    let (_, _, _, invalidate, _, defer_reason, defer_kind, drop_kind) =
        Actor::evaluate_rbc_deliver_outcome(1, &mut da_policy_session, key, &deliver, None, true);
    assert!(invalidate);
    assert!(defer_reason.is_none());
    assert_eq!(defer_kind, None);
    assert_eq!(
        drop_kind,
        Some(super::status::ConsensusMessageReason::InvalidPayload),
        "DA missing-chunk policy must still drop malformed over-counted sessions"
    );
    assert!(da_policy_session.is_invalid());
    assert!(!da_policy_session.delivered);
}

#[test]
fn evaluate_deliver_acceptance_rejects_mismatched_root() {
    let chunk = b"bytes".to_vec();
    let payload_hash = Hash::new(&chunk);
    let mut session = RbcSession::test_new(1, Some(payload_hash), None, 0);
    session.test_note_chunk(0, chunk, 0);
    // Inject an incorrect expected root to force a mismatch.
    session.expected_chunk_root = Some(Hash::new(b"wrong-root"));
    let _ = session.record_ready(0, vec![0xBB]);

    let decision = super::rbc::evaluate_deliver_acceptance(&session, 1);
    assert_eq!(decision, super::rbc::DeliverAcceptance::InvalidChunkRoot);
}

#[tokio::test(flavor = "current_thread")]
async fn rbc_deliver_deferral_throttles_until_cooldown_or_progress() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let key = session_key();
    let now = Instant::now();
    let cooldown = Duration::from_secs(5);

    assert!(actor.should_emit_rbc_deliver_deferral(key, now, 0, 0, 1, cooldown));
    assert!(
        !actor.should_emit_rbc_deliver_deferral(
            key,
            now + Duration::from_secs(1),
            0,
            0,
            1,
            cooldown
        ),
        "deferral should throttle until cooldown expires"
    );
    assert!(
        actor.should_emit_rbc_deliver_deferral(
            key,
            now + Duration::from_secs(1),
            1,
            0,
            1,
            cooldown
        ),
        "deferral should emit after READY quorum progresses"
    );
    assert!(
        actor.should_emit_rbc_deliver_deferral(
            key,
            now + Duration::from_secs(1) + cooldown + Duration::from_millis(1),
            1,
            0,
            1,
            cooldown
        ),
        "deferral should emit after cooldown"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rbc_ready_deferral_throttles_until_cooldown_or_progress() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let key = session_key();
    let now = Instant::now();
    let cooldown = Duration::from_secs(5);
    let reason = super::RbcReadyDeferralReason::CommitRosterMissing;

    assert!(actor.should_emit_rbc_ready_deferral(key, now, reason, 0, 0, 0, 1, cooldown));
    assert!(
        !actor.should_emit_rbc_ready_deferral(
            key,
            now + Duration::from_secs(1),
            reason,
            0,
            0,
            0,
            1,
            cooldown
        ),
        "ready deferral should throttle until cooldown expires"
    );
    assert!(
        actor.should_emit_rbc_ready_deferral(
            key,
            now + Duration::from_secs(1),
            reason,
            1,
            0,
            0,
            1,
            cooldown
        ),
        "ready deferral should emit after READY progress"
    );
    assert!(
        actor.should_emit_rbc_ready_deferral(
            key,
            now + Duration::from_secs(2),
            super::RbcReadyDeferralReason::CommitRosterUnverified,
            1,
            0,
            0,
            1,
            cooldown
        ),
        "ready deferral should emit after reason changes"
    );
    assert!(
        actor.should_emit_rbc_ready_deferral(
            key,
            now + Duration::from_secs(2) + cooldown + Duration::from_millis(1),
            super::RbcReadyDeferralReason::CommitRosterUnverified,
            1,
            0,
            0,
            1,
            cooldown
        ),
        "ready deferral should emit after cooldown"
    );

    harness.shutdown.send();
}

