#[tokio::test(flavor = "current_thread")]
async fn rebroadcast_stalled_rbc_payloads_requests_chunks_for_recovered_exact_frontier_session() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.da.enabled = true;
    consensus_cfg.rbc.chunk_max_bytes = 256;
    consensus_cfg.rbc.rebroadcast_sessions_per_tick = 1;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let height = actor.state.view().height() as u64 + 1;
    let view = 0u64;
    let parent = actor.state.view().latest_block_hash();
    let txs: Vec<_> = (0..16).map(|_| sample_transaction()).collect();
    let block = block_with_txs(height, view, parent, txs);
    let key = Actor::session_key(&block.hash(), height, view);
    let mut session =
        partial_rbc_session_for_block(actor, &block, actor.config.rbc.chunk_max_bytes);
    session.recovered_from_disk = true;

    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);
    let roster = actor.effective_commit_topology();
    assert!(!roster.is_empty(), "commit roster should be non-empty");
    actor.record_rbc_session_roster(key, roster, super::RbcRosterSource::Derived);

    actor
        .maybe_emit_rbc_ready(key)
        .expect("frontier READY deferral should arm exact body repair");
    let slot = actor.frontier_slot.as_ref().expect("frontier slot");
    assert_eq!(slot.block_hash, key.0);
    assert_eq!(slot.height, height);
    assert_eq!(slot.view, view);
    assert!(slot.exact_fetch_armed);
    assert!(!slot.body_present());

    let background_log = attach_background_log(actor);
    let _ = take_background_log(&background_log);

    assert!(
        actor.rebroadcast_stalled_rbc_payloads(Instant::now()),
        "recovered exact-frontier sessions should actively request missing chunks"
    );

    let entries = take_background_log(&background_log);
    assert!(
        entries.iter().any(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("RbcChunkRequest"),
                    ..
                }
            )
        }),
        "exact-frontier restart recovery must request the missing RBC chunks directly"
    );
    assert!(
        entries.iter().all(|entry| {
            !matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    msg_kind: Some("RbcInit" | "RbcChunk" | "RbcChunkCompact"),
                    ..
                }
            )
        }),
        "near-tip recovery should stay off the broad RBC hot loop while requesting chunks"
    );
    assert!(
        actor.subsystems.da_rbc.rbc.chunk_repair.contains_key(&key),
        "direct chunk repair should arm the per-session cooldown"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn maybe_request_missing_rbc_chunks_rejects_mismatched_session_metadata() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    actor.config.rbc.chunk_max_bytes = 32;

    let height = actor.state.view().height() as u64 + 1;
    let view = 0u64;
    let parent = actor.state.view().latest_block_hash();
    let block = block_with_txs(
        height,
        view,
        parent,
        (0..16).map(|_| sample_transaction()).collect(),
    );
    let key = Actor::session_key(&block.hash(), height, view);
    let roster = actor.effective_commit_topology();
    assert!(!roster.is_empty(), "commit roster should be non-empty");
    actor.record_rbc_session_roster(key, roster.clone(), super::RbcRosterSource::Derived);

    let mut session =
        partial_rbc_session_for_block(actor, &block, actor.config.rbc.chunk_max_bytes);
    let other_parent = Some(HashOf::<BlockHeader>::from_untyped_unchecked(
        Hash::prehashed([0xEA; Hash::LENGTH]),
    ));
    let other_block = block_with_txs(
        height,
        view,
        other_parent,
        (0..16).map(|_| sample_transaction()).collect(),
    );
    assert_ne!(other_block.hash(), key.0);
    session.test_set_block_header_and_signature(&other_block);

    let background_log = attach_background_log(actor);
    let _ = take_background_log(&background_log);
    let attempt = actor.maybe_request_missing_rbc_chunks(
        key,
        &session,
        &roster,
        Instant::now(),
        Duration::from_millis(1),
    );

    assert!(
        matches!(attempt, super::RbcRepairAttempt::Requested),
        "mismatched metadata should move to missing-block repair instead of chunk repair"
    );
    let entries = take_background_log(&background_log);
    assert!(
        entries.iter().all(|entry| {
            !matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("RbcChunkRequest"),
                    ..
                }
            )
        }),
        "mismatched metadata must not emit RBC chunk repair requests"
    );
    assert!(
        !actor.subsystems.da_rbc.rbc.chunk_repair.contains_key(&key),
        "mismatched metadata must not arm the chunk repair cooldown"
    );

    harness.shutdown.send();
}

#[test]
fn phase_tracker_on_view_change_sets_height_and_resets() {
    let start = Instant::now();
    let mut tracker = PhaseTracker::new(start);
    let change = start + Duration::from_millis(250);
    tracker.on_view_change(11, 3, change);
    let later = change + Duration::from_millis(750);
    let duration = tracker
        .record(PipelinePhase::Propose, 11, 3, later)
        .expect("phase tracker must allow recording after view change");
    assert_eq!(duration, Duration::from_millis(750));
}

#[test]
fn phase_tracker_back_to_back_view_changes_preserve_height() {
    let start = Instant::now();
    let mut tracker = PhaseTracker::new(start);
    tracker.start_new_round(7, start);
    let change1 = start + Duration::from_millis(100);
    tracker.on_view_change(7, 1, change1);
    let change2 = change1 + Duration::from_millis(150);
    tracker.on_view_change(7, 2, change2);

    assert_eq!(tracker.current_view(7), Some(2));
    assert_eq!(tracker.current_view(6), None);
    let age = tracker.view_age(7, change2 + Duration::from_millis(50));
    assert!(age.is_some(), "view age should track the latest view");
}

#[cfg(feature = "telemetry")]
#[test]
fn dispatch_background_request_post_enqueues() {
    use std::sync::{Arc, mpsc};

    let (tx, rx) = mpsc::sync_channel(1);
    let metrics = Arc::new(iroha_telemetry::metrics::Metrics::default());
    let telemetry = Telemetry::new(metrics, true);
    let peer = PeerId::from(checked_keypair().public_key().clone());
    let request = BackgroundRequest::Post {
        peer: peer.clone(),
        msg: wire(BlockMessage::ConsensusParams(
            super::message::ConsensusParamsAdvert {
                collectors_k: 1,
                redundant_send_r: 1,
                membership: None,
            },
        )),
    };

    assert!(dispatch_background_request(Some(&tx), request, &telemetry).is_ok());
    match rx.try_recv().expect("background task enqueued") {
        BackgroundPost::Post { peer: queued, .. } => assert_eq!(queued, peer),
        other => panic!("unexpected background task: {other:?}"),
    }
}

