#[test]
fn proposal_assembly_stale_window_scales_for_large_batches() {
    let base = Duration::from_millis(400);

    assert_eq!(Actor::proposal_assembly_stale_window(base, 1), base);
    assert_eq!(Actor::proposal_assembly_stale_window(base, 127), base);
    assert_eq!(
        Actor::proposal_assembly_stale_window(base, 128),
        base.saturating_mul(2)
    );
    assert_eq!(
        Actor::proposal_assembly_stale_window(base, 256),
        base.saturating_mul(3)
    );
    assert_eq!(
        Actor::proposal_assembly_stale_window(base, 512),
        base.saturating_mul(4)
    );
    assert_eq!(
        Actor::proposal_assembly_stale_window(base, 100_000),
        base.saturating_mul(4)
    );
}

#[test]
fn proposal_gas_cost_matches_isi_metering() {
    use iroha_data_model::transaction::Executable;

    let tx = sample_transaction();
    let instructions = match tx.instructions() {
        Executable::Instructions(batch) => batch.iter().map(Clone::clone).collect::<Vec<_>>(),
        Executable::ContractCall(_) => panic!("sample transaction should be ISI-based"),
        Executable::Ivm(_) => panic!("sample transaction should be ISI-based"),
        Executable::IvmProved(_) => panic!("sample transaction should be ISI-based"),
    };
    let expected = crate::gas::meter_instructions(&instructions);
    assert!(expected > 0, "expected non-zero ISI gas cost");

    let accepted = AcceptedTransaction::new_unchecked(Cow::Owned(tx));
    let measured = crate::queue::Queue::compute_proposal_gas_cost(&accepted);
    assert_eq!(measured, expected);
}

#[test]
fn resolve_prev_block_for_proposal_returns_none_when_parent_missing() {
    let kura = Kura::blank_kura_for_testing();
    let pending_blocks = BTreeMap::new();
    let highest_qc = sample_qc_ref(1, 0);

    let prev = super::propose::resolve_prev_block_for_proposal(
        2,
        &highest_qc,
        kura.as_ref(),
        &pending_blocks,
    );

    assert!(prev.is_none());
}

#[test]
fn resolve_prev_block_for_proposal_uses_pending_parent_when_available() {
    let kura = Kura::blank_kura_for_testing();
    let parent = sample_block(1, 0, None);
    let parent_hash = parent.hash();
    let payload_hash = Hash::new(parent.encode());
    let pending = PendingBlock::new(parent, payload_hash, 1, 0);
    let mut pending_blocks = BTreeMap::new();
    pending_blocks.insert(parent_hash, pending);

    let highest_qc = QcHeaderRef {
        subject_block_hash: parent_hash,
        ..sample_qc_ref(1, 0)
    };

    let prev = super::propose::resolve_prev_block_for_proposal(
        2,
        &highest_qc,
        kura.as_ref(),
        &pending_blocks,
    )
    .expect("pending parent should be returned");

    assert_eq!(prev.hash(), parent_hash);
}

