#[tokio::test(flavor = "current_thread")]
async fn reschedule_near_quorum_backlog_uses_explicit_sweep_time_for_pending_age() {
    let _worker_guard = super::status::worker_queue_test_guard();
    super::status::reset_worker_loop_snapshot_for_tests();
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let view = actor.state.view();
    let height = view.height() as u64 + 1;
    let parent = view.latest_block_hash();
    drop(view);

    let block = sample_block(height, 0, parent);
    let block_hash = block.hash();
    let payload_hash = Hash::new(b"near-quorum-explicit-sweep-time");
    let view_idx = block.header().view_change_index();
    seed_near_quorum_commit_votes_for_block(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        view_idx,
    );

    let quorum_timeout = actor.quorum_timeout(actor.runtime_da_enabled());
    let availability_timeout =
        actor.availability_timeout(quorum_timeout, actor.runtime_da_enabled());
    let near_timeout = super::reschedule::near_quorum_payload_timeout(actor.rebroadcast_cooldown())
        .min(quorum_timeout);
    assert!(
        near_timeout < quorum_timeout,
        "test requires reduced near-quorum timeout"
    );
    let sweep_now = Instant::now()
        .checked_sub(Duration::from_secs(30))
        .expect("test sweep time can be moved into the past");
    let pending_age = near_timeout + Duration::from_millis(1);
    assert!(
        pending_age < availability_timeout,
        "backlog suppression path should still be inside availability timeout"
    );
    let stale_progress_age = quorum_timeout + Duration::from_millis(1);

    let mut pending = PendingBlock::new(block, payload_hash, height, view_idx);
    pending.inserted_at = sweep_now
        .checked_sub(pending_age)
        .expect("pending insertion before sweep");
    pending.touch_progress(
        sweep_now
            .checked_sub(stale_progress_age)
            .expect("stale progress before sweep"),
    );
    actor.pending.pending_blocks.insert(block_hash, pending);

    let rbc_queue_backlog_threshold = usize::try_from(
        super::Actor::near_quorum_queue_depth_threshold(actor.config.queues.rbc_chunks),
    )
    .expect("queue threshold fits usize");
    for _ in 0..rbc_queue_backlog_threshold {
        super::status::record_worker_queue_enqueue(super::status::WorkerQueueKind::RbcChunks);
    }

    assert!(
        !actor.reschedule_stale_pending_blocks_with_now(sweep_now, None),
        "availability backoff must use the explicit sweep time, not wall-clock pending age"
    );
    assert!(
        actor
            .pending
            .pending_blocks
            .get(&block_hash)
            .and_then(|pending| pending.last_quorum_reschedule)
            .is_none(),
        "backlog suppression should not mark the quorum reschedule gate"
    );

    super::status::record_worker_queue_drain(
        super::status::WorkerQueueKind::RbcChunks,
        rbc_queue_backlog_threshold,
    );
    assert!(
        actor.reschedule_stale_pending_blocks_with_now(sweep_now, None),
        "draining the backlog should let the same explicit sweep time arm the reduced timeout"
    );
    assert!(
        actor
            .pending
            .pending_blocks
            .get(&block_hash)
            .and_then(|pending| pending.last_quorum_reschedule)
            .is_some(),
        "near-quorum reschedule should mark the gate after backlog drains"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn reschedule_near_quorum_vote_backed_defers_while_single_slot_ingress_backlogged() {
    let _worker_guard = super::status::worker_queue_test_guard();
    super::status::reset_worker_loop_snapshot_for_tests();
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);
    let _ = take_background_log(&background_log);

    let view = actor.state.view();
    let height = view.height() as u64 + 1;
    let parent = view.latest_block_hash();
    drop(view);

    let block = sample_block(height, 0, parent);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let view_idx = block.header().view_change_index();
    let required = seed_near_quorum_commit_votes_for_block(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        view_idx,
    );
    assert!(
        required >= 3,
        "test requires at least three votes for commit quorum"
    );

    let quorum_timeout = actor.quorum_timeout(actor.runtime_da_enabled());
    let near_quorum_recent_progress_grace =
        super::saturating_mul_duration(actor.rebroadcast_cooldown(), 4)
            .max(Duration::from_millis(500));
    let stale_progress_age = near_quorum_recent_progress_grace + Duration::from_millis(1);
    let now = Instant::now();

    let mut pending = PendingBlock::new(block, payload_hash, height, view_idx);
    pending.inserted_at = now - quorum_timeout - Duration::from_millis(1);
    pending.touch_progress(now - stale_progress_age);
    actor.pending.pending_blocks.insert(block_hash, pending);
    actor.note_proposal_seen(height, view_idx, payload_hash);

    record_test_worker_slot_ingress(
        super::status::WorkerQueueKind::BlockPayload,
        height,
        view_idx,
        super::status::ConsensusMessageKind::BlockCreated,
        Some(block_hash),
    );
    assert!(
        !actor.reschedule_stale_pending_blocks_with_now(now, None),
        "single inbound block-payload work item should suppress near-quorum vote-backed reschedule"
    );
    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained");
    assert!(
        pending_after.last_quorum_reschedule.is_none(),
        "single inbound block-payload work item should keep the near-quorum gate closed"
    );

    drain_test_worker_slot_ingress(
        super::status::WorkerQueueKind::BlockPayload,
        height,
        view_idx,
        super::status::ConsensusMessageKind::BlockCreated,
        Some(block_hash),
    );
    record_test_worker_slot_ingress(
        super::status::WorkerQueueKind::Blocks,
        height,
        view_idx,
        super::status::ConsensusMessageKind::BlockCreated,
        Some(block_hash),
    );
    assert!(
        !actor.reschedule_stale_pending_blocks_with_now(now, None),
        "single inbound block work item should suppress near-quorum vote-backed reschedule"
    );
    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained");
    assert!(
        pending_after.last_quorum_reschedule.is_none(),
        "single inbound block work item should keep the near-quorum gate closed"
    );

    drain_test_worker_slot_ingress(
        super::status::WorkerQueueKind::Blocks,
        height,
        view_idx,
        super::status::ConsensusMessageKind::BlockCreated,
        Some(block_hash),
    );
    assert!(
        actor.reschedule_stale_pending_blocks_with_now(now, None),
        "near-quorum vote-backed reschedule should rearm once same-slot ingress drains"
    );
    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained");
    assert!(
        pending_after.last_quorum_reschedule.is_none(),
        "pre-timeout near-quorum resend should not consume the full quorum-timeout marker"
    );
    let _ = harness.background_rx.try_iter().count();
    let posts = take_background_log(&background_log);
    assert!(
        !posts.is_empty(),
        "draining same-slot ingress should emit retransmit work"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn reschedule_near_quorum_vote_backed_retransmits_once_fast_resend_window_expires() {
    let _worker_guard = super::status::worker_queue_test_guard();
    super::status::reset_worker_loop_snapshot_for_tests();
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);
    let _ = take_background_log(&background_log);

    let view = actor.state.view();
    let height = view.height() as u64 + 1;
    let parent = view.latest_block_hash();
    drop(view);

    let block = sample_block(height, 0, parent);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let view_idx = block.header().view_change_index();
    let required = seed_near_quorum_commit_votes_for_block(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        view_idx,
    );
    assert!(
        required >= 3,
        "test requires at least three votes for commit quorum"
    );

    let quorum_timeout = actor.quorum_timeout(actor.runtime_da_enabled());
    let resend_window = super::reschedule::contiguous_frontier_vote_backed_resend_window(
        actor.rebroadcast_cooldown(),
        required.saturating_sub(1),
        required,
    );
    let settling_progress_age = resend_window.saturating_sub(Duration::from_millis(1));
    let now = Instant::now();

    let mut pending = PendingBlock::new(block, payload_hash, height, view_idx);
    pending.inserted_at = now - quorum_timeout - Duration::from_millis(1);
    pending.touch_progress(now - settling_progress_age);
    actor.pending.pending_blocks.insert(block_hash, pending);
    let _ = harness.background_rx.try_iter().count();
    let _ = take_background_log(&background_log);

    assert!(
        !actor.reschedule_stale_pending_blocks_with_now(now, None),
        "near-quorum vote-backed resend should stay closed until the fast resend window expires"
    );
    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained");
    assert!(
        pending_after.last_quorum_reschedule.is_none(),
        "pre-timeout near-quorum resend should not mark the full quorum-timeout reschedule gate"
    );
    let _ = harness.background_rx.try_iter().count();
    let posts = take_background_log(&background_log);
    assert!(
        posts.is_empty(),
        "pre-timeout near-quorum resend should not emit before the fast resend window expires"
    );

    let stale_now = now + Duration::from_millis(2);
    assert!(
        actor.reschedule_stale_pending_blocks_with_now(stale_now, None),
        "near-quorum vote-backed resend should arm once the fast resend window expires"
    );
    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained");
    assert!(
        pending_after.last_quorum_reschedule.is_none(),
        "pre-timeout near-quorum resend should not consume the full quorum-timeout reschedule marker"
    );
    let _ = harness.background_rx.try_iter().count();
    let posts_after = take_background_log(&background_log);
    assert!(
        !posts_after.is_empty(),
        "expired fast resend window should emit retransmit work"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn reschedule_ignores_vote_backed_quorum_timeout_rbc_queue_backlog() {
    let _worker_guard = super::status::worker_queue_test_guard();
    super::status::reset_worker_loop_snapshot_for_tests();
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let view = actor.state.view();
    let height = view.height() as u64 + 1;
    let parent = view.latest_block_hash();
    drop(view);

    let block = sample_block(height, 0, parent);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let view_idx = block.header().view_change_index();
    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let required = topology.min_votes_for_commit().max(1);
    assert!(
        required >= 3,
        "test requires at least three votes for commit quorum"
    );
    let epoch = actor.epoch_for_height(height);
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology =
        super::topology_for_view(&topology, height, view_idx, mode_tag, prf_seed);
    let signer_peer = signature_topology
        .as_ref()
        .first()
        .expect("signature topology must contain at least one signer");
    let signer_idx = signature_topology
        .as_ref()
        .iter()
        .position(|candidate| candidate == signer_peer)
        .expect("signer in topology");
    let signer = ValidatorIndex::try_from(signer_idx).expect("signer fits u32");
    let keypair = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("matching signer keypair");
    let mut vote = crate::sumeragi::consensus::Vote {
        phase: Phase::Commit,
        block_hash,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view: view_idx,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer,
        bls_sig: Vec::new(),
    };
    bind_vote_to_signature_topology_chain_order(&mut vote, actor, &signature_topology);
    let preimage = super::vote_preimage(&actor.common_config.chain, mode_tag, &vote);
    let signature = checked_signature(keypair.private_key(), &preimage);
    vote.bls_sig = signature.payload().to_vec();
    actor.handle_vote(vote);

    let vote_status =
        actor.commit_vote_quorum_status_for_block_detail(block_hash, height, view_idx);
    assert_eq!(
        vote_status.vote_count, 1,
        "test requires a single commit vote"
    );
    assert!(!vote_status.quorum_reached, "test must remain below quorum");
    assert!(
        vote_status.vote_count.saturating_add(1) < required,
        "test must stay outside near-quorum window"
    );

    let quorum_timeout = actor.quorum_timeout(actor.runtime_da_enabled());
    let quiet_window = super::saturating_mul_duration(actor.rebroadcast_cooldown(), 8)
        .max(Duration::from_millis(400))
        .max(quorum_timeout);
    let stalled_at = Instant::now() - quiet_window - Duration::from_millis(1);
    let mut pending = PendingBlock::new(block, payload_hash, height, view_idx);
    pending.inserted_at = stalled_at;
    pending.touch_progress(stalled_at);
    actor.pending.pending_blocks.insert(block_hash, pending);
    let _ = actor.try_replay_deferred_votes();
    if let Some(slot) = actor.frontier_slot.as_mut() {
        slot.timers.last_progress_at = stalled_at;
        slot.timers.last_updated_at = stalled_at;
        slot.quorum_progress.last_vote_at = Some(stalled_at);
    }
    actor
        .pending
        .missing_block_requests
        .retain(|_, request| !(request.height == height && request.view == view_idx));

    super::status::record_worker_queue_enqueue(super::status::WorkerQueueKind::RbcChunks);
    assert!(
        actor.reschedule_stale_pending_blocks(None),
        "unrelated RBC queue depth should not suppress a vote-backed quorum retransmit once the quiet window expires"
    );
    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained");
    assert!(
        pending_after.last_quorum_reschedule.is_some(),
        "vote-backed pending should still reschedule under unrelated RBC queue depth"
    );

    harness.shutdown.send();
}

