#[tokio::test(flavor = "current_thread")]
async fn reschedule_stale_pending_blocks_targets_snapshot_roster() {
    let _worker_guard = super::status::worker_queue_test_guard();
    let _rbc_guard = super::status::rbc_status_test_guard();
    let _history_guard = super::status::commit_history_test_guard();
    super::status::reset_worker_loop_snapshot_for_tests();
    super::status::set_tx_queue_backpressure(crate::queue::BackpressureState::Healthy {
        queued: 0,
        capacity: NonZeroUsize::new(1).expect("non-zero tx queue capacity"),
    });
    super::status::set_rbc_store_pressure(0, 0, 0);

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let background_log = attach_background_log(actor);
    let _ = take_background_log(&background_log);
    let view = actor.state.view();
    let height = view.height() as u64 + 1;
    let parent = view.latest_block_hash();
    drop(view);

    let block = sample_block(height, 0, parent);
    let block_hash = block.hash();
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    let view_idx = block.header().view_change_index();
    let quorum_timeout = actor.quorum_timeout(actor.runtime_da_enabled());
    let mut pending = PendingBlock::new(block, payload_hash, height, view_idx);
    pending.inserted_at = Instant::now() - quorum_timeout - Duration::from_millis(1);
    actor.pending.pending_blocks.insert(block_hash, pending);
    actor.note_proposal_seen(height, view_idx, payload_hash);

    let mut snapshot_roster = actor.effective_commit_topology();
    let local_peer = actor.common_config.peer.id().clone();
    let removed_peer = snapshot_roster
        .iter()
        .find(|peer| *peer != &local_peer)
        .cloned()
        .expect("non-local roster entry");
    snapshot_roster.retain(|peer| peer != &removed_peer);
    assert!(
        snapshot_roster.contains(&local_peer),
        "snapshot roster must include local peer"
    );

    let topology = super::network_topology::Topology::new(snapshot_roster.clone());
    let signers: BTreeSet<ValidatorIndex> = (0..snapshot_roster.len())
        .map(|idx| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_bitmap = super::build_signers_bitmap(&signers, snapshot_roster.len());
    let commit_qc = qc_with_bitmap(
        &actor.common_config.chain,
        block_hash,
        height,
        view_idx,
        0,
        signers_bitmap.clone(),
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );
    let checkpoint_signature = aggregate_vote_signature_for_bitmap(
        &actor.common_config.chain,
        PERMISSIONED_TAG,
        block_hash,
        height,
        view_idx,
        0,
        &signers_bitmap,
        &topology,
        &harness.key_pairs,
    );
    let checkpoint = ValidatorSetCheckpoint::new(
        height,
        view_idx,
        block_hash,
        commit_qc.parent_state_root,
        commit_qc.post_state_root,
        snapshot_roster.clone(),
        signers_bitmap,
        checkpoint_signature,
        VALIDATOR_SET_HASH_VERSION_V1,
        None,
    );
    {
        let mut journal = actor.state.commit_roster_journal.write();
        journal.upsert(commit_qc, checkpoint, None);
    }
    let required = topology.min_votes_for_commit().max(1);
    assert!(
        required >= 2,
        "test requires at least two snapshot validators"
    );
    let seeded = seed_verified_commit_votes_for_block_with_roster(
        actor,
        &harness.key_pairs,
        block_hash,
        height,
        view_idx,
        &snapshot_roster,
        required.saturating_sub(1),
    );
    assert_eq!(
        seeded,
        required.saturating_sub(1),
        "test setup should seed a snapshot-roster near-quorum"
    );
    actor
        .pending
        .pending_blocks
        .get_mut(&block_hash)
        .expect("pending retained")
        .touch_progress(Instant::now() - quorum_timeout - Duration::from_millis(1));
    let vote_status =
        actor.commit_vote_quorum_status_for_block_detail(block_hash, height, view_idx);
    assert!(
        vote_status.vote_count > 0,
        "test setup should produce a vote-backed reschedule candidate"
    );

    assert!(
        actor.reschedule_stale_pending_blocks(None),
        "pending block should be rescheduled"
    );

    let expected_targets: BTreeSet<_> = actor
        .quorum_retransmit_targets_for_missing_votes(
            block_hash,
            height,
            view_idx,
            &snapshot_roster,
            topology.min_votes_for_commit().max(1),
            vote_status.vote_count,
        )
        .into_iter()
        .collect();
    let targets: BTreeSet<_> = take_background_log(&background_log)
        .into_iter()
        .filter(|entry| {
            matches!(
                entry,
                super::BackgroundRequestLogEntry {
                    kind: super::BackgroundRequestLogKind::Post,
                    msg_kind: Some("BlockCreated" | "BlockSyncUpdate"),
                    peer: Some(_),
                }
            )
        })
        .filter_map(|entry| entry.peer)
        .collect();
    assert!(
        targets.is_superset(&expected_targets),
        "reschedule should rebroadcast to the snapshot roster"
    );
    assert!(
        !targets.contains(&removed_peer),
        "reschedule must not target peers outside the snapshot roster"
    );

    harness.shutdown.send();
}

