#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_defers_reschedule_until_availability_timeout() {
    let mut harness = test_actor_harness(4).await;
    let _worker_guard = super::status::worker_queue_test_guard();
    super::status::reset_worker_loop_snapshot_for_tests();
    let actor = &mut harness.actor;
    actor.relay_backpressure.reset_to_current();
    actor.queue_drop_backpressure.reset_to_current();
    actor.queue_block_backpressure.reset_to_current();
    let view = actor.state.view();
    let height = view.height() as u64 + 1;
    let parent = view.latest_block_hash();
    drop(view);

    let block = sample_block(height, 0, parent);
    let block_hash = block.hash();
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::prehashed([0xAA; Hash::LENGTH]);
    assert_ne!(
        Hash::new(&payload_bytes),
        payload_hash,
        "test requires mismatched payload hash"
    );
    let view_idx = block.header().view_change_index();
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view_idx),
    );
    let quorum_timeout = actor.quorum_timeout(true);
    let availability_timeout = actor.availability_timeout(quorum_timeout, true);
    {
        let pending = actor
            .pending
            .pending_blocks
            .get_mut(&block_hash)
            .expect("pending block");
        pending.validation_status = ValidationStatus::Valid;
        pending.inserted_at = Instant::now() - quorum_timeout - Duration::from_millis(1);
        pending.last_gate = Some(GateReason::ManifestGuard {
            lane: LaneId::new(2),
            epoch: 0,
            sequence: 1,
            kind: ManifestGateKind::Missing,
        });
    }
    assert!(
        quorum_timeout < availability_timeout,
        "availability timeout should exceed quorum timeout in DA mode"
    );
    assert!(actor.runtime_da_enabled(), "test requires DA to be enabled");
    actor.subsystems.da_rbc.rbc.sessions.clear();
    actor.subsystems.da_rbc.rbc.status_handle.clear();
    let payload_available = Hash::new(&payload_bytes) == payload_hash
        || super::rbc_payload_matches(
            &actor.subsystems.da_rbc.rbc.sessions,
            &actor.subsystems.da_rbc.rbc.status_handle,
            &block_hash,
            height,
            view_idx,
            &payload_hash,
        );
    assert!(!payload_available, "test requires missing local payload");
    actor.note_proposal_seen(height, view_idx, payload_hash);

    actor.process_commit_candidates_with_trigger(CommitPipelineTrigger::Event, None);

    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained");
    assert_eq!(
        pending_after.last_gate,
        Some(GateReason::MissingLocalData),
        "availability gate should record missing local data during commit processing"
    );
    assert!(
        pending_after.last_quorum_reschedule.is_none(),
        "commit pipeline should defer reschedule while availability is missing"
    );

    {
        let pending = actor
            .pending
            .pending_blocks
            .get_mut(&block_hash)
            .expect("pending retained");
        pending.inserted_at = Instant::now() - availability_timeout - Duration::from_millis(1);
    }

    actor.process_commit_candidates_with_trigger(CommitPipelineTrigger::Event, None);

    assert!(
        !actor.pending.pending_blocks.contains_key(&block_hash),
        "commit pipeline zero-vote reschedule should drop the pending block after availability timeout"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_skips_fast_timeout_with_da_enabled() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    super::status::reset_worker_loop_snapshot_for_tests();
    let view = actor.state.view();
    let height = view.height() as u64 + 1;
    let parent = view.latest_block_hash();
    drop(view);

    assert!(actor.runtime_da_enabled(), "test requires DA to be enabled");

    let block = sample_block(height, 0, parent);
    let block_hash = block.hash();
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    let view_idx = block.header().view_change_index();
    let (consensus_mode, _, _) = actor.consensus_context_for_height(height);
    let fast_timeout = {
        let view = actor.state.view();
        actor.pending_fast_path_timeout(&view, consensus_mode)
    };
    let quorum_timeout = actor.quorum_timeout(actor.runtime_da_enabled());
    assert!(
        fast_timeout < quorum_timeout,
        "test requires fast timeout to be shorter than quorum timeout"
    );

    let mut pending = PendingBlock::new(block, payload_hash, height, view_idx);
    pending.validation_status = ValidationStatus::Valid;
    pending.parent_state_root = Some(zero_state_root());
    pending.post_state_root = Some(zero_state_root());
    pending.inserted_at = Instant::now() - fast_timeout - Duration::from_millis(1);
    actor.pending.pending_blocks.insert(block_hash, pending);
    actor.note_proposal_seen(height, view_idx, payload_hash);

    actor.process_commit_candidates_with_trigger(CommitPipelineTrigger::Tick, None);

    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained");
    assert!(
        pending_after.last_quorum_reschedule.is_none(),
        "commit pipeline should not reschedule at fast timeout in DA mode"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn da_commit_validation_inline_fallback_timeout_has_750ms_floor() {
    use iroha_data_model::parameter::system::{Parameter, SumeragiParameter};

    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.da.enabled = true;
    consensus_cfg.da.quorum_timeout_multiplier = 1;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    {
        let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
        let mut block = state.world.block();
        let params = block.parameters.get_mut();
        params.set_parameter(Parameter::Sumeragi(SumeragiParameter::BlockTimeMs(100)));
        params.set_parameter(Parameter::Sumeragi(SumeragiParameter::CommitTimeMs(100)));
        block.commit();
    }

    let quorum_timeout = actor.quorum_timeout(actor.runtime_da_enabled());
    assert_eq!(
        quorum_timeout,
        Duration::from_millis(400),
        "test requires a tiny DA quorum timeout"
    );
    assert_eq!(
        actor.pending_fast_path_timeout_current(),
        Duration::from_millis(200),
        "test requires the generic fast timeout to collapse below the DA fallback floor"
    );
    assert_eq!(
        actor.commit_validation_inline_fallback_timeout(),
        Duration::from_millis(750),
        "DA inline-validation fallback timeout should stay at or above 750ms"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn da_validation_worker_stall_timeout_scales_with_pending_block_size() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let parent_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(0)
        .saturating_add(1);
    let view = 0_u64;
    let txs = (0..640)
        .map(|idx| sample_log_transaction_with_message_len(idx + 1))
        .collect();
    let block = block_with_txs(height, view, Some(parent_hash), txs);
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block, payload_hash, height, view),
    );

    let generic_timeout = actor.validation_worker_stall_timeout();
    let block_timeout = actor.validation_worker_stall_timeout_for(block_hash);
    assert!(
        block_timeout > generic_timeout,
        "large DA blocks should receive a larger worker-stall window"
    );
    assert!(
        block_timeout >= Duration::from_millis(10_240),
        "640 txs should scale the DA validation stall floor to at least 10240ms"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn commit_pipeline_keeps_validation_backpressured_after_fast_timeout_when_worker_queue_full()
{
    use iroha_data_model::parameter::system::{Parameter, SumeragiParameter};

    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    {
        let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
        let mut block = state.world.block();
        let params = block.parameters.get_mut();
        params.set_parameter(Parameter::Sumeragi(SumeragiParameter::BlockTimeMs(1500)));
        params.set_parameter(Parameter::Sumeragi(SumeragiParameter::CommitTimeMs(1500)));
        block.commit();
    }

    let parent_hash = seed_genesis_block_for_state(&actor.state);
    let height = u64::try_from(actor.state.view().height())
        .unwrap_or(0)
        .saturating_add(1);
    let view = 0;
    let block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, view, Some(parent_hash));
    let block_hash = block.hash();
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));

    let (consensus_mode, _, _) = actor.consensus_context_for_height(height);
    let commit_topology = actor.roster_for_vote_with_mode(block_hash, height, view, consensus_mode);
    let inline_fallback_timeout = actor.commit_validation_inline_fallback_timeout();
    assert!(
        inline_fallback_timeout > Duration::ZERO,
        "test requires non-zero inline fallback timeout"
    );

    let (_work_tx, _work_rx) =
        std::sync::mpsc::sync_channel::<super::validation::ValidationWork>(0);
    actor.subsystems.validation.work_txs = vec![_work_tx];
    actor.subsystems.validation.result_rx = None;
    actor.subsystems.validation.inflight.clear();

    let pending = PendingBlock::new(block, payload_hash, height, view);
    actor.pending.pending_blocks.insert(block_hash, pending);
    actor.note_proposal_seen(height, view, payload_hash);
    let outcome = actor.validate_pending_block_for_voting_inline(block_hash, &commit_topology);
    assert!(
        matches!(outcome, ValidationGateOutcome::Valid),
        "block should validate inline before testing fallback: {outcome:?}"
    );
    let mut pending = actor
        .pending
        .pending_blocks
        .remove(&block_hash)
        .expect("pending retained after inline validation");
    pending.validation_status = ValidationStatus::Pending;
    pending.parent_state_root = None;
    pending.post_state_root = None;
    pending.inserted_at = Instant::now() - inline_fallback_timeout - Duration::from_millis(1);
    actor.pending.pending_blocks.insert(block_hash, pending);

    actor.process_commit_candidates_with_trigger(CommitPipelineTrigger::Tick, None);

    let pending_after = actor
        .pending
        .pending_blocks
        .get(&block_hash)
        .expect("pending retained");
    assert_eq!(
        pending_after.validation_status,
        ValidationStatus::Pending,
        "queue-full pending work should stay deferred and backpressured"
    );
    assert!(
        pending_after.parent_state_root.is_none(),
        "queue-full redrive should not validate inline"
    );
    assert!(
        pending_after.post_state_root.is_none(),
        "queue-full redrive should not validate inline"
    );
    assert!(
        !actor
            .subsystems
            .validation
            .inflight
            .contains_key(&block_hash),
        "queue-full vNext validation should not register worker inflight work"
    );
    assert!(
        !actor
            .subsystems
            .validation
            .vnext_inflight
            .contains_key(&block_hash),
        "queue-full vNext validation should not register worker ownership without a dispatch"
    );
    let round_slot = actor
        .vnext_rounds
        .get(&(height, view))
        .and_then(|round| round.slot(block_hash))
        .expect("vNext round should retain the backpressured validation slot");
    assert!(matches!(
        round_slot.validation,
        crate::sumeragi::vnext::ValidationState::Backpressured { .. }
    ));

    harness.shutdown.send();
}

