    let (full_tx, _full_rx) = mpsc::sync_channel::<super::validation::ValidationWork>(0);
    let (_result_tx, result_rx) = mpsc::sync_channel::<super::validation::ValidationResult>(1);
    actor.subsystems.validation.work_txs = vec![full_tx];
