#[test]
fn ensure_locked_qc_rejects_conflicting_hash_at_same_height_even_with_higher_view() {
    let locked_hash = HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xDE; 32]));
    let other_hash = HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xAD; 32]));
    let locked = QcHeaderRef {
        phase: crate::sumeragi::consensus::Phase::Commit,
        subject_block_hash: locked_hash,
        height: 10,
        view: 2,
        epoch: 0,
    };
    let highest = QcHeaderRef {
        phase: crate::sumeragi::consensus::Phase::Commit,
        subject_block_hash: other_hash,
        height: 10,
        view: 3,
        epoch: 0,
    };
    assert_eq!(
        super::ensure_locked_qc_allows(Some(locked), highest),
        Err(LockedQcRejection::HashMismatch {
            locked: locked_hash,
            highest: other_hash
        })
    );
}

#[test]
fn child_qc_helper_detects_extending_qc() {
    let lock = QcHeaderRef {
        phase: crate::sumeragi::consensus::Phase::Commit,
        ..sample_qc_ref(7, 1)
    };
    let child = QcHeaderRef {
        phase: crate::sumeragi::consensus::Phase::Commit,
        ..sample_qc_ref(8, 2)
    };
    let result = super::child_qc_extending_lock(lock, [child], |hash, _height| {
        (hash == child.subject_block_hash).then_some(lock.subject_block_hash)
    });
    assert_eq!(result, Some(child));
}

#[test]
fn child_qc_helper_rejects_mismatched_parent() {
    let lock = QcHeaderRef {
        phase: crate::sumeragi::consensus::Phase::Commit,
        ..sample_qc_ref(10, 1)
    };
    let child = QcHeaderRef {
        phase: crate::sumeragi::consensus::Phase::Commit,
        ..sample_qc_ref(11, 0)
    };
    let other_parent = QcHeaderRef {
        phase: crate::sumeragi::consensus::Phase::Commit,
        ..sample_qc_ref(9, 0)
    };
    let result = super::child_qc_extending_lock(lock, [child], |hash, _height| {
        (hash == child.subject_block_hash).then_some(other_parent.subject_block_hash)
    });
    assert!(result.is_none());
}

fn session_key() -> SessionKey {
    (
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x11; 32])),
        1,
        0,
    )
}

fn leader_signature_for_header(
    actor: &Actor,
    roster: &[PeerId],
    header: &BlockHeader,
    key_pairs: &[KeyPair],
) -> BlockSignature {
    let mut topology = super::network_topology::Topology::new(roster.to_vec());
    let leader_index = actor
        .leader_index_for(
            &mut topology,
            header.height().get(),
            header.view_change_index(),
        )
        .expect("leader index available for tests");
    let leader_peer = topology
        .as_ref()
        .get(leader_index)
        .expect("leader exists in topology");
    let leader_key = key_pairs
        .iter()
        .find(|kp| kp.public_key() == leader_peer.public_key())
        .expect("leader key available in harness");
    let signature = checked_signature_of_hash(leader_key.private_key(), header.hash());
    let index = u64::try_from(leader_index).unwrap_or(u64::MAX);
    BlockSignature::new(index, signature)
}

fn bind_session_to_roster_leader(
    actor: &Actor,
    session: &mut RbcSession,
    block: &SignedBlock,
    roster: &[PeerId],
    key_pairs: &[KeyPair],
) {
    session.test_set_block_header_and_signature(block);
    session.leader_signature = Some(leader_signature_for_header(
        actor,
        roster,
        &block.header(),
        key_pairs,
    ));
}

fn rbc_header_and_signature(
    actor: &Actor,
    roster: &[PeerId],
    height: u64,
    view: u64,
    key_pairs: &[KeyPair],
) -> (BlockHeader, BlockSignature) {
    let header = BlockHeader::new(
        NonZeroU64::new(height).expect("block height must be non-zero"),
        None,
        None,
        None,
        0,
        view,
    );
    let mut topology = super::network_topology::Topology::new(roster.to_vec());
    let leader_index = actor
        .leader_index_for(&mut topology, height, view)
        .expect("leader index available for tests");
    let leader_peer = topology
        .as_ref()
        .get(leader_index)
        .expect("leader exists in topology");
    let leader_key = key_pairs
        .iter()
        .find(|kp| kp.public_key() == leader_peer.public_key())
        .expect("leader key available in harness");
    let signature = checked_signature_of_hash(leader_key.private_key(), header.hash());
    let index = u64::try_from(leader_index).unwrap_or(u64::MAX);
    (header, BlockSignature::new(index, signature))
}

#[derive(Clone, Copy, Debug)]
enum RbcInitLocalPayloadSource {
    Pending,
    CommitInflight,
    Kura,
}

fn rbc_init_with_block(
    actor: &Actor,
    roster: &[PeerId],
    height: u64,
    view: u64,
    key_pairs: &[KeyPair],
) -> (SignedBlock, crate::sumeragi::consensus::RbcInit, Hash) {
    let (block_header, leader_signature) =
        rbc_header_and_signature(actor, roster, height, view, key_pairs);
    let block = SignedBlock::presigned(leader_signature.clone(), block_header, Vec::new());
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    let epoch = actor.epoch_for_height(height);
    let seeded = Actor::build_rbc_session_from_payload(
        &payload_bytes,
        payload_hash,
        actor.config.rbc.chunk_max_bytes,
        epoch,
    )
    .expect("rbc session");
    let init = crate::sumeragi::consensus::RbcInit {
        block_hash: block.hash(),
        height,
        view,
        epoch,
        roster: roster.to_vec(),
        roster_hash: roster_hash(roster),
        total_chunks: seeded.total_chunks(),
        encoding: iroha_data_model::block::consensus::RbcEncoding::Plain,
        chunk_size_bytes: 0,
        payload_size_bytes: 0,
        data_shards: 0,
        parity_shards: 0,
        chunk_digests: seeded
            .expected_chunk_digests
            .clone()
            .expect("chunk digests"),
        payload_hash,
        chunk_root: seeded.chunk_root().expect("chunk root"),
        block_header,
        leader_signature,
    };
    (block, init, payload_hash)
}

fn insert_rbc_init_local_payload_source(
    actor: &mut Actor,
    source: RbcInitLocalPayloadSource,
    block: SignedBlock,
    payload_hash: Hash,
    height: u64,
    view: u64,
) {
    match source {
        RbcInitLocalPayloadSource::Pending => {
            actor.pending.pending_blocks.insert(
                block.hash(),
                PendingBlock::new(block, payload_hash, height, view),
            );
        }
        RbcInitLocalPayloadSource::CommitInflight => {
            let block_hash = block.hash();
            let pending = PendingBlock::new(block, payload_hash, height, view);
            let epoch = actor.epoch_for_height(height);
            let lock = QcHeaderRef {
                phase: Phase::Commit,
                subject_block_hash: block_hash,
                height,
                view,
                epoch,
            };
            let commit_topology = actor.effective_commit_topology();
            actor.subsystems.commit.inflight = Some(CommitInFlight {
                id: 1,
                lock,
                block_hash,
                pending,
                commit_topology: commit_topology.clone(),
                signature_topology: commit_topology,
                qc_signers: None,
                commit_qc: None,
                post_commit_qc: None,
                enqueue_time: Instant::now(),
                timeout_reported: false,
            });
        }
        RbcInitLocalPayloadSource::Kura => {
            actor.kura.store_block(block).expect("store block");
        }
    }
}

fn empty_block(height: u64, view: u64, parent: Option<HashOf<BlockHeader>>) -> SignedBlock {
    let header = BlockHeader {
        height: NonZeroU64::new(height).expect("block height must be non-zero"),
        prev_block_hash: parent,
        merkle_root: None,
        result_merkle_root: None,
        da_proof_policies_hash: None,
        da_commitments_hash: None,
        da_pin_intents_hash: None,
        prev_roster_evidence_hash: None,
        npos_effects_hash: None,
        execution_context_hash: None,
        sccp_commitment_root: None,
        creation_time_ms: 0,
        view_change_index: view,
        confidential_features: None,
    };
    let key_pair = checked_keypair();
    let (_, private_key) = key_pair.into_parts();
    let signature = checked_signature_of_hash(&private_key, header.hash());
    let block_signature = BlockSignature::new(0, signature);
    SignedBlock::presigned(block_signature, header, Vec::<SignedTransaction>::new())
}

fn sample_block(height: u64, view: u64, parent: Option<HashOf<BlockHeader>>) -> SignedBlock {
    sample_block_with_signature_index(height, view, parent, 0)
}

fn sample_block_with_signature_index(
    height: u64,
    view: u64,
    parent: Option<HashOf<BlockHeader>>,
    signatory_index: u64,
) -> SignedBlock {
    let chain: ChainId = "test-chain".parse().expect("chain id");
    let tx_params = TransactionParameters::default();
    let start_ms = height.saturating_sub(1);
    let (time_handle, time_source) = TimeSource::new_mock(Duration::from_millis(start_ms));
    let heartbeat = crate::tx::build_heartbeat_transaction_with_time_source(
        chain,
        &ALICE_KEYPAIR,
        &tx_params,
        height,
        &time_source,
    );
    time_handle.advance(Duration::from_millis(1));
    let creation_time_ms =
        u64::try_from(time_source.get_unix_time().as_millis()).expect("creation time fits in u64");
    let header = BlockHeader {
        height: NonZeroU64::new(height).expect("block height must be non-zero"),
        prev_block_hash: parent,
        merkle_root: None,
        result_merkle_root: None,
        da_proof_policies_hash: None,
        da_commitments_hash: None,
        da_pin_intents_hash: None,
        prev_roster_evidence_hash: None,
        npos_effects_hash: None,
        execution_context_hash: None,
        creation_time_ms,
        view_change_index: view,
        confidential_features: None,
        sccp_commitment_root: None,
    };
    let mut builder = BlockBuilder::new(header);
    builder.push_transaction(heartbeat);
    builder.build_with_signature(signatory_index, ALICE_KEYPAIR.private_key())
}

fn store_block_with_test_ancestors(kura: &Kura, block: impl Into<Arc<SignedBlock>>) {
    let block = block.into();
    let height = block.header().height().get();
    let current_count = kura.blocks_count();
    let current_height = u64::try_from(current_count).expect("Kura height fits in u64");
    let mut parent =
        NonZeroUsize::new(current_count).and_then(|height| kura.get_block_hash(height));

    for missing_height in current_height.saturating_add(1)..height {
        let ancestor = empty_block(missing_height, 0, parent);
        parent = Some(ancestor.hash());
        kura.store_block(ancestor)
            .expect("store canonical test ancestor");
    }

    kura.store_block(block).expect("store test block");
}

fn insert_pending_block(actor: &mut Actor, height: u64, view: u64) -> SessionKey {
    let parent = actor.state.view().latest_block_hash();
    let block = sample_block(height, view, parent);
    let payload_hash = Hash::new(super::proposals::block_payload_bytes(&block));
    let key = (block.hash(), height, view);
    let pending = PendingBlock::new(block, payload_hash, height, view);
    actor.pending.pending_blocks.insert(key.0, pending);
    key
}

fn insert_active_pending_block(actor: &mut Actor, view: u64) -> SessionKey {
    let height = actor
        .state
        .view()
        .height()
        .saturating_add(1)
        .try_into()
        .unwrap_or(u64::MAX);
    let key = insert_pending_block(actor, height, view);
    let payload_hash = actor
        .pending
        .pending_blocks
        .get(&key.0)
        .expect("pending block exists")
        .payload_hash;
    actor.note_proposal_seen(height, view, payload_hash);
    key
}

fn partial_rbc_session_for_block(
    actor: &Actor,
    block: &SignedBlock,
    chunk_max: usize,
) -> RbcSession {
    let payload_bytes = super::proposals::block_payload_bytes(block);
    let payload_hash = Hash::new(&payload_bytes);
    let mut session = Actor::build_rbc_session_from_payload(
        &payload_bytes,
        payload_hash,
        chunk_max,
        actor.epoch_for_height(block.header().height().get()),
    )
    .expect("partial RBC session");
    assert!(
        session.total_chunks() > 1,
        "test setup requires a multi-chunk RBC session"
    );
    let missing_idx = session
        .chunks
        .iter()
        .position(Option::is_some)
        .expect("chunk present");
    session.chunks[missing_idx] = None;
    session.received_chunks = session.received_chunks.saturating_sub(1);
    session.test_set_block_header_and_signature(block);
    assert!(
        session.received_chunks() < session.total_chunks(),
        "test setup requires a missing chunk"
    );
    session
}

fn missing_init_rebroadcast_session(
    actor: &mut Actor,
    key_pairs: &[KeyPair],
) -> (SessionKey, RbcSession, Vec<PeerId>) {
    let height = actor
        .state
        .view()
        .height()
        .saturating_add(1)
        .try_into()
        .unwrap_or(u64::MAX);
    let view = 0_u64;
    let parent = actor.state.view().latest_block_hash();
    let block = nonempty_block_for_actor(actor, key_pairs, height, view, parent);
    let block_hash = block.hash();
    let key = (block_hash, height, view);
    let payload_bytes = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload_bytes);
    let roster = actor.effective_commit_topology();
    assert!(!roster.is_empty(), "test requires a non-empty roster");
    let mut session = partial_rbc_session_for_block(actor, &block, 32);
    let header = block.header();
    let leader_signature = leader_signature_for_header(actor, &roster, &header, key_pairs);
    session.leader_signature = Some(leader_signature);
    assert!(
        session.allows_payload_recovery(),
        "partial session should carry payload recovery metadata"
    );
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block.clone(), payload_hash, height, view),
    );
    actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert(key, session.clone());
    actor.record_rbc_session_roster(key, roster.clone(), super::RbcRosterSource::Derived);
    assert!(
        actor.rbc_rebroadcast_active(key),
        "test session should be active for rebroadcast"
    );
    assert!(
        !actor.suppress_rbc_hot_repair(key),
        "pending block should keep missing-INIT hot repair enabled"
    );
    (key, session, roster)
}

