fn block_with_txs(
    height: u64,
    view: u64,
    parent: Option<HashOf<BlockHeader>>,
    txs: Vec<SignedTransaction>,
) -> SignedBlock {
    let header = BlockHeader {
        height: NonZeroU64::new(height).expect("block height must be non-zero"),
        prev_block_hash: parent,
        merkle_root: None,
        result_merkle_root: None,
        da_proof_policies_hash: None,
        da_commitments_hash: None,
        da_pin_intents_hash: None,
        prev_roster_evidence_hash: None,
        npos_effects_hash: None,
        execution_context_hash: None,
        sccp_commitment_root: None,
        creation_time_ms: 0,
        view_change_index: view,
        confidential_features: None,
    };
    let key_pair = checked_keypair();
    let (_, private_key) = key_pair.into_parts();
    let signature = checked_signature_of_hash(&private_key, header.hash());
    let block_signature = BlockSignature::new(0, signature);
    SignedBlock::presigned(block_signature, header, txs)
}

fn heartbeat_block_for_state(
    state: &State,
    chain_id: &ChainId,
    height: u64,
    view: u64,
    parent: Option<HashOf<BlockHeader>>,
    signer_kp: &KeyPair,
    signer_idx: u64,
) -> SignedBlock {
    let (tx_params, policies, confidential_features, previous_roster_evidence) = {
        let view = state.view();
        let tx_params = view.world().parameters().transaction().clone();
        let policies = crate::da::proof_policy_bundle(&view.nexus.lane_config);
        let digest =
            crate::state::compute_confidential_feature_digest(view.world(), &view.zk, height);
        let confidential_features = if digest.is_empty() {
            None
        } else {
            Some(digest)
        };
        let previous_roster_evidence = parent.and_then(|parent_hash| {
            let parent_height = height.checked_sub(1)?;
            let snapshot = state.commit_roster_snapshot_for_block(parent_height, parent_hash)?;
            Some(iroha_data_model::consensus::PreviousRosterEvidence {
                height: parent_height,
                block_hash: parent_hash,
                validator_checkpoint: snapshot.validator_checkpoint,
                stake_snapshot: snapshot.stake_snapshot.map(|snapshot| {
                    iroha_data_model::consensus::CommitStakeSnapshot {
                        validator_set_hash: snapshot.validator_set_hash,
                        entries: snapshot
                            .entries
                            .into_iter()
                            .map(
                                |entry| iroha_data_model::consensus::CommitStakeSnapshotEntry {
                                    peer_id: entry.peer_id,
                                    stake: entry.stake,
                                },
                            )
                            .collect(),
                    }
                }),
            })
        });
        (
            tx_params,
            policies,
            confidential_features,
            previous_roster_evidence,
        )
    };
    let start_ms = height.saturating_sub(1);
    let (time_handle, time_source) = TimeSource::new_mock(Duration::from_millis(start_ms));
    let (_, signer_public_key_bytes) = signer_kp
        .public_key()
        .try_to_bytes()
        .expect("fixture public key must be valid");
    // Include the elected signer so helper-produced heartbeat blocks stay distinct across test
    // harnesses that share the same height/view/parent inputs.
    let mut seed = Vec::with_capacity(24 + Hash::LENGTH + signer_public_key_bytes.len());
    seed.extend_from_slice(&height.to_le_bytes());
    seed.extend_from_slice(&view.to_le_bytes());
    if let Some(parent_hash) = parent {
        seed.extend_from_slice(parent_hash.as_ref());
    }
    seed.extend_from_slice(signer_public_key_bytes);
    let heartbeat_signer = deterministic_keypair(seed, Algorithm::Ed25519);
    let heartbeat = crate::tx::build_heartbeat_transaction_with_time_source(
        chain_id.clone(),
        &heartbeat_signer,
        &tx_params,
        height,
        &time_source,
    );
    let execution_context = {
        let accepted = crate::tx::AcceptedTransaction::new_unchecked(Cow::Borrowed(&heartbeat));
        let view = state.view();
        let routing = crate::queue::evaluate_policy_with_catalog_and_world(
            &view.nexus.routing_policy,
            &view.nexus.lane_catalog,
            &view.nexus.dataspace_catalog,
            &accepted,
            view.world(),
        )
        .expect("heartbeat transaction routing must resolve");
        BlockExecutionContextBundle::new(vec![ExternalExecutionContext::new(
            heartbeat.hash_as_entrypoint(),
            routing.lane_id,
            routing.dataspace_id,
        )])
    };
    time_handle.advance(Duration::from_millis(1));
    let creation_time_ms =
        u64::try_from(time_source.get_unix_time().as_millis()).expect("creation time fits in u64");
    let header = BlockHeader {
        height: NonZeroU64::new(height).expect("block height must be non-zero"),
        prev_block_hash: parent,
        merkle_root: None,
        result_merkle_root: None,
        da_proof_policies_hash: None,
        da_commitments_hash: None,
        da_pin_intents_hash: None,
        prev_roster_evidence_hash: None,
        npos_effects_hash: None,
        execution_context_hash: None,
        creation_time_ms,
        view_change_index: view,
        confidential_features,
        sccp_commitment_root: None,
    };
    let mut builder = BlockBuilder::new(header);
    builder.push_transaction(heartbeat);
    builder.set_execution_context(Some(execution_context));
    builder.set_da_proof_policies(Some(policies));
    builder.set_previous_roster_evidence(previous_roster_evidence);
    builder.build_with_signature(signer_idx, signer_kp.private_key())
}

fn nonempty_block_for_actor(
    actor: &Actor,
    key_pairs: &[KeyPair],
    height: u64,
    view: u64,
    parent: Option<HashOf<BlockHeader>>,
) -> SignedBlock {
    let mut roster = actor.effective_commit_topology();
    if roster.is_empty() {
        roster = actor.trusted_topology();
    }
    let topology = super::network_topology::Topology::new(roster);
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let signer_peer = signature_topology
        .as_ref()
        .first()
        .expect("non-empty signature topology");
    let signer_kp = key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair exists for selected leader");
    let signer_idx = signature_topology
        .position(signer_kp.public_key())
        .expect("signer index in topology");
    heartbeat_block_for_state(
        actor.state.as_ref(),
        &actor.common_config.chain,
        height,
        view,
        parent,
        signer_kp,
        u64::try_from(signer_idx).expect("signer index fits u64"),
    )
}

fn add_commit_quorum_signatures_for_actor(
    actor: &Actor,
    key_pairs: &[KeyPair],
    block: &mut SignedBlock,
) {
    let mut roster = actor.effective_commit_topology();
    if roster.is_empty() {
        roster = actor.trusted_topology();
    }
    let topology = super::network_topology::Topology::new(roster);
    let height = block.header().height().get();
    let view = block.header().view_change_index();
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let required = signature_topology.min_votes_for_commit().max(1);
    for (idx, peer) in signature_topology
        .as_ref()
        .iter()
        .enumerate()
        .take(required)
    {
        let idx_u64 = u64::try_from(idx).expect("signer index fits u64");
        if block
            .signatures()
            .any(|signature| signature.index() == idx_u64)
        {
            continue;
        }
        let key_pair = key_pairs
            .iter()
            .find(|key_pair| key_pair.public_key() == peer.public_key())
            .expect("signer keypair exists in harness");
        let signature = checked_signature_of_hash(key_pair.private_key(), block.header().hash());
        block
            .add_signature(BlockSignature::new(idx_u64, signature))
            .expect("signature added");
    }
    crate::block::ValidBlock::is_commit(block, &signature_topology)
        .expect("block signatures should satisfy commit quorum");
}

