#[tokio::test(flavor = "current_thread")]
async fn conflicting_vote_does_not_override_first() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let committed_height = u64::try_from(actor.state.view().height()).unwrap_or(0);
    let height = committed_height.saturating_add(1);
    let view = 0;
    let epoch = actor.current_epoch();
    let chain_id = actor.chain_id.clone();
    let (consensus_mode, mode_tag, prf_seed) = actor.consensus_context_for_height(height);

    let block_hash_a =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xB1; Hash::LENGTH]));
    let block_hash_b =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xB2; Hash::LENGTH]));

    let roster_a = actor.roster_for_vote_with_mode(block_hash_a, height, view, consensus_mode);
    assert!(
        !roster_a.is_empty(),
        "vote roster should resolve for first vote"
    );
    let topology_a = super::network_topology::Topology::new(roster_a.clone());
    let mut vote_a = crate::sumeragi::consensus::Vote {
        phase: crate::sumeragi::consensus::Phase::Commit,
        block_hash: block_hash_a,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: 0,
        bls_sig: Vec::new(),
    };
    let signature_topology_a =
        super::topology_for_view(&topology_a, height, view, mode_tag, prf_seed);
    bind_vote_to_signature_topology_chain_order(&mut vote_a, actor, &signature_topology_a);
    sign_vote_for_view_with_seed(
        &mut vote_a,
        &chain_id,
        &topology_a,
        &harness.key_pairs,
        mode_tag,
        prf_seed,
    );
    actor.handle_vote(vote_a.clone());

    let roster_b = actor.roster_for_vote_with_mode(block_hash_b, height, view, consensus_mode);
    assert!(
        !roster_b.is_empty(),
        "vote roster should resolve for conflicting vote"
    );
    assert_eq!(
        roster_a, roster_b,
        "commit vote roster must be deterministic for a round regardless of competing block hash"
    );
    let new_view_roster_a =
        actor.roster_for_new_view_with_mode(block_hash_a, height, view, consensus_mode);
    let new_view_roster_b =
        actor.roster_for_new_view_with_mode(block_hash_b, height, view, consensus_mode);
    assert_eq!(
        new_view_roster_a, new_view_roster_b,
        "NEW_VIEW roster must be deterministic for a round regardless of competing block hash"
    );
    let topology_b = super::network_topology::Topology::new(roster_b);
    let mut vote_b = crate::sumeragi::consensus::Vote {
        phase: crate::sumeragi::consensus::Phase::Commit,
        block_hash: block_hash_b,
        parent_state_root: zero_state_root(),
        post_state_root: zero_state_root(),
        height,
        view,
        epoch,
        chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
        rechain_seq: 0,
        highest_qc: None,
        signer: 0,
        bls_sig: Vec::new(),
    };
    let signature_topology_b =
        super::topology_for_view(&topology_b, height, view, mode_tag, prf_seed);
    bind_vote_to_signature_topology_chain_order(&mut vote_b, actor, &signature_topology_b);
    sign_vote_for_view_with_seed(
        &mut vote_b,
        &chain_id,
        &topology_b,
        &harness.key_pairs,
        mode_tag,
        prf_seed,
    );
    actor.handle_vote(vote_b);

    let key = vote_log_key_for_vote(&vote_a);
    let stored = actor.vote_log.get(&key).expect("vote recorded");
    assert_eq!(
        stored.block_hash, block_hash_a,
        "conflicting vote should not override the first vote"
    );

    harness.shutdown.send();
}

