#[tokio::test(flavor = "current_thread")]
async fn block_sync_update_uses_nonextending_commit_qc_hint_for_lock_realign() {
    let _guard = super::status::qc_status_test_guard();
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    let locked_block = sample_block(1, 0, None);
    actor
        .kura
        .store_block(locked_block.clone())
        .expect("store locked block");
    let state = Arc::get_mut(&mut actor.state).expect("state uniquely held");
    state.push_block_hash_for_testing(locked_block.hash());

    let locked_epoch = actor.epoch_for_height(1);
    actor.locked_qc = Some(QcHeaderRef {
        height: 1,
        view: 0,
        epoch: locked_epoch,
        subject_block_hash: locked_block.hash(),
        phase: Phase::Commit,
    });
    super::status::set_locked_qc(1, 0, Some(locked_block.hash()));

    let height = 2u64;
    let view = 1u64;
    let conflicting_parent =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xB2; 32]));
    let block = nonempty_block_for_actor(
        actor,
        &harness.key_pairs,
        height,
        view,
        Some(conflicting_parent),
    );
    let block_hash = block.hash();
    actor
        .kura
        .store_block(block.clone())
        .expect("store known conflicting block");

    let topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let signers: BTreeSet<ValidatorIndex> = topology
        .as_ref()
        .iter()
        .enumerate()
        .map(|(idx, _)| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_bitmap = super::build_signers_bitmap(&signers, topology.as_ref().len());
    let epoch = actor.epoch_for_height(height);
    let qc = qc_with_bitmap(
        &actor.common_config.chain,
        block_hash,
        height,
        view,
        epoch,
        signers_bitmap,
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );

    let mut update = super::message::BlockSyncUpdate::from(&block);
    update.commit_qc = Some(qc);

    actor
        .handle_block_sync_update(update, None)
        .expect("block sync update");
    drain_known_block_qc_work(actor);

    assert!(
        actor.block_known_locally(block_hash),
        "test setup expects known block payload"
    );
    let locked = actor.locked_qc.expect("locked qc updated");
    assert_eq!(locked.height, height);
    assert_eq!(locked.subject_block_hash, block_hash);

    super::status::set_locked_qc(0, 0, None);
    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn block_sync_update_does_not_advance_qc_for_unvalidated_payload() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let genesis_hash = seed_genesis_block_for_state(&actor.state);
    let committed_height = u64::try_from(actor.state.view().height()).unwrap_or(u64::MAX);
    let height = committed_height.saturating_add(1);
    let view = 0_u64;
    let topology_peers = actor.effective_commit_topology();
    let topology = super::network_topology::Topology::new(topology_peers);
    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology = super::topology_for_view(&topology, height, view, mode_tag, prf_seed);
    let signer_peer = signature_topology
        .as_ref()
        .first()
        .expect("signature topology has a signer");
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair");
    let signer_idx = signature_topology
        .position(signer_peer.public_key())
        .expect("signer index");
    let mismatched_idx = (signer_idx + 1) % signature_topology.as_ref().len();
    assert_ne!(
        signer_idx, mismatched_idx,
        "test requires at least two validators"
    );

    let block = heartbeat_block_for_state(
        actor.state.as_ref(),
        &actor.common_config.chain,
        height,
        view,
        Some(genesis_hash),
        signer_kp,
        u64::try_from(mismatched_idx).expect("signer index fits u64"),
    );
    let block_hash = block.hash();

    let required = signature_topology.min_votes_for_commit().max(1);
    let signers: BTreeSet<ValidatorIndex> = signature_topology
        .as_ref()
        .iter()
        .enumerate()
        .take(required)
        .map(|(idx, _)| ValidatorIndex::try_from(idx).expect("validator index fits"))
        .collect();
    let signers_bitmap = super::build_signers_bitmap(&signers, topology.as_ref().len());
    let epoch = actor.epoch_for_height(height);
    let qc = qc_with_bitmap(
        &actor.common_config.chain,
        block_hash,
        height,
        view,
        epoch,
        signers_bitmap,
        Phase::Commit,
        &topology,
        &harness.key_pairs,
    );

    let mut update = super::message::BlockSyncUpdate::from(&block);
    update.commit_qc = Some(qc);

    actor
        .handle_block_sync_update(update, None)
        .expect("block sync update");
    drain_known_block_qc_work(actor);

    assert!(
        !actor.block_known_for_lock(block_hash),
        "mismatched payload signature must remain unvalidated"
    );
    assert_ne!(
        actor
            .highest_qc
            .map(|qc| (qc.height, qc.subject_block_hash)),
        Some((height, block_hash)),
        "unvalidated block sync payload must not promote incoming QC to highest"
    );
    assert_ne!(
        actor.locked_qc.map(|qc| (qc.height, qc.subject_block_hash)),
        Some((height, block_hash)),
        "unvalidated block sync payload must not promote incoming QC to lock"
    );

    harness.shutdown.send();
}

