#[tokio::test(flavor = "current_thread")]
async fn block_sync_update_same_height_conflict_with_block_quorum_stays_passive_without_certified_evidence()
 {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;

    actor.locked_qc = None;
    let parent = Some(seed_genesis_block_for_state(&actor.state));
    let height = actor.committed_height_snapshot().saturating_add(1);
    let canonical_view = 0_u64;
    let conflicting_view = 2_u64;
    let now = Instant::now();
    actor.phase_tracker.start_new_round(height, now);
    actor
        .phase_tracker
        .on_view_change(height, conflicting_view, now);

    let vote_topology = super::network_topology::Topology::new(actor.effective_commit_topology());
    let epoch = actor.epoch_for_height(height);
    let canonical_block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, canonical_view, parent);
    let canonical_hash = insert_validated_pending(actor, canonical_block);
    assert!(
        actor.emit_precommit_vote(
            canonical_hash,
            height,
            canonical_view,
            epoch,
            ValidationStatus::Valid,
            &vote_topology,
            parent,
            Some((Hash::new([]), Hash::new([]))),
        ),
        "test setup should record a local same-height vote for the canonical branch"
    );

    let (_, mode_tag, prf_seed) = actor.consensus_context_for_height(height);
    let signature_topology =
        super::topology_for_view(&vote_topology, height, conflicting_view, mode_tag, prf_seed);
    let mut conflicting_block =
        nonempty_block_for_actor(actor, &harness.key_pairs, height, conflicting_view, parent);
    let required = signature_topology.min_votes_for_commit().max(1);
    let mut present = BTreeSet::new();
    for sig in conflicting_block.signatures() {
        if let Ok(idx) = usize::try_from(sig.index()) {
            present.insert(idx);
        }
    }
    for (idx, peer) in signature_topology
        .as_ref()
        .iter()
        .enumerate()
        .take(required)
    {
        if present.contains(&idx) {
            continue;
        }
        let kp = harness
            .key_pairs
            .iter()
            .find(|kp| kp.public_key() == peer.public_key())
            .expect("signer keypair");
        let sig = checked_signature_of_hash(kp.private_key(), conflicting_block.header().hash());
        conflicting_block
            .add_signature(BlockSignature::new(
                u64::try_from(idx).expect("signer index fits"),
                sig,
            ))
            .expect("signature added");
    }
    let conflicting_hash = conflicting_block.hash();

    let update = super::message::BlockSyncUpdate::from(&conflicting_block);
    actor
        .handle_block_sync_update(update, None)
        .expect("handle conflicting same-height block sync update");

    let pending_after = actor
        .pending
        .pending_blocks
        .get(&conflicting_hash)
        .expect("conflicting block-sync payload should still be retained locally");
    assert!(
        pending_after.is_retired_same_height(),
        "raw block-quorum evidence must not activate a same-height conflicting branch after a local vote"
    );
    assert_eq!(
        actor.authoritative_slot_owner_hash(height, conflicting_view),
        None,
        "uncertified same-height block-sync payload must not seize authoritative frontier ownership"
    );
    if let Some(slot) = actor.frontier_slot.as_ref() {
        assert_ne!(
            slot.block_hash, conflicting_hash,
            "uncertified same-height block-sync payload must remain passive"
        );
    }
    let retained = actor
        .slot_tracker
        .retained_branch_seed(height)
        .expect("passive conflicting block-sync payload should be tracked for repair");
    assert_eq!(retained.block_hash, conflicting_hash);
    assert_eq!(retained.view, conflicting_view);

    harness.shutdown.send();
}

#[test]
fn allow_stale_block_created_requires_missing_request_or_retained_match() {
    assert!(super::proposal_handlers::allow_stale_block_created(
        true, false, false
    ));
    assert!(super::proposal_handlers::allow_stale_block_created(
        false, true, false
    ));
    assert!(super::proposal_handlers::allow_stale_block_created(
        true, true, false
    ));
    assert!(super::proposal_handlers::allow_stale_block_created(
        false, false, true
    ));
    assert!(!super::proposal_handlers::allow_stale_block_created(
        false, false, false
    ));
}

#[tokio::test(flavor = "current_thread")]
async fn stale_view_accepts_rbc_messages_with_da() {
    let mut consensus_cfg = test_sumeragi_config();
    consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
    consensus_cfg.da.enabled = true;
    consensus_cfg.rbc.chunk_max_bytes = 1024;
    consensus_cfg.rbc.pending_max_chunks = 10;
    consensus_cfg.rbc.pending_max_bytes = 256 * 1024;
    let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
    let actor = &mut harness.actor;
    let height = 7;
    let local_view = 3;
    let stale_view = 2;
    let now = Instant::now();
    actor.phase_tracker.start_new_round(height, now);
    actor.phase_tracker.on_view_change(height, local_view, now);

    let payload_hash = Hash::prehashed([0x33; 32]);
    let chunk_root = Hash::prehashed([0x44; 32]);
    let roster = actor.effective_commit_topology();
    let (block_header, leader_signature) =
        rbc_header_and_signature(actor, &roster, height, stale_view, &harness.key_pairs);
    let block_hash = block_header.hash();
    let key = (block_hash, height, stale_view);
    let pending_block = sample_block(height, stale_view, None);
    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(
            pending_block,
            Hash::prehashed([0xEE; Hash::LENGTH]),
            height,
            stale_view,
        ),
    );

    let init = crate::sumeragi::consensus::RbcInit {
        block_hash,
        height,
        view: stale_view,
        epoch: 0,
        roster: roster.clone(),
        roster_hash: roster_hash(&roster),
        total_chunks: 1,
        encoding: iroha_data_model::block::consensus::RbcEncoding::Plain,
        chunk_size_bytes: 0,
        payload_size_bytes: 0,
        data_shards: 0,
        parity_shards: 0,
        chunk_digests: vec![[0x44; 32]],
        payload_hash,
        chunk_root,
        block_header,
        leader_signature: leader_signature.clone(),
    };
    actor.handle_rbc_init(init, None).expect("rbc init");
    assert!(actor.subsystems.da_rbc.rbc.sessions.contains_key(&key));

    let chunk = crate::sumeragi::consensus::RbcChunk {
        block_hash,
        height,
        view: stale_view,
        epoch: 0,
        idx: 0,
        bytes: vec![0x01],
    };
    actor.handle_rbc_chunk(chunk, None).expect("rbc chunk");
    assert!(actor.subsystems.da_rbc.rbc.pending.is_empty());

    let mut session = RbcSession::test_new(1, Some(payload_hash), Some(chunk_root), 0);
    session.block_header = Some(block_header);
    session.leader_signature = Some(leader_signature);
    actor.subsystems.da_rbc.rbc.sessions.insert(key, session);

    let session = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .cloned()
        .expect("session");
    let ready = actor.build_rbc_ready(key, &session).expect("ready");
    actor.handle_rbc_ready(ready).expect("rbc ready");
    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert!(
        !stored.ready_signatures.is_empty(),
        "stale-view READY should be accepted for known sessions"
    );

    let session = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .cloned()
        .expect("session");
    let _guard = super::status::message_handling_test_guard();
    super::status::reset_message_handling_for_tests();
    assert!(
        !actor.should_drop_stale_rbc_message(height, stale_view, &block_hash, "RbcDeliver"),
        "stale-view DELIVER should not be dropped as stale for known sessions"
    );
    let local_peer = actor.common_config.peer.id().clone();
    let signer_peer = roster
        .iter()
        .find(|peer| *peer != &local_peer)
        .expect("remote signer peer")
        .clone();
    let signer_idx = signature_sender_index(actor, &roster, key.1, key.2, &signer_peer);
    let signer_kp = harness
        .key_pairs
        .iter()
        .find(|kp| kp.public_key() == signer_peer.public_key())
        .expect("signer keypair");
    let chunk_root = session
        .expected_chunk_root
        .or_else(|| session.chunk_root())
        .expect("chunk root");
    let ready_signatures = session
        .ready_signatures
        .iter()
        .map(|entry| crate::sumeragi::consensus::RbcReadySignature {
            sender: entry.sender,
            signature: entry.signature.clone(),
        })
        .collect();
    let mut deliver = crate::sumeragi::consensus::RbcDeliver {
        block_hash: key.0,
        height: key.1,
        view: key.2,
        epoch: session.epoch,
        roster_hash: session
            .ready_roster_hash
            .unwrap_or_else(|| roster_hash(&roster)),
        chunk_root,
        sender: u32::try_from(signer_idx).expect("signer index fits u32"),
        signature: Vec::new(),
        ready_signatures,
    };
    let (_, mode_tag, _prf_seed) = actor.consensus_context_for_height(key.1);
    let preimage = super::rbc_deliver_preimage(&actor.common_config.chain, mode_tag, &deliver);
    let signature = checked_signature(signer_kp.private_key(), &preimage);
    deliver.signature = signature.payload().to_vec();
    actor.handle_rbc_deliver(deliver).expect("rbc deliver");
    let stored = actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .get(&key)
        .expect("session");
    assert!(
        !stored.delivered,
        "stale-view DELIVER without quorum should remain deferred"
    );
    let entries = super::status::snapshot().consensus_message_handling.entries;
    assert!(
        !entries.iter().any(|entry| {
            entry.kind == super::status::ConsensusMessageKind::RbcDeliver
                && entry.reason == super::status::ConsensusMessageReason::StaleView
        }),
        "stale-view DELIVER should not be dropped as stale"
    );

    super::status::reset_message_handling_for_tests();

    harness.shutdown.send();
}

#[derive(Clone, Copy, Debug)]
enum StaleProposalHintRepairCase {
    ExactCommittedQcRepair,
    DaDisabled,
    NonActiveHeight,
    LocalViewSame,
    LocalViewTooFar,
    NoCommittedQc,
    QcHeightMismatch,
    QcViewMismatch,
    QcHashMismatch,
    QcEpochMismatch,
    RejectDoesNotCache,
    RejectDoesNotObserve,
    RejectDoesNotMutateHighest,
}

impl StaleProposalHintRepairCase {
    const ALL: [Self; 13] = [
        Self::ExactCommittedQcRepair,
        Self::DaDisabled,
        Self::NonActiveHeight,
        Self::LocalViewSame,
        Self::LocalViewTooFar,
        Self::NoCommittedQc,
        Self::QcHeightMismatch,
        Self::QcViewMismatch,
        Self::QcHashMismatch,
        Self::QcEpochMismatch,
        Self::RejectDoesNotCache,
        Self::RejectDoesNotObserve,
        Self::RejectDoesNotMutateHighest,
    ];

    fn name(self) -> &'static str {
        match self {
            Self::ExactCommittedQcRepair => "exact_committed_qc_repair",
            Self::DaDisabled => "da_disabled",
            Self::NonActiveHeight => "non_active_height",
            Self::LocalViewSame => "local_view_same",
            Self::LocalViewTooFar => "local_view_too_far",
            Self::NoCommittedQc => "no_committed_qc",
            Self::QcHeightMismatch => "qc_height_mismatch",
            Self::QcViewMismatch => "qc_view_mismatch",
            Self::QcHashMismatch => "qc_hash_mismatch",
            Self::QcEpochMismatch => "qc_epoch_mismatch",
            Self::RejectDoesNotCache => "reject_does_not_cache",
            Self::RejectDoesNotObserve => "reject_does_not_observe",
            Self::RejectDoesNotMutateHighest => "reject_does_not_mutate_highest",
        }
    }

    fn expects_repair(self) -> bool {
        matches!(self, Self::ExactCommittedQcRepair)
    }

    fn handler_reachable_stale(self) -> bool {
        !matches!(self, Self::LocalViewSame)
    }
}

fn proposal_hint_stale_view_dropped_recorded() -> bool {
    super::status::snapshot()
        .consensus_message_handling
        .entries
        .iter()
        .any(|entry| {
            entry.kind == super::status::ConsensusMessageKind::ProposalHint
                && entry.outcome == super::status::ConsensusMessageOutcome::Dropped
                && entry.reason == super::status::ConsensusMessageReason::StaleView
                && entry.total > 0
        })
}

#[tokio::test(flavor = "current_thread")]
async fn stale_proposal_hint_repair_formal_gate_matrix() {
    let _message_guard = super::status::message_handling_test_guard();

    for case in StaleProposalHintRepairCase::ALL {
        super::status::reset_message_handling_for_tests();

        let mut consensus_cfg = test_sumeragi_config();
        consensus_cfg.consensus_mode = ConsensusMode::Permissioned;
        consensus_cfg.da.enabled = true;
        let mut harness = test_actor_harness_with_config(4, consensus_cfg, None).await;
        let actor = &mut harness.actor;
        if matches!(case, StaleProposalHintRepairCase::DaDisabled) {
            let mut timing = actor.effective_timing.get();
            timing.da_enabled = false;
            actor.effective_timing.set(timing);
        }

        let committed_qc = if matches!(case, StaleProposalHintRepairCase::NoCommittedQc) {
            None
        } else {
            seed_genesis_block_for_state(actor.state.as_ref());
            let committed_qc = actor
                .latest_committed_qc()
                .expect("genesis commit QC should be available");
            actor.highest_qc = Some(committed_qc);
            Some(committed_qc)
        };

        let mut height = actor.committed_height_snapshot().saturating_add(1);
        let view = 0_u64;
        let mut local_view = view.saturating_add(1);
        let mut highest_qc = committed_qc.unwrap_or_else(|| {
            proposal_hint_formal_qc(
                0,
                0,
                proposal_hint_formal_hash(0xB0),
                Phase::Commit,
                actor.epoch_for_height(0),
            )
        });

        match case {
            StaleProposalHintRepairCase::NonActiveHeight => {
                height = height.saturating_add(1);
            }
            StaleProposalHintRepairCase::LocalViewSame => {
                local_view = view;
            }
            StaleProposalHintRepairCase::LocalViewTooFar => {
                local_view = view.saturating_add(2);
            }
            StaleProposalHintRepairCase::QcHeightMismatch => {
                highest_qc.height = highest_qc.height.saturating_add(1);
            }
            StaleProposalHintRepairCase::QcViewMismatch => {
                highest_qc.view = highest_qc.view.saturating_add(1);
            }
            StaleProposalHintRepairCase::QcHashMismatch => {
                highest_qc.subject_block_hash = proposal_hint_formal_hash(0xB1);
            }
            StaleProposalHintRepairCase::QcEpochMismatch => {
                highest_qc.epoch = highest_qc.epoch.saturating_add(1);
            }
            StaleProposalHintRepairCase::RejectDoesNotCache
            | StaleProposalHintRepairCase::RejectDoesNotObserve
            | StaleProposalHintRepairCase::RejectDoesNotMutateHighest => {
                local_view = view.saturating_add(2);
            }
            StaleProposalHintRepairCase::ExactCommittedQcRepair
            | StaleProposalHintRepairCase::DaDisabled
            | StaleProposalHintRepairCase::NoCommittedQc => {}
        }

        let block_hash = proposal_hint_formal_hash(0xB2);
        let hint = super::message::ProposalHint {
            block_hash,
            height,
            view,
            highest_qc,
        };

        let helper_allows = actor.stale_proposal_hint_can_seed_frontier_repair(&hint, local_view);
        assert_eq!(
            helper_allows,
            case.expects_repair(),
            "{}: helper admission",
            case.name()
        );

        if case.handler_reachable_stale() {
            let now = Instant::now();
            actor.phase_tracker.start_new_round(height, now);
            actor.phase_tracker.on_view_change(height, local_view, now);
            let highest_before = actor.highest_qc;

            actor
                .handle_proposal_hint(hint)
                .expect("handle stale proposal hint");

            let cached = actor
                .subsystems
                .propose
                .proposal_cache
                .get_hint(height, view)
                .is_some_and(|cached| cached.block_hash == block_hash);
            let observed = actor.slot_tracker.proposals_seen.contains(&(height, view));
            let highest_mutated = actor.highest_qc != highest_before;
            let dropped = proposal_hint_stale_view_dropped_recorded();

            assert_eq!(cached, case.expects_repair(), "{}: hint cache", case.name());
            if !case.expects_repair() {
                assert!(
                    !observed,
                    "{}: rejected stale hint must not mark proposal observed",
                    case.name()
                );
            }
            assert_eq!(
                dropped,
                !case.expects_repair(),
                "{}: stale-view drop",
                case.name()
            );
            assert!(
                !highest_mutated,
                "{}: stale proposal hint must not mutate highest QC",
                case.name()
            );
        }

        harness.shutdown.send();
    }

    super::status::reset_message_handling_for_tests();
}

