#[test]
fn invalid_rbc_session_does_not_count_as_operator_backlog() {
    let _rbc_guard = super::status::rbc_status_test_guard();
    super::status::reset_rbc_backlog_stats_for_tests();

    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x54; Hash::LENGTH]));
    let key = (block_hash, 4, 0);
    let mut session = RbcSession::test_new(4, Some(Hash::new(b"invalid-delivery")), None, 0);
    session.test_note_chunk(0, vec![0xC1], 0);
    session.test_set_delivered(true);
    assert!(session.record_ready(0, vec![0xAA]));
    assert!(
        !session.record_ready(0, vec![0xBB]),
        "conflicting READY should invalidate the session"
    );
    assert!(session.is_invalid());
    session.lane_allocations.push(super::LaneAllocation {
        lane_id: LaneId::new(3),
        tx_count: 5,
        rbc_bytes_total: 32,
        teu_total: 7,
        total_chunks: 4,
    });
    session
        .dataspace_allocations
        .push(super::DataspaceAllocation {
            lane_id: LaneId::new(3),
            dataspace_id: DataSpaceId::new(9),
            tx_count: 2,
            rbc_bytes_total: 16,
            teu_total: 4,
            total_chunks: 2,
        });
    let sessions = BTreeMap::from([(key, session)]);

    Actor::update_rbc_backlog_snapshot(
        &sessions,
        &BTreeMap::new(),
        (usize::MAX, usize::MAX),
        Duration::from_secs(1),
        16,
        None,
    );

    let snapshot = super::status::rbc_backlog_snapshot();
    assert_eq!(
        snapshot.pending_sessions, 0,
        "invalid RBC sessions must not inflate pending backlog session counts"
    );
    assert_eq!(
        snapshot.total_missing_chunks, 0,
        "invalid RBC sessions must not inflate missing chunk totals"
    );
    assert_eq!(snapshot.max_missing_chunks, 0);
    let status = super::status::snapshot();
    assert!(
        status.rbc_lane_backlog.is_empty(),
        "invalid RBC sessions must not contribute lane backlog entries"
    );
    assert!(
        status.rbc_dataspace_backlog.is_empty(),
        "invalid RBC sessions must not contribute dataspace backlog entries"
    );

    super::status::reset_rbc_backlog_stats_for_tests();
}

#[test]
fn drain_rbc_state_for_block_retains_status_snapshot() {
    let block_hash = HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x55; 32]));
    let key = (block_hash, 4, 1);
    let mut sessions = BTreeMap::new();
    let chunk0 = b"retained-".to_vec();
    let chunk1 = b"status-".to_vec();
    let chunk2 = b"snapshot".to_vec();
    let payload = [chunk0.as_slice(), chunk1.as_slice(), chunk2.as_slice()].concat();
    let mut session = RbcSession::test_new(3, Some(Hash::new(&payload)), None, 0);
    session.test_note_chunk(0, chunk0, 0);
    session.test_note_chunk(1, chunk1, 0);
    session.test_note_chunk(2, chunk2, 0);
    session.test_set_delivered(true);
    session.lane_allocations.push(super::LaneAllocation {
        lane_id: LaneId::new(7),
        tx_count: 5,
        rbc_bytes_total: 9,
        teu_total: 11,
        total_chunks: 3,
    });
    session
        .dataspace_allocations
        .push(super::DataspaceAllocation {
            lane_id: LaneId::new(7),
            dataspace_id: DataSpaceId::new(22),
            tx_count: 5,
            rbc_bytes_total: 9,
            teu_total: 11,
            total_chunks: 3,
        });
    sessions.insert(key, session.clone());

    let mut pending_rbc = BTreeMap::new();
    pending_rbc.insert(key, PendingRbcMessages::new(Instant::now()));
    let mut session_rosters = BTreeMap::new();
    let (peer, _pop, _kp) = bls_peer("127.0.0.1:0");
    session_rosters.insert(key, vec![peer.id().clone()]);

    let status_handle = rbc_status::register_handle();
    status_handle.update(
        rbc_status::Summary {
            block_hash,
            height: key.1,
            view: key.2,
            total_chunks: 0,
            encoding: iroha_data_model::block::consensus::RbcEncoding::Plain,
            data_shards: 0,
            parity_shards: 0,
            received_chunks: 0,
            ready_count: 0,
            delivered: false,
            payload_hash: None,
            recovered_from_disk: false,
            invalid: false,
            reconstructed_stripes: 0,
            reconstructable_stripes: 0,
            lane_backlog: Vec::new(),
            dataspace_backlog: Vec::new(),
        },
        SystemTime::now(),
    );

    let (lane_totals, dataspace_totals) = super::drain_rbc_state_for_block(
        block_hash,
        &mut sessions,
        &mut pending_rbc,
        &mut session_rosters,
        &mut BTreeMap::new(),
        None,
        &status_handle,
        None,
        None,
        None,
        true,
    );

    assert!(sessions.is_empty());
    assert!(pending_rbc.is_empty());
    assert!(session_rosters.is_empty());
    let status_after = status_handle
        .get(&key)
        .expect("status entry retained after drain");
    assert!(status_after.delivered);
    assert_eq!(status_after.lane_backlog.len(), 1);
    assert_eq!(status_after.dataspace_backlog.len(), 1);
    assert_eq!(lane_totals.get(&LaneId::new(7)), Some(&(5, 3, 9, 11)));
    assert_eq!(
        dataspace_totals.get(&(LaneId::new(7), DataSpaceId::new(22))),
        Some(&(5, 3, 9, 11))
    );
}

