#[test]
fn rbc_prehashed_chunk_ingest_accepts_expected_digest() {
    let bytes = vec![0xA5; 32];
    let digest: [u8; 32] = Sha256::digest(&bytes).into();
    let root = MerkleTree::<[u8; 32]>::from_hashed_leaves_sha256(vec![digest])
        .root()
        .map(Hash::from)
        .expect("single digest root");
    let mut session = RbcSession::new(
        1,
        Some(Hash::new(&bytes)),
        Some(root),
        Some(vec![digest]),
        0,
    )
    .expect("session");

    let outcome = session.ingest_prehashed_chunk(0, bytes.clone(), digest, Some(0));

    assert_eq!(outcome, ChunkIngestOutcome::Accepted);
    assert_eq!(session.chunk_bytes(0), Some(bytes.as_slice()));
    assert_eq!(session.chunk_root(), Some(root));
}

#[test]
fn rbc_prehashed_chunk_ingest_rejects_digest_mismatch() {
    let bytes = vec![0x5A; 32];
    let expected: [u8; 32] = Sha256::digest(&bytes).into();
    let root = MerkleTree::<[u8; 32]>::from_hashed_leaves_sha256(vec![expected])
        .root()
        .map(Hash::from)
        .expect("single digest root");
    let mut session = RbcSession::new(
        1,
        Some(Hash::new(&bytes)),
        Some(root),
        Some(vec![expected]),
        0,
    )
    .expect("session");
    let mut mismatched = expected;
    mismatched[0] ^= 0xFF;

    let outcome = session.ingest_prehashed_chunk(0, bytes, mismatched, Some(0));

    assert_eq!(outcome, ChunkIngestOutcome::DigestMismatch);
    assert_eq!(session.received_chunks(), 0);
}

#[cfg(feature = "telemetry")]
#[tokio::test(flavor = "current_thread")]
async fn authoritative_payload_bytes_for_telemetry_uses_local_payload_fallback() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = 11u64;
    let view = 0u64;
    let parent = actor.state.view().latest_block_hash();
    let txs: Vec<_> = (0..16).map(|_| sample_transaction()).collect();
    let block = block_with_txs(height, view, parent, txs);
    let block_hash = block.hash();
    let payload = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload);
    let key = (block_hash, height, view);

    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block.clone(), payload_hash, height, view),
    );

    let mut session = partial_rbc_session_for_block(actor, &block, 1024);
    session.test_set_delivered(true);

    let fallback = actor.rbc_session_authoritative_payload_bytes_for_telemetry(key, &session);
    assert_eq!(
        fallback,
        Some(payload.len() as u64),
        "authoritative local payload should provide telemetry bytes when incomplete RBC chunks match advertised metadata"
    );

    assert_eq!(
        session.take_delivered_payload_bytes_for_telemetry_with_fallback(fallback),
        Some(payload.len() as u64),
        "fallback bytes should be consumable by the delivered-payload telemetry path"
    );

    harness.shutdown.send();
}

#[cfg(feature = "telemetry")]
#[tokio::test(flavor = "current_thread")]
async fn authoritative_payload_bytes_for_telemetry_rejects_invalid_chunk_shape_with_local_payload()
{
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    let telemetry = actor.telemetry_handle().expect("telemetry enabled").clone();

    let height = 12u64;
    let view = 0u64;
    let block = nonempty_block_for_actor(actor, &harness.key_pairs, height, view, None);
    let block_hash = block.hash();
    let payload = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload);
    let key = (block_hash, height, view);

    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block.clone(), payload_hash, height, view),
    );

    let mut session =
        RbcSession::test_new(1, Some(payload_hash), None, actor.epoch_for_height(height));
    session.test_note_chunk(0, payload.clone(), 0);
    session.test_set_received_chunks(2);
    session.test_set_delivered(true);

    let fallback = actor.rbc_session_authoritative_payload_bytes_for_telemetry(key, &session);
    assert_eq!(
        fallback, None,
        "authoritative local payload bytes must not mask an over-counted delivered session"
    );

    actor.maybe_record_rbc_payload_bytes_metric_for_active_session(key, &session);
    let metrics = telemetry.metrics().await;
    assert_eq!(
        metrics.sumeragi_rbc_payload_bytes_delivered_total.get(),
        0,
        "active-session telemetry must not record payload bytes for invalid chunk shapes"
    );
    assert!(
        !actor
            .subsystems
            .da_rbc
            .rbc
            .payload_metric_recorded_sessions
            .contains(&key),
        "rejecting invalid chunk shape must not consume the once-only payload marker"
    );

    harness.shutdown.send();
}

#[cfg(feature = "telemetry")]
#[tokio::test(flavor = "current_thread")]
async fn authoritative_payload_bytes_for_telemetry_rejects_local_payload_conflicting_with_chunk_root()
 {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;

    let height = actor.state.view().height() as u64 + 1;
    let view = 0u64;
    let parent = actor.state.view().latest_block_hash();
    let txs: Vec<_> = (0..16).map(|_| sample_transaction()).collect();
    let block = block_with_txs(height, view, parent, txs);
    let block_hash = block.hash();
    let payload = super::proposals::block_payload_bytes(&block);
    let payload_hash = Hash::new(&payload);
    let key = (block_hash, height, view);

    actor.pending.pending_blocks.insert(
        block_hash,
        PendingBlock::new(block.clone(), payload_hash, height, view),
    );

    let mut session = partial_rbc_session_for_block(actor, &block, 1024);
    let correct_chunk_root = session.expected_chunk_root.expect("chunk root");
    let mut wrong_root_bytes = *correct_chunk_root.as_ref();
    wrong_root_bytes[0] ^= 0xA5;
    session.expected_chunk_root = Some(Hash::prehashed(wrong_root_bytes));
    session.test_set_delivered(true);

    let fallback = actor.rbc_session_authoritative_payload_bytes_for_telemetry(key, &session);
    assert_eq!(
        fallback, None,
        "telemetry fallback must reject local bytes that conflict with advertised chunk root"
    );
    assert!(
        !session.is_invalid(),
        "telemetry hydration probe must not mutate the stored session"
    );
    assert_eq!(
        session.take_delivered_payload_bytes_for_telemetry_with_fallback(fallback),
        None,
        "rejecting contradictory chunk metadata must not consume the once-only telemetry marker"
    );

    session.expected_chunk_root = Some(correct_chunk_root);
    let fallback = actor.rbc_session_authoritative_payload_bytes_for_telemetry(key, &session);
    assert_eq!(
        fallback,
        Some(payload.len() as u64),
        "correct chunk metadata should allow the same local payload to supply fallback bytes"
    );
    assert_eq!(
        session.take_delivered_payload_bytes_for_telemetry_with_fallback(fallback),
        Some(payload.len() as u64),
        "the delivered-payload telemetry marker should remain available after the rejected fallback"
    );

    harness.shutdown.send();
}

