#[tokio::test(flavor = "current_thread")]
async fn pending_rbc_chunk_cap_eviction_releases_evicted_dedup() {
    let mut harness = test_actor_harness(4).await;
    let actor = &mut harness.actor;
    actor.config.rbc.pending_max_chunks = 1;

    let block_hash =
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x71; Hash::LENGTH]));
    let height = 12;
    let view = 0;
    let epoch = actor.epoch_for_height(height);
    let key = (block_hash, height, view);
    let chunk0 = crate::sumeragi::consensus::RbcChunk {
        block_hash,
        height,
        view,
        epoch,
        idx: 0,
        bytes: vec![0x01, 0x02],
    };
    let chunk1 = crate::sumeragi::consensus::RbcChunk {
        idx: 1,
        bytes: vec![0x03, 0x04],
        ..chunk0.clone()
    };
    let chunk0_key = crate::sumeragi::BlockPayloadDedupKey::RbcChunk {
        height: chunk0.height,
        view: chunk0.view,
        epoch: chunk0.epoch,
        block_hash: chunk0.block_hash,
        idx: chunk0.idx,
        bytes_hash: Hash::new(&chunk0.bytes),
    };
    let chunk1_key = crate::sumeragi::BlockPayloadDedupKey::RbcChunk {
        height: chunk1.height,
        view: chunk1.view,
        epoch: chunk1.epoch,
        block_hash: chunk1.block_hash,
        idx: chunk1.idx,
        bytes_hash: Hash::new(&chunk1.bytes),
    };
    {
        let mut guard = actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned");
        guard.insert(chunk0_key, Instant::now());
        guard.insert(chunk1_key, Instant::now());
    }

    actor
        .handle_rbc_chunk(chunk0.clone(), None)
        .expect("first chunk stashed");
    actor
        .handle_rbc_chunk(chunk1.clone(), None)
        .expect("second chunk stashed");

    let pending = actor
        .subsystems
        .da_rbc
        .rbc
        .pending
        .get(&key)
        .expect("pending RBC stash should remain for missing INIT");
    assert_eq!(pending.pending_chunks(), 1);
    assert_eq!(
        pending
            .chunks
            .front()
            .expect("surviving pending chunk")
            .chunk
            .idx,
        1,
        "the newer chunk should survive per-session cap eviction"
    );

    let guard = actor
        .block_payload_dedup
        .lock()
        .expect("block payload dedup cache poisoned");
    assert!(
        !guard.contains(&chunk0_key),
        "evicted pending chunk dedup key must be released"
    );
    assert!(
        guard.contains(&chunk1_key),
        "accepted pending chunk dedup key must stay registered"
    );

    harness.shutdown.send();
}

#[tokio::test(flavor = "current_thread")]
async fn rbc_drop_releases_block_payload_dedup_on_session_limit() {
    let mut harness = test_actor_harness(1).await;
    let actor = &mut harness.actor;
    actor.config.rbc.pending_session_limit = 1;

    let active_key = session_key();
    let epoch = actor.epoch_for_height(active_key.1);
    actor
        .subsystems
        .da_rbc
        .rbc
        .sessions
        .insert(active_key, RbcSession::test_new(1, None, None, epoch));
    actor
        .subsystems
        .da_rbc
        .rbc
        .pending
        .insert(active_key, PendingRbcMessages::new(Instant::now()));

    let drop_key = (
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x44; Hash::LENGTH])),
        active_key.1,
        active_key.2.saturating_add(1),
    );
    let epoch = actor.epoch_for_height(drop_key.1);
    let roster_hash = Hash::prehashed([0x55; Hash::LENGTH]);
    let chunk_root = Hash::prehashed([0x66; Hash::LENGTH]);

    let ready = crate::sumeragi::consensus::RbcReady {
        block_hash: drop_key.0,
        height: drop_key.1,
        view: drop_key.2,
        epoch,
        roster_hash,
        chunk_root,
        sender: 0,
        signature: vec![0x01],
    };
    let ready_key = crate::sumeragi::BlockPayloadDedupKey::RbcReady {
        height: ready.height,
        view: ready.view,
        block_hash: ready.block_hash,
        sender: ready.sender,
        signature_hash: Hash::new(&ready.signature),
    };
    {
        let mut guard = actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned");
        guard.insert(ready_key, Instant::now());
    }
    actor.handle_rbc_ready(ready).expect("ready handled");
    assert!(
        !actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned")
            .contains(&ready_key)
    );

    let deliver = crate::sumeragi::consensus::RbcDeliver {
        block_hash: drop_key.0,
        height: drop_key.1,
        view: drop_key.2,
        epoch,
        roster_hash,
        chunk_root,
        sender: 0,
        signature: vec![0x02],
        ready_signatures: Vec::new(),
    };
    let deliver_key = crate::sumeragi::BlockPayloadDedupKey::RbcDeliver {
        height: deliver.height,
        view: deliver.view,
        block_hash: deliver.block_hash,
        sender: deliver.sender,
        signature_hash: Hash::new(&deliver.signature),
    };
    {
        let mut guard = actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned");
        guard.insert(deliver_key, Instant::now());
    }
    actor.handle_rbc_deliver(deliver).expect("deliver handled");
    assert!(
        !actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned")
            .contains(&deliver_key)
    );

    let chunk = crate::sumeragi::consensus::RbcChunk {
        block_hash: drop_key.0,
        height: drop_key.1,
        view: drop_key.2,
        epoch,
        idx: 0,
        bytes: vec![0x03, 0x04],
    };
    let chunk_key = crate::sumeragi::BlockPayloadDedupKey::RbcChunk {
        height: chunk.height,
        view: chunk.view,
        epoch: chunk.epoch,
        block_hash: chunk.block_hash,
        idx: chunk.idx,
        bytes_hash: Hash::new(&chunk.bytes),
    };
    {
        let mut guard = actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned");
        guard.insert(chunk_key, Instant::now());
    }
    actor.handle_rbc_chunk(chunk, None).expect("chunk handled");
    assert!(
        !actor
            .block_payload_dedup
            .lock()
            .expect("block payload dedup cache poisoned")
            .contains(&chunk_key)
    );

    harness.shutdown.send();
}

#[test]
fn commitment_snapshot_builder_formal_gate_matrix() {
    let mut lane_totals = BTreeMap::new();
    lane_totals.insert(LaneId::new(5), (8, 10, 1024, 800));
    lane_totals.insert(LaneId::new(3), (7, 9, 512, 400));
    let mut dataspace_totals = BTreeMap::new();
    dataspace_totals.insert((LaneId::new(5), DataSpaceId::new(9)), (5, 7, 300, 200));
    dataspace_totals.insert((LaneId::new(3), DataSpaceId::new(11)), (4, 6, 256, 128));
    let block_hash = HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xCC; 32]));
    let height = 21;

    let (lane_commitments, dataspace_commitments) = super::build_commitment_snapshots_from_totals(
        lane_totals,
        dataspace_totals,
        block_hash,
        height,
    );

    let lane_output = lane_commitments
        .iter()
        .map(|lane| {
            (
                lane.block_height,
                lane.lane_id,
                lane.tx_count,
                lane.total_chunks,
                lane.rbc_bytes_total,
                lane.teu_total,
                lane.block_hash,
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        lane_output,
        vec![
            (height, 3, 7, 9, 512, 400, block_hash),
            (height, 5, 8, 10, 1024, 800, block_hash),
        ],
        "lane snapshots should preserve fields and BTreeMap order",
    );

    let dataspace_output = dataspace_commitments
        .iter()
        .map(|dataspace| {
            (
                dataspace.block_height,
                dataspace.lane_id,
                dataspace.dataspace_id,
                dataspace.tx_count,
                dataspace.total_chunks,
                dataspace.rbc_bytes_total,
                dataspace.teu_total,
                dataspace.block_hash,
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        dataspace_output,
        vec![
            (height, 3, 11, 4, 6, 256, 128, block_hash),
            (height, 5, 9, 5, 7, 300, 200, block_hash),
        ],
        "dataspace snapshots should preserve fields and BTreeMap order",
    );
}

#[test]
fn rbc_session_adopts_persisted_allocations() {
    let mut session = RbcSession::test_new(4, None, None, 0);
    assert!(session.lane_allocations.is_empty());
    let summary = rbc_status::Summary {
        block_hash: HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0x55; 32])),
        height: 5,
        view: 0,
        total_chunks: 4,
        encoding: iroha_data_model::block::consensus::RbcEncoding::Plain,
        data_shards: 0,
        parity_shards: 0,
        received_chunks: 2,
        ready_count: 1,
        delivered: false,
        payload_hash: None,
        recovered_from_disk: true,
        invalid: false,
        reconstructed_stripes: 0,
        reconstructable_stripes: 0,
        lane_backlog: vec![status::LaneRbcSnapshot {
            lane_id: 7,
            tx_count: 3,
            total_chunks: 4,
            pending_chunks: 2,
            rbc_bytes_total: 1024,
        }],
        dataspace_backlog: vec![status::DataspaceRbcSnapshot {
            lane_id: 7,
            dataspace_id: 42,
            tx_count: 3,
            total_chunks: 4,
            pending_chunks: 2,
            rbc_bytes_total: 1024,
        }],
    };

    session.adopt_allocations_from_summary(&summary);
    assert_eq!(session.lane_allocations.len(), 1);
    assert_eq!(session.dataspace_allocations.len(), 1);
    assert_eq!(session.lane_allocations[0].lane_id, LaneId::new(7));
    assert_eq!(
        session.dataspace_allocations[0].dataspace_id,
        DataSpaceId::new(42)
    );

    let mut session_again = session.clone();
    session_again.adopt_allocations_from_summary(&summary);
    assert_eq!(session_again.lane_allocations.len(), 1);
    assert_eq!(session_again.dataspace_allocations.len(), 1);
}

