#[test]
fn rbc_session_persists_allocations_across_roundtrip() {
    let key = session_key();
    let chain_hash = Hash::new(b"chain");
    let manifest = SoftwareManifest::current();
    let roster = vec![PeerId::new(checked_keypair().public_key().clone())];

    let mut session = RbcSession::test_new(4, None, None, 0);
    session.lane_allocations.push(super::LaneAllocation {
        lane_id: LaneId::new(7),
        tx_count: 3,
        rbc_bytes_total: 1024,
        teu_total: 11,
        total_chunks: 4,
    });
    session
        .dataspace_allocations
        .push(super::DataspaceAllocation {
            lane_id: LaneId::new(7),
            dataspace_id: DataSpaceId::new(42),
            tx_count: 3,
            rbc_bytes_total: 1024,
            teu_total: 11,
            total_chunks: 4,
        });

    let persisted = session.to_persisted(key, chain_hash, &manifest, &roster);
    assert_eq!(
        persisted.lane_allocations,
        vec![super::super::rbc_store::PersistedLaneAllocation {
            lane_id: 7,
            tx_count: 3,
            rbc_bytes_total: 1024,
            teu_total: 11,
            total_chunks: 4,
        }]
    );
    assert_eq!(
        persisted.dataspace_allocations,
        vec![super::super::rbc_store::PersistedDataspaceAllocation {
            lane_id: 7,
            dataspace_id: 42,
            tx_count: 3,
            rbc_bytes_total: 1024,
            teu_total: 11,
            total_chunks: 4,
        }]
    );

    let rebuilt = RbcSession::from_persisted_unchecked(&persisted).expect("rebuild session");
    assert_eq!(rebuilt.lane_allocations.len(), 1);
    assert_eq!(rebuilt.dataspace_allocations.len(), 1);
    assert_eq!(rebuilt.lane_allocations[0].lane_id, LaneId::new(7));
    assert_eq!(rebuilt.lane_allocations[0].teu_total, 11);
    assert_eq!(
        rebuilt.dataspace_allocations[0].dataspace_id,
        DataSpaceId::new(42)
    );
    assert_eq!(rebuilt.dataspace_allocations[0].teu_total, 11);

    let lane_backlog = rebuilt.lane_backlog_entries();
    let dataspace_backlog = rebuilt.dataspace_backlog_entries();
    assert_eq!(lane_backlog.len(), 1);
    assert_eq!(lane_backlog[0].pending_chunks, 4);
    assert_eq!(dataspace_backlog.len(), 1);
    assert_eq!(dataspace_backlog[0].pending_chunks, 4);
}

#[test]
fn rbc_session_from_persisted_rejects_malformed_allocations() {
    let key = session_key();
    let chain_hash = Hash::new(b"chain");
    let manifest = SoftwareManifest::current();
    let roster = vec![PeerId::new(checked_keypair().public_key().clone())];

    let mut session = RbcSession::test_new(4, None, None, 0);
    session.lane_allocations.push(super::LaneAllocation {
        lane_id: LaneId::new(7),
        tx_count: 3,
        rbc_bytes_total: 1024,
        teu_total: 11,
        total_chunks: 4,
    });
    session
        .dataspace_allocations
        .push(super::DataspaceAllocation {
            lane_id: LaneId::new(7),
            dataspace_id: DataSpaceId::new(42),
            tx_count: 3,
            rbc_bytes_total: 1024,
            teu_total: 11,
            total_chunks: 4,
        });

    let baseline = session.to_persisted(key, chain_hash, &manifest, &roster);
    let mut cases: Vec<(
        &'static str,
        super::super::rbc_store::PersistedSession,
        &'static str,
    )> = Vec::new();

    let mut lane_sum_mismatch = baseline.clone();
    lane_sum_mismatch.lane_allocations[0].total_chunks = 5;
    cases.push((
        "lane chunk sum mismatch",
        lane_sum_mismatch,
        "lane allocation chunk sum mismatch",
    ));

    let mut duplicate_lane = baseline.clone();
    duplicate_lane
        .lane_allocations
        .push(duplicate_lane.lane_allocations[0]);
    cases.push((
        "duplicate lane",
        duplicate_lane,
        "duplicate lane allocation",
    ));

    let mut duplicate_dataspace = baseline.clone();
    duplicate_dataspace
        .dataspace_allocations
        .push(duplicate_dataspace.dataspace_allocations[0]);
    cases.push((
        "duplicate dataspace",
        duplicate_dataspace,
        "duplicate dataspace allocation",
    ));

    let mut missing_dataspace_allocations = baseline.clone();
    missing_dataspace_allocations.dataspace_allocations.clear();
    cases.push((
        "missing dataspace allocations",
        missing_dataspace_allocations,
        "incomplete allocation metadata",
    ));

    let mut missing_lane_allocations = baseline.clone();
    missing_lane_allocations.lane_allocations.clear();
    cases.push((
        "missing lane allocations",
        missing_lane_allocations,
        "incomplete allocation metadata",
    ));

    let mut unknown_dataspace_lane = baseline.clone();
    unknown_dataspace_lane.dataspace_allocations[0].lane_id = 8;
    cases.push((
        "unknown dataspace lane",
        unknown_dataspace_lane,
        "dataspace allocation references unknown lane",
    ));

    let mut zero_lane_tx_count = baseline.clone();
    zero_lane_tx_count.lane_allocations[0].tx_count = 0;
    cases.push((
        "zero lane transaction count",
        zero_lane_tx_count,
        "zero lane allocation transaction count",
    ));

    let mut zero_dataspace_tx_count = baseline.clone();
    zero_dataspace_tx_count.dataspace_allocations[0].tx_count = 0;
    cases.push((
        "zero dataspace transaction count",
        zero_dataspace_tx_count,
        "zero dataspace allocation transaction count",
    ));

    let mut dataspace_sum_mismatch = baseline.clone();
    dataspace_sum_mismatch.dataspace_allocations[0].rbc_bytes_total = 1023;
    cases.push((
        "dataspace byte sum mismatch",
        dataspace_sum_mismatch,
        "dataspace allocation sum mismatch",
    ));

    let canonical_lanes = vec![
        super::super::rbc_store::PersistedLaneAllocation {
            lane_id: 7,
            tx_count: 1,
            rbc_bytes_total: 256,
            teu_total: 5,
            total_chunks: 1,
        },
        super::super::rbc_store::PersistedLaneAllocation {
            lane_id: 8,
            tx_count: 2,
            rbc_bytes_total: 768,
            teu_total: 6,
            total_chunks: 3,
        },
    ];
    let canonical_dataspaces = vec![
        super::super::rbc_store::PersistedDataspaceAllocation {
            lane_id: 7,
            dataspace_id: 42,
            tx_count: 1,
            rbc_bytes_total: 256,
            teu_total: 5,
            total_chunks: 1,
        },
        super::super::rbc_store::PersistedDataspaceAllocation {
            lane_id: 8,
            dataspace_id: 43,
            tx_count: 2,
            rbc_bytes_total: 768,
            teu_total: 6,
            total_chunks: 3,
        },
    ];

    let mut noncanonical_lane_order = baseline.clone();
    noncanonical_lane_order.lane_allocations = canonical_lanes.iter().rev().copied().collect();
    noncanonical_lane_order.dataspace_allocations = canonical_dataspaces.clone();
    cases.push((
        "non-canonical lane order",
        noncanonical_lane_order,
        "non-canonical lane allocation order",
    ));

    let mut noncanonical_dataspace_order = baseline.clone();
    noncanonical_dataspace_order.lane_allocations = canonical_lanes;
    noncanonical_dataspace_order.dataspace_allocations =
        canonical_dataspaces.iter().rev().copied().collect();
    cases.push((
        "non-canonical dataspace order",
        noncanonical_dataspace_order,
        "non-canonical dataspace allocation order",
    ));

    for (label, persisted, expected) in cases {
        let err = RbcSession::from_persisted_unchecked(&persisted)
            .expect_err("malformed persisted allocation should fail");
        assert_eq!(
            err,
            super::PersistedLoadError::InvalidAllocation(expected),
            "{label}"
        );
    }
}

#[test]
fn rbc_session_new_rejects_chunk_over_cap() {
    let too_many = super::RBC_MAX_TOTAL_CHUNKS + 1;
    let err = RbcSession::new(too_many, None, None, None, 0)
        .expect_err("session should reject chunk overflow");
    match err {
        super::RbcSessionError::TooManyChunks {
            total_chunks,
            max_chunks,
        } => {
            assert_eq!(total_chunks, too_many);
            assert_eq!(max_chunks, super::RBC_MAX_TOTAL_CHUNKS);
        }
        other => panic!("unexpected error: {other:?}"),
    }
}

#[test]
fn rbc_session_new_rejects_digest_count_mismatch() {
    let err = RbcSession::new(2, None, None, Some(vec![[0u8; 32]]), 0)
        .expect_err("session should reject digest count mismatch");
    match err {
        super::RbcSessionError::DigestCountMismatch {
            total_chunks,
            observed,
        } => {
            assert_eq!(total_chunks, 2);
            assert_eq!(observed, 1);
        }
        other => panic!("unexpected error: {other:?}"),
    }
}

#[test]
fn rbc_session_new_marks_expected_digest_root_mismatch_invalid() {
    let digests = vec![[0x11; 32], [0x22; 32]];
    let root = MerkleTree::<[u8; 32]>::from_hashed_leaves_sha256(digests.clone())
        .root()
        .map(Hash::from)
        .expect("non-empty digest list should produce a root");
    let mut wrong_root = *root.as_ref();
    wrong_root[0] ^= 0xFF;

    let session = RbcSession::new(2, None, Some(Hash::prehashed(wrong_root)), Some(digests), 0)
        .expect("digest/root mismatch should create an invalid diagnostic session");

    assert!(
        session.is_invalid(),
        "sessions with contradictory expected digest/root metadata must start invalid"
    );
}

#[test]
fn backpressure_gate_defers_when_saturated() {
    let capacity = NonZeroUsize::new(4).expect("non-zero");
    let (tx, rx) = watch::channel(BackpressureState::Healthy {
        queued: 0,
        capacity,
    });
    let mut gate = super::BackpressureGate::new(rx);
    assert!(!gate.should_defer());

    tx.send(BackpressureState::Saturated {
        queued: 4,
        capacity,
    })
    .expect("send saturated");
    assert!(gate.should_defer());

    tx.send(BackpressureState::Healthy {
        queued: 2,
        capacity,
    })
    .expect("send healthy");
    assert!(!gate.should_defer());
}

#[test]
fn backpressure_gate_refresh_reports_changes() {
    let capacity = NonZeroUsize::new(2).expect("non-zero");
    let (tx, rx) = watch::channel(BackpressureState::Healthy {
        queued: 0,
        capacity,
    });
    let mut gate = super::BackpressureGate::new(rx);

    // Initial refresh should be a no-op because the snapshot is unchanged.
    assert!(!gate.refresh());
    assert_eq!(
        gate.state(),
        BackpressureState::Healthy {
            queued: 0,
            capacity
        }
    );

    tx.send(BackpressureState::Saturated {
        queued: capacity.get(),
        capacity,
    })
    .expect("send saturated");

    // A changed snapshot should be observed once and cached for subsequent reads.
    assert!(gate.refresh());
    assert_eq!(
        gate.state(),
        BackpressureState::Saturated {
            queued: capacity.get(),
            capacity
        }
    );
    assert!(
        !gate.refresh(),
        "refresh should be false when the state has not changed again"
    );
}

#[test]
fn pacemaker_respects_refreshed_backpressure_state() {
    let capacity = NonZeroUsize::new(3).expect("non-zero");
    let (tx, rx) = watch::channel(BackpressureState::Healthy {
        queued: 0,
        capacity,
    });
    let mut gate = super::BackpressureGate::new(rx);
    let start = Instant::now();
    let mut pacemaker = super::Pacemaker::with_interval(Duration::from_millis(5), start);
    let mut tracker = super::PacemakerBackpressure::new();

    // Backpressure flips to saturated after the initial snapshot; refreshing via should_defer
    // must propagate to the pacemaker evaluation.
    tx.send(BackpressureState::Saturated {
        queued: capacity.get(),
        capacity,
    })
    .expect("send saturated");

    let should_defer = gate.should_defer();
    let state = gate.state();
    let backpressure = ProposalBackpressure {
        queue_state: state,
        active_pending: false,
        rbc_backlog: false,
        relay_backpressure: false,
        consensus_queue_backpressure: false,
    };
    let (log_first, log_fire, attempt) =
        Actor::evaluate_pacemaker(&mut pacemaker, &mut tracker, backpressure, start);

    assert!(should_defer, "gate should report saturation");
    assert!(state.is_saturated(), "state snapshot must reflect refresh");
    assert!(log_first, "first saturation should be logged");
    assert!(
        log_fire,
        "deferral logging should be requested under saturation"
    );
    assert!(
        !attempt,
        "pacemaker should not attempt before the deadline while saturated"
    );
}

#[test]
fn evaluate_pacemaker_continues_under_saturation() {
    let capacity = NonZeroUsize::new(4).expect("non-zero");
    let state = BackpressureState::Saturated {
        queued: 4,
        capacity,
    };
    let backpressure = ProposalBackpressure {
        queue_state: state,
        active_pending: false,
        rbc_backlog: false,
        relay_backpressure: false,
        consensus_queue_backpressure: false,
    };
    let now = Instant::now();
    let mut pacemaker = super::Pacemaker::with_interval(Duration::from_millis(5), now);
    let mut tracker = super::PacemakerBackpressure::new();

    let (log_first, log_fire, should_attempt) =
        Actor::evaluate_pacemaker(&mut pacemaker, &mut tracker, backpressure, now);

    assert!(
        !should_attempt,
        "pacemaker should defer proposal while saturated before the deadline"
    );
    assert!(log_first, "initial saturation should trigger deferral log");
    assert!(
        log_fire,
        "saturation should request deferral logging when deferring"
    );
}

#[test]
fn evaluate_pacemaker_defers_and_recovers_after_backoff() {
    let capacity = NonZeroUsize::new(3).expect("non-zero");
    let saturated = BackpressureState::Saturated {
        queued: 3,
        capacity,
    };
    let saturated_backpressure = ProposalBackpressure {
        queue_state: saturated,
        active_pending: false,
        rbc_backlog: false,
        relay_backpressure: false,
        consensus_queue_backpressure: false,
    };
    let start = Instant::now();
    let mut pacemaker = super::Pacemaker::with_interval(Duration::from_millis(5), start);
    let mut tracker = super::PacemakerBackpressure::new();

    // First firing while saturated should defer and log.
    let (log_first, log_fire, attempt) =
        Actor::evaluate_pacemaker(&mut pacemaker, &mut tracker, saturated_backpressure, start);
    assert!(log_first, "first saturation should be logged");
    assert!(log_fire, "saturation must request deferral logging");
    assert!(
        !attempt,
        "proposal assembly should be deferred while saturated"
    );

    // Within the same window nothing should fire again.
    let (log_repeat, log_fire_repeat, attempt_repeat) = Actor::evaluate_pacemaker(
        &mut pacemaker,
        &mut tracker,
        saturated_backpressure,
        start + Duration::from_millis(2),
    );
    assert!(!log_repeat);
    assert!(!log_fire_repeat);
    assert!(!attempt_repeat);

    // Once saturation clears after the deadline passes, pacemaker should resume.
    let healthy = BackpressureState::Healthy {
        queued: 0,
        capacity,
    };
    let healthy_backpressure = ProposalBackpressure {
        queue_state: healthy,
        active_pending: false,
        rbc_backlog: false,
        relay_backpressure: false,
        consensus_queue_backpressure: false,
    };
    let (log_recovered, log_fire_recovered, attempt_recovered) = Actor::evaluate_pacemaker(
        &mut pacemaker,
        &mut tracker,
        healthy_backpressure,
        start + Duration::from_millis(6),
    );
    assert!(!log_recovered);
    assert!(!log_fire_recovered);
    assert!(
        attempt_recovered,
        "pacemaker should attempt once backpressure clears"
    );
}

