#[test]
fn proposal_backpressure_formal_gate_matrix() {
    #[derive(Clone, Copy)]
    struct Case {
        name: &'static str,
        queue_saturated: bool,
        consensus_queue: bool,
        active_pending: bool,
        rbc_backlog: bool,
        relay_backpressure: bool,
        should_defer: bool,
        only_pacing: bool,
        allows_queue_work: bool,
    }

    let cases = [
        Case {
            name: "healthy_none",
            queue_saturated: false,
            consensus_queue: false,
            active_pending: false,
            rbc_backlog: false,
            relay_backpressure: false,
            should_defer: false,
            only_pacing: false,
            allows_queue_work: true,
        },
        Case {
            name: "queue_saturated",
            queue_saturated: true,
            consensus_queue: false,
            active_pending: false,
            rbc_backlog: false,
            relay_backpressure: false,
            should_defer: true,
            only_pacing: true,
            allows_queue_work: true,
        },
        Case {
            name: "consensus_queue",
            queue_saturated: false,
            consensus_queue: true,
            active_pending: false,
            rbc_backlog: false,
            relay_backpressure: false,
            should_defer: true,
            only_pacing: true,
            allows_queue_work: true,
        },
        Case {
            name: "queue_and_consensus",
            queue_saturated: true,
            consensus_queue: true,
            active_pending: false,
            rbc_backlog: false,
            relay_backpressure: false,
            should_defer: true,
            only_pacing: true,
            allows_queue_work: true,
        },
        Case {
            name: "active_pending",
            queue_saturated: false,
            consensus_queue: false,
            active_pending: true,
            rbc_backlog: false,
            relay_backpressure: false,
            should_defer: true,
            only_pacing: false,
            allows_queue_work: false,
        },
        Case {
            name: "rbc_backlog",
            queue_saturated: false,
            consensus_queue: false,
            active_pending: false,
            rbc_backlog: true,
            relay_backpressure: false,
            should_defer: true,
            only_pacing: false,
            allows_queue_work: false,
        },
        Case {
            name: "relay_backpressure",
            queue_saturated: false,
            consensus_queue: false,
            active_pending: false,
            rbc_backlog: false,
            relay_backpressure: true,
            should_defer: true,
            only_pacing: false,
            allows_queue_work: false,
        },
        Case {
            name: "active_pending_with_queue",
            queue_saturated: true,
            consensus_queue: false,
            active_pending: true,
            rbc_backlog: false,
            relay_backpressure: false,
            should_defer: true,
            only_pacing: false,
            allows_queue_work: false,
        },
        Case {
            name: "active_pending_with_consensus",
            queue_saturated: false,
            consensus_queue: true,
            active_pending: true,
            rbc_backlog: false,
            relay_backpressure: false,
            should_defer: true,
            only_pacing: false,
            allows_queue_work: false,
        },
        Case {
            name: "rbc_backlog_with_queue",
            queue_saturated: true,
            consensus_queue: false,
            active_pending: false,
            rbc_backlog: true,
            relay_backpressure: false,
            should_defer: true,
            only_pacing: false,
            allows_queue_work: false,
        },
        Case {
            name: "rbc_backlog_with_consensus",
            queue_saturated: false,
            consensus_queue: true,
            active_pending: false,
            rbc_backlog: true,
            relay_backpressure: false,
            should_defer: true,
            only_pacing: false,
            allows_queue_work: false,
        },
        Case {
            name: "relay_backpressure_with_queue",
            queue_saturated: true,
            consensus_queue: false,
            active_pending: false,
            rbc_backlog: false,
            relay_backpressure: true,
            should_defer: true,
            only_pacing: false,
            allows_queue_work: false,
        },
        Case {
            name: "relay_backpressure_with_consensus",
            queue_saturated: false,
            consensus_queue: true,
            active_pending: false,
            rbc_backlog: false,
            relay_backpressure: true,
            should_defer: true,
            only_pacing: false,
            allows_queue_work: false,
        },
        Case {
            name: "all_signals",
            queue_saturated: true,
            consensus_queue: true,
            active_pending: true,
            rbc_backlog: true,
            relay_backpressure: true,
            should_defer: true,
            only_pacing: false,
            allows_queue_work: false,
        },
    ];

    let capacity = NonZeroUsize::new(2).expect("non-zero");
    for case in cases {
        let queue_state = if case.queue_saturated {
            BackpressureState::Saturated {
                queued: capacity.get(),
                capacity,
            }
        } else {
            BackpressureState::Healthy {
                queued: 0,
                capacity,
            }
        };
        let backpressure = ProposalBackpressure {
            queue_state,
            active_pending: case.active_pending,
            rbc_backlog: case.rbc_backlog,
            relay_backpressure: case.relay_backpressure,
            consensus_queue_backpressure: case.consensus_queue,
        };

        assert_eq!(
            backpressure.should_defer(),
            case.should_defer,
            "{} should_defer",
            case.name
        );
        assert_eq!(
            backpressure.only_pacing_backpressure(),
            case.only_pacing,
            "{} only_pacing_backpressure",
            case.name
        );
        assert_eq!(
            super::proposal_backpressure_allows_queue_work(backpressure),
            case.allows_queue_work,
            "{} allows_queue_work",
            case.name
        );
    }
}

#[test]
fn proposal_backpressure_allows_queue_only_pacing_for_queue_work() {
    let capacity = NonZeroUsize::new(2).expect("non-zero");
    let saturated = BackpressureState::Saturated {
        queued: 2,
        capacity,
    };
    let backpressure = ProposalBackpressure {
        queue_state: saturated,
        active_pending: false,
        rbc_backlog: false,
        relay_backpressure: false,
        consensus_queue_backpressure: false,
    };

    assert!(backpressure.should_defer());
    assert!(backpressure.only_pacing_backpressure());
    assert!(super::proposal_backpressure_allows_queue_work(backpressure));

    let active_pending = ProposalBackpressure {
        active_pending: true,
        ..backpressure
    };
    assert!(
        !super::proposal_backpressure_allows_queue_work(active_pending),
        "active pending work remains hard proposal backpressure"
    );
}

#[test]
fn idle_view_budget_is_preserved_for_due_proposal_under_pacing_backpressure() {
    let capacity = NonZeroUsize::new(2).expect("non-zero");
    let saturated = BackpressureState::Saturated {
        queued: 2,
        capacity,
    };
    let backpressure = ProposalBackpressure {
        queue_state: saturated,
        active_pending: false,
        rbc_backlog: false,
        relay_backpressure: false,
        consensus_queue_backpressure: true,
    };

    assert!(should_preserve_idle_view_budget_for_proposal(
        16,
        false,
        false,
        backpressure,
        true,
    ));

    let active_pending = ProposalBackpressure {
        active_pending: true,
        ..backpressure
    };
    assert!(
        !should_preserve_idle_view_budget_for_proposal(16, false, false, active_pending, true,),
        "active pending work must keep idle-view repair available"
    );

    assert!(
        !should_preserve_idle_view_budget_for_proposal(16, false, false, backpressure, false,),
        "idle-view repair should run while the proposal deadline has not fired"
    );
}

#[test]
fn idle_view_repair_retries_after_skipped_due_proposal_only_when_frontier_empty() {
    assert!(should_retry_idle_view_after_proposal(true, 16, 0, false));
    assert!(
        !should_retry_idle_view_after_proposal(false, 16, 0, false),
        "no retry is needed when idle repair already ran before proposal evaluation"
    );
    assert!(
        !should_retry_idle_view_after_proposal(true, 0, 0, false),
        "idle repair must stay quiet without queued work"
    );
    assert!(
        !should_retry_idle_view_after_proposal(true, 16, 1, false),
        "active pending blocks already own same-height liveness"
    );
    assert!(
        !should_retry_idle_view_after_proposal(true, 16, 0, true),
        "commit-inflight work must not be interrupted by the post-proposal retry"
    );
}

