#[test]
fn activation_plan_defers_until_margin() {
    let params = ValidatorElectionParameters {
        max_validators: 2,
        min_self_bond: 1,
        min_nomination_bond: 1,
        max_nominator_concentration_pct: 25,
        seat_band_pct: 5,
        max_entity_correlation_pct: 25,
        finality_margin_blocks: 5,
    };
    let peer = PeerId::new(checked_keypair().public_key().clone());
    let election = ValidatorElectionOutcome {
        epoch: 1,
        snapshot_height: 10,
        seed: [0x11; 32],
        candidates_total: 1,
        validator_set: vec![peer.clone()],
        validator_set_hash: HashOf::new(&vec![peer.clone()]),
        params,
        rejection_reason: None,
        tie_break: Vec::new(),
    };
    let record = VrfEpochRecord {
        epoch: 1,
        seed: [0x22; 32],
        epoch_length: 10,
        commit_deadline_offset: 3,
        reveal_deadline_offset: 6,
        roster_len: 1,
        finalized: true,
        updated_at_height: 10,
        participants: Vec::new(),
        late_reveals: Vec::new(),
        committed_no_reveal: Vec::new(),
        no_participation: Vec::new(),
        penalties_applied: true,
        penalties_applied_at_height: Some(10),
        validator_election: Some(election),
    };

    let plan =
        Actor::activation_plan_from_vrf_record(12, &record).expect("plan should be produced");
    assert_eq!(plan.0, 15);
    assert!(
        !plan.2,
        "activation should defer when current height below activation threshold"
    );
}

#[test]
fn committed_vrf_record_does_not_cover_newer_pending_late_reveal() {
    use iroha_data_model::consensus::{VrfEpochRecord, VrfLateRevealRecord, VrfParticipantRecord};

    let participant = VrfParticipantRecord {
        signer: 0,
        commitment: Some([0x11; 32]),
        reveal: None,
        last_updated_height: 2,
    };
    let committed = VrfEpochRecord {
        epoch: 0,
        seed: [0x22; 32],
        epoch_length: 10,
        commit_deadline_offset: 4,
        reveal_deadline_offset: 4,
        roster_len: 4,
        finalized: false,
        updated_at_height: 2,
        participants: vec![participant],
        late_reveals: Vec::new(),
        committed_no_reveal: Vec::new(),
        no_participation: Vec::new(),
        penalties_applied: false,
        penalties_applied_at_height: None,
        validator_election: None,
    };
    let late_reveal = VrfLateRevealRecord {
        signer: 0,
        reveal: [0x33; 32],
        noted_at_height: 5,
    };
    let mut pending = committed.clone();
    pending.updated_at_height = 5;
    pending.late_reveals.push(late_reveal);

    assert!(
        !Actor::committed_vrf_record_covers_pending(&committed, &pending),
        "a stale committed seal must not drop a newer pending late reveal"
    );

    let mut committed_with_reveal = pending.clone();
    committed_with_reveal.finalized = true;
    assert!(
        Actor::committed_vrf_record_covers_pending(&committed_with_reveal, &pending),
        "a committed seal that contains the pending late reveal may clear it"
    );
}

